// ---------------------------------------------------------------------------
// Failures
// ---------------------------------------------------------------------------

/** A node error: what grammar 9's `on_error` decides the fate of. */
export class NodeFailure extends Error {
  readonly flow: string;
  readonly node: string;
  readonly attempts: number;

  constructor(flow: string, node: string, attempts: number, detail: string, cause?: unknown) {
    super(`${flow} node \`${node}\` failed: ${detail}`);
    this.name = "NodeFailure";
    this.flow = flow;
    this.node = node;
    this.attempts = attempts;
    this.cause = cause;
  }
}

/** A node whose `timeout:` budget ran out (grammar 9.2). */
export class NodeTimeout extends Error {
  constructor(node: string, budgetMs: number, attempts: number) {
    super(
      `\`${node}\` timed out: its ${budgetMs}ms budget was spent after ${attempts} attempt(s) (grammar 9.2)`,
    );
    this.name = "NodeTimeout";
  }
}

/** Grammar 7.3 rule 7: a completed node with no edge to take. */
export class NoViableRoute extends Error {
  /**
   * What each outgoing edge answered, in declaration order.
   *
   * The reason the error carries them: they are the routing decision PRD 5.3
   * asks a trace to hold, and the run that this error ends is exactly the run
   * whose trace never got to record them. [`runNode`] puts them on the entry it
   * hands the failure, so "which guard answered what" survives an abort.
   */
  readonly decisions: readonly EdgeDecision[];

  constructor(flow: string, node: string, decisions: readonly EdgeDecision[]) {
    super(
      `${flow}: no viable route out of \`${node}\` — every outgoing edge was untaken (grammar 7.3 rule 7)`,
    );
    this.name = "NoViableRoute";
    this.decisions = decisions;
  }
}

/**
 * A subflow a model invoked that did not answer (grammar 5.4, PRD 5.1).
 *
 * The boundary class of flow-as-tool, and it is a boundary in the same sense
 * [`ItemFailure`] is one: what happened below it is the *child instance's*
 * business, already recorded on the [`DispatchRecord`] this call filed
 * (`docs/trace.md` §5, PRD §9.20), so [`traceOf`] and [`dispatchesOf`] stop
 * here rather than walking on and stamping the child's account onto the
 * **agent** node's entry — where §3 says a `flow:` node's instance and a
 * `map`'s fan-out are, and an agent node's tool loop is not.
 *
 * It wraps every way a call can fail, including a pause this run cannot answer:
 * `interruptOf`, `abandonedOf` and `expiryOf` all walk the `cause` chain, so
 * wrapping is transparent to them and the run still ends the way the pause says
 * it does.
 *
 * What it does **not** wrap is the arguments failing the flow's own `inputs:`.
 * That failure happens before anything is instantiated, and it is reported the
 * way every other tool surface reports one — as a [`ToolCallRefused`], which
 * goes back to the model rather than out of the node (Decision D119).
 */
export class ToolFailure extends Error {
  /** The name the model called it by (grammar 5.4). */
  readonly tool: string;
  /** The flow behind that name, as a typed address (grammar 2.2). */
  readonly target: string;

  constructor(tool: string, target: string, cause: unknown) {
    super(`\`${tool}\` — the flow \`${target}\` a model called — failed: ${describe(cause)}`);
    this.name = "ToolFailure";
    this.tool = tool;
    this.target = target;
    this.cause = cause;
  }
}

/**
 * One dispatched `map` instance that did not complete (grammar 8.6 rule 10).
 *
 * Raised out of the map node when `on_item_error` resolves the item as `fail` —
 * either because that is the policy or because a parameterized `retry:` ran out
 * of attempts, which grammar 8.6 rule 10 says resolves as `fail` does. It is a
 * failure of the **map node**, so the node's own `on_error:` is what absorbs it,
 * and the item it names is the source-item index rather than a completion
 * ordinal: two runs over one array fail about the same item.
 */
export class ItemFailure extends Error {
  /** The source-item index, which is what identifies the item (PRD 5.6). */
  readonly index: number;
  /** The dispatch target the item went to. */
  readonly target: string;
  /** How many attempts the item's own policy made. */
  readonly attempts: number;
  /**
   * What the **whole** fan-out did, in source-item order (PRD 5.3, 5.6).
   *
   * Carried on the failure for the reason [`carryEntry`] carries a trace entry:
   * a map node that throws returns no answer, so the records it made have
   * nowhere else to go — and this is the path where they matter most. The items
   * that completed already had their effects, including any detached delivery
   * this dispatch issued, and the failure alone says nothing about them.
   */
  readonly dispatches: readonly DispatchRecord[];

  constructor(
    node: string,
    index: number,
    target: string,
    attempts: number,
    cause: unknown,
    dispatches: readonly DispatchRecord[] = [],
  ) {
    super(
      `\`${node}\` item ${index} was dispatched to \`${target}\` and failed after ${attempts} attempt(s): ${describe(cause)}`,
    );
    this.name = "ItemFailure";
    this.index = index;
    this.target = target;
    this.attempts = attempts;
    this.cause = cause;
    this.dispatches = dispatches;
  }
}

/**
 * A subflow instance that did not reach quiescence, or reached it holding no
 * value for one of its `outputs:` (grammar 7.5, 7.6.3, 10.1).
 *
 * The subgraph boundary is where a failure would otherwise lose its context: the
 * caller sees a node that failed, and what actually happened is a node three
 * levels down. So the message names the instance and the error keeps the
 * instance's own trace, which the `flow:` node then hands to its trace entry.
 */
export class SubflowFailure extends Error {
  /** The flow that was instantiated. */
  readonly flow: string;
  /** Every routing decision the instance made before it stopped (PRD 5.3). */
  readonly trace: readonly TraceEntry[];

  constructor(flow: string, what: string, trace: readonly TraceEntry[], cause: unknown) {
    super(`the instance of \`${flow}\` ${what}: ${describe(cause)}`);
    this.name = "SubflowFailure";
    this.flow = flow;
    this.trace = trace;
    this.cause = cause;
  }
}

/**
 * A result that does not match the schema its own contract declares (PRD 5.2).
 *
 * Structured output is load-bearing for routing, so the parse is where an answer
 * is held to the contract — and what a reader needs from a failed one is *which*
 * field and *what was there*. The emitted Zod says the first and, for two shapes
 * that matter most, not the second: a discriminated union reports "Invalid
 * discriminator value. Expected 'auto_fixable' | 'needs_human'" without ever
 * naming the tag it was handed, and a closed object reports an unrecognized key
 * without its value. Reading the document at each issue's own path is what makes
 * the message actionable rather than merely correct (PRD G3).
 */
export class ResultMismatch extends Error {
  /** What was being parsed, in diagnostic voice. */
  readonly subject: string;

  constructor(subject: string, value: unknown, issues: readonly ResultIssue[]) {
    super(`${subject}: ${describeIssues(value, issues)}`);
    this.name = "ResultMismatch";
    this.subject = subject;
  }
}

/**
 * A tool call the model can fix by **calling differently** (Decision D119, PRD
 * §9.22).
 *
 * The class the tool loop reads to tell the two kinds of tool-call failure
 * apart, and the whole of that distinction:
 *
 *  * a call the tool's declared contract **refuses** — arguments its schema does
 *    not admit, on any of the three surfaces (grammar §6, §5.4, §11.5), or a name
 *    the agent never offered — is raised as this, and the loop hands its
 *    `message` back to the model as an error tool result so the model can answer
 *    with a different call;
 *  * a failure of the tool's **execution** — a subprocess that exited nonzero, an
 *    HTTP request that was refused, a child flow instance that failed, a store
 *    backend that could not answer — is raised as whatever it is, leaves the
 *    tool, and fails the agent node the way it always has, with grammar §9's
 *    chain deciding the run. Rephrasing the call would not fix any of those.
 *
 * The `message` is therefore written for two readers at once: the *model*, which
 * is handed it verbatim as the error tool result, and the person reading
 * [`ToolCallRecord.error`], which carries it through [`describe`] — so the
 * record reads `ToolCallRefused: <message>`, `docs/trace.md` §3's shape for
 * every error this format spells, and the model's copy is the bare sentence
 * with no class in front of it. One sentence, two spellings of the same
 * envelope.
 *
 * It names what the compiler's own diagnostics would name — the tool, the field,
 * the constraint it failed, and an excerpt of the offending value (PRD G3). The
 * excerpt is the model's own arguments coming back to it, which is why quoting
 * them here costs nothing this format was protecting (`docs/trace.md` §11).
 */
export class ToolCallRefused extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ToolCallRefused";
  }
}

/** One issue a schema reported, in the shape both Zod and this module read. */
interface ResultIssue {
  readonly path: readonly PropertyKey[];
  readonly message: string;
}

/** What a schema this module parses with has to be able to do. */
export interface ResultSchema<T> {
  safeParse(value: unknown): {
    readonly success: boolean;
    readonly data?: T;
    readonly error?: { readonly issues: readonly ResultIssue[] };
  };
}

/** The value a document holds at one issue's path, if it holds one. */
function valueAt(value: unknown, path: readonly PropertyKey[]): unknown {
  let held = value;
  for (const step of path) {
    if (held === null || typeof held !== "object") return undefined;
    held = (held as Record<PropertyKey, unknown>)[step];
  }
  return held;
}

/** A value as a message quotes it: JSON, and short enough to read. */
function excerpt(value: unknown): string {
  const rendered = JSON.stringify(value) ?? String(value);
  return rendered.length <= 120 ? rendered : `${rendered.slice(0, 117)}...`;
}

/**
 * What a schema refused, in the voice [`ResultMismatch`] explains: the failing
 * path, the constraint, and what was actually there.
 *
 * Written once and read twice, because a refusal a *model* has to act on and a
 * mismatch a *person* has to fix want exactly the same sentence — see
 * [`ToolCallRefused`], whose message is this text under a different class.
 *
 * A schema that refused without saying why still gets a sentence, because both
 * readers are worse off with an empty one: a model handed `<subject>: ` has
 * nothing to correct and will spend the loop's bound repeating itself, and a
 * person reading it cannot tell a refusal from a truncation. The callers pass
 * `issues` defensively (`?? []`) for the same reason this clause exists.
 */
function describeIssues(value: unknown, issues: readonly ResultIssue[]): string {
  if (issues.length === 0) return "the schema refused it and reported no issue";
  return issues
    .map((issue) => {
      const path = issue.path.map(String).join(".");
      const found = valueAt(value, issue.path);
      const at = path === "" ? "" : `${path}: `;
      return found === undefined ? `${at}${issue.message}` : `${at}${issue.message} (found ${excerpt(found)})`;
    })
    .join("; ");
}

/**
 * Parse one result with the schema its contract declares, or say what was wrong
 * with it (PRD 5.2, and see [`ResultMismatch`]).
 *
 * This is also where resolved q29's **second** divergence is decided. A value
 * the journal answered with is a value some earlier generation's world produced
 * and this composition has since changed its mind about — "a recorded answer
 * [that] fails the current contract" — and q29 says outright that such a
 * divergence "fails the resume with a diagnostic naming the divergent step,
 * rather than silently re-executing an effect the journal claimed to hold".
 * A [`ResultMismatch`] would do exactly the thing it forbids: it is a node
 * failure, so a `retry:` absorbs it and the second attempt claims an ordinal
 * past the frontier and re-issues the effect **live** — the double side effect
 * durability exists to prevent, reported as an ordinary bad answer. So the
 * provenance of the value decides the class, and a [`ReplayDivergence`] travels
 * past every policy (see [`runActivity`], [`runNode`], [`attemptItem`]).
 *
 * And this is where the *other* half of that decision is written down. A live
 * answer this contract refuses is one a later generation will meet again, and
 * whether it was refused **then** is the whole of what tells resolved q29's
 * divergence from a mismatch the composition already had and already retried
 * past. Only this generation can say so, so it says so on the record
 * (`refuseRecorded` in `./journal.ts`) instead of leaving the next one to infer
 * it from the records around it — which cannot be done, because a retried call
 * and a repeated call leave the same sequence behind.
 */
export function parseResult<T>(schema: ResultSchema<T>, value: unknown, subject: string): T {
  const parsed = schema.safeParse(value);
  if (parsed.success) return parsed.data as T;
  const refused = new ResultMismatch(subject, value, parsed.error?.issues ?? []);
  const recorded = recordedAnswerOf(value, refused.message);
  if (recorded !== undefined) throw recorded;
  refuseRecorded(value);
  throw refused;
}

/**
 * Parse the arguments a **model** called a tool with (Decision D119, PRD §9.22).
 *
 * [`parseResult`]'s sibling at the one parse site whose failure is not the run's
 * problem to end: the model chose these arguments, so a schema that refuses them
 * is a call it can make again differently. The message is byte-for-byte the one
 * [`ResultMismatch`] would have raised — the same subject, the same issues, the
 * same excerpt — under [`ToolCallRefused`], which is the class [`callAgent`]
 * reads to decide that the failure goes back to the model instead of out of the
 * node.
 *
 * All three tool surfaces parse here, and that uniformity is the rule rather
 * than an implementation detail: grammar §5.4 makes "attached as a tool" mean one
 * thing, so a `tool.*`'s declared `input:`, a synthesized store tool's argument
 * surface and a `flow.*`'s `inputs:` refuse a call the same way. Each parses at
 * its **attachment** — the entry in an agent's `tools:` — rather than inside the
 * thing attached, which is what keeps the two `tool.*` call sites apart: the same
 * `tool.*` reached from a `function:` node parses with [`parseResult`], because
 * there the arguments are the composition's and grammar §8.4 has already checked
 * them field-by-field, so a mismatch is the graph's own failure and there is
 * nobody to hand it to.
 *
 * `subject` is therefore the name the **model** called, not the component's
 * address: the sentence is going to a reader whose only way to call again is the
 * name the wire offered it (`lookup`, not `tool.lookup`).
 *
 * What is *not* parsed here is any tool's **result** — that is [`parseResult`]
 * still, because a tool that answered off-contract is not a call the model can
 * rephrase.
 */
export function parseToolArguments<T>(
  schema: ResultSchema<T>,
  args: unknown,
  subject: string,
): T {
  const parsed = schema.safeParse(args);
  if (parsed.success) return parsed.data as T;
  throw new ToolCallRefused(`${subject}: ${describeIssues(args, parsed.error?.issues ?? [])}`);
}

/** A provider answered something other than a completion. */
export class ProviderFailure extends Error {
  readonly status: number;
  readonly body: string;

  constructor(model: string, status: number, body: string) {
    super(`\`${model}\` answered ${status}: ${body.slice(0, 400)}`);
    this.name = "ProviderFailure";
    this.status = status;
    this.body = body;
  }
}

/**
 * A request that never got an answer at all (PRD 5.9's `timeout`).
 *
 * Told apart from [`ProviderFailure`] because the two are different failover
 * conditions and from a `SyntaxError` because that one is not a condition: a
 * body that is not JSON is a response generated code must **reject**, and
 * failing over to the next route member would be asking a second provider about
 * the first one's malformed answer. So the socket is wrapped where it is used
 * ([`send`]) rather than classified by guessing at whatever `fetch` rejected
 * with, which differs between the two supported runtimes.
 */
export class ProviderUnreachable extends Error {
  constructor(model: string, cause: unknown) {
    super(`\`${model}\` answered nothing: ${describe(cause)}`);
    this.name = "ProviderUnreachable";
    this.cause = cause;
  }
}

/**
 * A request a route member did not answer inside the share of the node's budget
 * it was given (PRD 5.9's `timeout`, the other half of it).
 *
 * [`ProviderUnreachable`] is the failure a socket *reports* — a reset, a refused
 * connection, a name that did not resolve. This is the one nothing reports: a
 * provider that accepted the request and is still holding it. PRD 5.9's
 * `timeout` condition is written about that case, and without a request-level
 * budget there would be no moment at which to classify it — the node's own
 * deadline would arrive first and end the node with a declared fallback never
 * tried. See [`callModel`] for where the budget comes from.
 */
export class ProviderTimeout extends Error {
  constructor(model: string, budgetMs: number) {
    super(`\`${model}\` did not answer inside the ${budgetMs}ms this call was given`);
    this.name = "ProviderTimeout";
  }
}

// ---------------------------------------------------------------------------
// The environment, read where it is used
// ---------------------------------------------------------------------------

/**
 * One `${ENV}` reference, resolved at the moment a node needs it.
 *
 * `./index.ts` checks presence at process start (PRD 5.9) and this reads the
 * value. The read is late on purpose: importing `./graph.ts` builds descriptors
 * and constructs graphs, which a tool with no credentials — `tsc`, a graph
 * drawing, the construction gate — must be able to do.
 */
export function environmentValue(name: string, site: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`\`${name}\` is not set (referenced by ${site})`);
  }
  return value;
}

/** One part of an interpolable string (grammar 4.3 class 2). */
export type Interpolation = string | { readonly env: string; readonly site: string };

/** Substitute a class-2 string's references (grammar 4.3). */
export function interpolate(parts: readonly Interpolation[]): string {
  return parts
    .map((part) => (typeof part === "string" ? part : environmentValue(part.env, part.site)))
    .join("");
}

/**
 * The same string **as its author wrote it**: `${NAME}` where a reference is,
 * rather than what the reference resolved to.
 *
 * This is what an error message quotes. A class-2 surface is interpolable
 * end to end (grammar 4.3) — an `http:` binding's `url`, the whole `exec:`
 * block — so a composition may perfectly well write
 * `url: "${SIGNED_ENDPOINT}/reports"`, and a message that quoted the resolved
 * value would put a credential into a node's `error`, which is a field the
 * trace carries, the run prints and a reader files (`docs/trace.md` §11.1).
 * Naming the reference keeps the message diagnostic — it says which binding
 * failed, spelled the way the file spells it — and keeps it reproducible: two
 * environments produce one message.
 */
export function asWritten(parts: readonly Interpolation[]): string {
  return parts.map((part) => (typeof part === "string" ? part : `\${${part.env}}`)).join("");
}

// ---------------------------------------------------------------------------
// Policy: grammar 9
// ---------------------------------------------------------------------------

/** A resolved `retry:` block (grammar 9.1). */
export interface RetryPolicy {
  readonly max: number;
  readonly backoffMs: number;
  readonly multiplier: number;
  readonly maxBackoffMs?: number;
  readonly jitter: boolean;
}

/** What `on_error:` does once retries are exhausted (grammar 9.2). */
export type ErrorStrategy = "fail" | "skip" | { readonly fallback: string };

/** One node's resolved policy — levels 2, 3 and 4 of grammar 9.3's chain. */
export interface NodePolicy {
  readonly retry?: RetryPolicy;
  readonly timeoutMs?: number;
  readonly onError: ErrorStrategy;
}

/**
 * Level **1** of grammar 9.3's chain: the `policy:` of the `flow:` node that
 * instantiated the enclosing flow instance.
 *
 * It is carried in the instance's own `$run` rather than compiled into a node,
 * because it is a property of the *instantiation site* and one flow may be
 * instantiated from several of them — `flow.review_loop` under
 * `policy: { timeout: 30s }` here and with nothing there is the same emitted
 * node either way. `on_error` takes no `fallback` at this level: its target is a
 * node id of the flow the declaring node sits in, and this level names no flow
 * (§9.2, Decision D103).
 */
export interface InstancePolicy {
  readonly retry?: RetryPolicy;
  readonly timeoutMs?: number;
  readonly onError?: "fail" | "skip";
}

/**
 * Grammar 9.3 resolved for one node execution: its compiled levels 2–4, with
 * level 1 laid over them where the instance carries one.
 *
 * Level 1 wins per field, which is what "highest precedence first" says — and a
 * `human` node takes neither `timeout` nor `retry` from it, at this level as at
 * every other (Decision D102), which is what `exempt` marks.
 */
export function effectivePolicy(
  compiled: NodePolicy,
  exempt: boolean,
  override: InstancePolicy | undefined,
): NodePolicy {
  if (override === undefined) return compiled;
  return {
    ...(exempt ? {} : { retry: override.retry ?? compiled.retry }),
    ...(exempt
      ? {}
      : { timeoutMs: override.timeoutMs ?? compiled.timeoutMs }),
    onError: override.onError ?? compiled.onError,
  };
}

/**
 * A flow instance's run identity (grammar 4.1's `execution` root).
 *
 * `item_index` is the source-item index of the **innermost** enclosing `map`
 * dispatch. It is absent everywhere else, which is a property of the *site*
 * rather than of the composition — the same flow is a dispatch target at one
 * instantiation and a root instance at another — so an expression that reads it
 * outside a dispatch fails the execution rather than the build (Decision D115).
 */
export interface ExecutionIdentity {
  readonly id: string;
  readonly session_key: string;
  readonly item_index?: number;
}

/** What one node execution needs from the world. */
export interface RunContext {
  /** The flow instance's execution identity (grammar 4.1's `execution`). */
  readonly execution: ExecutionIdentity;
  /**
   * Aborted when the node's `timeout:` budget runs out.
   *
   * With one deliberate exception: a **detached** `map` dispatch runs under a
   * signal of its own, which nothing aborts. Its outcome is never observed
   * (Decision D94), so the node's deadline has nothing to say about it — and a
   * delivery the node's bound had merely delayed past that deadline would
   * otherwise be dropped on the floor rather than sent. See [`runMap`].
   */
  readonly signal: AbortSignal;
  /**
   * When [`signal`] is due to abort, as a `Date.now()` reading — present exactly
   * when the node resolved a `timeout:` (grammar 9.2, 9.3).
   *
   * The signal alone says *that* the budget will run out and never *when*, and
   * one activity has to divide the budget rather than merely observe it: a model
   * route gives each member that has a successor a share of what is left, which
   * is what makes PRD 5.9's `timeout` condition reachable for a provider that
   * answers nothing at all. See [`callModel`].
   *
   * **Read it, never keep it.** It answers the reading *at the moment of the
   * read*, because the budget it reports does not always run: a node holding a
   * `human` pause below it stops its own clock (Decision D102, and see
   * [`runActivity`]), and a value taken before the pause would hand the first
   * call after it a budget the wait had spent. Every consumer here reads it and
   * subtracts `Date.now()` in the same expression ([`requestBudget`]).
   */
  readonly deadline?: number;
  /** How this attempt is addressed, for a message. */
  readonly node: string;
  /**
   * The idempotency key this effect carries to its receiver (grammar 9.4).
   *
   * Present at exactly one kind of call: a **detached** `map` dispatch to a
   * `tool.*` — the sink of PRD 5.6, whose outcome is never observed and whose
   * delivery is therefore at-least-once. Every other call leaves it absent,
   * because grammar 9.4 fixes the carriers at two ("a detached `map` dispatch
   * and a store write") and a key on a call that is not one of them would be a
   * key a receiver dedupes on for effects that are *meant* to repeat.
   *
   * **The name is normative.** Grammar 9.4's delivery surface says a
   * `function:`-bound and a `module:`-bound target each "receive it as the
   * `idempotency_key` field of the invocation context they are called with",
   * and that context is this object ([`HostFunction`],
   * [`ModuleImplementation`]) — so this field *is* that surface for both, and is
   * spelled the way the spec spells it rather than the way the rest of this file
   * spells a name. One field for the two bindings that run in this process: a
   * call made here has a context to put a key on and needs no wire to carry it.
   * The other two carriers are named there too, and see [`runHttp`] and
   * [`runExec`] for the slot each puts it in.
   */
  readonly idempotency_key?: string;
  /**
   * Where a store op writes what it did, for this node's trace entry (PRD 5.8).
   *
   * The array is the **node execution's**, created by [`runNode`] and handed to
   * every attempt, because both surfaces of a store reach a store from inside an
   * activity and neither can return a record on its own: a store-op node answers
   * with the op's result, and an agent's synthesized store tool answers the
   * model. Reads land here because PRD 5.8 makes them recorded effects — "replay
   * consumes history, not the live store" — and writes land here because the
   * idempotency key they carried, and whether the backend had already seen it,
   * are the whole of what at-least-once delivery means at this store.
   *
   * **Absent on one context, and it is the same one [`deadline`] is absent
   * on**: a detached `map` delivery's. This array and its sibling below are
   * read the moment the join returns, and the join never waits for such a
   * delivery (D94), so a record it pushed would be on the node's entry or not
   * depending on when the sink answered. See [`runMap`], and `docs/trace.md`
   * §5.1.
   *
   * Mutable behind a `readonly` field on purpose: the field is the channel, and
   * what flows through it is appended by whoever runs an op.
   */
  readonly storeRecords?: StoreRecord[];
  /**
   * Where every model call this node makes is recorded (PRD 5.9).
   *
   * [`storeRecords`][`RunContext.storeRecords`]' sibling, and there for the same
   * reason: an activity that **throws** returns no answer, so a record that
   * travelled only on the answer would be missing from exactly the runs a reader
   * opens the trace for — a route that spent every member, or a tool loop whose
   * fourth call failed after three succeeded. Those calls really happened, and
   * PRD 5.9 asks for failover to be recorded rather than inferred from a
   * provider's own logs.
   *
   * [`callModel`] is what writes it, on both of its ways out, and [`runNode`]
   * reads it on both of *its* ways out — see [`merged`]. What arrives here
   * arrives in the order the calls were made, across every attempt the node's
   * `retry:` policy made and every instance a `map` **joined** — a detached
   * delivery is handed neither this nor its sibling above — while an answer
   * that carries `models` carries the subset it put in an order the node decided
   * (a `map`'s, which is source-item order). So the answer decides the order and
   * this decides the set.
   */
  readonly modelCalls?: ModelCall[];
  /**
   * Where a subflow a **model** invoked records its dispatch, for this node's
   * trace entry (grammar 5.4, PRD §9.20, `docs/trace.md` §5).
   *
   * The third of the same family, and it is here for the third instance of one
   * reason: a flow-as-tool call happens inside an agent's tool loop, which is
   * inside an activity, and an activity that **throws** returns no answer — so a
   * record that travelled only on the answer would be missing from exactly the
   * run a reader opens the trace for, the one whose fourth tool call failed
   * after three succeeded. Every instance a model started really ran, and its
   * trace is the only account of what it did.
   *
   * **Absent on a detached delivery's context**, with [`deadline`],
   * [`storeRecords`][`RunContext.storeRecords`] and
   * [`modelCalls`][`RunContext.modelCalls`], and for their reason: the join
   * never waits for it (Decision D94), so a record it pushed would be on the
   * node's entry or not depending on when the sink answered.
   */
  readonly toolDispatches?: DispatchRecord[];
  /**
   * Where every effect this site issues is journaled, and where a replay reads
   * one back from (PRD resolved q26–q29, `docs/durability.md`).
   *
   * Rooted at the effect **site** — the instance path of grammar 9.4 this
   * context belongs to — so the key an effect derives is the address
   * `docs/trace.md` §8 already gives it plus the effect's kind and its ordinal
   * at that site. [`runActivity`] creates one per node execution; [`runMap`]
   * hands each dispatch a child rooted at the dispatch's own path, which is what
   * keeps two items of one fan-out off each other's keys.
   *
   * Absent when nothing is journaling this execution — an ejected caller
   * driving a compiled graph directly, or a unit test — and every effect site
   * is written to work without one, which is what makes durability a property
   * of the *invocation* rather than a dependency of the graph.
   */
  readonly effects?: EffectRecorder;
}

/**
 * The context a **detached** dispatch runs its sink under: this node's, plus
 * the key grammar 8.6 rule 7 says the dispatch receives.
 *
 * Emitted at the dispatch site rather than applied to every scoped context in
 * [`runMap`], because which dispatches carry a key is a property of the *route*
 * and its target, and a compiled `graph.ts` is where a reader should be able to
 * see which of its deliveries is keyed.
 */
export function delivering(context: RunContext, site: DispatchSite): RunContext {
  return { ...context, idempotency_key: site.idempotencyKey };
}

/**
 * What an aborted signal is raised as.
 *
 * A `reason` is whatever the aborting side passed, and the one this runtime
 * passes is the node's own deadline failure — so it is re-raised as it came, and
 * anything else becomes an `Error` rather than reaching a `catch` as a string.
 */
function abortReason(signal: AbortSignal): Error {
  return signal.reason instanceof Error ? signal.reason : new Error("aborted");
}

const sleep = (ms: number, signal: AbortSignal): Promise<void> =>
  new Promise((resolve, reject) => {
    if (signal.aborted) {
      reject(abortReason(signal));
      return;
    }
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(abortReason(signal));
    };
    signal.addEventListener("abort", onAbort, { once: true });
  });

/**
 * A promise that never resolves and rejects with `signal`'s reason when it
 * aborts.
 *
 * The half of a deadline an `AbortSignal` alone cannot supply: something to
 * *race*. See [`runActivity`].
 */
function untilAborted(signal: AbortSignal): Promise<never> {
  return new Promise<never>((_, reject) => {
    const fail = () => reject(abortReason(signal));
    if (signal.aborted) {
      fail();
      return;
    }
    signal.addEventListener("abort", fail, { once: true });
  });
}

/** The delay before attempt `attempt` (1 = the first retry), per grammar 9.1. */
export function backoffFor(policy: RetryPolicy, attempt: number): number {
  const raw = policy.backoffMs * policy.multiplier ** (attempt - 1);
  const capped = policy.maxBackoffMs === undefined ? raw : Math.min(raw, policy.maxBackoffMs);
  // Full jitter: uniform over [0, capped]. The one nondeterminism in a run, and
  // it moves *when* an attempt happens, never what it answers.
  return policy.jitter ? Math.random() * capped : capped;
}

/**
 * Run one activity under its node's policy: attempts, backoff, and one deadline
 * across all of them (grammar 9.1, 9.2).
 *
 * Answers the activity's value, or throws — `on_error` is the router's to
 * apply, because `skip` and `fallback` are routing outcomes rather than values
 * (grammar 9.2, Decision D97).
 *
 * # The deadline is raced, not merely signalled
 *
 * `context.signal` is the **cooperative** half of the budget, and the activities
 * that observe it stop on time: `fetch` rejects when its signal aborts, and a
 * spawned child is killed and its promise rejected. It cannot be the whole
 * mechanism, because one activity is arbitrary caller code — a `function:`
 * binding (grammar 6.1), whether it is the node itself or a tool called inside
 * an agent's loop — and a host implementation that never looks at
 * `context.signal` would otherwise run to completion and write its result long
 * after the budget it was given. Grammar 9.2 bounds **one node execution** with
 * no exemption for a kind, so the deadline is raced against the activity: the
 * node fails on time whatever the activity does about the signal.
 *
 * What racing does not do is *stop* the work. An abandoned host function keeps
 * running to whatever it was going to do, and JavaScript offers no way to
 * unschedule it; what the node stops doing is waiting for it, and its value is
 * discarded when it arrives. That is the whole of what a timeout can mean here,
 * and the generated `README.md` says so where a host reads about registering
 * one.
 *
 * **One activity is an exception**, and it is the one where "keeps running" is a
 * whole graph rather than a call: a `flow:` node's instance, and a joined `map`
 * dispatch to a `flow.*`. An instance is a run of its own, so `context.signal`
 * is handed to it ([`Instantiation.signal`]) and LangGraph stops scheduling its
 * supersteps — leaving one abandoned activity inside it, exactly as above,
 * rather than every node the instance had left to run.
 *
 * # The budget does not run while a human is thinking
 *
 * Decision D102 withholds `timeout` from a `human` node at every level of
 * grammar 9.3's chain, so that *a composition-wide budget can never cut a wait
 * short* — but the node that **dispatches** a pause is not a `human` node and
 * resolves `defaults: { timeout: … }` like any other. Left alone, a `map` over a
 * subflow holding a `human` node would cap every one of its pauses at the
 * composition's default, which is the reading D102 exists to refuse, reached one
 * construct further out. So the deadline is *held still* for as long as a pause
 * at or under this node's instance path is open ([`pausesUnder`]): the budget
 * bounds the work this node execution does, and time spent waiting on a human is
 * not work it is doing. A node with no pause below it is unaffected — the timer
 * is armed once and never held — and the wait resumes the budget with exactly
 * the milliseconds it had left, so a `timeout: 60s` still means sixty seconds of
 * running.
 *
 * [`RunContext.deadline`] **moves with the hold**, because it is the same budget
 * seen from the other side: it answers where the armed timer is due to fire
 * while the budget runs, and `remaining` milliseconds from *now* while it is
 * held. Its consumer is a model route dividing the budget across its ladder
 * ([`callModel`], [`requestBudget`]), and an `agent` node **is** one of the
 * nodes that can have a pause below it: a `flow.*` in its `tools:` may hold a
 * `human` node (grammar 5.4, 8.7), and a model that calls it puts the wait
 * under the very node holding the timer. So the node dividing the budget and
 * the node holding it are one node, and making the two halves agree here is
 * what keeps the first model call after an hour-long pause from being refused
 * for a budget the wait spent. The other two routes to a pause — through a
 * `flow:` node or a `map` — divide no budget, so for them this is bookkeeping
 * the reader never sees.
 */
export async function runActivity<T>(
  flow: string,
  node: string,
  site: string,
  policy: NodePolicy,
  execution: RunContext["execution"],
  activity: (context: RunContext) => Promise<T>,
  storeRecords?: StoreRecord[],
  modelCalls?: ModelCall[],
  innerTraces?: TraceEntry[],
  toolDispatches?: DispatchRecord[],
): Promise<{ value: T; attempts: number }> {
  const attempts = 1 + (policy.retry?.max ?? 0);
  const controller = new AbortController();
  const budget = policy.timeoutMs;
  let expired = false;
  // What the node *did*, not what its policy allowed: a budget that ran out
  // during the second of three attempts made two, and a trace that reported
  // three would describe a run that did not happen. Declared out here because
  // the abort reason is read too — it becomes the `cause` of the failure below,
  // which a run prints under the message, and two different counts in one report
  // is worse than either.
  let made = 0;
  // The budget's remaining milliseconds and the moment the timer counting them
  // down was armed — the pair a hold needs, and the whole of the bookkeeping
  // *The budget does not run while a human is thinking* costs a node with no
  // pause below it.
  let remaining = budget ?? 0;
  let armedAt = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const arm = (): void => {
    armedAt = Date.now();
    timer = setTimeout(() => {
      timer = undefined;
      remaining = 0;
      // Re-read rather than trusted: a pause that opened in the same tick the
      // budget ran out is still a pause, and this is the only place the two can
      // be ordered.
      if (pausesUnder(execution.id, site) > 0) return;
      expired = true;
      controller.abort(new NodeTimeout(node, budget ?? 0, made));
    }, remaining);
  };
  const hold = (): void => {
    if (timer === undefined) return;
    clearTimeout(timer);
    timer = undefined;
    remaining = Math.max(0, remaining - (Date.now() - armedAt));
  };
  // The same budget the timer above is counting down, as the reading an activity
  // that *divides* it needs ([`RunContext.deadline`], [`callModel`]). Computed
  // per read rather than once: grammar 9.2's budget bounds the node execution
  // rather than an attempt, and a hold stops it — so while a pause below this
  // node is open the expiry is `remaining` from now and moves with the clock,
  // and while the timer is armed it is the instant that timer will fire.
  const deadline = (): number | undefined => {
    if (budget === undefined) return undefined;
    return timer === undefined ? Date.now() + remaining : armedAt + remaining;
  };
  const watching =
    budget === undefined
      ? undefined
      : watchHumanPauses(execution.id, () => {
          if (expired) return;
          if (pausesUnder(execution.id, site) > 0) hold();
          else if (timer === undefined) arm();
        });
  if (budget !== undefined) arm();
  // One rejection for the whole call rather than one per attempt: its listener
  // is registered before any activity starts, so it is the *first* reaction to
  // the abort and the reason a race sees is the `NodeTimeout` rather than
  // whatever the activity made of the signal. `Promise.race` attaches a handler
  // to it on every attempt, so a rejection nobody is waiting on is still a
  // handled one.
  const expiry = budget === undefined ? undefined : untilAborted(controller.signal);
  // One recorder per node **execution**, not per attempt: the ordinals a key
  // carries count every effect this site ever issues in this execution, so a
  // second attempt's model call is a second record rather than a collision with
  // the first attempt's (`docs/durability.md` §4).
  const effects = recorderFor(execution.id, site);
  // What this node execution is, to a reader asking whether the execution has
  // stopped advancing: one unit of concurrent work, in flight until the
  // `finally` below (PRD resolved q34, and see [`quiescent`]).
  const busy = working(execution.id, site);

  try {
    let last: unknown;
    for (let attempt = 1; attempt <= attempts; attempt += 1) {
      if (expired) break;
      made = attempt;
      try {
        const running = activity({
          execution,
          signal: controller.signal,
          // A getter rather than a field: the budget it reports is held still
          // while a pause below this node is open, so what a reader needs is the
          // reading at the moment it reads (see [`RunContext.deadline`]).
          get deadline(): number | undefined {
            return deadline();
          },
          node,
          ...(storeRecords === undefined ? {} : { storeRecords }),
          ...(modelCalls === undefined ? {} : { modelCalls }),
          ...(toolDispatches === undefined ? {} : { toolDispatches }),
          ...(effects === undefined ? {} : { effects }),
        });
        // The loser of the race rejects with nobody awaiting it — an activity
        // that observes the abort, after the deadline has already answered for
        // the node — and in Node an unhandled rejection ends the process. This
        // is the handler that keeps an abandoned activity from taking the run
        // down with it.
        if (expiry !== undefined) running.catch(() => {});
        const value =
          expiry === undefined ? await running : await Promise.race([running, expiry]);
        return { value, attempts: attempt };
      } catch (error) {
        last = error;
        // A `flow:` node's attempt is a whole instance, and the instance ran
        // whatever it ran before it failed: nodes, routing decisions, store
        // writes (PRD 5.3, 5.8). Its trace rides out on the [`SubflowFailure`]
        // and is the only account of that attempt — a later attempt starts a
        // *new* instance with a trace of its own, so a node that kept the last
        // one would report a run where the earlier attempt's effects never
        // happened, and the write the store deduped would have nothing in the
        // trace to have been a duplicate of. Collected here, beside
        // `storeRecords` and `modelCalls`, for exactly their reason and read by
        // [`runNode`] the same way. Every failed attempt is collected, the last
        // one included: whichever way the node leaves, this is the whole of what
        // ran inside the boundary.
        if (innerTraces !== undefined && error instanceof SubflowFailure) {
          innerTraces.push(...error.trace);
        }
        // A pause this run has no way to answer is not something the activity
        // did wrong, and it is emphatically not the retry ladder's to re-run:
        // grammar 8.5 makes a `retry:` on a `flow:` node "re-execute the
        // instance from its entry as a fresh instance", so retrying here would
        // re-issue every model call, `exec:` and store write that instance made
        // on its way to asking a question this run still cannot deliver — three
        // times over, to reach the same interrupt. Answered ahead of the policy
        // for the reason [`runNode`] answers it ahead of `on_error:`: the run's
        // own shape is not an activity outcome (see [`HumanInterrupt`]).
        if (interruptOf(error) !== undefined) {
          throw new NodeFailure(flow, node, made, describe(error), error);
        }
        // A pause the run stopped waiting for is not the ladder's either, and
        // for a stronger reason: whatever abandoned it did so because nothing is
        // reading this task's result any more (see [`abandonPausesUnder`]), so a
        // second attempt would re-open a pause under a node that has already
        // ended — parked for ever on a board no watcher is left to hold. Thrown
        // on bare rather than wrapped in a [`NodeFailure`]: by construction
        // there is nothing to report it to, which is what the class means.
        if (abandonedOf(error) !== undefined) throw error;
        // A journal that does not describe this run is not an activity outcome
        // either, and it is the one failure a `retry:` could make *worse*: every
        // attempt would consume the next ordinal at this site, so a ladder of
        // three would walk three recorded effects forward and report the last
        // disagreement rather than the first. Thrown bare, past the policy and
        // past `on_error:`, for the reason [`ReplayDivergence`] gives.
        //
        // Read off the **cause chain** rather than by class, because it travels:
        // a divergence inside a `flow:` node's instance arrives here restated as
        // a `SubflowFailure`, and one inside a dispatched item as an
        // `ItemFailure`. A check on the class alone would let exactly those two
        // be retried.
        if (divergenceOf(error) !== undefined) throw error;
        if (expired) break;
        if (attempt === attempts) break;
        // This attempt is over, so every pause it left open below it is one
        // nothing will read the answer of — the same statement the `finally`
        // below makes about the node, made one attempt at a time because the
        // next attempt **re-runs the same instance path**. A `flow:` node's
        // attempt is a whole instance and a failing branch of it is yielded as
        // soon as it settles, so a sibling branch can still be parked here; left
        // on the board its wait would share an id with the one the next attempt
        // opens at that path, and a live question would be marked expired by a
        // dead attempt's timer with the task holding it parked for ever. It is
        // also what gives back the `map` permits and store handles the parked
        // instance is holding, before the next attempt queues for them.
        abandonPausesUnder(execution.id, site);
        const delay = backoffFor(policy.retry!, attempt);
        try {
          await sleep(delay, controller.signal);
        } catch {
          break;
        }
      }
    }
    if (expired) {
      throw new NodeFailure(
        flow,
        node,
        made,
        new NodeTimeout(node, budget ?? 0, made).message,
        last,
      );
    }
    throw new NodeFailure(flow, node, made, describe(last), last);
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    watching?.();
    // However this node execution ended, it has ended — so a pause still open
    // below it is one nothing will ever read the answer of, and leaving it on
    // the board would publish a question to a human whose answer is thrown away
    // (see [`abandonPausesUnder`]). Reached by a deadline that ran out in the
    // tick a pause was opening: every other way one node execution ends is one
    // where the instance below it had already finished.
    abandonPausesUnder(execution.id, site);
    // …and the work is no longer in flight, which is announced **after** the
    // pauses are abandoned so that a reader woken by it sees the board this
    // node execution left rather than the one it was holding.
    busy();
  }
}

function describe(error: unknown): string {
  if (error instanceof Error) return `${error.name}: ${error.message}`;
  return String(error);
}

// ---------------------------------------------------------------------------
// Providers and models
// ---------------------------------------------------------------------------

/**
 * Every `kind:` grammar 12.1 admits — including the two this runtime cannot
 * call.
 *
 * Four of them speak an HTTP surface. `bedrock` and `vertex` are reached
 * through a cloud SDK, which is why grammar 12.1's rows give them neither
 * `base_url:` nor `headers:`: there is no bare endpoint to point at. They are
 * here because the type has to describe every binding the compiler emits — a
 * composition declaring one is valid, and `build` writes its project — and
 * [`callModel`] is where the gap is reported, once, in the run that reached it.
 */
export type ProviderKind =
  | "anthropic"
  | "openai"
  | "openai_compatible"
  | "azure_openai"
  | "bedrock"
  | "vertex";

/**
 * One entry of a provider's `server_tools:` — a tool the **provider** runs, on
 * its own side, inside the model call (grammar 12.1, Decision D122).
 *
 * Written in that provider's own wire vocabulary and appended verbatim to the
 * `tools` of every request the provider serves. Nothing here is dispatched by
 * this runtime: a server tool's results arrive woven into the assistant's turn,
 * which is why the type is an open record rather than anything with an
 * `invoke`. `type` is the only key the compiler reads.
 */
export interface ServerToolConfig {
  readonly type: string;
  readonly [key: string]: unknown;
}

/** A resolved `provider.*` (grammar 12.1). Values are read when a node runs. */
export interface ProviderBinding {
  readonly address: string;
  readonly kind: ProviderKind;
  /**
   * `api_key:`, where the composition declared one. **Absent** is a connection
   * through a gateway that injects the vendor credential itself (grammar 12.1,
   * Decision D120), and [`credential`] sends no authentication header for it —
   * so this stays optional rather than being defaulted to `""` anywhere.
   */
  readonly apiKey?: string;
  readonly baseUrl?: string;
  readonly apiVersion?: string;
  readonly organization?: string;
  readonly headers?: Readonly<Record<string, string>>;
  /**
   * `server_tools:`, where the composition declared any (Decision D122).
   *
   * **Absent** and **empty** are the same thing on the wire and are kept apart
   * anyway: the emitter omits the key entirely for a provider that declares no
   * suite, so a binding carrying `[]` is one whose array was emptied rather than
   * one that never had it — and on an `openai` provider that distinction is
   * load-bearing, since declaring a suite is what moves the connection onto the
   * Responses wire ([`speaksResponses`]).
   */
  readonly serverTools?: readonly ServerToolConfig[];
}

/**
 * Whether this connection speaks OpenAI's **Responses** API rather than Chat
 * Completions (Decision D122).
 *
 * All-or-nothing per provider, and that is the seam an author meets: the
 * built-in tool suite — web search, file search, code interpreter, image
 * generation — is a Responses-API surface that Chat Completions does not carry,
 * so an `openai` provider that declares `server_tools:` issues **every** one of
 * its calls to `/v1/responses`, and one that declares none keeps Chat
 * Completions exactly as before. One provider, one wire: a connection that
 * switched per request would make "what did this model see" depend on which
 * agent asked.
 *
 * `openai_compatible` is deliberately not here. A gateway's suite rides its
 * Chat Completions `tools` array verbatim — many honour one — and moving a
 * gateway onto a wire it may not implement at all would break the compositions
 * that work today.
 */
function speaksResponses(provider: ProviderBinding): boolean {
  return provider.kind === "openai" && (provider.serverTools ?? []).length > 0;
}

/** A resolved `model.*` in its direct form (grammar 12.2). */
export interface ModelBinding {
  readonly address: string;
  readonly id: string;
  readonly provider: ProviderBinding;
  readonly settings: Readonly<Record<string, unknown>>;
}

/**
 * A `model.*` in its **route** form: an ordered failover ladder (grammar 12.2,
 * PRD 5.9).
 *
 * Members are direct bindings — grammar 12.2 forbids a nested route, which is
 * what keeps "served by `model.fast`, fallback #1" a flat, unambiguous ordinal
 * (Decision D39). `routeOn` is non-empty for the same reason `route_on: []` is a
 * compile error: a route that never fails over is a direct model.
 */
export interface ModelRoute {
  readonly address: string;
  readonly route: readonly ModelBinding[];
  readonly routeOn: readonly RouteCondition[];
}

/** What an agent's `model:` resolves to: one binding, or a ladder. */
export type ModelSelection = ModelBinding | ModelRoute;

/** Grammar 12.2's `route_on:` vocabulary — infrastructure conditions only. */
export type RouteCondition = "rate_limit" | "overloaded" | "timeout" | "server_error";

/** Whether this selection is the route form. */
function isRoute(selection: ModelSelection): selection is ModelRoute {
  return Array.isArray((selection as ModelRoute).route);
}

/** The ladder a selection is tried in: a route's members, or the one binding. */
function ladder(selection: ModelSelection): readonly ModelBinding[] {
  return isRoute(selection) ? selection.route : [selection];
}

/**
 * One member's refusal, as the trace records it.
 *
 * The condition is present when the refusal classifies as one of grammar 12.2's
 * ([`classify`]) and absent when it does not — a 400, a body that is not JSON.
 * A refusal that ends a call can be either; a refusal that moved the ladder on
 * is always the first, which is what [`Failover`] narrows.
 */
export interface Refusal {
  /** The member that refused. */
  readonly model: string;
  /** Which of grammar 12.2's conditions it refused with, when it is one. */
  readonly condition?: RouteCondition;
  /** What it said, for a reader who has to fix it. */
  readonly detail: string;
}

/**
 * A refusal that moved the ladder on.
 *
 * The condition is what `route_on:` is written in, so a reader can see both that
 * the failover happened and that the composition asked for it — a failover is by
 * definition a refusal the route declared, so here the condition is never
 * absent.
 */
export interface Failover extends Refusal {
  readonly condition: RouteCondition;
}

/**
 * What one model call did, as the trace records it (PRD 5.9).
 *
 * PRD 5.9 asks for failover to be "deterministic runtime behavior recorded in
 * the trace (`served by model.fast, fallback #1`)", and this is that record:
 * the `model.*` the agent named, the member that answered, its ordinal in the
 * route — `0` for the first member, so a `fallback` of `1` reads as "fallback
 * #1" — and every member that refused on the way, with the condition it refused
 * with.
 *
 * A direct binding produces one too, with `model === servedBy`, `fallback: 0`
 * and an **empty** `failovers` — the key is there holding nothing, which is a
 * different record from one that omits it, and no record omits it. A trace that
 * kept only the interesting calls would leave a reader unable to tell a call
 * that did not fail over apart from a call nothing recorded at all.
 *
 * **A call nothing answered is recorded too**, and it is the one a reader most
 * often opens a trace for: a route that spent every member made a real call to
 * each, and the failover that happened on the way is exactly the data PRD 5.9
 * asks to be recorded rather than inferred. Such a record carries no `servedBy`
 * and no `fallback` — nothing served it — and names the refusal that ended it in
 * `refused`.
 */
export interface ModelCall {
  readonly model: string;
  /** The member that answered. Absent when none did. */
  readonly servedBy?: string;
  /** Its ordinal in the route, `0` for the first. Present with `servedBy`. */
  readonly fallback?: number;
  /**
   * Every member that refused and moved the ladder on, in the order they were
   * tried. On every record, and **empty** where none did — a direct binding's,
   * and a route whose first member answered.
   */
  readonly failovers: readonly Failover[];
  /** What ended the call, when no member answered it. */
  readonly refused?: Refusal;
  /**
   * What this call's answer asked the agent's tools to do, one record per tool
   * call the loop ran (`docs/trace.md` §7.3, PRD §9.20).
   *
   * The one field of this record the *loop* writes rather than [`callModel`],
   * and therefore the one that is not `readonly`: a tool call is run after its
   * answer has come back, so there is nothing to put here at the moment the
   * record is made. The array is the loop's channel into the record of the call
   * that asked for them, and it holds the very objects the loop is filling in —
   * so a call that ends the node still reports the tool call that ended it, by
   * the same identity [`merged`] relies on.
   *
   * Because it is written late it is also the one field an **entry** must not
   * hold live, which [`settled`] is for: an entry copies it at the moment it is
   * built, and drops it where the loop has recorded nothing yet.
   */
  toolCalls?: ToolCallRecord[];
}

/**
 * One tool call an agent's loop ran, on [`ModelCall.toolCalls`].
 *
 * PRD §9.20 asks the tool loop's story to be complete inside the `ModelCall` at
 * the cost of one indirection: what the model asked for, what came of it, the
 * result the model saw, and — for a `flow.*` attached as a tool (grammar 5.4) —
 * a **link** to the instance that answered it. The instance's own trace is not
 * here; it is on the [`DispatchRecord`] this call filed, which [`instance`]
 * names.
 */
export interface ToolCallRecord {
  /** The name the model called, as the request offered it. */
  readonly name: string;
  /**
   * The component behind that name, as a typed address (grammar 2.2). Absent on
   * the one call with no component behind it: a name the agent does not offer,
   * which since Decision D119 is a call the model is asked to make again.
   */
  readonly target?: string;
  /**
   * What the loop did with the call (Decision D119, `docs/trace.md` §7.3):
   *
   *  * `"completed"` — it ran, and the model was handed its result;
   *  * `"refused"` — the contract did not admit it, and the model was handed the
   *    refusal instead: arguments a schema refused, or a name the agent never
   *    offered. The loop carried on, so records **after** one of these exist;
   *  * `"failed"` — the tool's execution failed, which left the tool and **ended
   *    the node**; the model saw nothing back and the node's own `on_error:`
   *    decided the run (grammar 9.2).
   */
  readonly outcome: "completed" | "refused" | "failed";
  /**
   * The child instance this call ran, as the dispatch record carrying its trace
   * spells itself in `idempotencyKey` — so the link is string equality.
   *
   * Read off the record the call filed rather than derived a second time, which
   * is what makes the two unable to disagree.
   */
  readonly instance?: string;
  /**
   * **The result the model saw** — PRD §9.20's third clause, and the one field
   * of this record whose value came from outside the loop.
   *
   * On a **subset** of the calls [`instance`] is on: a flow-as-tool call that
   * ran an instance *and completed*, whose result is that instance's declared
   * `outputs:` — the composition's own data, under a schema the composition
   * wrote (grammar 5.4). A call carrying this carries [`instance`]; the reverse
   * does not hold. What the two share is one account: `docs/trace.md` §11 keeps
   * a tool's *answer* out of this format at every other surface, and PRD §9.20
   * is what carves this one out — "a bare dispatch record alone would leave a
   * tool call whose result came from nowhere".
   *
   * Absent on a call that **failed** or was **refused**, and that absence is the
   * record: a failure left the tool and a refusal never entered it, so in
   * neither case did the model see a result. A call whose instance failed is
   * exactly that — an [`instance`] with no result beside it — and a refused one
   * carries neither.
   */
  readonly result?: unknown;
  /**
   * What went wrong, in `docs/trace.md` §3's `<error name>: <message>` shape —
   * on a `"failed"` call and on a `"refused"` one, where the `<message>` half is
   * byte for byte the sentence the model was handed back and the `<error name>`
   * half is `ToolCallRefused`, the envelope this format adds and the model's
   * copy does not carry. The two differ by that prefix and by nothing else
   * (Decision D119, [`ToolCallRefused`]).
   */
  readonly error?: string;
  /**
   * **What the model ran**, on a call to a built-in tool (`docs/trace.md` §7.4,
   * PRD resolved q54 ruling c).
   *
   * The one carve-out from §11's rule that this format carries no tool's
   * arguments, and it is the tool whose arguments *are* the program: every other
   * binding runs what the composition wrote, which a reader already has, while a
   * built-in runs what the model wrote at run time. Present on every call that
   * reached a built-in — completed, failed, or refused by the tool itself — and
   * absent everywhere else, including on a built-in call the loop refused before
   * it (a schema the arguments failed), which never reached the tool.
   */
  readonly program?: BuiltinProgram;
}

/**
 * Which of grammar 12.2's conditions a failure is, or `undefined` when it is
 * none of them.
 *
 * The classification is the whole of what `route_on:` selects over, so it is
 * stated once, here:
 *
 * | what happened | condition |
 * |---|---|
 * | HTTP 429 | `rate_limit` |
 * | HTTP 503, HTTP 529 | `overloaded` — the two spellings of an overloaded provider (Anthropic answers 529, the OpenAI surface 503) |
 * | any other 5xx | `server_error` |
 * | no answer at all: a dropped connection, a refused socket, a name that did not resolve | `timeout` |
 * | no answer *yet*: the request outlived the budget this call was given ([`callModel`]) | `timeout` |
 * | anything else — a 4xx that is not 429, a body that is not JSON | **not a condition** |
 *
 * A failure that is not a condition, and a condition the route did not declare,
 * both fail the node rather than moving to the next member: `route_on:` is a
 * declaration, and a runtime that failed over on everything would make it mean
 * nothing.
 */
export function classify(error: unknown): RouteCondition | undefined {
  if (error instanceof ProviderUnreachable || error instanceof ProviderTimeout) return "timeout";
  if (!(error instanceof ProviderFailure)) return undefined;
  if (error.status === 429) return "rate_limit";
  if (error.status === 503 || error.status === 529) return "overloaded";
  if (error.status >= 500 && error.status <= 599) return "server_error";
  return undefined;
}

/** A JSON Schema, as `codegen::schema`'s JSON column publishes it. */
export type JsonSchema = Readonly<Record<string, unknown>>;

/** One tool as a provider is told about it. */
export interface ToolSpec {
  readonly name: string;
  readonly description: string;
  readonly schema: JsonSchema;
  /**
   * The **provider-defined tool type** this tool goes out as on the Messages
   * wire, where it has one (grammar 6.1, PRD resolved q54 ruling d).
   *
   * Present on the two built-ins and on nothing else. Anthropic ships `bash` and
   * the text editor as *its own* tool types — `{"type": "bash_20250124", "name":
   * "bash"}` — and a model is trained against the type rather than against a
   * schema somebody wrote, so declaring them that way is what engages the
   * behaviour the tools exist for. The type is dated because it versions: it is
   * a fact of the wire, so the compiler writes it here (`codegen::graph`'s
   * `BUILTIN_WIRE_TYPES`) rather than this runtime pinning a date of its own.
   *
   * The other two wires have no such thing and take [`schema`] as an ordinary
   * function tool, which is why every built-in has one either way: the same
   * arguments under the same names, so the same handlers serve every wire.
   */
  readonly providerType?: string;
}

/** One turn of the conversation, in a shape both surfaces can render. */
export type Turn =
  | { readonly role: "user"; readonly text: string }
  | {
      readonly role: "assistant";
      readonly text?: string;
      readonly toolCalls?: readonly { id: string; name: string; args: unknown }[];
      /**
       * The content blocks the model itself sent, when this turn is one being
       * replayed to the surface that produced it (see [`ModelAnswer.content`]).
       * Present, they are the turn: `text` and `toolCalls` are a *reading* of an
       * answer and a replay must be the answer.
       */
      readonly blocks?: readonly unknown[];
      /**
       * Which wire's vocabulary [`blocks`] is written in (see [`ContentWire`]).
       */
      readonly wire?: ContentWire;
    }
  | {
      readonly role: "tool";
      /**
       * One entry per call the answer being replied to asked for, in that order.
       *
       * `isError` marks the ones the loop **refused** (Decision D119): the
       * content is the refusal rather than a result, and each surface says so
       * its own way — the Messages API with `is_error: true` on the
       * `tool_result` block, Chat Completions with nothing, because a `tool`
       * role message carries no such flag and the text is the whole of what it
       * has (`WIRE-NOTES` (18)).
       *
       * `name` is carried for the one refusal that is not about arguments: a
       * call to a tool the agent never offered. Chat Completions refuses a
       * request whose history names an undeclared function, so
       * [`callChatCompletions`] reads this to tell the results it may answer as
       * `tool` messages from the one it has to carry another way.
       */
      readonly results: readonly {
        id: string;
        name: string;
        content: string;
        isError?: boolean;
      }[];
    };

/**
 * Which wire's vocabulary a replayed assistant turn's blocks are written in.
 *
 * Two surfaces send an answer as a list of objects and each takes back **its
 * own** list: the Messages wire's `text`/`tool_use`/`thinking` blocks and the
 * Responses wire's `message`/`function_call`/`reasoning`/`*_call` items are
 * disjoint vocabularies, and either one sent to the other is a 400 naming a
 * type that surface has never heard of. A route may cross the two — each member
 * of a ladder speaks its own provider's wire (Decision D122) — so a turn one
 * member answered can be replayed to another, and the reader has to be able to
 * tell whether the blocks in hand are its own. Where they are not, the turn is
 * rebuilt from the `text` and `toolCalls` read out of them, which is what every
 * wire can render.
 *
 * **Absent is `"messages"`,** and that is load-bearing rather than terse: a
 * `Turn` is part of a journaled model call's request identity ([`callModel`]),
 * so a key written onto every Messages turn would re-key every journal recorded
 * before this wire existed. The Messages wire was the only one that ever
 * produced blocks, so leaving its turns untagged keeps those identities exactly
 * as they were and `JOURNAL_VERSION` where it is (`docs/durability.md` §11.2).
 */
export type ContentWire = "messages" | "responses";

/** What a model answered. */
export interface ModelAnswer {
  readonly text: string | null;
  readonly toolCalls: readonly { id: string; name: string; args: unknown }[];
  readonly structured: unknown | null;
  readonly stopReason: string | null;
  /**
   * The answer's own content blocks, on a surface that sends them.
   *
   * A tool loop replays its assistant turns, and a turn rebuilt from `text` and
   * `toolCalls` is not the turn the model sent: the Messages API also answers
   * with `thinking` blocks — which a model with `settings: { thinking: … }`
   * sends as a matter of course, and which it requires back unaltered beside the
   * `tool_use` blocks they preceded. So the loop replays these when they are
   * here, and only falls back to the reading when they are not (Chat
   * Completions, whose answer is a message rather than a block list).
   */
  readonly content?: readonly unknown[];
  /**
   * Which wire wrote `content`, where that is not the Messages wire
   * ([`ContentWire`]).
   */
  readonly wire?: ContentWire;
  /**
   * The reason the model gave for declining, on a surface that states one.
   *
   * Chat Completions answers a refusal with `content: null` and a `refusal`
   * string, which is otherwise indistinguishable from an answer cut short by
   * `max_tokens` — both arrive as no structured output. Carrying it lets the
   * node error say which happened.
   */
  readonly refusal?: string | null;
}

/**
 * The `max_tokens` an Anthropic request carries when the model declares none.
 *
 * The Messages API requires the key (`WIRE-NOTES` (8)), and grammar 12.2 puts
 * the knob in `settings:` where an author sets it — so this is the value a
 * composition that did not is given, not a policy.
 */
const ANTHROPIC_MAX_TOKENS = 4096;

/**
 * Whether OpenAI's structured-output decoder can be asked to close this schema.
 *
 * `strict: true` is a promise the *service* checks: every object closed with
 * `additionalProperties: false`, and every declared property listed in
 * `required`, all the way down (`WIRE-NOTES` (13)). A schema that breaks either
 * is answered 400 rather than decoded loosely, so asking for it here would make
 * a legal composition unrunnable.
 *
 * Answering `false` is not free, and what it costs is written down rather than
 * discovered: under `strict: false` the decoder is not constrained by the schema
 * at all, so the model can answer something the emitted Zod then refuses — the
 * one property PRD 9.16 makes structured output load-bearing for. The
 * compiler's `codegen::runtime` module records that as
 * `strict-is-refused-by-an-optional-property`, with the alternatives and why
 * each is worse. The reachable way in is `optional:` on an object nested in an
 * agent's `output:`; the contract then lives in the parse, which runs over the
 * same schema either way.
 */
function strictable(schema: unknown): boolean {
  if (typeof schema !== "object" || schema === null) return true;
  const object = schema as Record<string, unknown>;
  if (object["type"] === "object") {
    if (object["additionalProperties"] !== false) return false;
    const properties = (object["properties"] ?? {}) as Record<string, unknown>;
    const required = (object["required"] ?? []) as unknown[];
    for (const name of Object.keys(properties)) {
      if (!required.includes(name)) return false;
    }
  }
  for (const value of Object.values(object)) {
    if (Array.isArray(value)) {
      if (!value.every(strictable)) return false;
    } else if (!strictable(value)) {
      return false;
    }
  }
  return true;
}

function baseUrl(provider: ProviderBinding): string {
  if (provider.baseUrl !== undefined) return provider.baseUrl.replace(/\/+$/, "");
  if (provider.kind === "anthropic") return "https://api.anthropic.com";
  if (provider.kind === "openai") return "https://api.openai.com";
  // `openai_compatible` and `azure_openai` require `base_url:` (grammar 12.1),
  // so reaching this is a binding that lost one between the spec and the
  // process — not an author who forgot to declare it.
  throw new Error(
    `\`${provider.address}\` is \`kind: ${provider.kind}\` and reached the wire with no \`base_url:\``,
  );
}

/**
 * The authentication header one connection sends — or **no header at all**.
 *
 * A provider that declares no `api_key:` declared a `base_url:` instead
 * (grammar 12.1, Decision D120): it points at a gateway that injects the vendor
 * credential server-side, so the request this runtime sends must carry none.
 * The header is *dropped*, not emptied. `x-api-key: ""` and
 * `authorization: Bearer ` are requests that claim to authenticate and fail — a
 * gateway is entitled to refuse one before injecting anything, and a gateway
 * that forwards headers verbatim turns it into a 401 at the vendor, which is
 * the one failure the keyless deployment was configured to avoid.
 *
 * `spelling` belongs to the **wire**, not to the kind: the Messages API reads
 * `x-api-key`, Chat Completions a bearer `authorization`, and Azure its own
 * `api-key` — whose `api_key:` grammar 12.1 still requires, so that branch
 * always has a key to send. Whatever a provider's `headers:` declares wins over
 * this, since `send` composes it as a later layer: a gateway wanting a token of
 * its own is a declared header rather than a vendor credential.
 */
function credential(
  provider: ProviderBinding,
  spelling: "x-api-key" | "authorization" | "api-key",
): Record<string, string> {
  const key = provider.apiKey;
  if (key === undefined) return {};
  return { [spelling]: spelling === "authorization" ? `Bearer ${key}` : key };
}

/**
 * One header set out of the layers that compose it, later layers winning.
 *
 * Header names are **case-insensitive** (grammar 6.1, 12.1) and `fetch` is not:
 * it builds its `Headers` by *appending* each key of the object it is handed, so
 * `Content-Type` beside `content-type` reaches the server as one header carrying
 * both values joined by a comma — two media types in the field an API dispatches
 * on. Folding the name is what makes a declared header replace the one this
 * runtime would have sent rather than join it; the spelling that won is the one
 * that goes out, because a server is entitled to read the name it was sent.
 */
function headerSet(
  ...layers: readonly (Readonly<Record<string, string>> | undefined)[]
): Record<string, string> {
  const folded = new Map<string, [string, string]>();
  for (const layer of layers) {
    for (const [name, value] of Object.entries(layer ?? {})) {
      folded.set(name.toLowerCase(), [name, value]);
    }
  }
  return Object.fromEntries(folded.values());
}

async function send(
  model: ModelBinding,
  url: string,
  headers: Record<string, string>,
  body: unknown,
  signal: AbortSignal,
): Promise<Record<string, unknown>> {
  // Parsed here rather than left to `fetch`, which quotes what it could not
  // parse: Node answers a malformed endpoint with `Failed to parse URL from
  // <the resolved string>`. That string is built from the provider's
  // `base_url:`, which grammar 4.3 class 1 makes a whole-value `${ENV}`
  // reference — a connection string, and one `docs/trace.md` §11.1 keeps out of
  // `Refusal.detail` and `TraceEntry.error`. So the provider is named and the
  // value is not. Raised as a [`ProviderUnreachable`] because that is what a
  // `fetch` refusing this URL already produced: only the message changes.
  let endpoint: URL;
  try {
    endpoint = new URL(url);
  } catch {
    throw new ProviderUnreachable(
      model.address,
      new Error(`\`${model.provider.address}\`'s resolved \`base_url:\` is not a URL`),
    );
  }
  // The type is spelled from `fetch` itself rather than as `Response`: the
  // global type comes from the runtime's own library types, and naming it here
  // would tie this module to one of them.
  let response: Awaited<ReturnType<typeof fetch>>;
  let text: string;
  try {
    response = await fetch(endpoint, {
      method: "POST",
      headers: headerSet({ "content-type": "application/json" }, headers, model.provider.headers),
      body: JSON.stringify(body),
      signal,
    });
    text = await response.text();
  } catch (error) {
    // A deadline reaches here as an abort rather than as a socket failure, and
    // it is not the provider's failure to answer — so it is raised as it came
    // and [`callModel`] decides which deadline it was: the node's own budget
    // (grammar 9.2), which ends the node, or this call's share of it, which is
    // PRD 5.9's `timeout` and moves the ladder on.
    if (signal.aborted) throw error;
    throw new ProviderUnreachable(model.address, error);
  }
  if (!response.ok) {
    throw new ProviderFailure(model.address, response.status, text);
  }
  return JSON.parse(text) as Record<string, unknown>;
}

/** What one model call answered, and which member of its route answered it. */
export interface ModelResult {
  readonly answer: ModelAnswer;
  readonly served: ModelCall;
}

/**
 * One model call: the failover ladder, then the surface the answering member's
 * provider kind reaches (PRD 5.9, grammar 12.2).
 *
 * A direct binding is a ladder of one, so there is a single path through here
 * and a single shape of record out of it. Each member is tried in **declaration
 * order** — the order is the composition's, and a route that reordered itself
 * would not be deterministic — and a member that refuses moves the call on
 * exactly when two things hold: the failure classifies as one of grammar 12.2's
 * conditions ([`classify`]), and that condition is in this route's `route_on:`.
 * Anything else is raised, which is what makes `route_on:` a declaration rather
 * than a description.
 *
 * The **last** member is not special-cased: when it refuses, its own error is
 * what the node sees, with the earlier refusals in the message so a reader is
 * not left wondering why one 429 ended a two-member route.
 *
 * # What `route_on: [timeout]` is measured against
 *
 * Three of grammar 12.2's four conditions are things a provider *says*. The
 * fourth is a thing it does not say: PRD 5.9's `timeout` is the call that never
 * comes back. A refused socket reports itself and reaches [`classify`] as a
 * [`ProviderUnreachable`], but a provider that accepted the request and holds it
 * reports nothing at all, so a ladder with no clock of its own would sit on the
 * first member until the **node's** deadline ended the node — with a declared
 * fallback never tried, which is the one outcome `route_on: [timeout]` is
 * written to prevent.
 *
 * So each member that has a successor is given a **share of what is left of the
 * node's budget**: `remaining / membersLeft`, taken when that member starts, and
 * a member that does not answer inside its share fails over as a `timeout`
 * ([`ProviderTimeout`]). Three properties make that the share rather than a
 * number this runtime chose:
 *
 *  * it is a **division** of grammar 9.2's budget and never an extension of it —
 *    the last member gets whatever remains and is bounded by the node's own
 *    deadline, so the ladder cannot outlive the node;
 *  * it is taken **only** when the route declares `timeout`, because a route
 *    that did not is a route that wants its member to keep waiting;
 *  * a **direct binding** is a ladder of one and is never sliced, so nothing
 *    about a single-model composition changes.
 *
 * And a node with **no** `timeout:` has no budget to divide: grammar 9.3's
 * built-in level is "no timeout", so there is no wall-clock bound to measure a
 * provider's silence against, and a member that never answers is a node that
 * never finishes — exactly as it is for a direct binding. A composition that
 * wants `route_on: [timeout]` to fire has to say by when, which is what
 * `timeout:` is; the emitted `README.md` says so where a reader meets the key.
 */
export async function callModel(
  selection: ModelSelection,
  request: {
    readonly system: string;
    readonly turns: readonly Turn[];
    readonly tools: readonly ToolSpec[];
    readonly pinned?: ToolSpec;
  },
  site: ModelSite,
): Promise<ModelResult> {
  const recorder = site.effects;
  if (recorder === undefined) return await callModelLive(selection, request, site);

  // The identity of *this* call, which a recorded answer has to match: which
  // `model.*` was asked, what it was asked, and which tools it was offered.
  // The conversation is in it because it is what a ladder answered — a replay
  // whose second call carries a different history is a different call, and
  // handing it the first generation's answer would be exactly the silent
  // re-keying resolved q29 refuses.
  //
  // The **server** tools are in it for the same reason the client ones are: a
  // provider's suite is part of what the model was offered, and a resume whose
  // provider gained or lost one is a resume of a different call — so it
  // diverges at the first model call rather than replaying an answer produced
  // under another tool surface (`docs/durability.md` §3.1, §7, Decision D122).
  //
  // Per **ladder member**, because that is the granularity the suite has: each
  // provider in a route declares its own array, so which tools were on offer
  // depends on which member served the call. And the key is **omitted
  // entirely** where no member declares one, which is what keeps every
  // composition that predates the key deriving the identity it already derived
  // — an older journal still replays, and `JOURNAL_VERSION` does not move
  // (`docs/durability.md` §11.2, §11.3).
  const suites = ladder(selection).map((member) => member.provider.serverTools ?? []);
  const slot = recorder.claim("model", {
    model: selection.address,
    system: request.system,
    turns: request.turns,
    tools: request.tools.map((tool) => tool.name),
    ...(request.pinned === undefined ? {} : { pinned: request.pinned.name }),
    ...(suites.some((suite) => suite.length > 0) ? { serverTools: suites } : {}),
  });

  if (slot.held !== undefined) {
    // A recorded model call is replayed **whole**: the answer the loop accepted,
    // and every `ModelCall` record the ladder filed on the way to it — the
    // failovers a route spent, and the refusal that ended a call that answered
    // nothing. Without the records the resumed generation's trace would say a
    // node called no model at all (`docs/trace.md` §7.2). A call is always kept
    // as a *value*, whichever way it went, so the error arm is unreachable and
    // is answered rather than assumed away.
    if (slot.held.kind === "error") throw replayedFailure(slot.held);
    const held = slot.held.value as JournaledCall;
    for (const call of held.calls) site.modelCalls?.push(call);
    if (!held.ok) throw replayedFailure({ kind: "error", ...held.error });
    // Which member answered, off the record's own field — and off the tail of
    // `calls` where there is one, because those are the objects just pushed into
    // the node's channel and the trace reconciles the two lists by **identity**
    // ([`merged`]). The field is what makes the empty case answerable: `calls`
    // is the *node execution's* collector, and a detached `map` delivery has
    // none by construction (D94, and see [`runMap`]) — so its record holds an
    // empty list, and a `served` inferred from that tail would fail a resume of
    // a composition nobody had touched.
    const served = held.calls[held.calls.length - 1] ?? held.served;
    if (served === undefined) {
      throw new ReplayDivergence(
        slot,
        "the journal recorded an answer with no record of which model served it",
      );
    }
    return { answer: held.answer, served };
  }

  const before = site.modelCalls?.length ?? 0;
  const filed = (): ModelCall[] => (site.modelCalls ?? []).slice(before);
  try {
    const result = await callModelLive(selection, request, site);
    // The **kept** answer rather than the live one, which is the same statement
    // the replay arm above makes and has to be: a model answer is the value that
    // most often reaches a later effect's request identity — an agent's next turn
    // carries it verbatim — so a generation that went on with a differently
    // ordered copy of it would be reported as divergent by its own successor
    // (`docs/durability.md` §11.1).
    const kept = slot.keep({
      ok: true,
      answer: result.answer,
      served: result.served,
      calls: filed(),
    } satisfies JournaledCall) as Extract<JournaledCall, { ok: true }>;
    return { answer: kept.answer, served: result.served };
  } catch (error) {
    // Kept as a **value** rather than through the slot's error path, because a
    // spent ladder is more than its message: the records it filed are what a
    // reader of the failed node's entry reads, and they have to survive into
    // the resumed generation's trace with it.
    slot.keep({
      ok: false,
      error: { name: nameOf(error), message: messageOf(error) },
      calls: filed(),
    } satisfies JournaledCall);
    throw error;
  }
}

/**
 * One model call as the journal keeps it (see [`callModel`]).
 *
 * `served` is the member of the route that answered, and `calls` is what the
 * ladder filed on the node's own trace channel on the way there. They overlap
 * wherever there *is* such a channel — the last of `calls` is this same call —
 * and the reason both are here is the case where there is not: a detached `map`
 * delivery runs with the node's collectors detached (D94), so `calls` is empty
 * and `served` is the only account of who answered. It is optional because a
 * record written before this field existed has none, which
 * `docs/durability.md` §11.2 makes a compatible reading rather than a bump.
 */
type JournaledCall =
  | {
      readonly ok: true;
      readonly answer: ModelAnswer;
      readonly served?: ModelCall;
      readonly calls: ModelCall[];
    }
  | {
      readonly ok: false;
      readonly error: { readonly name: string; readonly message: string };
      readonly calls: ModelCall[];
    };

/** An error's class name, as `describe` reads it. */
function nameOf(error: unknown): string {
  return error instanceof Error ? error.name : "Error";
}

/** An error's message, as `describe` reads it. */
function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** [`callModel`] with nothing between it and the provider. */
async function callModelLive(
  selection: ModelSelection,
  request: {
    readonly system: string;
    readonly turns: readonly Turn[];
    readonly tools: readonly ToolSpec[];
    readonly pinned?: ToolSpec;
  },
  site: ModelSite,
): Promise<ModelResult> {
  const members = ladder(selection);
  const routeOn: readonly RouteCondition[] = isRoute(selection) ? selection.routeOn : [];
  const failovers: Failover[] = [];

  for (let ordinal = 0; ordinal < members.length; ordinal += 1) {
    const model = members[ordinal]!;
    const share = requestBudget(site, routeOn, members.length - ordinal);
    const bound = share === undefined ? undefined : bounded(site.signal, share);
    try {
      const answer = await callDirect(model, request, bound?.signal ?? site.signal);
      const served: ModelCall = {
        model: selection.address,
        servedBy: model.address,
        fallback: ordinal,
        failovers: [...failovers],
      };
      site.modelCalls?.push(served);
      return { answer, served };
    } catch (raised) {
      // The node's own deadline wins: it ends the node, and a call abandoned by
      // it is not a provider that took too long. Only this call's own share
      // becomes a condition the ladder acts on.
      const error =
        bound?.expired() === true && !site.signal.aborted
          ? new ProviderTimeout(model.address, share!)
          : raised;
      const condition = classify(error);
      const last = ordinal + 1 === members.length;
      if (condition === undefined || !routeOn.includes(condition) || last) {
        // The call is recorded before it is raised: what a spent ladder did is
        // the record a reader of a *failed* run needs, and a record that left
        // only on the answer would never reach one (PRD 5.9).
        site.modelCalls?.push({
          model: selection.address,
          failovers: [...failovers],
          refused: {
            model: model.address,
            ...(condition === undefined ? {} : { condition }),
            detail: describe(error),
          },
        });
        throw failoverContext(selection, failovers, error);
      }
      failovers.push({ model: model.address, condition, detail: describe(error) });
    } finally {
      bound?.release();
    }
  }
  // Unreachable: grammar 12.2 requires at least two members on a route and a
  // direct binding is a ladder of one, so the loop always answers or throws.
  throw new Error(`\`${selection.address}\` has no route member to call`);
}

/**
 * What one model call is bounded by, and where its record goes.
 *
 * A [`RunContext`] is one, structurally: the call's clock is the node's clock
 * ([`RunContext.signal`], [`RunContext.deadline`]) and its record belongs on the
 * node's trace entry ([`RunContext.modelCalls`]). Stated as its own interface so
 * this function asks for what it uses.
 */
export interface ModelSite {
  /** Aborted when the node's `timeout:` budget runs out. */
  readonly signal: AbortSignal;
  /** That budget's expiry as a `Date.now()` reading. */
  readonly deadline?: number;
  /** Where this call is recorded, when the caller is collecting. */
  readonly modelCalls?: ModelCall[];
  /**
   * Where this call is **journaled**, when the execution is durable.
   *
   * [`RunContext.effects`], read through the same structural equivalence the
   * three fields above are read through: a model call is an effect of the node
   * that made it, and its site is that node's.
   */
  readonly effects?: EffectRecorder;
}

/**
 * This member's share of what is left of the node's budget, or `undefined` when
 * nothing bounds it but the node's own deadline. See [`callModel`].
 */
function requestBudget(
  site: ModelSite,
  routeOn: readonly RouteCondition[],
  membersLeft: number,
): number | undefined {
  // The last member — and every member of a route that did not declare
  // `timeout` — waits as long as the node does.
  if (membersLeft < 2 || !routeOn.includes("timeout")) return undefined;
  if (site.deadline === undefined) return undefined;
  const remaining = site.deadline - Date.now();
  // A budget already spent needs no share of itself: the node's deadline is
  // about to answer, and a 0ms request budget would report that as the
  // provider's silence.
  if (remaining <= 0) return undefined;
  return Math.max(1, Math.floor(remaining / membersLeft));
}

/**
 * A signal that follows `outer` and also aborts on its own budget.
 *
 * `AbortSignal.any` and `AbortSignal.timeout` would compose this in one line on
 * both supported runtimes, and are not used for the same reason the rest of this
 * module keeps its own timers: the caller has to be able to tell **which** of
 * the two fired, and it has to be able to release the timer the moment the call
 * answers rather than leaving one live per model call in a long tool loop.
 */
function bounded(
  outer: AbortSignal,
  budgetMs: number,
): { readonly signal: AbortSignal; expired: () => boolean; release: () => void } {
  const controller = new AbortController();
  let expired = false;
  const timer = setTimeout(() => {
    expired = true;
    controller.abort(new Error(`the ${budgetMs}ms budget of this model call was spent`));
  }, budgetMs);
  const follow = () => {
    clearTimeout(timer);
    controller.abort(outer.reason);
  };
  if (outer.aborted) follow();
  else outer.addEventListener("abort", follow, { once: true });
  return {
    signal: controller.signal,
    expired: () => expired,
    release: () => {
      clearTimeout(timer);
      outer.removeEventListener("abort", follow);
    },
  };
}

/**
 * The error a spent route raises: the failure that ended it, with what the
 * members before it did.
 *
 * The refusals are on the message rather than only in the trace because this is
 * what a node failure prints, and "`model.smart` answered 429" alone would
 * describe a route as though it were a binding.
 */
function failoverContext(
  selection: ModelSelection,
  failovers: readonly Failover[],
  error: unknown,
): unknown {
  if (failovers.length === 0) return error;
  const tried = failovers
    .map((one) => `\`${one.model}\` (${one.condition})`)
    .join(", ");
  return new Error(
    `\`${selection.address}\` spent its route: ${tried} failed over, and the next member also refused: ${describe(error)}`,
    { cause: error },
  );
}

/** One call to one direct binding, on whichever surface its kind reaches. */
async function callDirect(
  model: ModelBinding,
  request: {
    readonly system: string;
    readonly turns: readonly Turn[];
    readonly tools: readonly ToolSpec[];
    readonly pinned?: ToolSpec;
  },
  signal: AbortSignal,
): Promise<ModelAnswer> {
  // Grammar 12.1's two SDK-reached kinds. There is no request to compose for
  // them — no endpoint, no header set, and a signing scheme that belongs to a
  // cloud SDK — so the gap is reported here rather than as a malformed call.
  // `base_url:` is not the fix: those rows do not take one.
  if (model.provider.kind === "bedrock" || model.provider.kind === "vertex") {
    throw new Error(
      `\`${model.provider.address}\` is \`kind: ${model.provider.kind}\`, which is reached through a cloud SDK rather than an HTTP endpoint (grammar 12.1) and which this compiler release does not call: bind \`${model.address}\` to an \`anthropic\`, \`openai\`, \`openai_compatible\` or \`azure_openai\` provider`,
    );
  }
  if (model.provider.kind === "anthropic") return await callMessages(model, request, signal);
  // The one wire choice that is not the kind's alone: an `openai` provider
  // carrying a server-tool suite speaks Responses for **every** call it makes
  // (Decision D122, [`speaksResponses`]).
  if (speaksResponses(model.provider)) return await callResponses(model, request, signal);
  return await callChatCompletions(model, request, signal);
}

async function callMessages(
  model: ModelBinding,
  request: {
    readonly system: string;
    readonly turns: readonly Turn[];
    readonly tools: readonly ToolSpec[];
    readonly pinned?: ToolSpec;
  },
  signal: AbortSignal,
): Promise<ModelAnswer> {
  const settings = { ...model.settings };
  const maxTokens = settings["max_tokens"] ?? ANTHROPIC_MAX_TOKENS;
  delete settings["max_tokens"];

  const messages: Record<string, unknown>[] = [];
  // Whether the turn this loop just **dropped** is the one the next message
  // follows. Set at the single drop below, and spent by the very next `user`
  // whether it folded or not — nothing else can widen it.
  let dropped = false;
  // One user message, **folded into the one before it** across a dropped turn.
  //
  // Roles alternate on this wire (`WIRE-NOTES`, "Certain"), and there is exactly
  // one way this runtime composes two user turns in a row: the assistant turn
  // between them had nothing this surface can spell and was dropped below. That
  // used to be the last turn of the request, so dropping it left the request
  // ending on the user turn before; since resolved q52 the pinned call carries a
  // closing user turn *after* it, and the two would arrive as consecutive `user`
  // messages the API refuses. Folding is what two adjacent user turns mean — one
  // turn, its parts in the order they were written.
  //
  // It is `dropped` that the fold is conditioned on, and not merely "the last
  // message is a `user` one", because those are the same condition **only for as
  // long as the claim above holds**. A fold that ran on any two adjacent user
  // messages would also repair the ones that are mistakes — a closing turn
  // composed where no loop ran, a history channel that stopped alternating, a
  // subflow seam that doubled a turn — and repair them *silently*, on the way to
  // a wire whose alternation check (the mock's, `WIRE-NOTES` (18)) is the one
  // thing in this project that would have caught them. The conformance oracle is
  // only as strict as the requests that reach it, and resolved q52 exists
  // because a lenient wire hid a bad request once already.
  const user = (content: unknown): void => {
    const exposed = dropped;
    dropped = false;
    const last = messages[messages.length - 1];
    // An assistant message between the drop and here would leave nothing to fold
    // into — unreachable today (a dropped turn asked for no tool, so the loop
    // ended on it) and harmless if it ever is not.
    if (!exposed || last === undefined || last["role"] !== "user") {
      messages.push({ role: "user", content });
      return;
    }
    last["content"] = [...textBlocks(last["content"]), ...textBlocks(content)];
  };
  for (const turn of request.turns) {
    if (turn.role === "user") {
      user(turn.text);
      continue;
    }
    if (turn.role === "tool") {
      user(
        turn.results.map((result) => ({
          type: "tool_result",
          tool_use_id: result.id,
          content: result.content,
          // The Messages API's own way of saying "this call did not work":
          // the block is answered, so the `tool_use` it closes is not left
          // dangling, and the flag is what tells the model the content is a
          // refusal rather than a result (Decision D119, `WIRE-NOTES` (18)).
          // Absent — not `false` — on every result that is one, because the key
          // is optional and a request that spelled it out on every block would
          // be sending a field no successful call has.
          ...(result.isError === true ? { is_error: true } : {}),
        })),
      );
      continue;
    }
    // A turn *this* wire sent goes back exactly as it came — thinking blocks and
    // all, which the Messages API requires unaltered beside the `tool_use`
    // blocks they preceded. Two turns are rendered from their parts instead: one
    // this runtime *composed* (the shared history channel of grammar 10.4), and
    // one another **wire** answered, whose items this surface has never heard of
    // ([`ContentWire`]) — a route that fails over from a Responses member to an
    // Anthropic one replays its history across that seam.
    if (turn.blocks !== undefined && (turn.wire ?? "messages") === "messages") {
      messages.push({ role: "assistant", content: [...turn.blocks] });
      continue;
    }
    const content: unknown[] = [];
    if (turn.text !== undefined && turn.text !== "") content.push({ type: "text", text: turn.text });
    for (const call of turn.toolCalls ?? []) {
      content.push({ type: "tool_use", id: call.id, name: call.name, input: call.args });
    }
    if (content.length === 0) {
      // Nothing of that turn has a spelling on this wire, and
      // `{"role": "assistant", "content": []}` is a message the Messages API
      // refuses (`content: List should have at least 1 item`) — the very 400
      // [`replayed`] exists to keep this runtime from sending. The turn is
      // dropped rather than padded with a text block the model never wrote,
      // which is what [`callChatCompletions`] does with the same situation.
      //
      // It is reachable off the **other** block-carrying wire and nowhere else:
      // a Responses member can end a turn having only run a server tool — a
      // `web_search_call` item and no `output_text`, which is also the shape an
      // answer cut short by `max_output_tokens` takes — and a ladder that then
      // falls to an Anthropic member arrives here with a turn whose whole
      // content is items this surface has no vocabulary for. Those items are
      // lost across the seam either way; what the guard decides is whether the
      // loss is silent or is a provider 400 about the wrong request.
      //
      // Roles still alternate for the mock and the API alike (`WIRE-NOTES`
      // (18)): a turn this empty carried no tool call, so the loop ended on it
      // and it is the last turn the *loop* wrote. What can follow it is
      // [`CLOSING_TURN`] and nothing else, and `user` above folds that into the
      // user turn this drop exposed rather than leaving two of them in a row.
      // This assignment is the whole of the fold's reach: every other pair of
      // adjacent user turns still arrives at the wire as the two messages it
      // composed, to be refused there.
      dropped = true;
      continue;
    }
    messages.push({ role: "assistant", content });
  }

  const offered = [...request.tools, ...(request.pinned === undefined ? [] : [request.pinned])];
  const body: Record<string, unknown> = {
    model: model.id,
    max_tokens: maxTokens,
    system: request.system,
    messages,
    ...settings,
  };
  // The agent's own tools first, then the provider's server tools — the order
  // is pinned by the goldens rather than left to chance, because the array
  // reaches the wire as written and a reader comparing two builds should not
  // have to work out whether a reordering meant anything. Client tools lead
  // because they are the ones this composition declares; a server tool is a
  // property of the connection every agent on it shares.
  const server = model.provider.serverTools ?? [];
  if (offered.length > 0 || server.length > 0) {
    body["tools"] = [
      // A **provider-defined** tool goes out as its type and its name and
      // nothing else (grammar 6.1, PRD resolved q54 ruling d): the schema is the
      // provider's, the model is trained against the type, and an `input_schema`
      // beside it is a key this surface refuses. That is the whole difference
      // between the two built-ins here and every other client tool — the
      // arguments that come back are the same either way, which is what lets one
      // set of handlers serve every wire ([`ToolSpec.providerType`]).
      ...offered.map((tool) =>
        tool.providerType === undefined
          ? { name: tool.name, description: tool.description, input_schema: tool.schema }
          : { type: tool.providerType, name: tool.name },
      ),
      ...server,
    ];
  }
  if (request.pinned !== undefined) {
    body["tool_choice"] = { type: "tool", name: request.pinned.name };
  }

  const answer = await send(
    model,
    `${baseUrl(model.provider)}/v1/messages`,
    {
      ...credential(model.provider, "x-api-key"),
      "anthropic-version": "2023-06-01",
    },
    body,
    signal,
  );

  const blocks = (answer["content"] ?? []) as { type: string; [key: string]: unknown }[];
  const texts = blocks.filter((block) => block.type === "text").map((block) => block["text"]);
  // `tool_use` **exactly**, which is what keeps a server tool out of the tool
  // loop (Decision D122). A provider that ran one answers with a
  // `server_tool_use` block and its paired `*_tool_result` beside it: the call
  // already happened, on the provider's side, and there is nothing for this
  // runtime to dispatch. Reading them as calls would send the loop looking for a
  // tool the agent never declared, which since Decision D119 is a *refusal*
  // bounced back to the model — an answer that worked, reported as a mistake.
  // They travel instead on `content`, which [`replayed`] sends back unaltered.
  const uses = blocks.filter((block) => block.type === "tool_use");
  const pinnedUse =
    request.pinned === undefined
      ? undefined
      : uses.find((use) => use["name"] === request.pinned!.name);
  return {
    text: texts.length > 0 ? texts.join("") : null,
    toolCalls: uses
      .filter((use) => use !== pinnedUse)
      .map((use) => ({
        id: String(use["id"]),
        name: String(use["name"]),
        args: use["input"],
      })),
    structured: pinnedUse === undefined ? null : (pinnedUse["input"] ?? null),
    stopReason: (answer["stop_reason"] as string | null) ?? null,
    content: blocks,
  };
}

/**
 * One Messages `content` as the block list it is shorthand for, so two turns can
 * be folded into one (see the `user` helper in [`callMessages`]).
 *
 * The string spelling *is* one text block — the API normalises it into one and
 * addresses its complaints at the normalised block — so this is a rewriting
 * rather than a wrapping. An empty string is the one that becomes no block at
 * all: `{"type": "text", "text": ""}` is a block the API refuses, and a fold that
 * produced one would turn a legal turn into a 400.
 */
function textBlocks(content: unknown): unknown[] {
  if (typeof content !== "string") return content as unknown[];
  return content === "" ? [] : [{ type: "text", text: content }];
}

async function callChatCompletions(
  model: ModelBinding,
  request: {
    readonly system: string;
    readonly turns: readonly Turn[];
    readonly tools: readonly ToolSpec[];
    readonly pinned?: ToolSpec;
  },
  signal: AbortSignal,
): Promise<ModelAnswer> {
  // What this request declares is also what its **history** may name on this
  // surface, and that is the one rule the two wires do not share: Chat
  // Completions re-validates an assistant turn's `tool_calls` against `tools`
  // and refuses a name it does not find there, while the Messages API does not
  // (`WIRE-NOTES` (18)). The only turn that can carry such a name is an answer
  // that called a tool the agent never offered, which Decision D119 refuses and
  // the loop then replays — so that turn is rendered here rather than sent as it
  // stands.
  const declared = new Set(request.tools.map((tool) => tool.name));
  const messages: Record<string, unknown>[] = [{ role: "system", content: request.system }];
  for (const turn of request.turns) {
    if (turn.role === "user") {
      messages.push({ role: "user", content: turn.text });
      continue;
    }
    if (turn.role === "tool") {
      // A refused call is answered here too, and with no flag beside it: the
      // `tool` role message is closed to `role`, `content` and `tool_call_id`,
      // so this surface has no `is_error` to set and the refusal text *is* the
      // message (Decision D119, `WIRE-NOTES` (18)). Answering it at all is the
      // load-bearing half — an unanswered `tool_call_id` is a request this
      // surface refuses.
      //
      // Except for the calls whose `tool_call` this surface would not let the
      // assistant turn carry: a `tool` message answering an id no assistant
      // message asked for is refused just as loudly, so their refusals travel as
      // a `user` turn — after the `tool` messages, so that nothing comes between
      // an assistant turn and the answers to it.
      const unoffered: string[] = [];
      for (const result of turn.results) {
        if (!declared.has(result.name)) {
          unoffered.push(result.content);
          continue;
        }
        messages.push({ role: "tool", tool_call_id: result.id, content: result.content });
      }
      if (unoffered.length > 0) messages.push({ role: "user", content: unoffered.join("\n\n") });
      continue;
    }
    const offered = (turn.toolCalls ?? []).filter((call) => declared.has(call.name));
    const text = turn.text ?? null;
    if (offered.length === 0 && (text === null || text === "")) {
      // The whole of this turn was calls this request may not name, so there is
      // nothing left of it to send: an assistant message carrying neither
      // `content` nor `tool_calls` is one this surface refuses, and an empty
      // `content` invented to carry it would be a turn the model did not send.
      // Nothing is lost that the model needs — the refusal that follows names
      // the call it made, in full.
      continue;
    }
    const message: Record<string, unknown> = { role: "assistant", content: text };
    if (offered.length > 0) {
      message["tool_calls"] = offered.map((call) => ({
        id: call.id,
        type: "function",
        function: { name: call.name, arguments: JSON.stringify(call.args) },
      }));
    }
    messages.push(message);
  }

  const body: Record<string, unknown> = { model: model.id, messages, ...model.settings };
  // The agent's own tools first, then the provider's server tools — the same
  // order the other two wires use, and pinned by the goldens for the same
  // reason. The only kind that reaches here carrying a suite is
  // `openai_compatible`: an `openai` provider that declares one speaks Responses
  // instead ([`speaksResponses`]), and the remaining kinds are refused the key
  // at compile time. A gateway's suite rides this array verbatim — no table
  // could be authoritative about what a gateway honours, so the compiler warns
  // and carries, and dropping it here would make that warning a lie
  // (Decision D122).
  const server = model.provider.serverTools ?? [];
  if (request.tools.length > 0 || server.length > 0) {
    body["tools"] = [
      // Every client tool is a function tool here, the two built-ins included:
      // this surface has no provider-defined types, so what the Messages wire
      // declares as `{"type": "bash_20250124"}` is declared here as an ordinary
      // function under the same name with the compiler's own schema
      // ([`ToolSpec.providerType`], PRD resolved q54 ruling d). Same names, same
      // arguments, same handlers.
      ...request.tools.map((tool) => ({
        type: "function",
        function: { name: tool.name, description: tool.description, parameters: tool.schema },
      })),
      ...server,
    ];
  }
  if (request.pinned !== undefined) {
    // `response_format` rather than a forced function: the schema shapes the
    // content and leaves the request's own `tools` callable, which is what an
    // agent whose loop has just ended still has on offer (WIRE-NOTES (3)).
    body["response_format"] = {
      type: "json_schema",
      json_schema: {
        name: request.pinned.name,
        strict: strictable(request.pinned.schema),
        schema: request.pinned.schema,
      },
    };
  }

  const provider = model.provider;
  const { headers, query } = openAiRequest(provider);
  const path = provider.kind === "azure_openai" ? "/openai/v1/chat/completions" : "/v1/chat/completions";

  const answer = await send(model, `${baseUrl(provider)}${path}${query}`, headers, body, signal);
  const choice = ((answer["choices"] ?? []) as Record<string, unknown>[])[0] ?? {};
  const message = (choice["message"] ?? {}) as Record<string, unknown>;
  const content = (message["content"] ?? null) as string | null;
  const calls = ((message["tool_calls"] ?? []) as Record<string, unknown>[]).map((call) => {
    const fn = (call["function"] ?? {}) as Record<string, unknown>;
    return {
      id: String(call["id"]),
      name: String(fn["name"]),
      args: JSON.parse(String(fn["arguments"] ?? "{}")) as unknown,
    };
  });
  return {
    text: content,
    toolCalls: request.pinned === undefined ? calls : [],
    structured:
      request.pinned === undefined || content === null ? null : (JSON.parse(content) as unknown),
    stopReason: (choice["finish_reason"] as string | null) ?? null,
    // A refusal is `content: null` beside a stated reason (WIRE-NOTES (3)). The
    // absence of content is what every other branch here sees; the reason is the
    // only thing that tells a refusal from a `max_tokens` cut.
    refusal: (message["refusal"] as string | null) ?? null,
  };
}

/**
 * OpenAI's **Responses** API: `POST /v1/responses` (Decision D122).
 *
 * The wire an `openai` provider moves to when it declares `server_tools:`, and
 * the only one of OpenAI's two that carries the built-in tool suite at all —
 * web search, file search, code interpreter, image generation. Everything else
 * about the call is the same call: the same conversation, the same client
 * function tools, the same structured-output posture, the same failover ladder
 * around it.
 *
 * # What changes from Chat Completions
 *
 * * **The conversation is a list of items, not messages.** A user turn is a
 *   `message` item; a function call is its own `function_call` item beside the
 *   message rather than a field on it; a result is a `function_call_output`
 *   item keyed by `call_id`. The system prompt is `instructions`, which is why
 *   it is not the first item.
 * * **An assistant turn goes back as the items it came as.** [`ModelAnswer`]
 *   carries the raw `output` array, exactly as the Messages wire carries
 *   content blocks, and a replay sends it unaltered — which is what keeps a
 *   `web_search_call` item, a `reasoning` item, and the pairing between a
 *   `function_call` and the output that answers it intact. A turn rebuilt from
 *   `text` and `toolCalls` would drop every one of them.
 * * **A tool is flat.** `{ type: "function", name, parameters }` rather than
 *   `{ type: "function", function: { … } }`.
 * * **Two settings are spelled differently**, and are translated here:
 *   `max_tokens` is `max_output_tokens`, and `reasoning_effort` is
 *   `reasoning: { effort }`. Everything else in `settings:` travels as written,
 *   which means a knob this wire does not have (`stop`, `seed`) reaches the
 *   service and is refused by it — visibly, in the run that declared it, rather
 *   than dropped here into a request that quietly did something else.
 *   `docs/topics/models.md` says so where an author meets the seam, and
 *   `agent-compose validate` refuses those two on a provider that speaks this
 *   wire rather than leaving them to the 400.
 * * **`store` is the service's, and its default here is `true`** where Chat
 *   Completions' is `false` — so a connection moved onto this wire has its
 *   prompts and completions retained by the provider where before they were
 *   not. This request does not pin the key, and that is a decision rather than
 *   an omission: `store: false` makes the service refuse a replayed `reasoning`
 *   item, which is exactly what the loop above sends back on every turn of a
 *   reasoning model, so pinning it would trade a documented retention default
 *   for a broken tool loop. `docs/topics/models.md` says what moving wires
 *   changes about retention, where an author can act on it.
 *
 * # What does not change
 *
 * Structured output keeps the q16 posture exactly: what is **constrained** is
 * what is **parsed**. `text.format` is the Responses spelling of Chat
 * Completions' `response_format`, carrying the same schema under the same
 * `strict` decision ([`strictable`]), and the object parsed back out is the
 * assistant text that format shaped.
 *
 * And a function call is dispatched exactly as it is on the other two wires —
 * the loop, the refusals of Decision D119, the ordinals of grammar 9.4 — because
 * the loop is above this function and never learns which wire answered.
 */
async function callResponses(
  model: ModelBinding,
  request: {
    readonly system: string;
    readonly turns: readonly Turn[];
    readonly tools: readonly ToolSpec[];
    readonly pinned?: ToolSpec;
  },
  signal: AbortSignal,
): Promise<ModelAnswer> {
  const input: unknown[] = [];
  for (const turn of request.turns) {
    if (turn.role === "user") {
      input.push({
        type: "message",
        role: "user",
        content: [{ type: "input_text", text: turn.text }],
      });
      continue;
    }
    if (turn.role === "tool") {
      for (const result of turn.results) {
        // No error flag: a `function_call_output` is closed to its `call_id` and
        // its `output`, so a refusal *is* the output text — the same concession
        // Chat Completions makes, and for the same reason (Decision D119,
        // `WIRE-NOTES` (18), (21)). Answering every call at all is the
        // load-bearing half: an unanswered `call_id` is a request this surface
        // refuses.
        input.push({
          type: "function_call_output",
          call_id: result.id,
          output: result.content,
        });
      }
      continue;
    }
    // An answer **this** surface produced goes back as it came. Everything the
    // reading below does not read — a `reasoning` item, a `web_search_call`,
    // the annotations on an `output_text` — is in here and nowhere else.
    //
    // Blocks another wire wrote are not: the Messages wire's `text`/`tool_use`
    // vocabulary is not an item type this surface has, and a ladder that failed
    // over from an Anthropic member to this one replays exactly such a turn
    // ([`ContentWire`]). Those are rebuilt below, from the reading — which is
    // what the wire that produced them is *also* holding this turn to.
    if (turn.blocks !== undefined && turn.wire === "responses") {
      input.push(...turn.blocks);
      continue;
    }
    // The turns this runtime composed rather than received: the shared history
    // channel of grammar 10.4, and an answer off another wire.
    const text = turn.text ?? "";
    if (text !== "") {
      input.push({
        type: "message",
        role: "assistant",
        content: [{ type: "output_text", text }],
      });
    }
    for (const call of turn.toolCalls ?? []) {
      input.push({
        type: "function_call",
        call_id: call.id,
        name: call.name,
        arguments: JSON.stringify(call.args),
      });
    }
  }

  const settings = { ...model.settings };
  if (settings["max_tokens"] !== undefined) {
    settings["max_output_tokens"] = settings["max_tokens"];
    delete settings["max_tokens"];
  }
  if (settings["reasoning_effort"] !== undefined) {
    settings["reasoning"] = { effort: settings["reasoning_effort"] };
    delete settings["reasoning_effort"];
  }

  const body: Record<string, unknown> = {
    model: model.id,
    instructions: request.system,
    input,
    ...settings,
  };
  // Client tools first, then the provider's suite — the same order the Messages
  // wire uses, pinned by the goldens for the same reason.
  const server = model.provider.serverTools ?? [];
  // The built-ins are function tools here too, for [`callChatCompletions`]'
  // reason: this surface's provider-defined types are OpenAI's own server tools,
  // which are the provider's to run, and a client tool the *graph* runs is
  // declared with the compiler's schema whatever the Messages wire calls it.
  const functions = request.tools.map((tool) => ({
    type: "function",
    name: tool.name,
    description: tool.description,
    parameters: tool.schema,
    strict: strictable(tool.schema),
  }));
  if (functions.length > 0 || server.length > 0) {
    body["tools"] = [...functions, ...server];
  }
  if (request.pinned !== undefined) {
    body["text"] = {
      format: {
        type: "json_schema",
        name: request.pinned.name,
        strict: strictable(request.pinned.schema),
        schema: request.pinned.schema,
      },
    };
  }

  const { headers } = openAiRequest(model.provider);
  const answer = await send(model, `${baseUrl(model.provider)}/v1/responses`, headers, body, signal);

  const output = (answer["output"] ?? []) as Record<string, unknown>[];
  // **Per message item**, not one flat list of parts. A turn on this wire can
  // hold more than one `message` — a preamble the model wrote before a server
  // tool ran, the shaped answer after it — and the two answer different
  // questions. `text` is everything the assistant said, which is what a replay
  // on another wire has to carry; the *structured* answer is the last message
  // alone, because `text.format` shapes the turn's final message and says
  // nothing about what precedes it. Flattening them and parsing the join is how
  // `Let me look that up.{"answer":"…"}` reaches `JSON.parse`, and server tools
  // are exactly what makes a multi-`message` turn reachable (Decision D122).
  const said: string[] = [];
  let refusal: string | null = null;
  for (const item of output) {
    if (item["type"] !== "message") continue;
    const parts: string[] = [];
    for (const part of (item["content"] ?? []) as Record<string, unknown>[]) {
      if (part["type"] === "output_text") parts.push(String(part["text"] ?? ""));
      // A stated decline, which is what tells a refusal from an answer cut
      // short by `max_output_tokens` — both otherwise arrive as no structured
      // output (`WIRE-NOTES` (3), (21)).
      if (part["type"] === "refusal") refusal = String(part["refusal"] ?? "");
    }
    if (parts.length > 0) said.push(parts.join(""));
  }
  const calls = output
    .filter((item) => item["type"] === "function_call")
    .map((item) => ({
      id: String(item["call_id"]),
      name: String(item["name"]),
      args: JSON.parse(String(item["arguments"] ?? "{}")) as unknown,
    }));
  const text = said.length > 0 ? said.join("") : null;
  const shaped = said.length > 0 ? said[said.length - 1]! : null;
  // `status` is the call's own outcome and `incomplete_details.reason` is why an
  // incomplete one stopped; the narrower of the two is what a reader needs, so
  // it wins where there is one.
  const incomplete = (answer["incomplete_details"] ?? null) as Record<string, unknown> | null;
  const stopReason =
    incomplete !== null && incomplete["reason"] !== undefined
      ? String(incomplete["reason"])
      : ((answer["status"] as string | null) ?? null);
  return {
    text,
    toolCalls: request.pinned === undefined ? calls : [],
    structured: request.pinned === undefined ? null : shapedOutput(shaped),
    stopReason,
    content: output,
    // …and whose vocabulary those are, because a failover ladder may hand this
    // turn to a member on another wire ([`ContentWire`]).
    wire: "responses",
    refusal,
  };
}

/**
 * The structured answer a Responses turn's final message carries, or `null`.
 *
 * `text.format` shapes that message, so parsing it is parsing what the format
 * constrained — but only the **service** guarantees the shape, and a turn that
 * came back with prose where the schema was asked for is an answer this runtime
 * cannot use rather than a call that failed. So the absence is reported as an
 * absence, which is the same posture the Messages wire has when the pinned
 * `tool_use` block is not in the turn: `callAgent` then names the agent, the
 * output it asked for, and what the surface said about why — a stated refusal,
 * or a `max_output_tokens` cut. A `SyntaxError` thrown from here would name
 * none of those, and would be thrown *inside* the journaled model call, which
 * would record a call that worked as a call that did not.
 */
function shapedOutput(text: string | null): unknown {
  if (text === null) return null;
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return null;
  }
}

/**
 * How a request reaches an OpenAI-shaped surface: its auth header, and the
 * query an Azure connection needs.
 *
 * Shared by the two such surfaces this runtime speaks — Chat Completions and
 * Embeddings — because the difference between them is the route and the body,
 * never how a connection authenticates.
 */
function openAiRequest(provider: ProviderBinding): {
  headers: Record<string, string>;
  query: string;
} {
  const azure = provider.kind === "azure_openai";
  const headers: Record<string, string> = credential(provider, azure ? "api-key" : "authorization");
  if (!azure && provider.organization !== undefined) {
    headers["openai-organization"] = provider.organization;
  }
  const query =
    provider.kind === "azure_openai" && provider.apiVersion !== undefined
      ? `?api-version=${encodeURIComponent(provider.apiVersion)}`
      : "";
  return { headers, query };
}

// ---------------------------------------------------------------------------
// Embeddings: what turns a vector store's text into a vector (grammar 11.2)
// ---------------------------------------------------------------------------

/**
 * A vector store's `embed:` block, resolved (grammar 11.2, Decision D116).
 *
 * `provider` is the connection that **computes** the vectors and is a
 * `provider.*` like any other; where the vectors *live* is the store's
 * `backend:`, which is a different question and the one that forks per target.
 */
export interface EmbedBinding {
  /** The store this embeds for, for a message. */
  readonly store: string;
  /** `model:` — a provider-native embedding model id (Decision D36). */
  readonly model: string;
  /** `provider:` — the connection that serves the embeddings. */
  readonly provider: ProviderBinding;
  /** `dimensions:` — asserted against what the provider answers with. */
  readonly dimensions?: number;
}

/**
 * Embed one batch of texts, in order (grammar 11.2).
 *
 * The wire is OpenAI's `/v1/embeddings`, which is the surface every provider
 * kind the capability table marks as embedding-capable speaks — `anthropic` is
 * marked as not, and the validator refuses an `embed.provider` naming one, so
 * reaching here with one is a binding that lost its kind between the spec and
 * the process.
 *
 * `dimensions:` is **checked** rather than merely forwarded: grammar 11.2 says
 * it is "asserted against the backend's index", and a store whose declared width
 * silently disagreed with what the provider answered would fill an index with
 * vectors no later search could compare against.
 */
export async function callEmbeddings(
  embed: EmbedBinding,
  texts: readonly string[],
  signal: AbortSignal,
): Promise<number[][]> {
  const provider = embed.provider;
  if (provider.kind === "anthropic" || provider.kind === "bedrock" || provider.kind === "vertex") {
    throw new Error(
      `\`${embed.store}\` embeds through \`${provider.address}\`, whose \`${provider.kind}\` plugin this compiler release cannot reach for embeddings: name a provider of kind \`openai\`, \`openai_compatible\` or \`azure_openai\` (grammar 11.2)`,
    );
  }
  const { headers, query } = openAiRequest(provider);
  const path = provider.kind === "azure_openai" ? "/openai/v1/embeddings" : "/v1/embeddings";
  // `send` reports a refusal as a `ProviderFailure` naming its subject, which
  // here is the store rather than a model: an embeddings call belongs to a
  // store's `embed:` block and nothing about a `model.*` is involved.
  const answer = await send(
    { address: embed.store, id: embed.model, provider, settings: {} },
    `${baseUrl(provider)}${path}${query}`,
    headers,
    { model: embed.model, input: [...texts] },
    signal,
  );
  const data = (answer["data"] ?? []) as Record<string, unknown>[];
  if (data.length !== texts.length) {
    throw new Error(
      `\`${embed.store}\` asked \`${provider.address}\` to embed ${texts.length} text(s) and was answered ${data.length}`,
    );
  }
  // The API is documented to answer in request order, and it also carries an
  // `index` on every row; sorting by it is what makes the promise this code
  // relies on the *response's* rather than the documentation's.
  const ordered = [...data].sort(
    (left, right) => Number(left["index"] ?? 0) - Number(right["index"] ?? 0),
  );
  return ordered.map((row, position) => {
    const vector = row["embedding"];
    if (!Array.isArray(vector) || vector.some((value) => typeof value !== "number")) {
      throw new Error(
        `\`${embed.store}\` was answered an embedding that is not a list of numbers (row ${position})`,
      );
    }
    if (embed.dimensions !== undefined && vector.length !== embed.dimensions) {
      throw new Error(
        `\`${embed.store}\` declares \`dimensions: ${embed.dimensions}\` and \`${provider.address}\` answered a vector of ${vector.length}`,
      );
    }
    return vector as number[];
  });
}

// ---------------------------------------------------------------------------
// Agents: the intra-agent tool loop (grammar 5, PRD §9.14)
// ---------------------------------------------------------------------------

/** One tool an agent may call, and how the graph runs it. */
export interface AgentTool extends ToolSpec {
  readonly address: string;
  invoke(args: unknown, context: RunContext, site: ToolCallSite): Promise<unknown>;
}

/**
 * Where an agent execution sits, for the one tool that needs to know.
 *
 * A `tool.*` and a synthesized store tool are called with the node's context and
 * nothing else — an `http:` request and a store op have no instance beneath
 * them. A `flow.*` attached to `tools:` (grammar 5.4) does: it starts a subflow
 * instance, which needs an instance path to derive its nested effects' keys from
 * (grammar 9.4) and a level-1 policy to resolve its nodes' against (grammar 9.3).
 * Both are the *calling node's*, so both are handed to [`callAgent`] rather than
 * captured in the module-level binding, which knows nothing about the execution.
 */
export interface AgentSite {
  /**
   * The instance-path frames down to this agent execution, outermost first
   * (grammar 9.4): [`instancePath`] at an `agent:` node, and the dispatch's own
   * path where a `map` dispatched the agent.
   */
  readonly path: readonly string[];
  /**
   * Grammar 9.3 level 1 for an instance the loop starts — what already reached
   * *this* instance, which crosses the boundary with it (Decision D79).
   *
   * A `map`-dispatched agent passes none, because grammar 8.6 rule 10 resolves a
   * dispatched instance's nodes with level 1 absent.
   */
  readonly policy?: InstancePolicy;
}

/**
 * Where one tool call sits, and where what it did is recorded.
 *
 * Handed to every tool for one uniform signature; read by the only one that
 * instantiates anything ([`callSubflowTool`]).
 */
export interface ToolCallSite {
  /** The calling agent execution's own frames ([`AgentSite.path`]). */
  readonly path: readonly string[];
  /**
   * How many times **this tool** has already been *invoked* in this agent
   * execution, `0` on the first — grammar 9.4's flow-tool ordinal (PRD §9.19).
   *
   * Invoked, not called, and the word is grammar 9.4's own: a call the tool's
   * contract **refused** (Decision D119) never reached the tool, so it claims no
   * ordinal and the next call takes the frame the refused one was offered. That
   * is what keeps a model's mistake from re-keying work that has nothing to do
   * with it — a loop that refused once and then got it right derives the same
   * key as one that got it right first time.
   *
   * It counts within one agent-node *execution*, so a node-level `retry:`
   * restarts it: the Nth invocation of a retried attempt reuses the Nth key of
   * the failed one, which is the positional — not semantic — reuse the grammar
   * states openly.
   */
  readonly ordinal: number;
  /** [`AgentSite.policy`], for an instance this call starts. */
  readonly policy?: InstancePolicy;
  /**
   * The agent execution's own list of the subflow dispatches its loop made, in
   * call order.
   *
   * [`ModelCall.toolCalls`]' counterpart for the record that carries the
   * instance's trace, and the list a `map` orders by source-item index before it
   * answers. A record pushed here is pushed to
   * [`RunContext.toolDispatches`][`RunContext.toolDispatches`] too, and is the
   * same object in both.
   */
  readonly dispatches: DispatchRecord[];
  /**
   * Where a **built-in** files what the model asked it to run
   * (`docs/trace.md` §7.4).
   *
   * One slot rather than a channel: this array is built per call, so what a call
   * filed is `builtin[0]` and a tool that is not a built-in files nothing. The
   * shape is [`dispatches`]' — a list the callee appends to and the loop reads
   * off afterwards — because the reason is the same: only the call knows what it
   * ran, and only the loop has the record to put it on.
   */
  readonly builtin: BuiltinProgram[];
}

/**
 * The instance path of the subflow one model tool call starts (grammar 9.4,
 * PRD §9.19).
 *
 * [`instancePath`]'s counterpart for the other call site a `flow.*` has: the
 * calling agent execution's frames, then `<tool name>/<call ordinal>`. The tool
 * name is the flow's local name (grammar 2.2) and the ordinal is decimal, so —
 * exactly as for a node frame — no component can contain the separator.
 *
 * Derived here rather than at each of its two readers, so the key a dispatch
 * record files and the link a [`ToolCallRecord`] carries cannot drift apart.
 */
export function toolInstancePath(site: ToolCallSite, tool: string): readonly string[] {
  return [...site.path, `${tool}/${site.ordinal}`];
}

/** Everything a compiled `agent:` node needs (grammar 5, 8.1). */
export interface AgentBinding {
  readonly address: string;
  readonly prompt: string;
  /** Its `model:` — a direct binding or a failover route (grammar 12.2). */
  readonly model: ModelSelection;
  readonly output: ToolSpec;
  readonly tools: readonly AgentTool[];
  readonly maxToolIterations: number;
}

/** A `flow.*` attached to an agent's `tools:` — flow-as-tool (grammar 5.4, PRD 5.1). */
export interface SubflowTool {
  /** The name the model calls it by: the flow's local name (grammar 2.2). */
  readonly name: string;
  /** The module one call instantiates. */
  readonly binding: SubflowBinding;
  /**
   * Its `inputs:`, which is the parameter schema the model's arguments are held
   * to — the same column the request constrained the model with (PRD §9.16).
   *
   * Absent where the flow declares no `inputs:`, which is a no-argument tool
   * (grammar 3.1): there is no field map to parse against, and the instance is
   * started with an empty object.
   */
  readonly inputs?: ResultSchema<unknown>;
}

/**
 * One flow-as-tool call: the model's arguments, an instance, and its outputs
 * back as the tool's result (grammar 5.4, PRD 5.1, §9.19, §9.20).
 *
 * PRD 5.1 makes a flow's I/O surface interchangeable with a tool's, and this is
 * where that equivalence is executed rather than asserted. Four things happen,
 * and each is somebody else's rule kept here:
 *
 *  * **the arguments are parsed** against the flow's own `inputs:` before an
 *    instance exists. A mismatch is reported exactly as one is for a `tool.*`
 *    and for a synthesized store tool — as a [`ToolCallRefused`], which
 *    [`callAgent`] hands **back to the model** as an error tool result so it can
 *    call again with arguments the contract admits (Decision D119, PRD §9.22).
 *    An argument the contract refuses is the same event on all three tool
 *    surfaces, and one surface answering it differently would make "attached as
 *    a tool" mean two things;
 *  * **the instance runs beneath this call's own frame** (grammar 9.4, PRD
 *    §9.19), so a store write inside it derives a key no other call of this loop
 *    derives, and the node's clock crosses the boundary the way a `flow:` node's
 *    does;
 *  * **its outputs are the result the model sees** — the object grammar 5.4
 *    makes this tool's result schema;
 *  * **it files a dispatch record** carrying the instance's whole trace, which
 *    is PRD §9.20's canonical surface for it, whether the instance answered or
 *    failed. A child that failed reaches the model as nothing at all: the
 *    failure leaves the tool wrapped in a [`ToolFailure`], never silently as a
 *    plausible result.
 */
export async function callSubflowTool(
  tool: SubflowTool,
  args: unknown,
  context: RunContext,
  site: ToolCallSite,
): Promise<unknown> {
  // Outside the `try`, and outside the record: nothing was instantiated, so
  // there is no dispatch to report and no instance for a trace to come from —
  // and, since D119, nothing for the *model* to have caused beyond a call it can
  // make again.
  const inputs =
    tool.inputs === undefined
      ? {}
      : (parseToolArguments(
          tool.inputs,
          args,
          `the arguments \`${tool.name}\` was called with`,
        ) as Record<string, unknown>);

  const path = toolInstancePath(site, tool.name);
  const filed = (record: DispatchRecord): void => {
    site.dispatches.push(record);
    context.toolDispatches?.push(record);
  };
  const common = {
    index: site.ordinal,
    target: tool.binding.address,
    attempts: 1,
    idempotencyKey: [context.execution.id, ...path].join("/"),
  } as const;

  try {
    const answer = await runSubflow(tool.binding, {
      inputs,
      execution: context.execution,
      path,
      // The calling node's deadline, inside the boundary — a `flow:` node's
      // reason exactly (grammar 9.2, and see [`Instantiation.signal`]).
      signal: context.signal,
      ...(site.policy === undefined ? {} : { policy: site.policy }),
    });
    filed({
      ...common,
      outcome: "completed",
      ...(answer.inner === undefined ? {} : { inner: answer.inner }),
    });
    return answer.output;
  } catch (error) {
    // A subflow that failed still made a trace, and this record is its only
    // account: the caller is an agent node, whose entry carries no `inner`
    // (`docs/trace.md` §3, §8).
    const held = traceOf(error);
    filed({
      ...common,
      outcome: "failed",
      ...(held === undefined ? {} : { inner: held }),
      error: describe(error),
    });
    throw new ToolFailure(tool.name, tool.binding.address, error);
  }
}

/**
 * The turn that closes a tool exchange, so the pinned call ends on the user
 * (PRD §9 resolved q52, and see [`callAgent`]).
 *
 * Fixed text, and unconditional on every wire: there is no gateway capability to
 * declare and no key to set. It is harmless where the old shape was tolerated —
 * the ask to emit the verdict becomes a real user turn instead of a prefill — and
 * it is what a strict gateway requires.
 *
 * It belongs to **one request** and not to the conversation: it is composed onto
 * a copy of the loop's turns, so it never reaches the agent's durable history
 * ([`MessageLike`], grammar 10.4) and never appears in the trace. That the copy
 * is a copy is held by the type rather than by a test — [`callAgent`]'s `turns`
 * is `readonly`, because nothing downstream reads it and appending here would
 * therefore change no observable behaviour until some later refactor made the
 * conversation and the loop's turns the same list again.
 *
 * It *is* part of the pinned call's request identity, because that identity is
 * the request ([`callModel`]). A journal whose pinned call was recorded before
 * this turn existed therefore **diverges** on resume rather than replaying the
 * wrong answer, which is the direction `docs/durability.md` §11.3 asks for and
 * why no `JOURNAL_VERSION` moves: what the identity is composed of has not
 * changed, only what this runtime sends.
 */
const CLOSING_TURN: Turn = { role: "user", text: "Now produce the structured result." };

/**
 * One agent node: the tool loop, then the pinned structured-output call.
 *
 * Two shapes, and which one runs is decided by the agent's own `tools:` list:
 *
 *  * **No tools** — one call, the output schema offered as the single tool and
 *    pinned by name. A pinned choice is a promise that the pinned tool is what
 *    gets called, which is exactly the ask PRD 5.2 makes.
 *  * **With tools** — the loop first, on calls that offer the agent's tools and
 *    pin **nothing** (a pinned choice would make the loop unreachable), and the
 *    pinned call is what ends it. The loop is bounded by `max_tool_iterations`
 *    (Decision D51, PRD §9.14): the bound counts model calls in the loop, and
 *    spending it is a node error rather than a silent stop, because a model that
 *    only ever asks for tools has not answered.
 *
 * **A call the contract refuses goes back to the model** (Decision D119, PRD
 * §9.22): arguments a tool's schema does not admit, on any of the three
 * surfaces, and a name the agent never offered, are answered as an error tool
 * result and the loop turns again. That is the whole of the split — a
 * [`ToolCallRefused`] is a call the model can make differently, and every other
 * failure is the tool's *execution* failing, which leaves the node the way it
 * always has. The bound is what keeps it terminating: a correction is another
 * model call, so a model that never corrects spends `max_tool_iterations` and
 * fails the node with the last refusal in hand.
 *
 * Every call of an answer comes back to the model, refused or not — so a refusal
 * does not stop the loop over the calls of one answer, while a failure still
 * does. On the wire that is the call's own id being answered, because both
 * surfaces refuse a request that leaves a `tool_use` / `tool_call_id`
 * unanswered; the one exception is a call naming a tool the agent never offered,
 * which Chat Completions will not let a request name at all, so
 * [`callChatCompletions`] drops it from the replayed assistant turn and sends
 * its refusal as a `user` turn instead (`WIRE-NOTES` (18)).
 *
 * The final call still offers the agent's tools beside the pinned one: the
 * history it carries holds `tool_use`/`tool_result` blocks, and both surfaces
 * refuse a request that carries those without declaring the tools they name.
 *
 * Every loop answer is replayed by [`replayed`], which is where an answer that
 * carried nothing at all stops the node instead of becoming an empty turn the
 * next request could not legally carry — and where the turn records which wire
 * wrote it, so a ladder that fails over to a member on the *other* wire replays
 * a turn that member can read ([`ContentWire`]).
 *
 * **The pinned call always ends on a user turn** ([`CLOSING_TURN`], PRD §9
 * resolved q52). The loop exits on the model's own answer, so the conversation
 * it hands the pinned call ends on an *assistant* turn — and on the Messages
 * wire a trailing assistant turn is the **prefill** feature, which contradicts
 * the forced `tool_choice` beside it: "continue this turn" against "your answer
 * must be this tool call". `api.anthropic.com` happens to tolerate the pair;
 * strict Anthropic-compatible gateways refuse it with a 400 naming the shape
 * ("the conversation must end with a user message"), and a refusal that is
 * shape-determined is replayed by every member of the ladder. So the loop's
 * exchange is closed with one fixed user turn before the output tool is pinned.
 * The tool-less path composes a request that already ends on the user turn and
 * is untouched.
 */
export async function callAgent(
  agent: AgentBinding,
  input: unknown,
  history: readonly Turn[],
  context: RunContext,
  where: AgentSite,
): Promise<{
  output: unknown;
  history: MessageLike[];
  models: readonly ModelCall[];
  toolDispatches?: readonly DispatchRecord[];
}> {
  try {
    return await agentLoop(agent, input, history, context, where);
  } finally {
    // A `builtin.bash` session belongs to this node activity and to nothing
    // else (PRD resolved q54): the shell holds a working directory inside a
    // workspace the run may be about to remove, and a `retry:` that reached
    // the second attempt must start from the workspace rather than from
    // wherever the first attempt had `cd`ed to. Ended however this loop leaves
    // — answered, failed, or thrown out of by a deadline that abandoned it —
    // which is what the wrapper is for: this is the one thing the node owns
    // that a `return` alone would not release ([`endShellSessions`]).
    endShellSessions(context);
  }
}

/** [`callAgent`]'s loop, with the sessions it opens released around it. */
async function agentLoop(
  agent: AgentBinding,
  input: unknown,
  history: readonly Turn[],
  context: RunContext,
  where: AgentSite,
): Promise<{
  output: unknown;
  history: MessageLike[];
  models: readonly ModelCall[];
  toolDispatches?: readonly DispatchRecord[];
}> {
  const rendered = typeof input === "string" ? input : JSON.stringify(input);
  const turn: Turn = { role: "user", text: rendered };
  // The conversation this node holds, and `readonly` is load-bearing: it is what
  // keeps [`CLOSING_TURN`] out of it (resolved q52). Nothing downstream reads
  // this array — the history the node contributes is composed from `rendered`
  // and the structured answer ([`MessageLike`]) — so a `turns.push(CLOSING_TURN)`
  // before the pinned call would send the right request and be caught by no test
  // at all. Typed this way it is caught by `tsc`, which every emitted project
  // runs over its own copy of this file. The loop below rebinds rather than
  // pushes: one copy per turn it adds, bounded by `max_tool_iterations` and
  // dwarfed by the model call that earned each one.
  let turns: readonly Turn[] = [...history, turn];
  // Every call this node makes, in the order it made them (PRD 5.9). A tool
  // loop makes several, and which member of a route served each one is a
  // separate fact about each.
  // The node's own channel ([`RunContext.modelCalls`]) is written by
  // [`callModel`] rather than here, because a call the ladder *lost* has no
  // answer to travel out on and this list only holds what came back.
  const models: ModelCall[] = [];
  // Every subflow this loop instantiated, in the order it called them
  // (PRD §9.20). The node's own channel ([`RunContext.toolDispatches`]) holds
  // the same objects, and this list is what a `map` can put in source-item
  // order before it answers — [`merged`] then reconciles the two by identity,
  // exactly as it does for `models` above.
  const dispatches: DispatchRecord[] = [];
  // How many times each tool has been **invoked**, which is the ordinal grammar
  // 9.4 gives a flow-tool's frame (PRD §9.19). It starts empty **per call of
  // this function**, and that is the whole of "an agent-node retry restarts the
  // ordinals": a retry is a second call of the node's activity.
  const ordinals = new Map<string, number>();

  if (agent.tools.length > 0) {
    let iterations = 0;
    // The refusal this loop is **holding**, for the message a spent budget
    // raises (Decision D119). A model that never corrects is the way a bounce
    // reaches the bound, and a node failure that named only the bound would
    // leave a reader with the symptom and none of the cause — the same run
    // whose model called correctly and simply kept going produces the very same
    // sentence.
    //
    // Held only for as long as the *last* call was one, which is why a call that
    // completes clears it: a loop whose model corrected and then went on asking
    // has no refusal outstanding, and a message that produced the last one it
    // ever saw would say the opposite of what happened.
    let refusal: string | undefined;
    for (;;) {
      if (iterations >= agent.maxToolIterations) {
        throw new Error(
          `\`${agent.address}\` reached its \`max_tool_iterations\` bound of ${agent.maxToolIterations} without answering (Decision D51)${
            refusal === undefined ? "" : `; its last tool call was refused: ${refusal}`
          }`,
        );
      }
      iterations += 1;
      const { answer, served: by } = await callModel(
        agent.model,
        { system: agent.prompt, turns, tools: agent.tools },
        context,
      );
      models.push(by);
      turns = [...turns, replayed(agent, answer)];
      if (answer.toolCalls.length === 0) break;

      // The record of this call's tool calls, on the record of the call that
      // asked for them (`docs/trace.md` §7.3). [`callModel`] has already pushed
      // `by` into the node's own channel and this is the same object, so a
      // record written here reaches the trace even on the call that **ends** the
      // node — which is why the failure path below writes one before it throws.
      //
      // The key is attached on the **first** record rather than beside the empty
      // array, and that is a presence rule rather than a tidiness: `docs/trace.md`
      // §7 makes `toolCalls` a key that is never empty, so a reader is entitled
      // to treat `[]` there as impossible (§10.1). The array is empty for as long
      // as the first call is still running, and a node deadline that fires in
      // that window abandons the loop mid-flight — an entry built from `by`
      // would otherwise carry exactly the value the format promises never to
      // produce.
      const asked: ToolCallRecord[] = [];
      const record = (entry: ToolCallRecord): void => {
        asked.push(entry);
        by.toolCalls = asked;
      };

      const results: { id: string; name: string; content: string; isError?: boolean }[] = [];
      // One refusal, recorded and answered: the record with no `result` and no
      // `instance` (`docs/trace.md` §7.3), and the model handed the text so it
      // can call again (Decision D119).
      const refuse = (
        call: { id: string; name: string },
        why: ToolCallRefused,
        target?: string,
        instance?: { instance: string } | Record<string, never>,
        program?: { program: BuiltinProgram } | Record<string, never>,
      ): void => {
        record({
          name: call.name,
          ...(target === undefined ? {} : { target }),
          outcome: "refused",
          ...(instance ?? {}),
          error: describe(why),
          ...(program ?? {}),
        });
        refusal = why.message;
        results.push({ id: call.id, name: call.name, content: why.message, isError: true });
      };

      for (const call of answer.toolCalls) {
        const tool = agent.tools.find((candidate) => candidate.name === call.name);
        if (tool === undefined) {
          // Recorded with no `target`: there is no component behind a name the
          // agent does not offer, and a reader should still see what the model
          // asked for. The text goes through [`describe`] like every other
          // message field, so it carries the class the way `docs/trace.md` §3
          // says one does — and it names the tools that *are* on the wire,
          // because this refusal is one the model corrects by picking one of
          // them (PRD G3).
          refuse(
            call,
            new ToolCallRefused(
              `\`${agent.address}\` was answered with a call to \`${call.name}\`, which is not one of its tools: it offers ${agent.tools
                .map((offered) => `\`${offered.name}\``)
                .join(", ")}`,
            ),
          );
          continue;
        }
        // Claimed here and **handed back** where the contract refuses the call:
        // grammar §9.4's ordinal counts how many times this tool has already
        // been *invoked*, and a refusal never reaches the tool. Claiming it up
        // front is what lets the site — and so the key the invocation derives —
        // be built before `invoke` is entered, which is the only moment it could
        // be built at.
        const ordinal = ordinals.get(call.name) ?? 0;
        ordinals.set(call.name, ordinal + 1);
        const site: ToolCallSite = {
          path: where.path,
          ordinal,
          ...(where.policy === undefined ? {} : { policy: where.policy }),
          dispatches,
          // One per call, because what it holds is this call's program rather
          // than the loop's history (`docs/trace.md` §7.4).
          builtin: [],
        };
        // Which dispatches this call filed is decided by counting, so the link
        // below is read off the record the call really made rather than derived
        // a second time — [`ToolCallRecord.instance`] and
        // [`DispatchRecord.idempotencyKey`] cannot disagree. A tool that
        // instantiates nothing files none and carries no link.
        //
        // It decides [`ToolCallRecord.result`] too, for the reason that field
        // gives: PRD §9.20 carves the *subflow* call's result out of
        // `docs/trace.md` §11's rule, and "the call filed a dispatch record" is
        // what "this was a flow-as-tool call" is, read off what happened rather
        // than off the tool's shape.
        const before = dispatches.length;
        const started = (): { instance: string } | Record<string, never> => {
          const filed = dispatches[before];
          return filed === undefined ? {} : { instance: filed.idempotencyKey };
        };
        // …and the same idiom for the other thing a call can file: the program a
        // **built-in** was handed (`docs/trace.md` §7.4). Read off what the call
        // filed rather than off the tool's shape, so a record carries one
        // because a built-in ran rather than because this loop assumed which
        // tools are built-ins.
        const ran = (): { program: BuiltinProgram } | Record<string, never> => {
          const filed = site.builtin[0];
          return filed === undefined ? {} : { program: filed };
        };
        let result: unknown;
        try {
          result = await tool.invoke(call.args, context, site);
        } catch (error) {
          // The one branch in this loop that reads a class rather than a value:
          // a contract the model can satisfy differently goes back to it, and
          // everything else — the exec that exited nonzero, the request that was
          // refused, the child instance that failed, the store that could not
          // answer — leaves the node (Decision D119). `started()` is read on
          // both paths for the reason it is read at all: the link is what the
          // call really filed, so a refusal reports no instance because it
          // started none rather than because this branch assumed so.
          if (error instanceof ToolCallRefused) {
            // The ordinal goes back, because nothing was invoked under it
            // (grammar §9.4, Decision D119). The next call of this tool takes
            // the frame this one was offered, so a loop that got it wrong and
            // then got it right derives the very key a loop that got it right
            // first time derives — and a node `retry:` whose second attempt
            // needs no correction re-derives its first attempt's keys instead
            // of firing every child flow's effects again.
            ordinals.set(call.name, ordinal);
            refuse(call, error, tool.address, started(), ran());
            continue;
          }
          record({
            name: call.name,
            target: tool.address,
            outcome: "failed",
            ...started(),
            error: describe(error),
            ...ran(),
          });
          throw error;
        }
        record({
          name: call.name,
          target: tool.address,
          outcome: "completed",
          ...started(),
          ...(dispatches[before] === undefined ? {} : { result }),
          ...ran(),
        });
        // The call worked, so the loop is holding no refusal: a budget spent
        // after this says the bound stopped a model that was calling correctly
        // and never answered, which is a different run to diagnose.
        refusal = undefined;
        results.push({ id: call.id, name: call.name, content: JSON.stringify(result) });
      }
      turns = [...turns, { role: "tool", results }];
    }
  }

  const { answer: final, served: finalServed } = await callModel(
    agent.model,
    {
      system: agent.prompt,
      // Over a **copy**, and only where a loop ran: `turns` is the conversation
      // this node held, and [`CLOSING_TURN`] is the shape of one request made
      // over it (resolved q52). Appending it to the conversation instead would
      // send this very request and, today, differ in nothing else at all — which
      // is why `turns` is `readonly` above and that way of writing this line
      // does not compile, rather than a test standing where no run can see.
      turns: agent.tools.length > 0 ? [...turns, CLOSING_TURN] : turns,
      tools: agent.tools,
      pinned: agent.output,
    },
    context,
  );
  models.push(finalServed);
  if (final.structured === null) {
    // Why there is no answer, where the surface said: a stated refusal first,
    // and otherwise the stop reason, which is what tells a `max_tokens` cut from
    // a model that simply sent nothing. Without either, "no structured output"
    // is true and says nothing a reader can act on.
    const why =
      final.refusal !== undefined && final.refusal !== null
        ? `: the model declined — ${final.refusal}`
        : final.stopReason === null
          ? ""
          : ` (\`stop_reason: ${final.stopReason}\`)`;
    throw new Error(
      `\`${agent.address}\` asked for \`${agent.output.name}\` and the answer carried no structured output${why}`,
    );
  }
  return {
    output: final.structured,
    history: [
      { role: "user", content: rendered },
      { role: "assistant", content: JSON.stringify(final.structured) },
    ],
    models,
    // Absent rather than empty on the agents that instantiate nothing, which is
    // most of them: `docs/trace.md` §3 gives the key to the entries that have
    // one to report.
    ...(dispatches.length === 0 ? {} : { toolDispatches: dispatches }),
  };
}

/**
 * The assistant turn one loop answer goes back into the conversation as.
 *
 * Two things happen here, and the second is why it is a function rather than an
 * object literal at the call site.
 *
 * The turn is the model's **own** content where the surface sent blocks, rather
 * than a turn rebuilt from the `text` and `toolCalls` this runtime read out of
 * them. Rebuilding drops whatever it does not read — a `thinking` block, which a
 * model with `settings: { thinking: … }` sends with every answer and which the
 * Messages API requires back unaltered beside the `tool_use` blocks it preceded.
 *
 * And an answer that carried **nothing** ends the node here, with a message
 * about the answer. A `max_tokens` cut can end a turn with an empty content
 * list, and the turn built from one is `{"role": "assistant", "content": []}` —
 * a message the Messages API refuses (`content: List should have at least 1
 * item`), as does `crates/mock-provider`, which holds this project to that same
 * wire. Sending it anyway would report the model's empty answer as a provider
 * 400 one call later, about the wrong request.
 */
function replayed(agent: AgentBinding, answer: ModelAnswer): Turn {
  const blocks = answer.content;
  const empty =
    blocks === undefined
      ? (answer.text ?? "") === "" && answer.toolCalls.length === 0
      : blocks.length === 0;
  if (empty) {
    const why = answer.stopReason === null ? "" : ` (\`stop_reason: ${answer.stopReason}\`)`;
    throw new Error(
      `\`${agent.address}\` was answered with no content${why}, so its tool loop has no turn to send back`,
    );
  }
  return {
    role: "assistant",
    text: answer.text ?? "",
    ...(answer.toolCalls.length > 0 ? { toolCalls: answer.toolCalls } : {}),
    ...(blocks === undefined ? {} : { blocks }),
    // Which wire's vocabulary those blocks are, where it is not the Messages
    // one. Absent for a Messages answer on purpose — a key written there would
    // re-key every journal recorded before the second wire existed
    // ([`ContentWire`]).
    ...(answer.wire === undefined ? {} : { wire: answer.wire }),
  };
}

/**
 * What one agent node contributes to the shared history channel: its rendered
 * input, and its structured answer (grammar 10.4, PRD 5.7 tier 3).
 *
 * The intra-agent tool loop's own turns are **not** among them, and the reason
 * is a property of the surface rather than a preference: an assistant turn
 * carrying `tool_use` blocks is only well formed when the very next turn answers
 * every one of them, so a history that kept the loop's turns and was then
 * appended to by the *next* node would hand a provider a conversation it
 * refuses. The loop is the agent's own business — the trace records what it
 * called (PRD 5.3) — and what crosses into the shared channel is the exchange:
 * one user turn in, one assistant turn out, strictly alternating however many
 * agent nodes a flow instance runs.
 */
export type MessageLike = { readonly role: "user" | "assistant"; readonly content: string };

/** The shared history channel as an agent call reads it. */
export function historyTurns(messages: readonly unknown[]): Turn[] {
  return messages.map((message) => {
    const held = message as { role?: string; content?: unknown; getType?: () => string };
    const role = typeof held.getType === "function" ? held.getType() : (held.role ?? "user");
    const text = typeof held.content === "string" ? held.content : JSON.stringify(held.content);
    return role === "ai" || role === "assistant"
      ? ({ role: "assistant", text } as const)
      : ({ role: "user", text } as const);
  });
}

// ---------------------------------------------------------------------------
// `exec` and `http` (grammar 6.1, 8.2, 8.3)
// ---------------------------------------------------------------------------

/** How a result is read out of a process or a response (grammar 8.2, 8.3). */
export interface Decoding {
  /** Envelope fields the surface binds directly, by name. */
  readonly envelope: readonly string[];
  /** Fields decoded from the payload. */
  readonly decoded: readonly string[];
  /**
   * The single string property that takes the raw stream whole — the
   * `tool.*`-surface exception of grammar 6.1, absent on inline nodes (D91).
   *
   * What "whole" means is the surface's, not this descriptor's: see [`decode`].
   */
  readonly raw?: string;
  /** No result at all: nothing is decoded (grammar 6.1's `output: {}`). */
  readonly empty: boolean;
}

/** A resolved `exec:` block. */
export interface ExecBinding {
  readonly command: readonly Interpolation[];
  readonly args: readonly (readonly Interpolation[])[];
  readonly cwd?: readonly Interpolation[];
  readonly env: readonly { readonly name: string; readonly value: readonly Interpolation[] }[];
  readonly expectExit: readonly number[];
  readonly decoding: Decoding;
}

/** The environment-variable spelling of an input field (grammar 6.1). */
export function environmentName(field: string): string {
  return field.toUpperCase();
}

/**
 * The variable a subprocess sink reads its idempotency key out of — the name
 * grammar 9.4's delivery surface fixes for an `exec:`-bound target.
 *
 * The environment rather than the argument vector: `args:` is the author's exact
 * command line and a runtime that appended to it would be changing the program's
 * arguments — while the environment is the out-of-band channel a process already
 * has.
 *
 * The name is a plain one, so [`runExec`] clears it out of the inherited
 * environment first: a target receives it when this runtime delivered it, and
 * not because the process happened to be started with a variable by that name.
 *
 * [`environmentName`] spells an input field by upper-casing it, so a target that
 * declared an input field called `idempotency_key` would name this same
 * variable. **No compiled graph reaches that**: grammar 9.4 says the key is
 * "delivery metadata, never part of the target's declared input schema", and the
 * validator refuses a detached dispatch to an `exec:` sink declaring one rather
 * than letting either value be discarded in silence — the rule Decision D66
 * already applies to the binding's own `env:` (`check::maps`). What is left for
 * this function to settle is the order a *direct* call resolves it in, and it is
 * 9.4's: the delivery is written **after** the input fields, and **before** the
 * binding's own `env:` — the layer an author configures their wire from, which
 * sits over the delivery exactly as a declared header sits over the emitted
 * media type.
 */
export const IDEMPOTENCY_ENV = "IDEMPOTENCY_KEY";

/**
 * The header an HTTP sink reads its idempotency key out of — the name
 * grammar 9.4's delivery surface fixes for an `http:`-bound target, and the one
 * sinks already dedupe on. Header names are case-insensitive and [`headerSet`]
 * folds them, so this is the spelling that reaches the wire rather than a
 * second name for one header.
 */
export const IDEMPOTENCY_HEADER = "Idempotency-Key";

/**
 * A write to a child's standard input that failed for a reason neither EPIPE nor
 * a destroyed stream covers.
 *
 * Its own class because [`runExec`] has one promise and two rejections to tell
 * apart: a spawn the platform refused, where the command never ran, and this,
 * where it did. Restating this one as "could not be run" would assert something
 * false — a reader chasing an `ENOENT` would go looking for a path that is
 * there — so the message is composed at the reject site and carried through the
 * catch untouched.
 */
class ExecInputFailure extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ExecInputFailure";
  }
}

/** Run one `exec:` binding (grammar 6.1, 8.2). */
export async function runExec(
  binding: ExecBinding,
  input: unknown,
  context: RunContext,
): Promise<unknown> {
  // The identity is the **whole binding** as the composition wrote it, rather
  // than as it resolved — which is `docs/trace.md` §11.1's discipline read where
  // the reader is a replay: one composition derives one identity whatever
  // environment it runs in, so an execution journaled on one machine is not
  // reported as divergent on another for having a different `${TOOLBIN}`.
  //
  // Whole, and that is the load-bearing word (`docs/durability.md` §3.2). A
  // `cwd:`, an `env:` entry, an `expect_exit:` and the `output:` shape all
  // change what this call is and what its answer means, so a binding that moved
  // in any of them is a call this run does not make and the recorded answer is
  // not its. Leaving one out would hand the graph an answer recorded under a
  // binding the composition no longer has, silently.
  return await journaled(
    context.effects,
    "tool",
    {
      surface: "exec",
      command: asWritten(binding.command),
      args: binding.args.map((argument) => asWritten(argument)),
      ...(binding.cwd === undefined ? {} : { cwd: asWritten(binding.cwd) }),
      env: binding.env.map((entry) => ({ name: entry.name, value: asWritten(entry.value) })),
      expectExit: binding.expectExit,
      decoding: binding.decoding,
      input,
    },
    () => runExecLive(binding, input, context),
  );
}

/** [`runExec`] with nothing between it and the child process. */
async function runExecLive(
  binding: ExecBinding,
  input: unknown,
  context: RunContext,
): Promise<unknown> {
  const environment: Record<string, string> = { ...(process.env as Record<string, string>) };
  // The delivery slot starts empty, whatever the process was started with. The
  // name grammar 9.4 fixes is a plain one, and a variable that happened to be in
  // this process's environment would otherwise reach every `exec:` target in the
  // composition as a key a sink dedupes on — silently dropping repeat calls that
  // were meant to repeat. A target receives this variable when, and only when,
  // this runtime delivered it (or the binding's own `env:` set it, below).
  delete environment[IDEMPOTENCY_ENV];
  let stdin: string | undefined;
  if (typeof input === "string") {
    stdin = input;
  } else if (input !== null && typeof input === "object") {
    for (const [field, value] of Object.entries(input as Record<string, unknown>)) {
      environment[environmentName(field)] =
        typeof value === "string" ? value : JSON.stringify(value);
    }
  }
  // The key a detached delivery carries, where this call is one (grammar 8.6
  // rule 7, 9.4). Under the declared `env:` for the same reason a declared
  // header sits under the runtime's media type: what the binding wrote out is
  // the author's statement about this process's environment, and an automatic
  // addition that overwrote it would break a sink using its own scheme. Over the
  // input fields, which no compiled graph puts here — the validator refuses a
  // composition whose detached sink declares the slot (see [`IDEMPOTENCY_ENV`])
  // — because a delivery a sink cannot dedupe on is the failure the key exists
  // to prevent.
  if (context.idempotency_key !== undefined) {
    environment[IDEMPOTENCY_ENV] = context.idempotency_key;
  }
  for (const entry of binding.env) {
    environment[entry.name] = interpolate(entry.value);
  }

  const command = interpolate(binding.command);
  const args = binding.args.map((argument) => interpolate(argument));
  // Resolved **here**, beside the command and the args, rather than in the
  // executor below. A `cwd:` whose `${ENV}` reference is unset makes
  // [`environmentValue`] throw, and a throw inside a `new Promise` executor is a
  // rejection — which the catch below restates as "`<command>` could not be
  // run", a message that names the command for a fault in the working
  // directory. Out here the precise `` `REPO_ROOT` is not set (referenced by
  // …) `` propagates as raised, and the catch keeps its one meaning: the
  // platform declined to start a command whose inputs all resolved.
  const cwd = binding.cwd === undefined ? undefined : interpolate(binding.cwd);
  const spawned = new Promise<{ code: number; stdout: string; stderr: string }>(
    (resolve, reject) => {
      const child = spawn(command, args, {
        cwd,
        env: environment,
        signal: context.signal,
      });
      let stdout = "";
      let stderr = "";
      child.stdout.on("data", (chunk: Buffer) => {
        stdout += chunk.toString();
      });
      child.stderr.on("data", (chunk: Buffer) => {
        stderr += chunk.toString();
      });
      child.on("error", reject);
      child.on("close", (code) => resolve({ code: code ?? -1, stdout, stderr }));
      // A command that never reads its input closes the pipe while this write is
      // still in flight, and Node reports that as an `error` **event on the
      // stream** rather than as a rejected promise. Unhandled, an EventEmitter
      // `error` aborts the whole process — past `retry`, `timeout`, `skip` and
      // `fallback` alike (grammar 9), past `runFlow`'s own `catch`, so the run
      // would not even leave the trace PRD 5.3 promises, and under `serve` it
      // would take every concurrent execution down with it. EPIPE is the child
      // declining the input rather than a failure — `printf` declines it by
      // design — so the exit code and the streams stay the result; a destroyed
      // stream is this run being aborted, which the abort path already reports;
      // anything else fails the node through the same promise a spawn error
      // does — but as its own class and with its own message, because the
      // command *ran* and the catch below is written for one that did not
      // (see [`ExecInputFailure`]). Restated here for the reason the spawn
      // failure is restated there: the platform words this one too, and one
      // composition should produce one message whatever environment it runs in.
      child.stdin.on("error", (error: NodeJS.ErrnoException) => {
        if (error.code === "EPIPE" || error.code === "ERR_STREAM_DESTROYED") return;
        reject(
          new ExecInputFailure(
            `\`${asWritten(binding.command)}\`'s standard input could not be written${
              error.code === undefined ? "" : ` (${error.code})`
            }`,
          ),
        );
      });
      if (stdin !== undefined) {
        child.stdin.end(stdin);
      } else {
        child.stdin.end();
      }
    },
  );

  let result: { code: number; stdout: string; stderr: string };
  try {
    result = await spawned;
  } catch (error) {
    // A deadline, or a run somebody cancelled, arrives here as an abort rather
    // than as a failure to start, and it is not this binding's failure — so it
    // is raised as it came, the way [`send`] raises one.
    if (context.signal.aborted) throw error;
    // The other rejection this promise has, already restated where it was
    // raised: the command started and its input could not be written, which is
    // not what the restatement below says (see [`ExecInputFailure`]).
    if (error instanceof ExecInputFailure) throw error;
    // Everything else is the platform declining to run the command, and the
    // message it declines with quotes the **resolved** path: Node says
    // `spawn /opt/tokens/rg ENOENT`, Bun `ENOENT: no such file or directory,
    // posix_spawn '/opt/tokens/rg'`. That string would reach `TraceEntry.error`,
    // the trace file and stderr, which `docs/trace.md` §11.1 says no resolved
    // `${ENV}` value does — so the failure is restated: the command as the
    // composition spells it ([`asWritten`]), and the platform's own error
    // **code**, which names what went wrong without naming what it went wrong
    // on. The same restatement is what keeps one composition producing one
    // message whatever environment it runs in.
    const code = (error as NodeJS.ErrnoException | null | undefined)?.code;
    throw new Error(
      `\`${asWritten(binding.command)}\` could not be run${code === undefined ? "" : ` (${code})`}`,
    );
  }

  if (!binding.expectExit.includes(result.code)) {
    // The command as the composition spells it ([`asWritten`]): a resolved
    // `${ENV}` value has no business in a field the trace carries.
    throw new Error(
      `\`${asWritten(binding.command)}\` exited ${result.code}, which is outside \`expect_exit: [${binding.expectExit.join(", ")}]\`${result.stderr === "" ? "" : `: ${result.stderr.trim()}`}`,
    );
  }

  return decode(
    binding.decoding,
    result.stdout,
    {
      exit_code: result.code,
      stdout: result.stdout,
      stderr: result.stderr,
    },
    "trimmed",
  );
}

// ---------------------------------------------------------------------------
// The built-in tools (grammar 5.5, 6.1, Decision D135, PRD resolved q54)
// ---------------------------------------------------------------------------

/**
 * Which built-in a binding holds (grammar 5.5, 6.1).
 *
 * The two PRD resolved q54 ships, written as the shorthand `builtin.bash` /
 * `builtin.files` in an agent's `tools:` or as a `tool.*` carrying a `builtin:`
 * binding. The set is closed in the grammar and the emitter writes one of these
 * two, so a third name reaching this runtime is a build from another release.
 */
export type BuiltinName = "bash" | "files";

/**
 * One built-in an agent holds, with the bounds its binding declared.
 *
 * Every field but `tool` is a **bound**, and every bound is the binding's rather
 * than the model's: a model that could name its own workspace, its own deadline
 * or its own environment would hold exactly the capability these exist to hold
 * still. What the model chooses is the program — the command, or the file
 * operation and its path — and that is the whole of the trust shift Decision
 * D135 says out loud.
 */
export interface BuiltinBinding {
  /** Which built-in. */
  readonly tool: BuiltinName;
  /**
   * `workspace:` — the directory `bash` starts in and every `files` path
   * resolves inside.
   *
   * Interpolation parts rather than a string, because the value reaches the
   * process at start (grammar 4.3 class 2). **Empty** is the binding that wrote
   * none, which is the execution's own workspace ([`sharedWorkspace`]): one
   * fresh directory per execution, shared by every built-in of that execution
   * that took the default, removed when the execution settles.
   */
  readonly workspace: readonly Interpolation[];
  /**
   * `timeout:` — how long one `bash` command may run. `millis` is what the timer
   * is set to and `written` is what the model is told, so a command that outran
   * it reads in the author's own units.
   *
   * Absent on `builtin.files`, which runs no command. Present on every emitted
   * `bash` binding, written or defaulted to grammar 6.1's 120s.
   */
  readonly timeout?: { readonly millis: number; readonly written: string };
  /**
   * `env:` — the variables this tool's children run with, as written
   * (grammar 4.3 class 2), and **the whole of what they run with** unless
   * [`inheritEnv`] says otherwise.
   *
   * Empty on `builtin.files`, which forks nothing.
   */
  readonly env: readonly { readonly name: string; readonly value: readonly Interpolation[] }[];
  /**
   * `inherit_env:` — whether those children also see this process's own
   * environment, with [`env`] layered over it.
   *
   * Absent is `false`, which is the scrubbed default PRD resolved q54 ruling b
   * fixes: a placement's environment manifest is the whole answer to what a
   * machine is asked for (resolved q41), and a child that inherited this
   * process's environment would read credentials nobody declared to it.
   */
  readonly inheritEnv?: boolean;
}

/**
 * **The model's program**, as `docs/trace.md` §7.4 records it (PRD resolved q54
 * ruling c).
 *
 * The carve-out, and its whole extent. §11 keeps a tool's *answer* out of this
 * format at every surface and that rule is untouched here: a command's stdout
 * and a file's contents are answers, and they stay in the journal. What a
 * built-in adds is the half no other tool has — for every other binding the
 * program is the composition's, written in a spec the reader already has, and
 * for this one the **model wrote it at run time**, so a trace without it would
 * record that an agent ran something and nothing about what.
 *
 * Every field is capped ([`PROGRAM_LIMIT`]) and none of them is a file body: an
 * edit is recorded as [`change`], a sentence this runtime composes about the
 * shape of the edit rather than an excerpt of what was written.
 */
export interface BuiltinProgram {
  /**
   * Which built-in ran it.
   *
   * The union is written out rather than named ([`BuiltinName`], which is the
   * same two members): a record type of this format names only types
   * `docs/trace.md` specifies, and the alias is the *binding's* vocabulary
   * rather than the trace's.
   */
  readonly tool: "bash" | "files";
  /** `bash`: the command as the model wrote it, capped. */
  readonly command?: string;
  /** `files`: which operation it asked for. */
  readonly operation?: "view" | "create" | "str_replace" | "insert";
  /** `files`: the path as the model wrote it, capped — never the resolved one. */
  readonly path?: string;
  /**
   * `bash`: the command's exit status, where one completed.
   *
   * Mutable for [`ModelCall.toolCalls`]' reason: the record is made from the
   * call's arguments, before there is an outcome to put in it.
   */
  exitCode?: number;
  /** `bash`: `true` where the command outran its bound and was killed. */
  timedOut?: boolean;
  /** `files`: what an edit changed, as a sentence — never file contents. */
  change?: string;
}

/**
 * How much of one stream or one file view a call answers with.
 *
 * Not containment — containment is the workspace and the command deadline, and
 * nothing here narrows what an agent may reach. It is a bound on one *answer*,
 * because a tool result is text a model reads and a `cat` of a large file would
 * spend a context window rather than fail. What was cut is **said** in the
 * result rather than left for the model to infer from a round number.
 */
const BUILTIN_OUTPUT_LIMIT = 30_000;

/** The same, for the fields `docs/trace.md` §7.4 carries. */
const PROGRAM_LIMIT = 1_000;

/** How many entries one directory view answers with. [`capped`]'s reason. */
const LISTING_LIMIT = 1_000;

/** How many lines of context an edit's result shows around what it changed. */
const SNIPPET_LINES = 4;

/**
 * How many bytes of one file this runtime will **hold in memory**.
 *
 * [`BUILTIN_OUTPUT_LIMIT`] bounds what a `files` call answers with, and that
 * bound is applied to a string the whole file is already inside of — which is
 * the same gap [`SHELL_BUFFER_LIMIT`] closes on the shell's side, reached from
 * the other end: there a model writes the program, here a model writes the
 * **path**. `view` of a multi-gigabyte file in the workspace would allocate it
 * whole, and then a numbered copy of it, inside a `serve` process that is
 * running every other execution too, to answer with thirty thousand characters
 * of it.
 *
 * So a read stops here. The two operations then divide, because a truncated read
 * means different things to them:
 *
 *  * `view` answers with the **front** of the file and says the rest was not
 *    read — the same statement [`capped`] makes one level along, and a model
 *    that wants the tail of a large file has `bash`;
 *  * `str_replace` and `insert` are **refused**, because an edit reads the whole
 *    file and writes the whole file back: an edit built on a truncated read
 *    would not truncate the answer, it would truncate the file.
 *
 * Comfortably above any source file and far below what would hurt this process.
 */
const FILE_READ_LIMIT = 4_000_000;

/** How much of a file one read takes, on the way to [`FILE_READ_LIMIT`]. */
const FILE_READ_CHUNK = 65_536;

/**
 * Run one built-in call (grammar 5.5, 6.1, PRD resolved q54).
 *
 * The seam every built-in goes through, journaled like every other tool
 * execution: the record holds what the call answered, and a resumed generation
 * is handed it back rather than running the command again
 * (`docs/durability.md` §3.2). That is the whole of what durability owes a
 * built-in — a `bash` that appended a line to a file appends it once across any
 * number of process generations — and the one thing it cannot restore is the
 * shell's own state, because a replayed command is a command that did not run: a
 * generation that resumes past the frontier opens a fresh session in the
 * workspace, whatever the recorded prefix had `cd`ed into.
 *
 * The identity is the **binding as the composition wrote it** plus the arguments
 * the model chose: the tool, the `workspace:` unresolved, `bash`'s `timeout:`,
 * and the environment as written. Unresolved for [`runExec`]'s reason — one
 * composition derives one identity whatever machine it runs on — and *whole* for
 * the other: a workspace that moved is a different directory to work in, a
 * timeout that moved is a different bound to have survived, and an environment
 * that moved is a different program, so none is a call this run makes under the
 * recorded key.
 *
 * **A refusal survives the journal as a refusal.** The two outcomes a tool call
 * has are different kinds of thing (Decision D119): a path that leaves the
 * workspace, a `str_replace` that matched nothing, an `insert` past the end of a
 * file are the model's to correct and go back to it, while a workspace that
 * does not exist is the world's and fails the node. The journal records either
 * as the effect's outcome, and a replayed failure arrives as a plain `Error`
 * carrying the recorded class *name* — so the class is restored on the way out
 * ([`restoredRefusal`]) and a resumed generation bounces what the first
 * generation bounced instead of failing a node over it.
 */
export async function runBuiltin(
  binding: BuiltinBinding,
  args: Record<string, unknown>,
  context: RunContext,
  site: ToolCallSite,
): Promise<unknown> {
  // Filed before the call runs, so the record exists however the call ends: a
  // command that failed the node is exactly the one a reader opens the trace
  // for, and what it holds is an argument the *model* chose rather than an
  // answer this format keeps out (`docs/trace.md` §7.4, §11).
  const program = programOf(binding, args);
  site.builtin.push(program);
  let answered: unknown;
  try {
    answered = await journaled(
      context.effects,
      "tool",
      {
        surface: "builtin",
        tool: binding.tool,
        workspace: asWritten(binding.workspace),
        ...(binding.timeout === undefined ? {} : { timeout: binding.timeout.written }),
        env: binding.env.map((entry) => ({ name: entry.name, value: asWritten(entry.value) })),
        ...(binding.inheritEnv === true ? { inheritEnv: true } : {}),
        input: args,
      },
      () => runBuiltinLive(binding, args, context),
    );
  } catch (error) {
    throw restoredRefusal(error);
  }
  recordOutcome(program, answered);
  return answered;
}

/**
 * A replayed [`ToolCallRefused`], back in its class.
 *
 * The journal keeps an error as its `name` and its `message` and hands a resume
 * a plain `Error` carrying both (`./journal.ts`'s `replayedFailure`), which is
 * right for every failure this runtime *reports* and wrong for the one it
 * **classifies**: [`callAgent`] reads the class to decide whether a call goes
 * back to the model or ends the node, so a refusal that came back as an `Error`
 * would fail a node the generation that recorded it carried on from — a resume
 * doing something the run it is resuming did not.
 *
 * Read off the recorded name, which is the only thing a record keeps of a class.
 * Written here rather than in `./journal.ts` because the class is this module's
 * and the journal is the module beneath it.
 */
function restoredRefusal(error: unknown): unknown {
  if (error instanceof ToolCallRefused) return error;
  if (error instanceof Error && error.name === "ToolCallRefused") {
    return new ToolCallRefused(error.message);
  }
  return error;
}

/** The program half of a call's record: what the model asked for. */
function programOf(binding: BuiltinBinding, args: Record<string, unknown>): BuiltinProgram {
  if (binding.tool === "bash") {
    const command = typeof args["command"] === "string" ? args["command"] : "";
    const written = command.trim() === "" && args["restart"] === true ? "restart" : command;
    return { tool: "bash", command: capped(written, PROGRAM_LIMIT) };
  }
  const operation = String(args["command"] ?? "");
  return {
    tool: "files",
    ...(isFileOperation(operation) ? { operation } : {}),
    path: capped(String(args["path"] ?? ""), PROGRAM_LIMIT),
  };
}

/**
 * The outcome half, read off the **answer** rather than off the call.
 *
 * Which is what makes it survive a resume: a replayed call performs nothing, so
 * a runtime that filled these in where the command ran would write a trace whose
 * built-in calls lost their exit status on every generation but the first. The
 * answer is the journal's, replayed or live.
 */
function recordOutcome(program: BuiltinProgram, answered: unknown): void {
  if (answered === null || typeof answered !== "object") return;
  const result = answered as Record<string, unknown>;
  if (typeof result["exit_code"] === "number") program.exitCode = result["exit_code"];
  if (result["timed_out"] === true) program.timedOut = true;
  if (typeof result["change"] === "string") {
    program.change = capped(result["change"], PROGRAM_LIMIT);
  }
}

/** [`runBuiltin`] with nothing between it and the machine. */
async function runBuiltinLive(
  binding: BuiltinBinding,
  args: Record<string, unknown>,
  context: RunContext,
): Promise<unknown> {
  // Resolved once per call, before anything is touched: every path check below
  // is against a directory that really exists, so a `workspace:` naming one that
  // does not is reported as itself rather than as every path inside it failing
  // to resolve.
  const workspace = await builtinWorkspace(binding, context);
  if (binding.tool === "bash") return await runBuiltinBash(binding, workspace, args, context);
  return await runBuiltinFiles(workspace, args);
}

/**
 * The directory this call works in: the binding's `workspace:`, or the
 * execution's own.
 *
 * A **written** workspace is resolved with `realpath` rather than normalized,
 * because the containment rule of PRD resolved q54 is resolution rather than
 * string prefix — symlinks and `..` count — and comparing a resolved target
 * against an unresolved root would answer the question about two different
 * directories. A workspace that is itself a symlink is perfectly legal; it is
 * the *resolved* one that bounds the calls.
 *
 * One that does not exist fails the call as an execution failure, so the node's
 * `retry:`/`on_error:` decides it (Decision D119): a model cannot make a
 * directory exist by calling differently. The message quotes it **as written**,
 * which is what keeps a resolved `${WORKSPACE}` out of a field the trace carries
 * (`docs/trace.md` §11.1).
 *
 * One that resolves to **nothing** fails the same way, and is checked before
 * anything else because it is the one empty answer the file system would accept:
 * `path.resolve("")` is this process's working directory, so a binding whose
 * `${WORKSPACE}` came back empty would silently bound the tool to wherever the
 * runtime happened to be started — the ambient capability grammar 6.1 refuses in
 * its own words. The parser refuses an empty `workspace:` as written; this is
 * the same rule where only the environment can break it.
 */
async function builtinWorkspace(binding: BuiltinBinding, context: RunContext): Promise<string> {
  if (binding.workspace.length === 0) return await sharedWorkspace(context.execution.id);
  const written = asWritten(binding.workspace);
  const declared = interpolate(binding.workspace);
  if (declared.trim() === "") {
    throw new Error(
      `\`builtin.${binding.tool}\`'s \`workspace:\` \`${written}\` resolved to nothing, and a tool bounded to nothing would be bounded to whatever directory this process was started in`,
    );
  }
  const resolved = await realpathOrAbsent(path.resolve(declared));
  const directory =
    resolved === undefined
      ? false
      : await fs.promises.stat(resolved).then(
          (entry) => entry.isDirectory(),
          () => false,
        );
  if (resolved === undefined || !directory) {
    throw new Error(
      `\`builtin.${binding.tool}\`'s \`workspace:\` \`${written}\` is not a directory that exists, and every path this tool takes resolves inside it`,
    );
  }
  return resolved;
}

/**
 * The execution's own workspace: one fresh directory, shared by every built-in
 * of that execution that wrote no `workspace:` (grammar 6.1).
 *
 * Under the project's data directory rather than the platform's temporary one,
 * for the reason everything else a run leaves behind is: a person asking where
 * an agent's files went finds them beside the journal and the traces, and a
 * directory the operating system may sweep under a running process is a
 * workspace that vanishes mid-node. The generated `README.md` names the layout.
 *
 * **One per execution, not one per tool**, because a composition whose agent
 * writes a file with `builtin.files` and then compiles it with `builtin.bash` is
 * the shape these two tools exist for. The *promise* is memoized rather than the
 * path, so two calls racing in one superstep make one directory.
 *
 * A **worker** running a placed agent reaches this too, and there the execution
 * ends with the dispatch (`docs/distributed.md` §3.2): that process runs one
 * node and exits, so the directory is that node's and goes on the way out. What
 * a placed built-in shares with the rest of its execution is the placement, not
 * the disk — which is what "the machine with the capability" already means.
 */
async function sharedWorkspace(execution: string): Promise<string> {
  const held = executionWorkspaces.get(execution);
  if (held !== undefined) return await held;
  const made = (async (): Promise<string> => {
    const directory = path.join(dataRoot(), "workspaces", execution);
    await fs.promises.mkdir(directory, { recursive: true });
    // `realpath` for [`builtinWorkspace`]'s reason: `AGENT_COMPOSE_DATA_DIR` is
    // a path a person typed and may reach the directory through a symlink,
    // and containment compares resolved locations.
    return await fs.promises.realpath(directory);
  })();
  executionWorkspaces.set(execution, made);
  return await made;
}

/** The workspaces this process has made, by execution ([`sharedWorkspace`]). */
const executionWorkspaces = new Map<string, Promise<string>>();

/**
 * Remove what an execution's built-ins were given, or leave it standing for the
 * generation that will finish the run.
 *
 * `scope: execution` read for a directory: what this run's own workspace held
 * goes when the run ends, however it ended — a `serve` process runs many
 * executions, and a workspace that stayed would be both a leak and a lifetime
 * the composition did not declare.
 *
 * **Unless the run has not ended.** An execution whose journal row stays open —
 * parked at a `human` pause, stopped by a divergence — is one a resume replays,
 * and what it wrote has to still be there when the resumed generation runs past
 * the frontier: a file the recorded prefix created is a file the next command
 * expects to find. It is the rule `./stores.ts` follows for a `scope: execution`
 * store, decided by the same predicate (`staysOpen`) for the same reason
 * (`docs/durability.md` §5).
 *
 * A binding that wrote its own `workspace:` is untouched: the composition named
 * that directory, so its lifetime is the composition's rather than this run's.
 */
export async function releaseWorkspaces(execution: string, parked: boolean): Promise<void> {
  const held = executionWorkspaces.get(execution);
  if (held === undefined) return;
  executionWorkspaces.delete(execution);
  if (parked) return;
  const directory = await held.catch(() => undefined);
  if (directory === undefined) return;
  await fs.promises.rm(directory, { recursive: true, force: true }).catch(() => {
    // A workspace that would not go is not this run's outcome. What is left
    // behind is a directory under `.agent-compose/`, which the generated
    // `README.md` says is safe to remove.
  });
}

/**
 * Whether a resolved path is the workspace or sits beneath it.
 *
 * Both sides are already `realpath`ed by the time this is asked, which is what
 * makes a string comparison the right one *here* and the wrong one anywhere
 * else: what is being compared is two real locations, not two spellings.
 */
function withinWorkspace(workspace: string, target: string): boolean {
  if (target === workspace) return true;
  const prefix = workspace.endsWith(path.sep) ? workspace : `${workspace}${path.sep}`;
  return target.startsWith(prefix);
}

/**
 * The real path one `files` argument names, **refused** if it lands outside the
 * workspace (PRD resolved q54, Decision D119).
 *
 * Two cases, and the second one is why this is not one `realpath` call:
 *
 *  * the path **exists** — it is resolved whole, symlinks and all, and checked;
 *  * it does **not exist yet**, which is every `create` of a new file. Then the
 *    **deepest ancestor that does exist** is resolved and the components below
 *    it are appended lexically, so a write through a symlinked directory is
 *    checked against where that directory really is.
 *
 * That walk climbs rather than stopping at the parent, and the difference is a
 * hole: `create` makes its parent directories (`createFile`), so a
 * `link/deep/file.txt` whose `link` is a symlink out of the workspace and whose
 * `deep` does not exist yet has no parent to resolve — and a check that gave up
 * there would hand back the lexical path, pass the prefix test, and then let
 * `mkdir -p` follow the link and write outside. Resolving the deepest existing
 * ancestor sees `link` for what it is however many missing components sit under
 * it. What is left below that ancestor cannot be a symlink, because it does not
 * exist.
 *
 * A **dangling symlink** is refused rather than written through, and that is the
 * case the second branch would otherwise get wrong: `writeFile` follows a
 * symlink, so a link inside the workspace pointing at a file outside it that
 * does not exist yet would be a write outside the workspace with every check
 * passed.
 *
 * What this cannot see is a **hard** link, and that is a fact about resolution
 * rather than an oversight: a second name for one inode has no target, so
 * `realpath` answers with the path inside the workspace and is right to. The
 * write is the half that reaches out, and it is refused where the write is made
 * ([`refuseSecondName`]) rather than here.
 *
 * The refusal goes **back to the model**: it chose the path and can choose
 * another, which is exactly what Decision D119 divides on.
 */
async function targetWithinWorkspace(
  workspace: string,
  requested: string,
): Promise<string> {
  const absolute = path.resolve(workspace, requested);
  const resolved = await realpathOrAbsent(absolute);
  let target = resolved;
  if (target === undefined) {
    const link = await fs.promises.lstat(absolute).then(
      (entry) => entry.isSymbolicLink(),
      () => false,
    );
    if (link) {
      throw new ToolCallRefused(
        `\`${FILE_TOOL}\` will not follow \`${requested}\`: it is a symbolic link whose target does not exist, so where it points cannot be checked against this tool's workspace`,
      );
    }
    target = await underDeepestExisting(absolute);
  }
  if (!withinWorkspace(workspace, target)) {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` refused \`${requested}\`: it resolves outside this tool's workspace, which every path it takes is relative to. Ask again with a path inside the workspace — one with no leading \`/\`, and no \`..\` that climbs out of it`,
    );
  }
  return target;
}

/** A path's real location, or `undefined` where nothing is there to resolve. */
async function realpathOrAbsent(target: string): Promise<string | undefined> {
  return await fs.promises.realpath(target).then(
    (resolved) => resolved,
    () => undefined,
  );
}

/**
 * A path that does not exist, rebuilt on the real location of the deepest
 * ancestor that does.
 *
 * The climb ends at the filesystem root, where `path.dirname` stops moving —
 * and a root that will not `realpath` is a host this runtime has nothing to say
 * about, so the lexical path is what comes back and the caller's own prefix test
 * decides it. `path.resolve` has already collapsed every `..`, so that fallback
 * still refuses a climb out of the workspace.
 */
async function underDeepestExisting(absolute: string): Promise<string> {
  const below: string[] = [];
  let ancestor = absolute;
  for (;;) {
    const parent = path.dirname(ancestor);
    if (parent === ancestor) return absolute;
    below.unshift(path.basename(ancestor));
    const real = await realpathOrAbsent(parent);
    if (real !== undefined) return path.join(real, ...below);
    ancestor = parent;
  }
}

// ---------------------------------------------------------------------------
// `builtin.bash`: one shell session per node activity
// ---------------------------------------------------------------------------

/**
 * One `builtin.bash` shell, held for as long as the agent node activity that
 * opened it (PRD resolved q54).
 *
 * A session rather than a fork per command, because the two are different tools
 * to a model: `cd build` followed by `make` is one thought, and a runtime that
 * forked twice would answer the second call from the workspace root with the
 * model's own account of what it had already done as the only record. So the
 * shell is a child process with its standard input open, commands are *typed*
 * into it, and its working directory, its variables, its functions and its shell
 * options carry from one call to the next.
 *
 * **Where a session begins and ends is the node activity**, which is the
 * ordinal-reset rule read for a shell: an agent-node `retry:` runs the activity
 * again, and the second attempt opens a shell of its own rather than inheriting
 * the directory the failed attempt happened to be in — the same statement
 * grammar 9.4 makes about the keys a retried attempt derives. [`callAgent`] ends
 * them ([`endShellSessions`]) whichever way its loop leaves.
 */
interface ShellSession {
  /** The shell itself. */
  readonly child: ReturnType<typeof forkBoundShell>;
  /** What the marker protocol is keyed on: one random id per session. */
  readonly marker: string;
  /** What has been read off each pipe since the last command settled. */
  stdout: string;
  stderr: string;
  /** Where the command in flight is answered, if one is. */
  pending?: (settled: ShellAnswer) => void;
  /** Whether this shell is gone — killed, or exited under the model. */
  ended: boolean;
  /** How it went, for the notice the next call carries. */
  ending?: string;
}

/** What one typed command answered. */
interface ShellAnswer {
  readonly stdout: string;
  readonly stderr: string;
  /** `$?`, absent where no command completed. */
  readonly code?: number;
  /** Whether the command outran the binding's `timeout:` and was killed. */
  readonly timedOut?: boolean;
  /** How the *session* ended under the command, where it did. */
  readonly ended?: string;
}

/**
 * The shells one node activity is holding, keyed by the binding that opened
 * each.
 *
 * A `WeakMap` on the **context**, which is what makes "one session per node
 * activity" a fact of the structure rather than a convention: [`runActivity`]
 * builds one context per attempt and hands it to the activity, so two attempts
 * of one node are two keys and a `map`'s dispatched items are one key each.
 * Nothing enumerates it — [`endShellSessions`] is handed the context it is
 * closing — so a context that ended without reaching that call is collected with
 * its sessions rather than held for the life of the process.
 *
 * Keyed **within** a context by the binding as written, because two `bash` tools
 * on one agent are two shells: different workspaces, different environments,
 * different bounds. One tool attached twice is one shell, which is what an
 * author means by attaching one tool.
 */
const shellSessions = new WeakMap<RunContext, Map<string, ShellSession>>();

/** The key one binding's session is held under ([`shellSessions`]). */
function sessionKeyOf(binding: BuiltinBinding): string {
  return JSON.stringify([
    asWritten(binding.workspace),
    binding.timeout?.written ?? "",
    binding.env.map((entry) => [entry.name, asWritten(entry.value)]),
    binding.inheritEnv === true,
  ]);
}

/**
 * End every shell one node activity opened.
 *
 * Called by [`callAgent`] on its way out, however it leaves: the session is the
 * activity's, and a shell that outlived it would be a process holding the event
 * loop open with a working directory inside a workspace the run may be about to
 * remove. A node deadline that abandons the activity mid-call is covered by the
 * abort listener each session registers instead, which fires where there is no
 * `finally` left to run.
 */
export function endShellSessions(context: RunContext): void {
  const held = shellSessions.get(context);
  if (held === undefined) return;
  shellSessions.delete(context);
  for (const session of held.values()) endShell(session, "the agent node that opened it ended");
}

/** End one shell, and the process group it leads. */
function endShell(session: ShellSession, why: string): void {
  if (!session.ended) {
    session.ended = true;
    session.ending = why;
    killCommandGroup(session.child);
    releaseCommand(session.child);
    // …and this runtime's **hold** on what the kill could not reach, which is
    // the other half of ending a session. A process that left the group
    // deliberately — `set -m` and a backgrounded job is the portable spelling,
    // a double-forking daemon the other — survives the group kill and can still
    // be holding the pipes this session is reading. Left attached, the `data`
    // handlers go on appending to a buffer nobody will ever read, and the open
    // handles go on holding the event loop: in `serve`, or any host embedding a
    // compiled graph, unbounded memory and a process that will not exit,
    // minutes after the node that opened the shell has finished. So the streams
    // are dropped rather than merely ignored (grammar 5.5, Decision D124).
    for (const stream of [session.child.stdin, session.child.stdout, session.child.stderr]) {
      stream.removeAllListeners("data");
      stream.destroy();
    }
    session.child.unref();
  }
  const pending = session.pending;
  session.pending = undefined;
  pending?.({ stdout: session.stdout, stderr: session.stderr, ended: why });
}

/**
 * The session this call runs in, opened where the activity has none.
 *
 * A shell that **ended** — killed at a command deadline, or exited because the
 * model typed `exit` — is replaced here rather than reported as a failure: the
 * model asked for a command, and a runtime that answered "your shell is gone"
 * would spend an iteration of the loop on bookkeeping. What it *is* told is that
 * the state went with it, which is the part it has to know
 * ([`shellNotice`]).
 */
async function shellFor(
  binding: BuiltinBinding,
  workspace: string,
  context: RunContext,
): Promise<{ session: ShellSession; restarted?: string }> {
  let held = shellSessions.get(context);
  if (held === undefined) {
    held = new Map<string, ShellSession>();
    shellSessions.set(context, held);
  }
  const key = sessionKeyOf(binding);
  const existing = held.get(key);
  if (existing !== undefined && !existing.ended) return { session: existing };
  const session = await openShell(binding, workspace, context);
  held.set(key, session);
  return existing === undefined ? { session } : { session, restarted: existing.ending };
}

/**
 * Fork one `builtin.bash` shell into a process group of its own, with the stop
 * sweep armed **first**.
 *
 * The one place a shell is forked, and it exists to make that ordering a fact
 * rather than a habit: the arming and the fork are two adjacent statements whose
 * order is the whole of [`armCommandSweep`]'s window argument, and a call site
 * that reached `spawn` directly would reopen it. `crates/compose-core/src/
 * codegen/runtime.rs` reads this body and holds the two lines in this order.
 *
 * `detached` is what puts the shell in a group of its own (see
 * [`killCommandGroup`] for why the group is the unit). There is no `signal:`
 * here, because the shell outlives the call: what ends it is [`endShell`], from
 * the node's abort listener, from [`callAgent`]'s way out, or from a command's
 * own deadline.
 *
 * The **executable is resolved before the fork** rather than looked up by name,
 * because the child's environment is scrubbed: `spawn` resolves the program
 * against the environment it is *giving the child*, so a `bash` looked up by
 * name would be looked for on a `PATH` the binding may never have declared.
 * Resolving it here keeps PRD resolved q54's posture — the shell comes off *this
 * process's* `PATH` at the call, and a host without one fails the call naming
 * the requirement — while the child still sees only what the binding declared.
 *
 * The return type is **inferred** rather than written, which is the one place
 * this file leaves one off: the overload `spawn` resolves for this `stdio` tuple
 * types the three pipes as streams, and naming a wider type here would put a
 * null check on every read of them for a stream this call can never be without.
 */
function forkBoundShell(executable: string, workspace: string, environment: NodeJS.ProcessEnv) {
  armCommandSweep();
  try {
    return spawn(executable, SHELL_ARGUMENTS, {
      cwd: workspace,
      stdio: ["pipe", "pipe", "pipe"],
      detached: true,
      env: environment,
    });
  } catch (error) {
    if (runningCommands.size === 0) standDown();
    throw error;
  }
}

/**
 * How the shell is started: no startup files, and commands off standard input.
 *
 * `--noprofile --norc` because a session that read a person's shell
 * configuration would answer differently on two machines running one
 * composition — and, under the scrubbed environment, would be looking for those
 * files with no `HOME` to find them under. `-s` is "read commands from standard
 * input", which is what makes this a session rather than a command.
 */
const SHELL_ARGUMENTS = ["--noprofile", "--norc", "-s"];

/** Open one shell for this binding, in this workspace. */
async function openShell(
  binding: BuiltinBinding,
  workspace: string,
  context: RunContext,
): Promise<ShellSession> {
  const executable = await shellExecutable();
  const child = forkBoundShell(executable, workspace, shellEnvironment(binding));
  holdCommand(child);
  const session: ShellSession = {
    child,
    marker: `__agent_compose_${globalThis.crypto.randomUUID().replace(/-/g, "")}`,
    stdout: "",
    stderr: "",
    ended: false,
  };
  child.stdout.setEncoding("utf8");
  child.stderr.setEncoding("utf8");
  // A write to a shell that died between the check and the write — the model's
  // own `exit`, a `kill` from outside, the deadline — arrives as an `error` on
  // this stream, and an `error` nothing listens for ends the process. What
  // answers such a call is the session ending ([`endShell`], from `close`), so
  // the write's own failure has nothing left to say.
  child.stdin.on("error", () => {});
  child.stdout.on("data", (chunk: string) => {
    session.stdout += chunk;
    settleShell(session);
    holdShellOutput(session);
  });
  child.stderr.on("data", (chunk: string) => {
    session.stderr += chunk;
    settleShell(session);
    holdShellOutput(session);
  });
  // A shell this runtime could not start — no such file, a `bash` that is not
  // executable — arrives here rather than as a throw, and ends the session with
  // the reason. The call waiting on it is answered by [`endShell`].
  child.on("error", (error) => endShell(session, `the shell could not be run: ${describe(error)}`));
  child.on("close", () => endShell(session, "the shell exited"));
  // A node deadline (grammar 9.2) or a cancelled run aborts the context's
  // signal, and a shell is the one thing a compiled graph holds that would go on
  // running afterwards: the node has stopped waiting and the process group is
  // still inside the workspace. Registered once per session rather than once per
  // command, because the session is what outlives a call.
  context.signal.addEventListener("abort", () => endShell(session, "the run was stopped"), {
    once: true,
  });
  // …and the abort that arrived **while this shell was being opened**, which the
  // listener above would never hear: a listener registered on an already-aborted
  // signal is never called, so a shell forked in the window between the deadline
  // firing and this line would be one nothing was left to kill. Ended here
  // instead, which the caller then reports as the session having gone.
  if (context.signal.aborted) endShell(session, "the run was stopped");
  return session;
}

/**
 * The environment the shell and its children run with (PRD resolved q54
 * ruling b).
 *
 * **Scrubbed by default**: only what the binding declared, so a placement's
 * environment manifest is the whole answer to what a machine is asked for
 * (resolved q41) and a model-authored command cannot read a credential nobody
 * handed it. `inherit_env: true` is the explicit opt-in for the machines where
 * inheriting is the point, and a declared `env:` still layers over it — the
 * binding is the author's statement about this process's environment, exactly as
 * it is for an `exec:` tool.
 *
 * A scrubbed environment has no `PATH`, and `bash` supplies its compiled-in
 * default where it finds none — which is why the shorthand is usable at all on
 * an ordinary host. A composition that wants a `PATH` it can name declares one,
 * which is what the `env:` in grammar 6.1's own example is.
 */
function shellEnvironment(binding: BuiltinBinding): NodeJS.ProcessEnv {
  const environment: NodeJS.ProcessEnv =
    binding.inheritEnv === true ? { ...process.env } : {};
  for (const entry of binding.env) environment[entry.name] = interpolate(entry.value);
  return environment;
}

/**
 * Where `bash` is on this host, resolved from **this process's** `PATH` at the
 * call.
 *
 * The posture PRD resolved q54 fixes: a host with no shell fails the call as an
 * execution failure naming the requirement, rather than the compiler deciding at
 * build time what a deployment machine has.
 */
async function shellExecutable(): Promise<string> {
  for (const directory of (process.env["PATH"] ?? "").split(path.delimiter)) {
    if (directory === "") continue;
    const candidate = path.join(directory, "bash");
    const usable = await fs.promises.access(candidate, fs.constants.X_OK).then(
      () => true,
      () => false,
    );
    if (usable) return candidate;
  }
  throw new Error(
    "`builtin.bash` could not be run: this host has no `bash` on `PATH`, which the tool resolves it from at the call",
  );
}

/**
 * Run one command in this activity's shell and answer with what it printed
 * (grammar 5.5, 6.1, PRD resolved q54).
 *
 * **An exit status is an answer, not a failure.** A command that exited nonzero
 * is a fact the model asked for — a test that failed, a file that was not there
 * — and the model is what decides what to do about it, so the status comes back
 * beside the output rather than ending the node. It is the split Decision D119
 * draws everywhere else, read where the *model* writes the program: what fails
 * the node is the tool being unusable — no shell on the host, a workspace that
 * does not exist — and never what a command said.
 *
 * **A command that outruns its bound is killed and reported**, for that same
 * reason. The kill takes the shell's whole process group, because the shell is
 * almost never where the work is (`npm run build`, `a | b`,
 * `(cd sub && make)` are all `bash` forking) — so the session goes with it and
 * the next call opens a fresh one in the workspace. The model is told exactly
 * that, because the shell state it was relying on is what it lost.
 *
 * **A `restart` ends the session, and a command sent with it runs in the fresh
 * one.** The provider-defined tool's parameter is written for the restart alone,
 * and that is the call this answers with a notice and *no* status: nothing ran,
 * so there is no `exit_code` to report and none in the trace's record of it
 * (`docs/trace.md` §7.4). A model that sent both asked for a shell it could
 * trust and a command in it, which is one call rather than two — so the command
 * runs, after the restart, and comes back with its own status. What it must
 * never be is dropped: a discarded command answered `exit_code: 0` would tell
 * the model its write happened and leave the trace claiming a command ran on
 * this host that never did, which is worse than recording nothing at all.
 */
async function runBuiltinBash(
  binding: BuiltinBinding,
  workspace: string,
  args: Record<string, unknown>,
  context: RunContext,
): Promise<unknown> {
  const command = typeof args["command"] === "string" ? args["command"] : "";
  const restart = args["restart"] === true;
  if (!restart && command.trim() === "") {
    // The one shape the schema admits and the tool cannot: `restart` is
    // optional, so `{}` parses, and a call with neither a command nor a restart
    // has asked for nothing. Back to the model, which can say which it meant
    // (Decision D119).
    throw new ToolCallRefused(
      "`bash` was called with no `command` and no `restart`: send the shell command to run, or `restart: true` to start a fresh shell session",
    );
  }
  if (restart) {
    const held = shellSessions.get(context)?.get(sessionKeyOf(binding));
    if (held !== undefined) endShell(held, "the model asked for a restart");
  }
  if (command.trim() === "") {
    // A restart on its own. The shell is opened here rather than left to the
    // next call, so a `restart` that cannot open one fails now — with the
    // reason — instead of on whatever command follows it.
    await shellFor(binding, workspace, context);
    return {
      // No `exit_code`: no command ran, and a status invented for a call that
      // ran nothing would say one completed here and be copied into the trace
      // as such (`docs/trace.md` §7.4's presence rule for the field).
      stdout: "",
      stderr: "",
      notice:
        "the shell session was restarted: its working directory is the workspace again, and no shell state carried over",
    };
  }
  // A command sent *with* a restart lands here too, in the shell the restart
  // just left ended — so [`shellFor`] opens the fresh one and reports the
  // restart back through [`shellNotice`], the way it does for a session that
  // ended any other way.
  const { session, restarted } = await shellFor(binding, workspace, context);
  const answer = await typeIntoShell(session, command, binding.timeout, context);
  const notice = shellNotice(binding, answer, restarted);
  return {
    stdout: trimmedMiddle(answer.stdout),
    stderr: trimmedMiddle(answer.stderr),
    ...(answer.code === undefined ? {} : { exit_code: answer.code }),
    ...(answer.timedOut === true ? { timed_out: true } : {}),
    ...(notice === undefined ? {} : { notice }),
  };
}

/** What the model is told about its *session*, beside what the command printed. */
function shellNotice(
  binding: BuiltinBinding,
  answer: ShellAnswer,
  restarted: string | undefined,
): string | undefined {
  const next =
    "the next call opens a fresh shell in the workspace, with none of this session's state";
  if (answer.timedOut === true) {
    return `the command ran longer than \`${binding.timeout?.written ?? ""}\` and was killed, with what it had printed by then returned above; ${next}`;
  }
  if (answer.ended !== undefined) return `${answer.ended}; ${next}`;
  if (restarted !== undefined) {
    return `${restarted}, so this command ran in a fresh shell in the workspace, with none of the previous session's state`;
  }
  return undefined;
}

/**
 * Type one command into a live shell and wait for the marker that closes it.
 *
 * A session cannot be asked "has the command finished" the way a forked one can
 * — nothing exits — so the shell is asked to **say so**: the command is followed
 * by two `printf`s writing a per-session marker, one to each stream, and the
 * call settles when both have arrived. The exit status rides the stdout marker,
 * which is the one place `$?` is still the command's.
 *
 * The marker is random per session rather than a constant, so text the *model*
 * writes cannot close a command early by printing one — a `printf` of a fixed
 * string would be a command able to make its own status up. It is not a boundary
 * against a command that reads its own environment: the trust level is the one
 * D135 names, and this is about accidents rather than about containment.
 *
 * **The command gets a standard input of its own**, and that is not a detail: the
 * shell reads its *script* from standard input (`-s`, [`SHELL_ARGUMENTS`]), which
 * is the same pipe these lines are typed into — so a command that reads standard
 * input reads the protocol. `read -r line` eats the `…_status=$?` line and the
 * call settles with no status at all; `cat`, `head -n 1`, anything interactive
 * eats both `printf`s, burns the whole `timeout:` and answers the model with this
 * runtime's own marker text as the command's output. So the command runs inside a
 * brace group redirected from `/dev/null`, and a `read` that finds nothing is the
 * honest answer to a shell with no input to give.
 *
 * A brace group rather than a subshell, because a subshell would end the session
 * the tool is for: `cd build` has to still be true for the next call, and so do
 * the variables, the functions and the shell options. A group runs in this shell.
 *
 * The status is read into a variable **inside** the group, for two reasons: the
 * `printf` that reports it would otherwise be what `$?` is about, and the
 * assignment is what keeps the group from ever being empty — a command that is
 * only a comment would otherwise close as `{ }`, a syntax error that ends the
 * session. A command with an unterminated construct still ends it, and better
 * than it did before: the group's `}` closes the parse, so the shell says
 * `syntax error` and exits at once rather than waiting out the bound for a
 * command it was never going to run.
 *
 * Three things end the wait besides the marker, and each is answered where it
 * belongs: the command's own deadline and a shell that exited under it are facts
 * about the model's program and come back to the model, while a **cancelled
 * run** is raised as it came, because there is no model left to answer.
 */
async function typeIntoShell(
  session: ShellSession,
  command: string,
  bound: BuiltinBinding["timeout"],
  context: RunContext,
): Promise<ShellAnswer> {
  if (context.signal.aborted) throw abortReason(context.signal);
  // Nothing the last command left is this one's. A background job it started can
  // still be writing, and that output belongs to the call that started it.
  session.stdout = "";
  session.stderr = "";
  const answer = await new Promise<ShellAnswer>((resolve) => {
    let done = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const settle = (settled: ShellAnswer): void => {
      if (done) return;
      done = true;
      if (timer !== undefined) clearTimeout(timer);
      session.pending = undefined;
      resolve(settled);
    };
    if (bound !== undefined) {
      timer = setTimeout(() => {
        const printed = { stdout: session.stdout, stderr: session.stderr };
        // Taken away from [`endShell`] first: the kill settles whatever call the
        // session is holding, and this call is the deadline's to answer.
        session.pending = undefined;
        endShell(session, "the command outran its bound");
        settle({ ...printed, timedOut: true });
      }, bound.millis);
    }
    session.pending = settle;
    // The group, its `/dev/null`, and the assignment inside it are all load
    // bearing — see this function's own note on each.
    session.child.stdin.write(
      `{ ${command}\n${session.marker}_status=$?\n} < /dev/null\nprintf '\\n%s:%s\\n' '${session.marker}' "$${session.marker}_status"\nprintf '\\n%s\\n' '${session.marker}' >&2\n`,
    );
  });
  if (context.signal.aborted) throw abortReason(context.signal);
  return answer;
}

/**
 * Settle the command in flight where both of its markers have arrived.
 *
 * Both, and in the order the shell wrote them rather than the order they were
 * read: the two pipes are independent, so a command whose stderr arrives after
 * its stdout marker would otherwise be answered with the stderr of a command
 * that had not finished being reported.
 *
 * What follows a marker is left in the buffer rather than thrown away here —
 * the platform can deliver a marker and the bytes after it in one chunk — and
 * the **next command clears it** ([`typeIntoShell`]), which is where that
 * decision belongs: late output is a background job's, and a job belongs to the
 * command that started it, so attributing its writing to the next command would
 * be worse than losing it.
 */
function settleShell(session: ShellSession): void {
  const pending = session.pending;
  if (pending === undefined) return;
  const closing = `\n${session.marker}:`;
  const at = session.stdout.indexOf(closing);
  if (at < 0) return;
  const rest = session.stdout.slice(at + closing.length);
  const ends = rest.indexOf("\n");
  if (ends < 0) return;
  const marked = `\n${session.marker}\n`;
  const errored = session.stderr.indexOf(marked);
  if (errored < 0) return;
  const status = Number.parseInt(rest.slice(0, ends), 10);
  const stdout = session.stdout.slice(0, at);
  const stderr = session.stderr.slice(0, errored);
  session.stdout = rest.slice(ends + 1);
  session.stderr = session.stderr.slice(errored + marked.length);
  session.pending = undefined;
  pending({ stdout, stderr, ...(Number.isNaN(status) ? {} : { code: status }) });
}

/**
 * How much of one command's output this runtime will **hold in memory** before
 * it starts dropping the middle of it.
 *
 * [`BUILTIN_OUTPUT_LIMIT`] bounds what a call *answers with*, and that bound is
 * applied when the call settles — which is too late for the one command that can
 * hurt this process rather than the model's context window: `cat` of a large
 * file, a build that prints a megabyte a second, `yes` left running. Those are
 * bytes this runtime accumulates as they arrive, and a model writes the program.
 *
 * So the buffer is held to this, and what is dropped is the **middle**: the head
 * is what a result answers with, and the tail is where the marker that closes
 * the command will be ([`settleShell`]) — so trimming has to keep both or it
 * would either lose the answer or lose the command's own ending. The drop is
 * said in the text rather than silent, for [`capped`]'s reason.
 */
const SHELL_BUFFER_LIMIT = 1_000_000;

/**
 * How much of the **tail** a trim keeps: comfortably more than one chunk, so a
 * marker split across two reads is never cut in half by the trim between them.
 */
const SHELL_TAIL = 65_536;

/** Hold one session's buffers to [`SHELL_BUFFER_LIMIT`]. */
function holdShellOutput(session: ShellSession): void {
  session.stdout = held(session.stdout);
  session.stderr = held(session.stderr);
}

/** One buffer, with the middle dropped where it has outgrown the bound. */
function held(buffered: string): string {
  if (buffered.length <= SHELL_BUFFER_LIMIT) return buffered;
  const dropped = buffered.length - BUILTIN_OUTPUT_LIMIT - SHELL_TAIL;
  return `${buffered.slice(0, BUILTIN_OUTPUT_LIMIT)}\n…[${dropped} characters dropped as they arrived: this command printed more than this runtime holds]\n${buffered.slice(-SHELL_TAIL)}`;
}

/**
 * Kill a `builtin.bash` shell **and every process it started**.
 *
 * The shell is spawned `detached`, which on a POSIX host makes it the leader of
 * a process group of its own; a signal sent to the negated pid goes to the whole
 * group, which is where the commands' real work lives. That distinction is the
 * whole point of this function: `npm run build` is a shell that forks, and a
 * `SIGKILL` aimed at the session's own pid ends the session while the build
 * keeps compiling — inside the very workspace the binding bounded it to, for as
 * long after the node ended as it likes.
 *
 * What still escapes is what **left the group deliberately**: a command that
 * calls `setsid`, one that turned job control on (`set -m`), a daemon that
 * double-forks away. Those are the same processes a hand-rolled `exec:` tool
 * would leave behind, and containing them is the distribution work's rather than
 * this bound's (grammar 5.5, Decision D124).
 *
 * The fallback is for the host where the group kill is not a thing —
 * `process.kill` with a negative pid is a POSIX call, and Windows is a posture
 * q54 defers — where killing the shell alone is still better than killing
 * nothing. Both are guarded: a group that has already gone answers `ESRCH`, and
 * a spawn that never started has no pid to aim at.
 */
function killCommandGroup(child: ChildProcess): void {
  const pid = child.pid;
  if (pid !== undefined) {
    try {
      process.kill(-pid, "SIGKILL");
      return;
    } catch {
      // Already gone, or a host without process groups: fall through.
    }
  }
  try {
    child.kill("SIGKILL");
  } catch {
    // Already gone. The deadline's job is that nothing is left running, and
    // nothing is.
  }
}

/** The `builtin.bash` shells this process has running right now. */
const runningCommands = new Set<ChildProcess>();

/** The stop signals swept for, and the handlers installed for them. */
const SWEPT_SIGNALS = ["SIGINT", "SIGTERM"] as const;
const commandSweeps: (() => void)[] = [];

/**
 * Arrange for a stop signal to take a shell's process group with it, from
 * **before** the shell that group belongs to exists.
 *
 * A detached shell is one the **terminal** can no longer reach: its group is not
 * the foreground one any more, so the `SIGINT` a person types reaches this
 * process and nothing below it. Left there, `Ctrl-C` on a `run` would end the
 * graph and leave the build it was in the middle of still writing into the
 * workspace — a regression against a hand-rolled `exec:` tool, whose child *is*
 * in that group and does die. So the group a session detached is swept here
 * instead, and what the terminal used to do the runtime now does.
 *
 * **Armed before the fork rather than after it**, which is an ordering and not a
 * detail. A stop signal has a *disposition* before it has a listener: until the
 * first `process.on` for it, the platform installs no handler and the kernel's
 * default ends this process where it stands — nothing runs, this module
 * included. A shell forked before that call is therefore a shell whose group a
 * `Ctrl-C` in the window between the two would leave running, with the graph
 * that started it gone: exactly the escape the sweep exists to close, in the one
 * instant it is easiest to reach. Once the handler is installed the window
 * cannot reopen — a listener runs between turns of the loop, and the spawn and
 * the [`holdCommand`] beside it are one turn — so arming first is the whole of
 * the fix. `crates/compose-core/src/codegen/runtime.rs` pins the order.
 *
 * Two properties keep this from being a runtime that seizes an embedder's
 * signals. The handlers exist **only while a shell does** — armed for the first,
 * removed with the last, so a process running none has exactly the disposition
 * it had before this module was imported, and a spawn that throws stands them
 * down again on its way out. And the sweep **re-raises**: it kills the groups,
 * stands down, and delivers the same signal again, so whatever would have
 * happened — `serve`'s own handler closing the app (`src/serve.ts`), or the
 * default disposition ending the process — happens, unchanged and with the same
 * exit status (grammar 5.5, Decision D124).
 */
function armCommandSweep(): void {
  if (commandSweeps.length > 0) return;
  for (const signal of SWEPT_SIGNALS) {
    const sweep = (): void => {
      for (const running of runningCommands) killCommandGroup(running);
      runningCommands.clear();
      standDown();
      process.kill(process.pid, signal);
    };
    commandSweeps.push(() => process.removeListener(signal, sweep));
    process.on(signal, sweep);
  }
}

/** Register a running shell with the sweep [`armCommandSweep`] armed. */
function holdCommand(child: ChildProcess): void {
  armCommandSweep();
  runningCommands.add(child);
}

/** Drop a shell that has ended, and the sweep with the last of them. */
function releaseCommand(child: ChildProcess): void {
  runningCommands.delete(child);
  if (runningCommands.size === 0) standDown();
}

/** Remove the sweep handlers, giving the process back the disposition it had. */
function standDown(): void {
  for (const remove of commandSweeps.splice(0)) remove();
}

// ---------------------------------------------------------------------------
// `builtin.files`: the text editor, under the workspace
// ---------------------------------------------------------------------------

/**
 * The name the model calls the file tool by, which is the provider's rather than
 * this compiler's (grammar 6.1, PRD resolved q54 ruling d).
 *
 * On the Messages wire these go out as the provider-defined tool types, and each
 * of those carries a name the wire dictates; the other wires declare the same
 * name as an ordinary function tool, so one set of handlers serves all of them.
 * Written here because it is what a **message** the model reads has to call it.
 */
const FILE_TOOL = "str_replace_based_edit_tool";

/** The operations this file tool implements, in the order grammar 6.1 lists them. */
const FILE_OPERATIONS = ["view", "create", "str_replace", "insert"] as const;

/** One of them. */
type FileOperation = (typeof FILE_OPERATIONS)[number];

/** Whether a string the model sent names one. */
function isFileOperation(value: string): value is FileOperation {
  return (FILE_OPERATIONS as readonly string[]).includes(value);
}

/**
 * Run one `builtin.files` call (grammar 5.5, 6.1, PRD resolved q54).
 *
 * The operations and their parameter names are Anthropic's text-editor tool's,
 * because on the Messages wire this *is* that tool and a trained model fills
 * exactly those names — so the same handlers serve the OpenAI wires, where the
 * compiler declares the same shape as a function tool.
 *
 * **Every failure of a path is the model's to correct**, and goes back to it as
 * a refusal (Decision D119): a path outside the workspace, a file that is not
 * there, a `str_replace` that matched nothing or matched twice, an `insert` past
 * the end of a file. Each is a statement about arguments the model chose, and it
 * can choose again — failing the agent node because a model guessed a filename
 * wrong would end a run over something the next call would have fixed. What
 * fails the node is the **workspace** being unusable, which no call can fix.
 */
async function runBuiltinFiles(
  workspace: string,
  args: Record<string, unknown>,
): Promise<unknown> {
  const operation = String(args["command"] ?? "");
  if (!isFileOperation(operation)) {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` was asked for \`command: "${operation}"\`, which is not one of ${FILE_OPERATIONS.map((name) => `\`${name}\``).join(", ")}`,
    );
  }
  const requested = String(args["path"] ?? "");
  const target = await targetWithinWorkspace(workspace, requested);
  const text = (name: string): string => (typeof args[name] === "string" ? args[name] : "");
  switch (operation) {
    case "view":
      return await viewPath(requested, target);
    case "create":
      return await createFile(requested, target, text("file_text"));
    case "str_replace":
      return await replaceInFile(requested, target, text("old_str"), text("new_str"));
    default:
      return await insertIntoFile(
        requested,
        target,
        typeof args["insert_line"] === "number" ? args["insert_line"] : 0,
        text("new_str"),
      );
  }
}

/**
 * `view`: a file's contents with line numbers, or a directory's entries.
 *
 * Numbered because the two editing operations are addressed by line — `insert`
 * takes one, and a `str_replace` a model composes from a numbered view is one it
 * can see is unique — and because it is what the provider-defined tool answers,
 * so a trained model reads it without being told.
 *
 * A directory is listed one level deep, its entries sorted, with a `/` on the
 * ones that are directories. Not walked: a workspace holding a dependency tree
 * would answer a `view` with a hundred thousand paths, and a model that wants
 * one asks `bash` for it.
 */
async function viewPath(requested: string, target: string): Promise<unknown> {
  const entry = await fs.promises.stat(target).catch(() => undefined);
  if (entry === undefined) {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` could not view \`${requested}\`: nothing is there. \`view\` the directory above it to see what is`,
    );
  }
  if (entry.isDirectory()) {
    const held = await fs.promises.readdir(target, { withFileTypes: true }).catch((error: unknown) => {
      throw fileRefusal("view", requested, error);
    });
    const listed = held.map((item) => (item.isDirectory() ? `${item.name}/` : item.name)).sort();
    return {
      path: requested,
      entries: listed.slice(0, LISTING_LIMIT),
      truncated: listed.length > LISTING_LIMIT,
    };
  }
  const held = await readFileText("view", requested, target);
  const shown = capped(numbered(held.text), BUILTIN_OUTPUT_LIMIT);
  return {
    path: requested,
    content: held.whole
      ? shown
      : `${shown}\n…[only the first ${FILE_READ_LIMIT} bytes of this file were read: it is larger than this tool views. Use \`bash\` to reach the rest]`,
  };
}

/**
 * `create`: the whole file, written or replaced.
 *
 * Parent directories are made, because a model that wrote `src/lib/a.ts` meant
 * the directories too and the alternative is an `ENOENT` it corrects with a
 * `bash mkdir`. They are inside the workspace by construction: the target has
 * already been checked, and every parent of a contained path is contained.
 *
 * **An empty `file_text` writes an empty file**, which is what the
 * provider-defined text editor does with one — and here it is the only thing
 * that can be done with one. `file_text` carries `default: ""` so that the three
 * operations which never read it are callable without it (`builtin_tool_input`),
 * and the parse fills that default in, so a model that sent `""` and a model
 * that sent nothing arrive here identically. Refusing the pair would leave
 * `.gitkeep` and `__init__.py` with **no spelling that works** for an agent
 * holding only this tool; writing it costs a model that forgot its contents one
 * `create` it repeats, with `wrote 0 bytes` in the answer saying why.
 */
async function createFile(requested: string, target: string, contents: string): Promise<unknown> {
  try {
    await fs.promises.mkdir(path.dirname(target), { recursive: true });
  } catch (error) {
    throw fileRefusal("create", requested, error);
  }
  await writeFileText("create", requested, target, contents);
  const bytes = Buffer.byteLength(contents, "utf8");
  return { path: requested, bytes_written: bytes, change: `wrote ${bytes} bytes` };
}

/**
 * `str_replace`: one occurrence, swapped.
 *
 * **Exactly one**, which is the provider-defined tool's own contract and the
 * reason it is a good edit primitive: a match that appears twice is an edit the
 * model cannot have meant unambiguously, so it is refused with the count and
 * asked for more context rather than applied to the first one.
 */
async function replaceInFile(
  requested: string,
  target: string,
  before: string,
  after: string,
): Promise<unknown> {
  if (before === "") {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` was asked to \`str_replace\` in \`${requested}\` with no \`old_str\`: send the exact text to replace`,
    );
  }
  const held = await readWholeFileText("str_replace", requested, target);
  const at = held.indexOf(before);
  if (at < 0) {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` found no \`old_str\` in \`${requested}\`: it has to match the file character for character, whitespace included. \`view\` the file and copy the text out of it`,
    );
  }
  const occurrences = held.split(before).length - 1;
  if (occurrences > 1) {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` found \`old_str\` ${occurrences} times in \`${requested}\`, and \`str_replace\` edits exactly one: include enough surrounding text to name the one you mean`,
    );
  }
  const updated = `${held.slice(0, at)}${after}${held.slice(at + before.length)}`;
  await writeFileText("str_replace", requested, target, updated);
  const line = held.slice(0, at).split("\n").length;
  return {
    path: requested,
    replaced_at_line: line,
    snippet: snippetAround(updated, line),
    change: `replaced one occurrence at line ${line}`,
  };
}

/**
 * `insert`: text put in after a line, `0` for the top of the file.
 *
 * A line outside the file is refused with the length rather than clamped: a
 * model that meant line 400 of a 40-line file has misread something, and
 * appending at the end would hide it.
 *
 * An empty `new_str` **is** refused here, where an empty `file_text` is written
 * by [`createFile`], and the difference is whether the refusal closes anything
 * off: a blank line has a spelling that works — a lone newline, which this
 * splits into one empty line — and the message names it, while an empty file has
 * no spelling at all if `create` will not write one. So the defaulted parameter
 * costs a forgetful model one call here and takes nothing away from a
 * deliberate one.
 */
async function insertIntoFile(
  requested: string,
  target: string,
  at: number,
  addition: string,
): Promise<unknown> {
  if (addition === "") {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` was asked to \`insert\` into \`${requested}\` with no \`new_str\`: send the text to insert, or a lone newline for a blank line`,
    );
  }
  const held = await readWholeFileText("insert", requested, target);
  const trailing = held === "" || held.endsWith("\n");
  const lines = held === "" ? [] : held.replace(/\n$/, "").split("\n");
  if (!Number.isInteger(at) || at < 0 || at > lines.length) {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` was asked to \`insert\` after line ${at} of \`${requested}\`, which has ${lines.length} line(s): \`insert_line\` is 0 for the top of the file and at most its length`,
    );
  }
  const added = addition.replace(/\n$/, "").split("\n");
  const next = [...lines.slice(0, at), ...added, ...lines.slice(at)];
  const updated = `${next.join("\n")}${trailing ? "\n" : ""}`;
  await writeFileText("insert", requested, target, updated);
  return {
    path: requested,
    inserted_after_line: at,
    lines_inserted: added.length,
    snippet: snippetAround(updated, at + 1),
    change: `inserted ${added.length} line(s) after line ${at}`,
  };
}

/**
 * One file's text, refused to the model where the path would not give it up —
 * and read under [`FILE_READ_LIMIT`] rather than under whatever size the file
 * happens to be.
 *
 * `whole` is false where the file had more than was read, which only a `view`
 * is allowed to see: [`readWholeFileText`] is what the two editing operations
 * call, and it refuses that case outright.
 */
async function readFileText(
  operation: FileOperation,
  requested: string,
  target: string,
): Promise<{ readonly text: string; readonly whole: boolean }> {
  const handle = await fs.promises.open(target, "r").catch((error: unknown) => {
    throw fileRefusal(operation, requested, error);
  });
  try {
    // Chunked rather than one `readFile`, so the allocation follows what the
    // file actually holds and stops at the bound rather than after it: a
    // `stat` first would be a size this runtime then has to trust.
    const chunks: Buffer[] = [];
    let filled = 0;
    let whole = true;
    for (;;) {
      const chunk = Buffer.alloc(FILE_READ_CHUNK);
      const { bytesRead } = await handle.read(chunk, 0, chunk.length);
      if (bytesRead === 0) break;
      chunks.push(chunk.subarray(0, bytesRead));
      filled += bytesRead;
      if (filled > FILE_READ_LIMIT) {
        whole = false;
        break;
      }
    }
    const held = Buffer.concat(chunks, Math.min(filled, FILE_READ_LIMIT));
    return { text: held.toString("utf8"), whole };
  } catch (error) {
    throw fileRefusal(operation, requested, error);
  } finally {
    await handle.close().catch(() => {
      // A handle that would not close is not this call's outcome.
    });
  }
}

/**
 * The same, for an operation that will **write the file back**.
 *
 * A file larger than [`FILE_READ_LIMIT`] is refused here rather than truncated,
 * because `str_replace` and `insert` rewrite what they read: the truncation
 * would land on disk. The refusal names the bound and the tool that has no such
 * bound, which is the repair a model can act on (Decision D119).
 */
async function readWholeFileText(
  operation: FileOperation,
  requested: string,
  target: string,
): Promise<string> {
  const held = await readFileText(operation, requested, target);
  if (!held.whole) {
    throw new ToolCallRefused(
      `\`${FILE_TOOL}\` will not \`${operation}\` \`${requested}\`: it is larger than the ${FILE_READ_LIMIT} bytes this tool reads, and an edit rewrites the whole file. Edit a file this size with \`bash\``,
    );
  }
  return held.text;
}

/**
 * The same, writing — and the one place the workspace bound is asked a question
 * [`targetWithinWorkspace`] cannot answer.
 *
 * Every write of this tool goes through here, `create` included, so the hard-link
 * refusal below is a property of writing rather than of a caller remembering to
 * ask for it.
 */
async function writeFileText(
  operation: FileOperation,
  requested: string,
  target: string,
  contents: string,
): Promise<void> {
  await refuseSecondName(operation, requested, target);
  try {
    await fs.promises.writeFile(target, contents, "utf8");
  } catch (error) {
    throw fileRefusal(operation, requested, error);
  }
}

/**
 * Refuse to **write** a file that has more than one name (PRD resolved q54,
 * Decision D119).
 *
 * The one escape resolution cannot close. [`targetWithinWorkspace`] asks where a
 * path really is, which is the whole answer for a symbolic link — a link has a
 * target, and where it points is where the write would land. A **hard** link has
 * no target: it is a second directory entry for one inode, so `realpath` answers
 * with the path inside the workspace and a `writeFile` through it rewrites the
 * bytes every other name reads, one of which may be outside. The file is not
 * followed anywhere; the workspace is simply not the whole of where it is.
 *
 * It cannot be narrowed to "…and the other name is outside", because a
 * filesystem offers no way to ask where a link's siblings are short of walking
 * every mount — so a file hard-linked twice *inside* the workspace is refused
 * too, and the refusal says what it saw so the model can copy the file and edit
 * the copy. The case is a **configured** `workspace:` that something else
 * populated (a checkout, a package manager that links rather than copies);
 * nothing puts a second name in a fresh per-execution workspace.
 *
 * A `view` is deliberately left alone: reading a file that is genuinely at a path
 * inside the workspace is inside the bound whatever else names it, and refusing
 * the read would buy nothing — the model could read the same bytes with `bash`.
 * It is the write that reaches out of the directory.
 */
async function refuseSecondName(
  operation: FileOperation,
  requested: string,
  target: string,
): Promise<void> {
  const entry = await fs.promises.lstat(target).catch(() => undefined);
  if (entry === undefined || !entry.isFile() || entry.nlink <= 1) return;
  throw new ToolCallRefused(
    `\`${FILE_TOOL}\` will not \`${operation}\` \`${requested}\`: ${entry.nlink} names point at that one file, and this tool cannot tell whether the others are inside its workspace — so writing it could change a file outside. \`create\` a copy at a new path and work on that`,
  );
}

/**
 * What a file operation that would not work says, in one sentence this runtime
 * composes.
 *
 * The platform's own message quotes the **resolved** path — the directory a
 * `${WORKSPACE}` resolved to on this machine, and so a value `docs/trace.md`
 * §11.1 keeps out of a trace field. So the failure is restated: the path as the
 * *model* asked for it, and the platform's error **code**, which says what went
 * wrong without saying what it went wrong on.
 */
function fileRefusal(operation: FileOperation, requested: string, error: unknown): ToolCallRefused {
  const code = (error as NodeJS.ErrnoException | null | undefined)?.code;
  return new ToolCallRefused(
    `\`${FILE_TOOL}\` could not \`${operation}\` \`${requested}\`${code === undefined ? "" : ` (${code})`}`,
  );
}

/** A file's text with each line numbered, which is what `view` answers with. */
function numbered(contents: string): string {
  const lines = contents.split("\n");
  if (lines.length > 0 && lines[lines.length - 1] === "") lines.pop();
  return lines.map((line, at) => `${String(at + 1).padStart(6, " ")}\t${line}`).join("\n");
}

/** The lines around an edit, numbered — what an edit answers with. */
function snippetAround(contents: string, line: number): string {
  const lines = numbered(contents).split("\n");
  const from = Math.max(0, line - 1 - SNIPPET_LINES);
  return capped(lines.slice(from, line + SNIPPET_LINES).join("\n"), BUILTIN_OUTPUT_LIMIT);
}

/**
 * One command's stream, held to [`BUILTIN_OUTPUT_LIMIT`] by dropping its
 * **middle**.
 *
 * The head and the tail rather than the head alone, which is the difference
 * between a bound on a *file* and a bound on a *command*: a build that failed
 * says why in its last lines, and a runtime that answered with the first thirty
 * thousand characters of a hundred-thousand-character log would hand a model
 * everything except the part it asked for. What was dropped is said, for
 * [`capped`]'s reason — and said without a count, because this may be trimming
 * a buffer [`held`] has already trimmed and a number here would be a number
 * about the wrong string.
 */
function trimmedMiddle(text: string): string {
  if (text.length <= BUILTIN_OUTPUT_LIMIT) return text;
  const head = Math.floor((BUILTIN_OUTPUT_LIMIT * 2) / 3);
  return `${text.slice(0, head)}\n…[the middle of this output was dropped: it printed more than this tool answers with]\n${text.slice(head - BUILTIN_OUTPUT_LIMIT)}`;
}

/**
 * `text`, cut to `limit` characters with the cut **said**.
 *
 * A model reading a truncated answer has to know it was truncated, or it will
 * reason about a file it has only the first half of. The **head** is what is
 * kept here — a `view` is read from line 1 and a path is read from its root — 
 * which is the difference from [`trimmedMiddle`], the bound a command's output
 * gets. See [`BUILTIN_OUTPUT_LIMIT`].
 */
function capped(text: string, limit: number): string {
  if (text.length <= limit) return text;
  return `${text.slice(0, limit)}\n…[${text.length - limit} more characters, not shown]`;
}

/** A resolved `http:` block. */
export interface HttpBinding {
  readonly method: string;
  readonly url: readonly Interpolation[];
  readonly headers: readonly { readonly name: string; readonly value: readonly Interpolation[] }[];
  readonly expectStatus: readonly number[] | "2xx";
  readonly decoding: Decoding;
}

/** Run one `http:` binding (grammar 6.1, 8.3). */
export async function runHttp(
  binding: HttpBinding,
  request: { readonly query?: Record<string, unknown>; readonly body?: unknown },
  context: RunContext,
): Promise<unknown> {
  return await journaled(
    context.effects,
    "tool",
    {
      surface: "http",
      method: binding.method,
      // The whole binding, as written — [`runExec`]'s rule and its reason. A
      // changed `headers:` (a new `Authorization`, a bumped `x-api-version`), a
      // changed `expect_status:` or a changed `output:` shape is a different
      // call, and an answer recorded under the old one is not this call's.
      url: asWritten(binding.url),
      headers: binding.headers.map((header) => ({
        name: header.name,
        value: asWritten(header.value),
      })),
      expectStatus: binding.expectStatus,
      decoding: binding.decoding,
      request,
    },
    () => runHttpLive(binding, request, context),
  );
}

/** [`runHttp`] with nothing between it and the network. */
async function runHttpLive(
  binding: HttpBinding,
  request: { readonly query?: Record<string, unknown>; readonly body?: unknown },
  context: RunContext,
): Promise<unknown> {
  // Resolved **before** the `try`, not inside it. A `url:` whose `${ENV}`
  // reference is unset makes [`environmentValue`] throw, and inside the `try`
  // that throw would be restated as "is not a URL once its `${ENV}` references
  // are resolved" — a message asserting something false, since the references
  // were never resolved at all, and one indistinguishable from the message a
  // reference that *is* set to a non-URL produces. Out here the precise
  // `` `SIGNED_ENDPOINT` is not set (referenced by …) `` propagates as raised,
  // and the `catch` keeps its one meaning: everything resolved, and what it
  // resolved to is not a URL.
  const resolved = interpolate(binding.url);
  let url: URL;
  try {
    url = new URL(resolved);
  } catch {
    // The platform's own parse failure quotes the **resolved** string — Bun says
    // `"secret/reports" cannot be parsed as a URL` — and grammar 4.3 class 2
    // makes this surface interpolable, so that string can be a credential. It
    // would reach `TraceEntry.error` and the trace file, which `docs/trace.md`
    // §11.1 says no resolved `${ENV}` value does, so the binding is named as the
    // composition spells it ([`asWritten`]) and the resolved value is not
    // repeated. There is nothing else to say about it: the whole failure is that
    // what the references resolved to is not a URL.
    throw new Error(
      `\`${asWritten(binding.url)}\` is not a URL once its \`\${ENV}\` references are resolved`,
    );
  }
  for (const [name, value] of Object.entries(request.query ?? {})) {
    url.searchParams.set(name, typeof value === "string" ? value : JSON.stringify(value));
  }
  const declared: Record<string, string> = {};
  for (const header of binding.headers) {
    declared[header.name] = interpolate(header.value);
  }
  const sendsBody = request.body !== undefined && !["GET", "HEAD"].includes(binding.method);
  // The body this runtime composes is JSON, so `application/json` is the media
  // type a binding that said nothing gets — and a binding that *did* say
  // something replaces it rather than adding to it. See [`headerSet`].
  //
  // The idempotency key rides in the same layering, one layer down from the
  // binding's own headers (grammar 8.6 rule 7, 9.4). A **header** rather than a
  // body field: the body of a `tool.*` request is the object its declared
  // `input:` parsed, so a field injected into it would be a property the tool's
  // own contract does not declare — and could collide with one it does. A
  // header is out of band, and `Idempotency-Key` is the name sinks already
  // dedupe on.
  const headers = headerSet(
    sendsBody ? { "content-type": "application/json" } : undefined,
    context.idempotency_key === undefined
      ? undefined
      : { [IDEMPOTENCY_HEADER]: context.idempotency_key },
    declared,
  );

  const response = await fetch(url, {
    method: binding.method,
    headers,
    body: sendsBody ? JSON.stringify(request.body) : undefined,
    signal: context.signal,
  });
  const text = await response.text();
  const accepted =
    binding.expectStatus === "2xx"
      ? response.status >= 200 && response.status < 300
      : binding.expectStatus.includes(response.status);
  if (!accepted) {
    // The URL as the composition spells it ([`asWritten`]), which is the whole
    // of what this runtime puts in the message: `text` below is what the server
    // answered, and is the server's to say.
    throw new Error(
      `\`${asWritten(binding.url)}\` answered ${response.status}, which is outside ${
        binding.expectStatus === "2xx" ? "the 2xx range" : `\`expect_status: [${binding.expectStatus.join(", ")}]\``
      }: ${text.slice(0, 200)}`,
    );
  }
  return decode(binding.decoding, text, { status: response.status, body: text }, "verbatim");
}

/**
 * Read a result out of a raw stream and an envelope (grammar 8.2, 8.3, 6.1).
 *
 * `binds` is how the single string-typed property of a `tool.*` takes the raw
 * stream, and the two surfaces differ there by one word of grammar 6.1: the
 * `exec` binding says **"trimmed raw stdout"**, the `http` binding says **"the
 * raw response text"**. The difference is the streams rather than the rule —
 * trailing whitespace is a shell artefact on stdout, where a command that ends
 * its output with a newline has said nothing by it, and is payload in a response
 * body, where every byte is what the server chose to send.
 */
function decode(
  decoding: Decoding,
  raw: string,
  envelope: Readonly<Record<string, unknown>>,
  binds: "trimmed" | "verbatim",
): unknown {
  if (decoding.empty) return {};
  if (decoding.raw !== undefined) {
    return { [decoding.raw]: binds === "trimmed" ? raw.trim() : raw };
  }

  const result: Record<string, unknown> = {};
  for (const field of decoding.envelope) {
    result[field] = envelope[field];
  }
  if (decoding.decoded.length === 0) return result;

  let payload: unknown;
  try {
    payload = JSON.parse(raw) as unknown;
  } catch (error) {
    throw new Error(`the result is not JSON: ${describe(error)}`);
  }
  if (payload === null || typeof payload !== "object") {
    throw new Error(`the result decoded to a ${typeof payload}, not an object`);
  }
  for (const field of decoding.decoded) {
    result[field] = (payload as Record<string, unknown>)[field];
  }
  return result;
}

// ---------------------------------------------------------------------------
// The host function registry (grammar 6.1's escape hatch)
// ---------------------------------------------------------------------------

/**
 * What a host-registered function is: arguments in, a result out.
 *
 * `context` is the invocation context grammar 9.4's delivery surface names: a
 * host function reached as the sink of a **detached** dispatch finds that
 * dispatch's key in `context.idempotency_key`, and finds it absent on every
 * other call. The generated `README.md` says so where a host reads about
 * registering one.
 */
export type HostFunction = (args: unknown, context: RunContext) => unknown | Promise<unknown>;

const REGISTRY = new Map<string, HostFunction>();

/**
 * Register the implementation of a `function:` tool binding (grammar 6.1).
 *
 * The escape hatch, and the one construct that breaks spec portability — a
 * composition using it needs this call to have happened before the graph runs.
 * See the generated `README.md`.
 */
export function registerFunction(name: string, implementation: HostFunction): void {
  REGISTRY.set(name, implementation);
}

/** Call a host-registered function, or say which registration is missing. */
export async function callFunction(
  name: string,
  args: unknown,
  context: RunContext,
): Promise<unknown> {
  const implementation = REGISTRY.get(name);
  if (implementation === undefined) {
    throw new Error(
      `no host function is registered as \`${name}\`: call \`registerFunction(${JSON.stringify(name)}, …)\` before running the graph`,
    );
  }
  // Journaled like the other two surfaces, and it is the one where the promise
  // is worth stating outright: a host function is arbitrary caller code, so
  // "replay does not re-run it" is what keeps a resumed execution from mailing
  // a second invoice. What it answered has to be JSON, which grammar 6.1
  // already requires of it — the answer is parsed against the binding's
  // declared `output:`.
  return await journaled(
    context.effects,
    "tool",
    { surface: "function", name, args },
    async () => await implementation(args, context),
  );
}

// ---------------------------------------------------------------------------
// Authored module implementations (grammar 6.1's `module:` binding)
// ---------------------------------------------------------------------------

/**
 * One `module:` binding, as the composition wrote it (grammar 6.1, PRD resolved
 * q48, q49).
 *
 * The *identity* of the call and nothing else: which tool, which file, and the
 * environment the binding declared. The implementation is not here — it reaches
 * [`callModule`] as an argument, through `./modules.ts`, because that is the one
 * seam generated code is allowed to reach authored code across.
 */
export interface ModuleBinding {
  /** The tool's address, as the composition spells it (grammar 2.2). */
  readonly address: string;
  /** The authored file, project-relative — the path it takes in the artifact. */
  readonly path: string;
  /** `env:` — what this implementation declared it reads (grammar 4.3 class 2). */
  readonly env: readonly { readonly name: string; readonly value: readonly Interpolation[] }[];
}

/**
 * The environment one `module:` binding declared, resolved for one call
 * (grammar 4.3 class 2, 6.1).
 *
 * **A map of its own, never `process.env`.** An `exec:` binding's `env:` reaches
 * its implementation as the *child's* environment, which no other call in this
 * process shares; a module runs here, so its declaration is handed to it the
 * same way — as an argument. Written into the ambient environment instead it
 * would outlive the call it belongs to and reach every later `exec:` child,
 * every other module, and whatever ran concurrently beside it, which is the one
 * thing "these names hold these values **when this implementation runs**" does
 * not say. It would also differ under replay, which never enters the
 * implementation at all.
 *
 * `./modules.ts` states this per tool, over the names that binding declared, so
 * a read of a variable the YAML does not list is a type error rather than an
 * `undefined` at three in the morning. This is the erased version the runtime
 * builds and passes.
 */
export type ModuleEnv = Readonly<Record<string, string>>;

/**
 * What an authored module is, from this side: the tool's parsed input in, its
 * declared result out.
 *
 * `./modules.ts` states the same shape *per tool*, over the tool's own schemas,
 * and that is the one `tsc` holds an authored file to. This is the erased
 * version the runtime dispatches through, and it takes `context` for
 * [`HostFunction`]'s reason: a module tool reached as the sink of a **detached**
 * dispatch finds that dispatch's key in `context.idempotency_key`, and finds it
 * absent on every other call. `E` is the binding's own [`ModuleEnv`], which the
 * generated contract narrows to the names it declared.
 */
export type ModuleImplementation<I, O, E extends ModuleEnv = ModuleEnv> = (
  input: I,
  context: RunContext,
  env: E,
) => O | Promise<O>;

/**
 * Call an authored module implementation, in this process (grammar 6.1).
 *
 * **Parity is the point.** A module tool is a tool: its arguments are parsed
 * against its declared `input:` before this is reached, its answer against its
 * `output:` after, its node's `retry:`/`timeout:`/`on_error:` wrap the whole of
 * it, and a model that called it wrongly gets the refusal back rather than the
 * node failing (Decision D119). Only the binding differs, so only the journal's
 * `surface` differs.
 *
 * **What identifies the call.** The address, the file the binding names, the
 * declared environment **as written**, and the input. Whole, for [`runExec`]'s
 * reason: a binding that moved in any of those is a call this run does not make,
 * and the recorded answer is not its. The authored file's *contents* are not in
 * it, exactly as a host function's registration is not in that surface's key —
 * an implementation that changed is a new artifact hash rather than a new effect
 * identity, and `docs/durability.md` §3.2's subject is the composition.
 *
 * **The environment is resolved into an argument.** `env:` is the same
 * declaration an `exec:` binding makes and it means the same thing — these names
 * hold these values when the implementation runs — so it is delivered the way an
 * `exec:`'s is: as the call's own environment, which nothing outside the call
 * shares. An `exec:` builds a child's environment; this builds the third
 * argument, and [`ModuleEnv`] says why it is not `process.env`. A binding that
 * maps a name to itself (`SIGNING_KEY: "${SIGNING_KEY}"`, the ordinary spelling)
 * hands on the value already there, resolved at the moment of the call like
 * every other class-2 reference.
 */
export async function callModule<I, O, E extends ModuleEnv>(
  binding: ModuleBinding,
  implementation: ModuleImplementation<I, O, E>,
  input: I,
  context: RunContext,
): Promise<O> {
  return await journaled(
    context.effects,
    "tool",
    {
      surface: "module",
      address: binding.address,
      path: binding.path,
      env: binding.env.map((entry) => ({ name: entry.name, value: asWritten(entry.value) })),
      input,
    },
    async () => {
      // `Object.fromEntries` rather than assignment into an object literal,
      // because a declared name is data and one of them is a *setter* on
      // `Object.prototype`: `environment["__proto__"] = "…"` is a silent no-op,
      // so a binding declaring `__proto__` — which the validator's environment
      // variable form accepts — would hand the implementation an `env.__proto__`
      // holding `Object.prototype` where `./modules.ts` typed it `string`. This
      // defines own properties, so every name the composition declared arrives
      // as the value it declared.
      const environment = Object.fromEntries(
        binding.env.map((entry) => [entry.name, interpolate(entry.value)] as const),
      );
      // The cast is the compiler's own guarantee rather than a claim about
      // arbitrary data: `E` is the type `./modules.ts` wrote from this binding's
      // `env:`, and the map above filled exactly those names from the same
      // declaration. One emitter wrote both.
      return await implementation(input, context, environment as E);
    },
  );
}

// ---------------------------------------------------------------------------
// The router (grammar 7.3, 7.4, 7.6)
// ---------------------------------------------------------------------------

/** One outgoing edge, in the declaration order grammar 7.3 evaluates them in. */
export interface EdgeDescriptor {
  /** The target node id, or `"__end__"`. */
  readonly to: string;
  /** The `when:` guard, as CEL source. */
  readonly when?: string;
  /** Whether the guard reads the source node's own output (Decision D97). */
  readonly readsOutput?: boolean;
  /** `else: true`. */
  readonly otherwise?: boolean;
  /** The `max_iterations` budget, and the counter it spends (grammar 7.4). */
  readonly budget?: { readonly key: string; readonly max: number };
}

/** What one edge did, as the trace records it (PRD 5.3). */
export interface EdgeDecision {
  readonly to: string;
  readonly when?: string;
  readonly else?: true;
  readonly value?: boolean;
  readonly budget?: { readonly key: string; readonly used: number; readonly max: number };
  readonly taken: boolean;
  readonly reason?: string;
}

/** One node's whole routing decision. */
export interface RoutingDecision {
  readonly edges: EdgeDecision[];
  readonly targets: string[];
  readonly counters: Record<string, number>;
}

/**
 * Evaluate a node's outgoing edges (grammar 7.3, 7.4, Decision D97).
 *
 * Declaration order, multicast, `else:` suppressed by a **taken** guarded
 * sibling, and an exhausted budget untakeable whatever its guard says. A
 * `skip`ped node changes exactly one thing: a guard that references its output
 * is `false` without being evaluated, while a guard over `input`/`state`/
 * `execution` is evaluated normally.
 */
export function route(
  flow: string,
  node: string,
  edges: readonly EdgeDescriptor[],
  roots: Roots,
  counters: Readonly<Record<string, number>>,
  skipped: boolean,
): RoutingDecision {
  // One slot per edge, filled at the edge's **declaration index** rather than
  // in the order the two passes below reach it. Declaration order is what the
  // trace records (`docs/trace.md` §4), and an `else:` edge is decided in a
  // second pass — it needs to know whether a guarded sibling was taken — so a
  // list appended to in evaluation order would put an `else:` declared before an
  // unconditional edge after it, in both `edges` and `targets`.
  const slots: (EdgeDecision | undefined)[] = edges.map(() => undefined);
  const spent: Record<string, number> = {};
  let guardedTaken = false;

  edges.forEach((edge, index) => {
    if (edge.otherwise === true) return;
    if (edge.when === undefined) {
      slots[index] = { to: edge.to, taken: true, reason: "unconditional" };
      return;
    }

    let value: boolean;
    if (skipped && edge.readsOutput === true) {
      value = false;
    } else {
      try {
        value = evaluateGuard(edge.when, roots);
      } catch (error) {
        throw new Error(
          `${flow} node \`${node}\`: the guard \`${edge.when}\` could not be evaluated: ${describe(error)}`,
        );
      }
    }

    if (!value) {
      slots[index] = { to: edge.to, when: edge.when, value, taken: false };
      return;
    }
    if (edge.budget !== undefined) {
      const used = counters[edge.budget.key] ?? 0;
      if (used >= edge.budget.max) {
        slots[index] = {
          to: edge.to,
          when: edge.when,
          value,
          budget: { key: edge.budget.key, used, max: edge.budget.max },
          taken: false,
          reason: "the `max_iterations` budget is spent",
        };
        return;
      }
      spent[edge.budget.key] = used + 1;
      slots[index] = {
        to: edge.to,
        when: edge.when,
        value,
        budget: { key: edge.budget.key, used: used + 1, max: edge.budget.max },
        taken: true,
      };
    } else {
      slots[index] = { to: edge.to, when: edge.when, value, taken: true };
    }
    guardedTaken = true;
  });

  edges.forEach((edge, index) => {
    if (edge.otherwise !== true) return;
    slots[index] = guardedTaken
      ? { to: edge.to, else: true, taken: false, reason: "a guarded sibling was taken" }
      : { to: edge.to, else: true, taken: true };
  });

  const decisions = slots.filter((decision): decision is EdgeDecision => decision !== undefined);
  // The targets in the order their edges are declared in, deduplicated: a
  // multicast reads the way the file does, and so does the `goto` it becomes.
  const targets: string[] = [];
  for (const decision of decisions) {
    if (!decision.taken) continue;
    if (!targets.includes(decision.to)) targets.push(decision.to);
  }

  if (targets.length === 0) {
    // The decisions travel in the same order a returned one does, because the
    // trace entry this ends up on is read the same way whether the run survived
    // it or not.
    throw new NoViableRoute(flow, node, decisions);
  }
  return { edges: decisions, targets, counters: spent };
}

// ---------------------------------------------------------------------------
// The run channel: what the compiler keeps beside a composition's own state
// ---------------------------------------------------------------------------

/**
 * The version of the trace format this compiler release emits
 * (`docs/trace.md`, PRD §7 M2's "a documented, stable trace format").
 *
 * It sits on the **envelope** ([`TraceDocument`], and the `trace_version` key
 * every delivery surface carries beside its `trace`) rather than on an entry: a
 * run's entries are all of one format, and a version per entry would be a
 * per-step cost for a fact about the release that produced them.
 *
 * The number is bumped when a reader that pinned it would be wrong: a field
 * removed, renamed, or given a different meaning. Adding a field is not a bump —
 * `docs/trace.md`'s *Stability* section is the contract, and it is what a reader
 * is entitled to rely on.
 */
export const TRACE_VERSION = 4;

/**
 * One run's whole trace, as a surface delivers it (`docs/trace.md`).
 *
 * The **envelope**: the version a reader pins, the run it describes, and the
 * entries themselves. `agent-compose run --format json` spreads these keys into
 * the record it prints (its `trace` is this document's `entries`), the trace
 * **file** is exactly one of these, and the generated app's status route carries
 * `trace_version` beside the `trace` it already reported.
 *
 * Its keys are `snake_case` while an entry's are `camelCase`, and the seam is
 * deliberate: these are document keys, alongside `execution_id`, `trace_path`
 * and `status_url` on the same surfaces, while an entry is a runtime record —
 * the very object `runFlow` answers with in `FlowRun.trace`, read by in-process
 * callers as JavaScript rather than as a document.
 */
export interface TraceDocument {
  /** [`TRACE_VERSION`]: the format the `entries` below are written in. */
  readonly trace_version: number;
  /** The flow that was run, as its typed address (grammar 2.2). */
  readonly flow: string;
  /** The execution the entries belong to (grammar 4.1's `execution.id`). */
  readonly execution_id: string;
  /**
   * How the run ended: with an answer, without one, or holding a pause.
   *
   * `"interrupted"` is a run that reached a `human` node it had no way to answer
   * (grammar 8.7, [`HumanInterrupt`]) — what `agent-compose run` does with every
   * pause, since resume is `serve`'s route. It is told apart from `"failed"`
   * because the two ask for different things from whoever is reading: one is a
   * run to look into, the other is a question to answer.
   */
  readonly status: "completed" | "failed" | "interrupted";
  /**
   * What stopped a run that produced no answer.
   *
   * Present exactly on `status: "failed"` and `status: "interrupted"`, and there
   * because such a run's *last* entry does not always say why: a run stopped by
   * the superstep ceiling ([`SuperstepCeiling`]) has no aborting node to carry
   * one, and a file that held only `status: "failed"` would name no reason at
   * all.
   */
  readonly error?: string;
  /**
   * Every entry the run recorded, ordered by `(step, node)` — the order
   * [`mergeRun`] folds them in.
   *
   * A **failed** run appends one entry outside that fold: [`failedTrace`] puts
   * the entry of the node the run aborted at last, wherever its `(step, node)`
   * would have sorted to. Re-sorting this array moves that entry into the middle
   * of the run.
   */
  readonly entries: readonly TraceEntry[];
}

/**
 * One entry of the routing trace (PRD 5.3: routing decisions are data).
 *
 * A run that **fails** carries one final entry too: the node it aborted at,
 * with `outcome: "failed"` and an `error` saying what stopped it. That entry
 * records no `writes`, because the superstep a run dies in lands none of them —
 * every task's update in that step is discarded — and it carries `routing` only
 * when the routing decision is what failed ([`NoViableRoute`]), where the guard
 * values are the whole explanation. See [`abortedEntry`].
 */
export interface TraceEntry {
  readonly step: number;
  readonly flow: string;
  readonly node: string;
  readonly traversal: number;
  readonly outcome: "completed" | "skipped" | "failed";
  readonly attempts: number;
  readonly writes?: readonly string[];
  readonly routing?: RoutingDecision;
  /**
   * What a `map` node dispatched, one entry per source item in **index** order
   * (grammar 8.6, PRD 5.6).
   *
   * Cardinality and destination are data in this design, so they are trace data
   * too: which route each item took, whether the instance completed, was skipped
   * by `on_item_error`, failed under it, or was resolved at dispatch by
   * `detach: true`. Without it a fan-out is the one construct whose whole
   * decision — how many, and to where — leaves no record at all.
   *
   * A map node that **failed** carries it too, whether the failure ended the run
   * or its own `on_error:` absorbed it: the items that ran already had their
   * effects, and that is the reading of a fan-out an operator most needs. See
   * [`ItemFailure.dispatches`], which is how it gets out of a node that returned
   * no answer, and [`plannedDispatches`], which is how it gets out of a node
   * whose own `timeout:` fired before it could raise one. In that last case the
   * entry holds the dispatches that had **resolved** — every detached delivery,
   * and every joined instance that had settled — rather than one per source
   * item: an instance the deadline caught mid-flight has no outcome to record,
   * and the entry's `error` names the budget that ended it.
   */
  readonly dispatches?: readonly DispatchRecord[];
  /**
   * What a **model** dispatched: one record per flow-as-tool call an agent this
   * node ran made (grammar 5.4, PRD 5.1, §9.20).
   *
   * The same record type as [`dispatches`][`TraceEntry.dispatches`] and a
   * different key, because the two are different fan-outs of the same entry: a
   * `map` dispatches over source items and a tool loop over the calls a model
   * asked for, and a `map` whose target is an `agent.*` with a `flow.*` in its
   * `tools:` has both at once. One array each is what keeps their `index`
   * spaces — a source-item index and a call ordinal — from being read as one.
   *
   * Every instance a model started is findable here, whether it answered or
   * failed, which is the invariant PRD §9.20 keeps: a subflow instance's trace
   * lives on a dispatch record, and the tool-call entry inside the
   * [`ModelCall`] links to it by [`DispatchRecord.idempotencyKey`].
   */
  readonly toolDispatches?: readonly DispatchRecord[];
  /**
   * The trace of the subflow instance a `flow:` node ran (grammar 8.5).
   *
   * A subgraph's routing decisions are its own instance's, and a flat trace
   * would either lose them or pretend they were the caller's. Nesting them keeps
   * PRD 5.3's record complete across a module boundary without moving anyone's
   * step numbers.
   *
   * A **dispatched** instance is not here. A `map`'s items each have a record of
   * their own and the instance goes under [`DispatchRecord.inner`], including
   * the item whose failure ended the map node — see [`traceOf`], which is what
   * keeps the two apart, and `docs/trace.md` §3 and §8.
   */
  readonly inner?: readonly TraceEntry[];
  /**
   * Every store op this node performed, in the order it performed them
   * (PRD 5.8).
   *
   * Both consumption surfaces land here: a `store:` node's own op, and every op
   * an agent's synthesized store tools ran inside its tool loop — which PRD 5.8
   * asks to be "recorded as tool calls", and a tool call this graph made is a
   * thing the trace has to hold rather than only the provider transcript.
   */
  readonly stores?: readonly StoreRecord[];
  /**
   * Every model call this node made, and which member of its route served it
   * (PRD 5.9).
   *
   * "Served by `model.fast`, fallback #1" is PRD 5.9's own phrasing of what a
   * trace must carry, so failover is data rather than behaviour a reader has to
   * infer from a provider's logs. See [`ModelCall`].
   */
  readonly models?: readonly ModelCall[];
  /**
   * The wait a `human` node held, and how it ended (grammar 8.7, PRD 5.5).
   *
   * A pause is a routing-relevant event with no other record: without it the
   * only trace of a wait that ran for a day is an entry that looks exactly like
   * one that took a millisecond. What is **not** here is what the human
   * answered, for the reason no field carries a model's completion either —
   * see [`HumanPause`] and `docs/trace.md` §11.
   *
   * A node that is not a `human` node never carries the key.
   */
  readonly human?: HumanPause;
  readonly error?: string;
  readonly fallback?: string;
}

/**
 * One store op, as the trace records it (PRD 5.8).
 *
 * Reads and writes are both here and are told apart by `effect`, because the
 * two are recorded for different reasons. A **read** is recorded because PRD 5.8
 * makes store ops effects whose reads replay from history rather than from the
 * live store: the answer is kept so a replay has something to consume. A
 * **write** is recorded because it is at-least-once — a store-op *node*'s write
 * carries the idempotency key of grammar 9.4, and `deduped` says whether the
 * backend had already applied that key, which is the difference between "this
 * run wrote it" and "an earlier attempt of this same effect did".
 *
 * A write an agent made through a synthesized store tool (grammar 11.5) carries
 * neither: grammar 9.4 names the store-op node catalog (§11.4) as the carrier,
 * and a tool call's outcome goes straight back to the model that asked for it,
 * so there is no unobserved effect for a key to substitute for. See
 * `src/stores.ts`'s module header for the whole argument, and `docs/trace.md`
 * §6 for the presence rule a reader is given.
 */
export interface StoreRecord {
  /** The store's typed address (grammar 2.2). */
  readonly store: string;
  /** The op, spelled as grammar 11.4 spells it. */
  readonly op: string;
  /** Which half of the replay discipline this record belongs to. */
  readonly effect: "read" | "write";
  /** Which consumption surface ran it (PRD 5.8's two modes). */
  readonly via: "node" | "tool";
  /** The store's lifetime, and with it which partition was addressed. */
  readonly scope: "execution" | "session" | "global";
  /** The key the op addressed, on the ops that address one. */
  readonly key?: string;
  /** What a read answered — the history a replay consumes. */
  readonly answer?: unknown;
  /** A store-op node write's idempotency key (grammar 9.4). */
  readonly idempotencyKey?: string;
  /** Whether the backend had already applied that key (at-least-once). */
  readonly deduped?: boolean;
}

/** What one dispatched `map` instance did (grammar 8.6, PRD 5.6). */
export interface DispatchRecord {
  /** The source-item index — what orders every write this instance made. */
  readonly index: number;
  /**
   * The route's variant tag, `"$default"` for the catch-all, absent on the
   * homogeneous form.
   *
   * The catch-all's name carries a sigil the identifier grammar cannot produce
   * (§2.1: `lower , { lower | digit | "_" }`) because a union may declare a
   * variant tagged `default` *and* a `default:` catch-all beside it — legal
   * together, and resolved correctly by [`selectRoute`], which searches the
   * named routes first. Spelling both `"default"` here would make the one
   * distinction a reader has between them the target, and two routes may share
   * a target.
   */
  readonly route?: string;
  /**
   * The discriminator value the item itself carried, on the routed form
   * (grammar 8.6 rule 8).
   *
   * Present on every record a `map` that declares `route_by:` files, and on no
   * other. "Every" holds through [`variantOf`], which leaves a discriminator
   * that is not a string unrecorded rather than rendering it: an item carrying
   * one is an item the parse should have refused, and no artifact `build`
   * accepted produces one. Recorded rather than read back off [`route`], because
   * [`route`] is not always the same fact. PRD §7 M2 asks for "which map variant
   * a discriminator chose" as trace data, and a route's tag answers that only
   * while a *named* route was selected: an item the `default:` catch-all took is
   * recorded as `"$default"`, which names the route and says nothing about the
   * variant that fell through to it — and the item is not in the trace, so
   * nothing else could be read to recover it. The producing node's own result
   * is not either: only the nodes a `map.over` reads are kept
   * ([`RunChannel.outputs`]), and they are kept in graph state rather than in
   * the trace.
   *
   * It is a declared variant tag rather than anything a model chose freely: the
   * item was parsed against the union its producer declares (PRD 5.2) before any
   * of this ran, so the set of values that can appear here is the composition's
   * own (grammar 3.2's `variants:`).
   */
  readonly variant?: string;
  /** The component the item was dispatched to. */
  readonly target: string;
  /**
   * What became of the item, which is what `on_item_error` decided (grammar 8.6
   * rule 10): `skipped` is the policy dropping it and the fan-out carrying on,
   * `failed` is `fail` — or a `retry:` out of attempts, which "resolves as
   * `fail` does" — taking the map node down with it.
   *
   * `detached` is *resolved at dispatch*: the join counted it the moment the
   * dispatch was issued and never learned its outcome (Decision D94), so no
   * strategy ever applied to it.
   */
  readonly outcome: "completed" | "skipped" | "failed" | "detached";
  /**
   * How many attempts the item's policy **made** — not how many it allowed, so
   * a node deadline that ended a backoff early is reported as the attempts that
   * really happened. `0` for a detached dispatch, which has no observed outcome
   * for `on_item_error` to have acted on.
   */
  readonly attempts: number;
  /**
   * The key this dispatch's effect site derives (grammar 9.4).
   *
   * A **detached** delivery carries it to its sink on the surface grammar 9.4
   * fixes per binding kind — the `Idempotency-Key` header of an `http:`
   * binding, the `IDEMPOTENCY_KEY` variable in an `exec:` binding's
   * environment, the `idempotency_key` field of the context a `function:` or a
   * `module:` binding is invoked with — which is what makes at-least-once
   * delivery a defensible trade rather than a lost message (PRD 5.6). It is
   * recorded for every dispatch because it is the same derivation either way,
   * and because it is the one place the flattened instance path of a nested
   * fan-out is observable at all.
   */
  readonly idempotencyKey: string;
  /**
   * The instance's own trace, when a **joined** dispatch's target was a
   * `flow.*`.
   *
   * A `detach: true` route is the exception, and for the reason its whole
   * record is: this record is written when the dispatch is *issued* (Decision
   * D94), before the instance it names has run a node, and the join never comes
   * back for it. So a detached dispatch carries no `inner` whatever its target
   * is — see `docs/trace.md` §5.
   */
  readonly inner?: readonly TraceEntry[];
  /**
   * Why the item did not complete.
   *
   * On **both** outcomes that did not: `skipped` and `failed` alike, because
   * `on_item_error` decides which of the two an item's failure becomes and not
   * whether there was one. Absent on `completed` and on `detached`, the second
   * for the reason its whole record is thin — nothing was observed to fail.
   */
  readonly error?: string;
}

/**
 * Where a node hands its own trace entry to the failure that ends the run.
 *
 * A node that throws returns no `Command`, so the entry it had reached has
 * nowhere to be written: LangGraph discards the whole superstep. Carrying it on
 * the error is what gets it to [`runFlow`], which appends it to the trace it
 * recovered. `Symbol.for` rather than a field name so that nothing a
 * composition can spell collides with it, and non-enumerable so an error that
 * carries one still logs and serializes the way the same error without one does.
 */
const ABORTED = Symbol.for("agent-compose.abortedEntry");

/** Carry `entry` on `error`, and answer with the error unchanged otherwise. */
export function carryEntry<E>(error: E, entry: TraceEntry): E {
  if (typeof error === "object" && error !== null && Object.isExtensible(error)) {
    Object.defineProperty(error, ABORTED, { value: entry, enumerable: false, configurable: true });
  }
  return error;
}

/**
 * What a failed `map` node dispatched, recovered from the failure it raised.
 *
 * The `cause` chain is followed for the same reason [`abortedEntry`] follows it:
 * `runActivity` wraps whatever the activity threw in a [`NodeFailure`], so the
 * [`ItemFailure`] carrying the records is never the outermost error by the time
 * a node's `on_error:` is deciding what to do with it.
 *
 * **Two boundaries stop the walk**, and they are the two module boundaries a
 * failure can cross on its way here. Below either one is a fan-out some *other*
 * instance ran, already on that instance's own entries — inside the trace the
 * caller carries — and walking past one would stamp a child's fan-out onto the
 * caller's entry, where `docs/trace.md` §3 says only a `map` node has one.
 *
 * This is where the two recoveries differ, and deliberately: [`traceOf`]
 * *returns* at a [`SubflowFailure`], because the trace it holds is exactly what
 * the `flow:` node calling it owes its entry — while the records under one
 * belong to the child's own `map` node and to nothing above it.
 */
function dispatchesOf(error: unknown): readonly DispatchRecord[] | undefined {
  for (let held: unknown = error; typeof held === "object" && held !== null; ) {
    if (held instanceof ItemFailure) return held.dispatches;
    // A subflow instance is the first boundary: a `flow:` node whose child holds
    // a `map` that failed would otherwise take the **child's** dispatch records
    // onto its own entry, and a `flow:` node dispatches nothing (see
    // [`SubflowFailure`]). [`traceOf`] meets the same error and *answers* with
    // it — the trace is what the caller owes its `inner`, and these records are
    // already inside it.
    if (held instanceof SubflowFailure) return undefined;
    // A flow-as-tool call is the second, for the same reason one construct over:
    // what a `map` inside the instance dispatched is the *instance's* — already
    // on its own entries, inside the trace this call's dispatch record carries.
    // Walking past it would put a subflow's fan-out on the **agent** node's
    // entry (see [`ToolFailure`]).
    if (held instanceof ToolFailure) return undefined;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/**
 * The trace of the subflow instance this error came out of, if it came out of
 * one (grammar 8.5, PRD 5.3).
 *
 * The one account of what happened inside a module boundary, and the caller's
 * own failure says nothing about it — so it is recovered wherever a failed
 * instance is recorded: a `flow:` node's trace entry ([`runNode`]) and a
 * dispatched instance's [`DispatchRecord`] ([`runMap`]). The `cause` chain is
 * followed for the reason [`dispatchesOf`] follows it: `runActivity` wraps
 * whatever the activity threw, so the [`SubflowFailure`] is rarely the outermost
 * error by the time anyone asks.
 *
 * An [`ItemFailure`] is where the walk **stops**, and that is the difference
 * between the two recording sites above. Below one is a *dispatched* instance's
 * failure, whose trace belongs to that item — [`runMap`] has already put it on
 * the item's own [`DispatchRecord.inner`], reading from underneath this
 * boundary. Walking past it would put one item's instance on the **map node's**
 * `inner` as well: the lowest-indexed failure only, and only on the
 * `on_error: fail` path, where `docs/trace.md` §3 says a `flow:` node's own
 * instance is and §8 says a dispatched one is under its record instead.
 */
function traceOf(error: unknown): readonly TraceEntry[] | undefined {
  for (let held: unknown = error; typeof held === "object" && held !== null; ) {
    if (held instanceof SubflowFailure) return held.trace;
    if (held instanceof ItemFailure) return undefined;
    // The second boundary, for the second reason a caller must not claim an
    // instance it did not run: below a [`ToolFailure`] is a subflow a *model*
    // asked for, whose trace [`callSubflowTool`] has already put on its own
    // dispatch record. An agent node carries no `inner` (`docs/trace.md` §3).
    if (held instanceof ToolFailure) return undefined;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/**
 * What a `map` node dispatched, read off the **plan** rather than off an answer
 * or a failure (grammar 8.6, PRD 5.3, 5.6).
 *
 * The last resort of the three, and the only one there is when a node's own
 * `timeout:` fired: the deadline is raced ([`runActivity`]), so [`runMap`]'s
 * promise is abandoned where it stands and neither its answer nor an
 * [`ItemFailure`] ever arrives. The plan is [`runNode`]'s own object — it built
 * it, outside the policy — and the map writes each dispatch into it as that
 * dispatch resolves, so what survives here is every detached delivery (resolved
 * at dispatch, D94) and every joined instance that had settled. An instance
 * still in flight when the budget ran out has no outcome yet and so no record;
 * the entry's own `error`, which names the node and its budget, is what accounts
 * for it.
 *
 * Recognised by its **brand** rather than by its shape, because `runNode` holds
 * every node's input as `unknown` and reaches here for *any* node that failed.
 * A structural test — an object carrying `instances` and `records` arrays — is
 * one a node that is not a map can pass: `instances` and `records` are legal
 * field names (grammar 2.1), so a composition declaring an `input:` with both
 * would, on failure, have its own data attached to its entry as `dispatches`,
 * where `docs/trace.md` §3 says only a `map` node has one and §5 says the
 * elements are [`DispatchRecord`]s. The brand is [`MAP_PLAN`], which only
 * [`mapPlan`] sets, so the only object that answers here is one this runtime
 * built for a map.
 */
function plannedDispatches(input: unknown): readonly DispatchRecord[] | undefined {
  if (typeof input !== "object" || input === null) return undefined;
  if ((input as Record<symbol, unknown>)[MAP_PLAN] !== true) return undefined;
  const plan = input as MapPlan;
  if (plan.records.length === 0) return undefined;
  return [...plan.records].sort((left, right) => left.index - right.index);
}

/**
 * The entry of the node this error aborted, if it came from one.
 *
 * The `cause` chain is followed, because an error can be restated on the way out
 * — `SuperstepCeiling` puts the original underneath itself — and the entry
 * belongs to whichever error in that chain a node actually raised.
 */
export function abortedEntry(error: unknown): TraceEntry | undefined {
  for (let held: unknown = error; typeof held === "object" && held !== null; ) {
    const entry = (held as Record<symbol, unknown>)[ABORTED];
    if (entry !== undefined) return entry as TraceEntry;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/**
 * A run that produced no answer, and the trace it made before it stopped.
 *
 * PRD 5.3 asks that routing decisions appear in traces as data, and a failed run
 * is where a trace is wanted most: it is the record of which guards answered
 * what, which budgets were spent and how many attempts each node made on the way
 * to whatever went wrong. The graph's state — `$run` included — does not survive
 * an `invoke` that throws, so [`runFlow`] streams the run instead, keeps the last
 * state each superstep produced, and raises this in place of the error the graph
 * threw. The original is the `cause`, so a report that prints the chain says
 * exactly what it said before.
 *
 * `what` is which of a run's two ways of failing this is, because both of them
 * have a trace to carry: a run that never reached quiescence, and a run that
 * reached it and could not materialize an output (grammar 7.6.3, 10.1). One
 * error type for both is what lets every caller — `agent-compose run`, the
 * generated `serve` app, an ejected project — read `.trace` without asking which
 * kind of failure it has.
 */
export class FlowFailure extends Error {
  /** The flow that was running. */
  readonly flow: string;
  /** What landed, plus the entry of the node the run aborted at. */
  readonly trace: readonly TraceEntry[];

  constructor(flow: string, what: string, trace: readonly TraceEntry[], cause: unknown) {
    super(`\`${flow}\` ${what}: ${describe(cause)}`);
    this.name = "FlowFailure";
    this.flow = flow;
    this.trace = trace;
    this.cause = cause;
  }
}

/**
 * A run stopped by the superstep ceiling rather than by anything it declared.
 *
 * The ceiling is the compiler's safety net (see `CompiledFlow.recursionLimit`),
 * and LangGraph announces reaching it in its own terms — a `recursionLimit`
 * config key and a link to its troubleshooting page, neither of which is a thing
 * this composition has. What a reader needs instead is that the net caught a
 * loop the composition did not bound itself: grammar 7.4 clause 2 admits a cycle
 * bounded only by a CEL exit condition, PRD 5.4 accepts it as a bound that is
 * *not* a static termination proof, and a guard that never goes false therefore
 * loops until something outside the composition stops it.
 */
export class SuperstepCeiling extends Error {
  /** The ceiling the run was given. */
  readonly ceiling: number;

  constructor(ceiling: number, cause: unknown) {
    super(
      `the run reached its ceiling of ${ceiling} supersteps. The ceiling is the compiler's ` +
        "safety net rather than one of the composition's own bounds: it is sized from the " +
        "`max_iterations` budgets the flow declares, plus an allowance for every cycle " +
        "bounded only by a CEL exit condition (grammar 7.4 clause 2) — which declares no " +
        "number of passes at all, so a guard that never goes false loops until the net " +
        "catches it. Bound the loop where it is, with `max_iterations:` on a `when:`-guarded " +
        "edge inside it, or raise the net for one run with " +
        "`runFlow(flow, inputs, { recursionLimit })`",
    );
    this.name = "SuperstepCeiling";
    this.ceiling = ceiling;
    this.cause = cause;
  }
}

/**
 * LangGraph's recursion error, restated in the composition's own terms, and the
 * error unchanged otherwise.
 *
 * The pinned import is the detection: a release that renamed the class fails
 * `tsc` on this module rather than silently passing its message through.
 */
export function restateCeiling(ceiling: number, error: unknown): unknown {
  return error instanceof GraphRecursionError ? new SuperstepCeiling(ceiling, error) : error;
}

/**
 * The trace a failed run carries: every entry that landed, then the aborting
 * node's own.
 *
 * `state` is the last one a superstep produced, which is the last one whose
 * writes were committed — so its `$run` holds exactly the entries of the steps
 * that completed. The aborting node's entry is appended rather than merged
 * because it never reached the reducer, and it belongs last for the same reason:
 * it is the step the recovered ones stopped short of.
 */
export function failedTrace(state: unknown, error: unknown): readonly TraceEntry[] {
  const held = (state as { $run?: RunChannel } | undefined)?.$run;
  const landed = held?.trace ?? [];
  const aborted = abortedEntry(error);
  return aborted === undefined ? landed : [...landed, aborted];
}

/**
 * The compiler's own state channel.
 *
 * A composition's `state:` channels are the author's (grammar 10); this is what
 * the *runtime* needs beside them and cannot put anywhere else: the flow
 * instance's input object and execution identity, which every CEL surface reads
 * as `input` and `execution`; the per-bounded-edge counters grammar 7.4 requires
 * in graph state; the per-node traversal ordinals of grammar 9.4; the step
 * number of grammar 7.6; and the routing trace PRD 5.3 asks for.
 *
 * It is named `$run` because grammar 2.1's identifier cannot spell it, so no
 * composition can collide with it.
 */
export interface RunChannel {
  readonly step: number;
  readonly input: Readonly<Record<string, unknown>>;
  readonly execution: ExecutionIdentity;
  readonly iterations: Readonly<Record<string, number>>;
  readonly traversals: Readonly<Record<string, number>>;
  /**
   * The result of every node a `map.over` in this flow reads (grammar 8.6
   * rule 11, 4.2).
   *
   * `over: plan.output.tasks` is the one place a node's result is read from
   * *another* node's task — Decision D42 keeps every other surface off node
   * outputs — and the producer ran in an earlier step, so its answer has to be
   * somewhere. Only the nodes a map actually reads are kept, because a node
   * output is arbitrarily large and this channel is copied into every superstep.
   * A node that was **skipped** writes its key back as `undefined`, which is how
   * grammar 8.6 rule 11's "dispatches zero instances" tells a producer that did
   * not run this pass from a stale value it left on the last one.
   */
  readonly outputs: Readonly<Record<string, unknown>>;
  /**
   * The frames of every node crossed from the **root** flow instance down to
   * this one, outermost first (grammar 9.4).
   *
   * Empty in the instance an invocation started; a `flow:` node appends
   * `<node>/<traversal>` and a `map` dispatch `<node>/<traversal>/<index>`. It is
   * what makes the idempotency key of a detached dispatch or a store write name
   * *one* effect site rather than a node id two instances share.
   */
  readonly path: readonly string[];
  /** Level 1 of grammar 9.3, if a `flow:` node instantiated this instance. */
  readonly policy?: InstancePolicy;
  readonly trace: readonly TraceEntry[];
}

/** The empty run channel a flow instance starts at. */
export function emptyRun(): RunChannel {
  return {
    step: 0,
    input: {},
    execution: { id: "", session_key: "" },
    iterations: {},
    traversals: {},
    outputs: {},
    path: [],
    trace: [],
  };
}

/**
 * Fold one node's contribution into the run channel.
 *
 * Concurrent nodes in one step each supply a partial update, and every field
 * merges in a way that does not depend on which of them the reducer sees first:
 * `step` takes the larger, the three key-wise maps merge key-wise (a node only
 * ever writes its own keys), and the trace is concatenated and then ordered by
 * `(step, node)` — the canonical write order of grammar 7.6.4, read for the one
 * channel whose order is otherwise the scheduler's.
 *
 * `path` and `policy` are the instance's own identity rather than anything a
 * node contributes: they are set once, in the state a flow instance is started
 * from, and a partial update that carries neither leaves them alone.
 */
export function mergeRun(left: RunChannel, right: Partial<RunChannel>): RunChannel {
  const trace = [...left.trace, ...(right.trace ?? [])];
  trace.sort((a, b) => a.step - b.step || (a.node < b.node ? -1 : a.node > b.node ? 1 : 0));
  const policy = right.policy ?? left.policy;
  return {
    step: Math.max(left.step, right.step ?? 0),
    input: right.input ?? left.input,
    execution: right.execution ?? left.execution,
    iterations: { ...left.iterations, ...(right.iterations ?? {}) },
    traversals: { ...left.traversals, ...(right.traversals ?? {}) },
    // Spread rather than `??`, so a skipped producer's `{ [node]: undefined }`
    // *replaces* the value it left on an earlier pass instead of being read as
    // "nothing to say" (grammar 8.6 rule 11).
    outputs: { ...left.outputs, ...(right.outputs ?? {}) },
    path: right.path ?? left.path,
    ...(policy === undefined ? {} : { policy }),
    trace,
  };
}

// ---------------------------------------------------------------------------
// Reading and writing a composition's own channels (grammar 8.0, 10)
// ---------------------------------------------------------------------------

/** How a write reaches its channel, which decides what one write supplies. */
export type Reduce = "set" | "append" | "merge";

/** One field of a node's output, and where it goes (grammar 8.0's write map). */
export interface WriteDescriptor {
  readonly field: string;
  readonly channel: string;
  readonly reduce: Reduce;
}

/**
 * The writes a **`map`** node makes to one channel, already in the canonical
 * order of grammar 7.6.4 clause 2 — source-item index, never completion order.
 *
 * A step's writers reach a channel one at a time and LangGraph's reducers are
 * called once per writer, so a map's *N* instances cannot each be a writer: a
 * fan-out of three appends would have to be three calls, and the order of those
 * calls is the scheduler's rather than the source array's. PRD 5.6 calls
 * unordered reduces a silent break of replay, so what the map node writes is one
 * value carrying all *N* contributions in index order — the "index-tagged and
 * reordered before the join" of PRD 5.6, arrived at as one write rather than as
 * a sorting reducer. Every reducer this compiler emits unpacks it
 * ([`appendReduce`], [`mergeReduce`], [`setReduce`]), so the map occupies its
 * own place in clause 1's node-id ordering while its instances are ordered
 * inside it by clause 2.
 *
 * It is a **class** rather than a tagged object because a composition's data is
 * JSON: no `default:`, no model answer, and no `exec` result can be an instance
 * of one, so `instanceof` cannot be spoofed by a value that merely looks like a
 * batch.
 */
export class OrderedWrites {
  /** The contributions, in ascending source-item index. */
  readonly values: readonly unknown[];

  constructor(values: readonly unknown[]) {
    this.values = values;
  }
}

/** What a channel's reducer may be handed: one write, or a `map`'s batch. */
export type Written<T> = T | OrderedWrites;

/** Whether this update is a `map` node's ordered batch rather than one write. */
export function isOrdered(value: unknown): value is OrderedWrites {
  return value instanceof OrderedWrites;
}

/**
 * What a `map`'s contributions to one channel go to LangGraph **as**: a batch
 * for the policies that unpack one, and the folded value for the one that
 * cannot be handed a batch at all.
 *
 * A channel that starts **unset** never calls its reducer for the first write.
 * LangGraph's `BinaryOperatorAggregate.update` keeps the first value verbatim
 * while it holds nothing — `if (this.value === void 0) { this.value = first;
 * newValues = newValues.slice(1); }` — so a batch arriving there would *become*
 * the channel's value: an `OrderedWrites` object where a declared type says
 * `string`, read back by every `state.<channel>` expression, every downstream
 * write, and the flow's own `outputs:`.
 *
 * Exactly one policy can be in that position. `append` and `merge` start at the
 * identity element their policy names (`[]`, `{}` — see `codegen::state`), so
 * their channel always holds a value and their reducer is always called;
 * `reduce: last_wins` with no `default:` starts unset, because grammar 10.1 and
 * Decision D78 say a channel with no declared default does and reading one
 * before its first write is an execution failure rather than a silent default.
 * So the batch is folded here for `set`, and the fold is exactly what
 * [`setReduce`] would have returned — the highest-indexed item's write
 * (grammar 8.6 rule 5, 10.2). The value a run ends with is the same under
 * either shaping; what changes is that it reaches the channel as the value.
 *
 * The half of that argument this function cannot see is the channel table, which
 * `codegen::state` emits: the identity elements are what make "always called"
 * true for `append` and `merge`, and a policy that stopped declaring one would
 * turn an unfolded batch into a channel's value with nothing here to notice.
 * `every_policy_a_map_batch_reaches_unfolded_starts_at_a_value`
 * (`codegen::state`) is the pairing asserted where the initial value is decided.
 */
export function orderedUpdate(batch: ChannelWrite): unknown {
  if (batch.reduce !== "set") return new OrderedWrites(batch.values);
  return batch.values[batch.values.length - 1];
}

/** `reduce: append` — one element per write, in canonical order (D58). */
export function appendReduce<T>(left: readonly T[], right: Written<T>): T[] {
  return isOrdered(right) ? [...left, ...(right.values as readonly T[])] : [...left, right];
}

/** `reduce: merge` — shallow key-wise, so the last writer in order wins a key. */
export function mergeReduce<T>(left: T, right: Written<T>): T {
  if (!isOrdered(right)) return { ...left, ...right };
  let value = left;
  for (const one of right.values) value = { ...value, ...(one as T) };
  return value;
}

/** `reduce: last_wins`, and a defaulted unreduced channel: the last write wins. */
export function setReduce<T>(left: T, right: Written<T>): T {
  if (!isOrdered(right)) return right;
  // A map contributes a channel entry only when it has at least one write for
  // it, so the batch is never empty — and `left` is what an empty one would
  // have to leave behind anyway.
  return right.values.length === 0 ? left : (right.values[right.values.length - 1] as T);
}

/** Read a state channel by name, failing the way Decision D78 says (grammar 10.1). */
export function channelValue(
  state: Readonly<Record<string, unknown>>,
  channel: string,
  reader: string,
): unknown {
  const value = state[channel];
  if (value === undefined) {
    throw new Error(
      `the state channel \`${channel}\` is unset and ${reader} reads it (grammar 10.1, Decision D78)`,
    );
  }
  return value;
}

/** Read one field of the enclosing flow's input object (grammar 8.0 step 3). */
export function flowInput(run: RunChannel, field: string, reader: string): unknown {
  const value = run.input[field];
  if (value === undefined) {
    throw new Error(`the flow input \`${field}\` is absent and ${reader} reads it`);
  }
  return value;
}

/** The value a channel holds once this write has landed, for a guard to read. */
export function applyWrite(previous: unknown, value: unknown, reduce: Reduce): unknown {
  if (reduce === "append") return appendReduce((previous as unknown[]) ?? [], value);
  if (reduce === "merge") {
    return mergeReduce((previous as Record<string, unknown>) ?? {}, value as Record<string, unknown>);
  }
  return setReduce(previous, value);
}

// ---------------------------------------------------------------------------
// Subgraph instantiation (grammar 7.5, 8.5) and fan-out (grammar 8.6)
// ---------------------------------------------------------------------------

/**
 * Anything that can be run to quiescence: a compiled flow, or one of them
 * reached as a subflow.
 *
 * `signal` is LangGraph's own cancellation key (`RunnableConfig.signal`, which
 * the Pregel runner races against each superstep), and it is here because a
 * subgraph is the one activity this runtime can really *stop*: an aborted run
 * stops scheduling tasks instead of carrying on to quiescence. Who supplies it
 * is [`Instantiation.signal`].
 */
export interface Quiescible<S> {
  stream(
    initial: Record<string, unknown>,
    options: { recursionLimit: number; signal?: AbortSignal },
  ): Promise<AsyncIterable<S>>;
}

/**
 * Run a compiled graph until it quiesces, keeping the last state each superstep
 * produced.
 *
 * A stream rather than an invocation because of what a **failure** must leave
 * behind: LangGraph's `invoke` is this loop with the last value kept, and an
 * error thrown out of it discards the state it was keeping — the routing trace
 * of PRD 5.3 with it. Taking the supersteps one at a time keeps every one that
 * did complete, which is what a failure is then reported with. Both callers need
 * that, which is why it is here rather than written twice.
 *
 * `signal` is the caller's deadline, when the caller has one: a `flow:` node and
 * a joined `map` dispatch each run their instance inside a node budget, and a
 * top-level run has no clock above it to pass. See [`Instantiation.signal`].
 */
export async function quiesce<S extends { $run: RunChannel }>(
  graph: Quiescible<S>,
  initial: Record<string, unknown>,
  recursionLimit: number,
  signal?: AbortSignal,
): Promise<{ state?: S; error?: unknown }> {
  let state: S | undefined;
  try {
    const supersteps = await graph.stream(initial, { recursionLimit, signal });
    for await (const superstep of supersteps) {
      // An interrupt is announced as a chunk of its own rather than as a state,
      // and reading it as one would lose the run's.
      if (!isInterrupted(superstep)) state = superstep;
    }
  } catch (error) {
    return { state, error: restateCeiling(recursionLimit, error) };
  }
  return { state };
}

/**
 * The instance path of the flow instance a `flow:` node is about to start
 * (grammar 9.4).
 *
 * The frame is `<node id>/<traversal ordinal>`, where the ordinal is how many
 * times this node has already begun executing in *its own* instance — so the
 * second traversal of a bounded cycle instantiates a different effect site than
 * the first, and a node-level `retry:` re-running the same attempt does not.
 */
export function instancePath(view: NodeView, node: string): readonly string[] {
  return [...view.run.path, `${node}/${view.run.traversals[node] ?? 0}`];
}

/**
 * Grammar 9.3 level 1 for the instance a `flow:` node starts: what already
 * reached this instance, then what this site declares (Decision D79).
 *
 * **Outermost wins, per field.** A caller's hardening of a module it does not
 * own cannot be undone by that module's own instantiation of a deeper one, so an
 * inherited value is never replaced — only an absent one is filled in.
 */
export function instancePolicy(
  inherited: InstancePolicy | undefined,
  declared: InstancePolicy | undefined,
): InstancePolicy | undefined {
  if (inherited === undefined) return declared;
  if (declared === undefined) return inherited;
  const retry = inherited.retry ?? declared.retry;
  const timeoutMs = inherited.timeoutMs ?? declared.timeoutMs;
  const onError = inherited.onError ?? declared.onError;
  return {
    ...(retry === undefined ? {} : { retry }),
    ...(timeoutMs === undefined ? {} : { timeoutMs }),
    ...(onError === undefined ? {} : { onError }),
  };
}

/** One compiled flow, as a `flow:` node or a `map` dispatch reaches it. */
export interface SubflowBinding extends Quiescible<GraphStateLike> {
  /** Its typed address (grammar 2.2). */
  readonly address: string;
  /** The fields its `outputs:` declares, each read from the channel of that name. */
  readonly outputs: readonly string[];
  /** The superstep ceiling one instance of it takes. */
  readonly recursionLimit: number;
}

/** What one instantiation supplies to the instance it starts (grammar 7.5). */
export interface Instantiation {
  /**
   * The subflow's `inputs:`, bound by the instantiating node.
   *
   * **Total, and the only thing that crosses**: a subgraph receives parent state
   * exclusively through these (PRD 5.7, Decision D68). The instance's channels
   * start at their own `default:`s, which is what makes a flow's behaviour
   * independent of the caller that ran it (grammar 10.1).
   */
  readonly inputs: Record<string, unknown>;
  /** The run identity the instance carries (grammar 4.1). */
  readonly execution: ExecutionIdentity;
  /** Its instance path, for anything nested inside it (grammar 9.4). */
  readonly path: readonly string[];
  /**
   * The instantiating node's deadline, which crosses the boundary with it
   * (grammar 9.2).
   *
   * A subgraph is the one activity a `timeout:` can really **stop**. Every other
   * kind is either cooperative (`fetch` takes a signal, `spawn` is killed) or
   * uncancellable (a host function), so [`runActivity`] races the budget and the
   * node fails on time whatever the activity does — but an instance nothing
   * aborted would run on to quiescence *after* the node that started it had
   * already failed: issuing every effect its remaining nodes were going to
   * issue, and holding the [`Admission`] permit a later execution of the same
   * `map` node has to wait for. LangGraph stops scheduling supersteps when this
   * aborts, so what is left in flight inside is one abandoned activity rather
   * than the whole rest of the instance.
   *
   * A **detached** dispatch supplies it too, and it is the delivery's own signal
   * — the one nothing aborts (Decision D94, and see [`runMap`]) — so an instance
   * reached that way runs to quiescence exactly as its sink does. Quiescence is
   * something it can always *reach*, because the one construct that could stop
   * an instance short of it while nothing is waiting is refused at build time: a
   * detached dispatch reaching a `human` node is a validation error
   * (Decision D118).
   */
  readonly signal?: AbortSignal;
  /** Level 1 of grammar 9.3 for every node inside it. */
  readonly policy?: InstancePolicy;
  /**
   * The caller's conversation history, on a `context: inherit` instantiation
   * (grammar 8.5, 10.4).
   *
   * Absent is `isolated`, which is the default and what a `map` dispatch always
   * gets: the instance starts on a fresh history, and what it says there is
   * discarded when it finishes (Decision D105).
   */
  readonly history?: readonly unknown[];
}

/**
 * Instantiate one subflow and materialize its `outputs:` at quiescence
 * (grammar 7.5, 7.6.3, 8.5).
 *
 * The instance is a **separate run of a separate compiled graph**, which is what
 * gives it its own channel values: grammar 10.1 makes the channel set
 * composition-global in shape and per-instance in value, and a subgraph added to
 * the caller's graph would share the caller's values instead. Only two things
 * cross the boundary, in each direction: the `inputs:` this instantiation bound,
 * and the `outputs:` read back out of the instance's own channels.
 *
 * What crosses beside them is not data but a **clock**: the instantiating node's
 * deadline ([`Instantiation.signal`]), so a `timeout:` on a `flow:` node — or on
 * the `map` node a joined dispatch belongs to — ends the instance rather than
 * only the node's wait for it.
 */
export async function runSubflow(
  binding: SubflowBinding,
  instance: Instantiation,
): Promise<NodeAnswer> {
  const seeded = instance.history ?? [];
  const initial: Record<string, unknown> = {
    $run: {
      ...emptyRun(),
      input: instance.inputs,
      execution: instance.execution,
      path: instance.path,
      ...(instance.policy === undefined ? {} : { policy: instance.policy }),
    },
    ...(instance.history === undefined ? {} : { messages: [...seeded] }),
  };

  const { state, error } = await quiesce(
    binding,
    initial,
    binding.recursionLimit,
    instance.signal,
  );
  const trace = state?.$run.trace ?? [];
  if (error !== undefined) {
    // The node that stopped the instance is part of the account of it, and it is
    // the part a reader looks for first: it never reached the reducer, so the
    // committed state does not have it. [`failedTrace`] recovers it from the
    // error the way [`runFlow`] does for a top-level run — the boundary is a
    // module boundary, not a reason to report less about what happened inside
    // it (grammar 8.5, PRD 5.3).
    throw new SubflowFailure(
      binding.address,
      "did not run to quiescence",
      failedTrace(state, error),
      error,
    );
  }
  if (state === undefined) {
    // Unreachable: `streamMode: "values"` emits the state the instance started
    // from before any node has run.
    throw new SubflowFailure(
      binding.address,
      "produced no state",
      trace,
      new Error("the instance emitted no superstep"),
    );
  }

  const held = state as unknown as Record<string, unknown>;
  const output: Record<string, unknown> = {};
  try {
    for (const field of binding.outputs) {
      output[field] = channelValue(
        held,
        field,
        `\`${binding.address}\`'s output field \`${field}\``,
      );
    }
  } catch (cause) {
    throw new SubflowFailure(binding.address, "reached quiescence without an output", trace, cause);
  }

  // On `context: inherit`, what the instance *added* is what goes back to the
  // caller's channel: the seeded turns are already there, and appending them
  // again would double the conversation (grammar 8.5, 10.4).
  const grown = held["messages"];
  const added =
    instance.history === undefined || !Array.isArray(grown) ? [] : grown.slice(seeded.length);
  return {
    output,
    ...(added.length === 0 ? {} : { history: added }),
    inner: trace,
  };
}

/**
 * A counting semaphore: `max_concurrency`, enforced (grammar 8.6 rule 1, D28).
 *
 * LangGraph's own `maxConcurrency` is a **run-level** config key — the Pregel
 * runner reads it once per superstep and applies it to every task in that step —
 * so it cannot say "this map at 8, its `auto_fixable` route at 4, and the
 * `announce` node running beside them unbounded", which is exactly what D28
 * declares. The bound is normative, so it is counted here.
 *
 * It is an **admission** bound: a permit is taken before a dispatch starts and
 * held until it settles, so what the number bounds is how many of this map's
 * instances are in flight at once — every one of them, detached included
 * (grammar 8.6's key table). Which gate a dispatch takes its permit from is
 * [`Admission`]'s: the bound is over a node, not over a call.
 *
 * **A joined waiter is served before a detached one**, which is grammar 8.6 rule
 * 7's "nothing it does can *delay* the enclosing flow instance" enforced at the
 * one place a detached dispatch could: the queue. A joined instance waiting
 * behind a queued delivery waits out that delivery's whole duration, and the
 * queue spans executions — [`Admission`] belongs to the node, so a bounded
 * cycle's second traversal, or the node's own `retry:`, would otherwise line its
 * instances up behind deliveries the previous traversal left in flight. Ordering
 * the queue costs the delivery nothing: it still starts under a permit (the key
 * table), just never ahead of work the join is waiting for. [`runMap`] keeps the
 * other half — a delivery is not *issued* until this call's joined instances are
 * admitted, because a permit already taken cannot be reordered.
 *
 * `permits > 0` implies both queues are empty, because [`release`] hands a
 * permit straight to a waiter rather than returning it to the count — so the
 * fast path cannot jump a detached dispatch over a waiting joined one.
 */
class Gate {
  private permits: number;
  /** Joined waiters: the dispatches the map node's join is waiting on. */
  private readonly waiting: (() => void)[] = [];
  /** Detached waiters, served only once no joined dispatch wants a permit. */
  private readonly deferred: (() => void)[] = [];

  constructor(permits: number) {
    this.permits = Math.max(1, permits);
  }

  async acquire(kind: DispatchKind = "joined"): Promise<void> {
    if (this.permits > 0) {
      this.permits -= 1;
      return;
    }
    await new Promise<void>((resolve) => {
      (kind === "detached" ? this.deferred : this.waiting).push(resolve);
    });
  }

  release(): void {
    const next = this.waiting.shift() ?? this.deferred.shift();
    if (next === undefined) {
      this.permits += 1;
    } else {
      next();
    }
  }
}

/** Which half of grammar 8.6 rule 7 a dispatch queues under (see [`Gate`]). */
type DispatchKind = "joined" | "detached";

/**
 * The permits one `map` **node** admits its dispatches against (grammar 8.6's
 * key table, Decision D28).
 *
 * A gate built inside [`runMap`] would bound one *call*, and a dispatch can
 * outlive the call that issued it: `detach: true` is resolved at dispatch (D94)
 * and its delivery is still in flight when the map node returns. So a node-level
 * `retry:` and a second traversal of a bounded cycle each start a fresh call
 * while the previous one's deliveries hold permits nothing counts any more — and
 * a map declaring 1 reaches 2 in flight, which is the number an author wrote it
 * down to prevent. The gates therefore belong to the node, and every execution
 * of it draws on the same ones.
 *
 * **Which node.** The enclosing flow *instance*'s, not the flow's: the key is
 * the execution id, the instance path, and the node id ([`MapPlan.admission`]).
 * Two concurrent instances of one dispatched subflow are two separate runs of
 * that flow, each bounding its own map node, and a bound shared between them
 * would serialize siblings an author asked to run side by side — and would
 * deadlock outright on a flow that dispatches itself, where the outer instance
 * holds a permit the inner one is waiting for.
 *
 * **Why it is counted.** The entry is retired when the last dispatch counted
 * against it settles, so the table holds one entry per map node that is *doing
 * something* rather than one per node the process ever ran. A delivery that
 * never settles keeps its node's entry — and its permit — which is the same
 * unbounded wait an abandoned host function is, and is bounded for the run by
 * the node's own `timeout:` rather than by anything here.
 *
 * Spanning executions is also the one way a detached delivery can still be in
 * front of a joined instance, so it is the reason [`Gate`] orders its queue: the
 * call that *issued* the delivery cannot queue behind it ([`runMap`] admits its
 * joined instances first), but a second traversal of a bounded cycle knows
 * nothing of it. A delivery this table is still holding a permit for is served
 * after every joined waiter, so the only one that can delay a later execution is
 * one that already *started* — which is the abandoned-host-function wait above,
 * and is what that execution's own `timeout:` is racing.
 */
interface Admission {
  /** `max_concurrency:` — the node-wide bound (grammar 8.6 rule 1). */
  readonly node: Gate;
  /** A route's own bound, keyed by its position in the descriptor. */
  readonly routes: Map<string, Gate>;
  /** Dispatches counted against it: in flight, or still queued for a permit. */
  outstanding: number;
}

/** Every map node with a dispatch outstanding, by [`MapPlan.admission`]. */
const admissions = new Map<string, Admission>();

/** One fresh set of permits, for the bounds this descriptor declares. */
function permitsFor(map: MapDescriptor): Admission {
  return { node: new Gate(map.maxConcurrency), routes: new Map(), outstanding: 0 };
}

/**
 * The permits this dispatch of `map` is admitted against, counting its
 * instances in.
 *
 * A plan of **zero** instances registers nothing: an entry with no dispatch to
 * retire it is an entry that never goes away, and a map that dispatched nothing
 * has nothing to bound.
 */
function admit(map: MapDescriptor, plan: MapPlan): Admission {
  if (plan.instances.length === 0) return permitsFor(map);
  let held = admissions.get(plan.admission);
  if (held === undefined) {
    held = permitsFor(map);
    admissions.set(plan.admission, held);
  }
  held.outstanding += plan.instances.length;
  return held;
}

/** One dispatch has settled; the node's permits go away with the last of them. */
function retire(key: string, admission: Admission): void {
  admission.outstanding -= 1;
  if (admission.outstanding <= 0 && admissions.get(key) === admission) {
    admissions.delete(key);
  }
}

/** `on_item_error:` — per item, and map-wide (grammar 8.6 rule 10, D73). */
export type ItemPolicy = "fail" | "skip" | { readonly retry: RetryPolicy };

/** Where one dispatch sits, for everything nested inside it (grammar 9.4). */
export interface DispatchSite {
  /** The instance's run identity, carrying this dispatch's `item_index`. */
  readonly execution: ExecutionIdentity;
  /** Its instance path (grammar 9.4). */
  readonly path: readonly string[];
  /**
   * The key a **detached** delivery carries, derived from the execution id and
   * this dispatch's flattened instance path (grammar 9.4, PRD 5.6).
   *
   * Derived for every dispatch rather than only the detached ones: it costs a
   * `join` and it is what a `store` write inside a dispatched `flow.*` will need
   * from the same site. What *delivers* it is [`delivering`], at the one kind of
   * dispatch grammar 9.4 names as a carrier.
   */
  readonly idempotencyKey: string;
}

/** One dispatch target of a `map` (grammar 8.6). */
export interface MapRoute {
  /**
   * Its variant tag, `"$default"` for the catch-all, absent on `node:`.
   *
   * Read for the trace and for nothing else: which route an item takes is
   * [`selectRoute`]'s, and the catch-all is a field of its own on
   * [`MapDescriptor`] rather than an entry in `routes`. See
   * [`DispatchRecord.route`] for why the catch-all's spelling is not one an
   * author could have written.
   */
  readonly tag?: string;
  /** The component it dispatches to. */
  readonly target: string;
  /** Its own bound, at most the map's (grammar 8.6 rule 1). */
  readonly maxConcurrency: number;
  /** `detach: true` — resolved at dispatch (grammar 8.6 rule 7, D94). */
  readonly detach: boolean;
  /**
   * The shape the item is read through: **this route's variant payload**, not
   * the union (grammar 8.6 rule 4).
   */
  readonly itemShape: Shape;
  /** Build one instance's input from the item (grammar 8.6 rule 12). */
  input(roots: Roots): unknown;
  /** Run one instance. */
  run(input: unknown, context: RunContext, site: DispatchSite): Promise<NodeAnswer>;
  /** Where its result's fields go — reduced channels only (rule 5). */
  readonly writes: readonly WriteDescriptor[];
}

/** Everything `./graph.ts` says about one `map` node (grammar 8.6). */
export interface MapDescriptor {
  /** The flow-local node id, which every frame and message is written from. */
  readonly node: string;
  /** `as:` — what the item is called in the per-item expressions. */
  readonly as: string;
  /** `over:` — the path expression, and the node whose result it reads. */
  readonly source: {
    readonly path: string;
    readonly producer?: string;
    readonly shape: Shape;
  };
  /** `max_concurrency:` — the node-wide admission bound (D28, and see [`Gate`]). */
  readonly maxConcurrency: number;
  /** `on_item_error:` — map-wide, and read from the `map:` block alone (rule 10). */
  readonly onItemError: ItemPolicy;
  /** `route_by:` — the literal discriminator field, on the routed form (rule 8). */
  readonly routeBy?: string;
  /** The named routes in declaration order, or the single homogeneous target. */
  readonly routes: readonly MapRoute[];
  /** `default:` — the catch-all (D30). */
  readonly fallback?: MapRoute;
}

/** One instance a `map` will dispatch, decided before any of them runs. */
interface PlannedInstance {
  readonly index: number;
  readonly route: MapRoute;
  /** The discriminator the item carried, on the routed form (rule 8). */
  readonly variant?: string;
  readonly input: unknown;
  readonly site: DispatchSite;
}

/**
 * What a `map` node's input phase answers: every dispatch, already bound.
 *
 * Every plan also carries [`MAP_PLAN`], which is what [`plannedDispatches`]
 * recognises one by. Not declared here on purpose: it is set with
 * `Object.defineProperty` the way [`carryEntry`] sets [`ABORTED`], so no
 * consumer of this type is shown a member it would have to spell a symbol to
 * construct.
 */
export interface MapPlan {
  readonly instances: readonly PlannedInstance[];
  /**
   * Which map node this is a dispatch of: the execution id, the enclosing
   * instance's path, and the node id.
   *
   * What [`Admission`] is keyed by, and the reason it is derived here rather
   * than in [`runMap`]: the plan is built once per node execution and reused
   * across the node's own `retry:` attempts, and a later traversal of a bounded
   * cycle builds a new plan with the same key — which is exactly the span the
   * bound has to cover.
   */
  readonly admission: string;
  /**
   * What this node's dispatches resolved to, as they resolve.
   *
   * [`runMap`] answers with the whole account when it returns and carries it on
   * an [`ItemFailure`] when an item fails it, and neither reaches [`runNode`]
   * when the node's own `timeout:` fires: the deadline is *raced*, so the map's
   * promise — and everything riding on it — is abandoned where it stands. The
   * plan is the one thing both sides hold, so the records are written here too
   * and `runNode` reads them off a node it never got an answer from.
   *
   * Reset at the start of every call, because a node retry re-executes the whole
   * fan-out and the trace reports the attempt it made, not the sum of them.
   * Every value that escapes is a copy: this array is cleared in place, and a
   * trace entry an earlier traversal already holds must not empty out under it.
   */
  readonly records: DispatchRecord[];
}

/**
 * What marks an object as a [`MapPlan`], for [`plannedDispatches`] to read.
 *
 * `Symbol.for` and non-enumerable for the two reasons [`ABORTED`] is both: a
 * composition can spell any field name grammar 2.1 allows, and cannot spell
 * this; and a plan carrying one still serializes and logs the way the same
 * object without one does.
 */
const MAP_PLAN = Symbol.for("agent-compose.mapPlan");

/**
 * Decide a `map`'s whole dispatch **before** anything runs: how many instances,
 * which route each takes, and what each is passed (grammar 8.6 rules 4, 11, 12).
 *
 * This is the map's *input phase*, and it is separate from [`runMap`] for the
 * reason `runNode` builds every node's input outside its policy: reading an
 * absent value fails the **execution** (grammar 4.1, Decisions D110, D78), and
 * neither `on_item_error` nor the map node's `on_error:` may absorb that. A
 * per-item binding that reads a channel nothing has written is a broken
 * composition, not a failed item.
 */
export function mapPlan(map: MapDescriptor, view: NodeView): MapPlan {
  const traversal = view.run.traversals[map.node] ?? 0;
  const items = mapSource(map, view);
  const instances: PlannedInstance[] = items.map((item, index) => {
    const route = selectRoute(map, item);
    const execution: ExecutionIdentity = { ...view.run.execution, item_index: index };
    const frame = `${map.node}/${traversal}/${index}`;
    const path = [...view.run.path, frame];
    const site: DispatchSite = {
      execution,
      path,
      idempotencyKey: [view.run.execution.id, ...path].join("/"),
    };
    const roots: Roots = {
      ...view.roots,
      execution: bindRoot(execution, EXECUTION_SHAPE),
      [map.as]: bindRoot(item, route.itemShape),
    };
    const variant = variantOf(map, item);
    return {
      index,
      route,
      ...(variant === undefined ? {} : { variant }),
      input: route.input(roots),
      site,
    };
  });
  const plan: MapPlan = {
    instances,
    admission: [view.run.execution.id, ...view.run.path, map.node].join("/"),
    records: [],
  };
  Object.defineProperty(plan, MAP_PLAN, { value: true, enumerable: false });
  return plan;
}

/**
 * The array `over` resolves to (grammar 4.2, 8.6 rule 11).
 *
 * A producer that was **skipped** on this pass has no result, and the map then
 * dispatches zero instances — grammar 8.6 rule 11's last sentence, which rule 6
 * makes a completion rather than a failure.
 */
function mapSource(map: MapDescriptor, view: NodeView): unknown[] {
  let roots = view.roots;
  const producer = map.source.producer;
  if (producer !== undefined) {
    const produced = view.run.outputs[producer];
    if (produced === undefined) return [];
    roots = {
      ...roots,
      [producer]: bindRoot({ output: produced }, { properties: { output: map.source.shape } }),
    };
  }
  const value = toJson(evaluate(map.source.path, roots));
  if (!Array.isArray(value)) {
    // Unreachable over an artifact `build` accepted: `over` is resolved against
    // the declared schemas and must land on an array (grammar 8.6 rule 1).
    throw new Error(
      `\`${map.node}\`'s \`over: ${map.source.path}\` did not resolve to an array (grammar 8.6 rule 1)`,
    );
  }
  return value;
}

/**
 * How one route is addressed inside its node's [`Admission`].
 *
 * By **position** in the descriptor rather than by `tag:`, because the tag is
 * the author's spelling of a variant and the catch-all has one of its own: two
 * routes whose tags collided would share a bound neither declared. The
 * descriptor a compiled `graph.ts` passes is a module constant, so a route's
 * position is the same on every traversal.
 */
function routeKey(map: MapDescriptor, route: MapRoute): string {
  const at = map.routes.indexOf(route);
  return at < 0 ? "*" : String(at);
}

/**
 * The discriminator one item carries, for its dispatch record (rule 8, and see
 * [`DispatchRecord.variant`]).
 *
 * `undefined` on the homogeneous form, which declares no `route_by:` and whose
 * items are not a union — there is no variant to name. On the routed form it is
 * the value at the literal discriminator field, read as a string because that is
 * what a variant tag is (grammar 3.2), and a validated artifact has no other
 * kind: `route_by:` names the discriminator of a discriminated union, and the
 * items were parsed against their producer's declared schema before the fan-out
 * planned anything (PRD 5.2). So the narrowing below is what makes the read
 * total rather than a policy about values that reach it.
 *
 * A non-string that reached here anyway is left **unrecorded** rather than
 * rendered, and not because [`selectRoute`] would have refused it — with a
 * `default:` catch-all it routes it (rule 4, D30) — but because a number spelled
 * as a string would be a `variant` that is not one of the union's declared tags,
 * which is the one thing [`DispatchRecord.variant`] promises it is.
 */
function variantOf(map: MapDescriptor, item: unknown): string | undefined {
  if (map.routeBy === undefined) return undefined;
  const tag = (item as Record<string, unknown> | null)?.[map.routeBy];
  return typeof tag === "string" ? tag : undefined;
}

/** Which route one item takes (grammar 8.6 rules 2, 4). */
function selectRoute(map: MapDescriptor, item: unknown): MapRoute {
  if (map.routeBy === undefined) {
    return map.routes[0]!;
  }
  const tag = (item as Record<string, unknown> | null)?.[map.routeBy];
  const named = map.routes.find((route) => route.tag === tag);
  if (named !== undefined) return named;
  if (map.fallback !== undefined) return map.fallback;
  // Unreachable: exhaustiveness is a compile error, and the item's own schema
  // admits no other tag (grammar 8.6 rule 4). An item that got here anyway is
  // one the parse should have refused, so it says so rather than being dropped.
  throw new Error(
    `\`${map.node}\` has no route for \`${map.routeBy}: ${JSON.stringify(tag)}\` and no \`default:\` (grammar 8.6 rule 4)`,
  );
}

/**
 * Dispatch a `map`, join, and answer with the writes its instances made — in
 * source-item order (grammar 8.6 rules 5, 6, 10, PRD 5.6).
 *
 * **The join is the node.** The map node completes when every instance has
 * completed, been resolved by `on_item_error`, or been detached, which is
 * grammar 7.6's fan-out barrier; because the node's own outgoing edges are
 * evaluated in its own task after it completes (P1), the downstream edge fires
 * exactly once, after the join, whatever order the instances finished in. A
 * dispatch of **zero** instances completes immediately and writes nothing, and
 * its edges fire as if every instance had finished (rule 6).
 *
 * **A detached dispatch is admitted, but never ahead of the join.** It takes a
 * node permit before it starts, because `max_concurrency` bounds every in-flight
 * dispatch (grammar 8.6's key table) — a map declaring 2 against a rate-limited
 * provider would otherwise reach 2 + the detached route's bound. What the join
 * never does is wait on its *outcome* (D94): the delivery is counted resolved
 * the moment it is issued, and the map node returns while it is still in flight.
 *
 * Those two are a bound and a queue, and a queue is the one place the second can
 * take the first back. A delivery that held a permit a joined instance was
 * waiting for would *delay* the enclosing flow instance, which rule 7 says
 * outright that a detached dispatch cannot do: at `max_concurrency: 1` a
 * detached item ahead of a joined one made the map node wait out the sink, and a
 * sink that never answered never released the permit at all — the join hung for
 * ever on a delivery it is defined not to wait for. So a detached dispatch
 * queues **behind every joined instance**, in both of the ways it could get
 * ahead of one:
 *
 *   * it is not *issued* until every joined instance of this call has been
 *     admitted. A permit is taken synchronously by whichever dispatch asks
 *     first, and the loop below issues them in source-item order, so a detached
 *     item at index 0 would otherwise hold the permit before the joined item at
 *     index 1 had asked — no queue discipline can reorder a permit already
 *     taken, so it is not taken;
 *   * once issued it waits as a `"detached"` [`Gate`] waiter, which is served
 *     only when no joined dispatch wants a permit. That covers the executions
 *     this call cannot see: [`Admission`] belongs to the node, so a bounded
 *     cycle's second traversal — or the node's own `retry:` — would otherwise
 *     line its joined instances up behind deliveries this one left queued.
 *
 * Both halves of the key table then hold at once: a detached dispatch waits for
 * a permit to *start*, and the join waits for none of it. Nothing is lost to the
 * ordering either — a delivery that is merely *later* is still delivered, which
 * is the distinction rule 7 and PRD 5.6 trade dedupe-on-a-key to keep. What
 * survives is narrower and honest: a delivery that has already *started* and
 * never settles still holds its permit, exactly as an abandoned host function
 * holds a slot, and only a *later* execution of this node can meet it there
 * ([`Admission`]).
 *
 * **A detached delivery is off the node's clock.** It runs under a signal of its
 * own, never `context.signal`. That signal is the map node's `timeout:`
 * (grammar 9.2), and a delivery still queued for a permit when the budget ran
 * out would otherwise *start* against an already-aborted signal — [`runHttp`]
 * hands it to `fetch` and [`runExec`] to `spawn`, so it would throw before
 * anything reached the wire, be swallowed by the dispatch's own catch, and leave
 * a record saying `detached` for a message that was never sent. That is the lost
 * message grammar 8.6 rule 7 and PRD 5.6 trade dedupe-on-a-key to avoid, and the
 * budget has nothing to say about it: a deadline bounds what the node *waits*
 * for, and D94 is the statement that the node waits for none of this.
 *
 * **Order comes from the index, never from completion.** Results are collected
 * per instance and folded into one [`ChannelWrite`] per channel afterwards, in
 * ascending source-item index — so two runs over one array leave every channel
 * holding the same value even when the provider answers them in the opposite
 * order (grammar 7.6.4 clause 2, 10.2).
 */
export async function runMap(
  map: MapDescriptor,
  plan: MapPlan,
  context: RunContext,
): Promise<NodeAnswer> {
  const admission = admit(map, plan);
  const node = admission.node;
  const gateOf = (route: MapRoute): Gate => {
    const key = routeKey(map, route);
    let gate = admission.routes.get(key);
    if (gate === undefined) {
      gate = new Gate(Math.min(route.maxConcurrency, map.maxConcurrency));
      admission.routes.set(key, gate);
    }
    return gate;
  };

  // The plan's own account, which is the copy a node that never returns an
  // answer is read from — so it starts this execution empty. Everything that
  // leaves here is a copy of it, because it is cleared in place.
  const records = plan.records;
  records.length = 0;
  const landed: {
    index: number;
    route: MapRoute;
    output: unknown;
    models?: readonly ModelCall[];
    toolDispatches?: readonly DispatchRecord[];
  }[] = [];
  const failed: { index: number; target: string; attempts: number; error: unknown }[] = [];
  const joined: Promise<void>[] = [];

  // What a detached dispatch waits behind before it asks for a permit at all:
  // every joined instance of this call, admitted (grammar 8.6 rule 7, and see
  // *A detached dispatch is admitted, but never ahead of the join* above). The
  // count is taken before anything runs, because the loop below issues the
  // dispatches in source-item order and a detached item at index 0 would
  // otherwise take the permit before the joined item at index 1 exists.
  //
  // A plan of no joined instances releases it immediately: there is nothing for
  // a delivery to get ahead of, and a barrier nothing resolves would strand
  // every delivery a fire-and-forget map exists to make.
  let unadmitted = plan.instances.reduce(
    (count, dispatch) => count + (dispatch.route.detach ? 0 : 1),
    0,
  );
  let admitted = (): void => {};
  const joinedAdmitted: Promise<void> =
    unadmitted === 0
      ? Promise.resolve()
      : new Promise<void>((resolve) => {
          admitted = () => {
            unadmitted -= 1;
            if (unadmitted === 0) resolve();
          };
        });

  for (const instance of plan.instances) {
    const { index, route, site } = instance;
    // What this dispatch is *about*, on every record it produces: the route the
    // item took, and — on the routed form — the discriminator it carried, which
    // the catch-all's own tag does not name (see [`DispatchRecord.variant`]).
    const named = {
      ...(route.tag === undefined ? {} : { route: route.tag }),
      ...(instance.variant === undefined ? {} : { variant: instance.variant }),
    };
    // The node's context with the instance's own identity. `deadline` is
    // re-exposed as a getter rather than left to the spread, which would have
    // copied one reading of a budget that moves: the map node's clock stops
    // while a pause below it is open (Decision D102), and an instance holding a
    // copy would divide a budget the wait had already spent
    // (see [`RunContext.deadline`]).
    const scoped: RunContext = {
      ...context,
      execution: site.execution,
      get deadline(): number | undefined {
        return context.deadline;
      },
      // And the instance's own effect site, which is what keeps two items of one
      // fan-out off each other's journal keys: the dispatch's path is the
      // frame `docs/trace.md` §8 gives it, `<node>/<traversal>/<index>`, and an
      // effect under it derives its key from that rather than from the map
      // node's. The counters stay the execution's, so a node `retry:` that
      // re-runs the whole fan-out records a second set of effects instead of
      // colliding with the first attempt's (`docs/durability.md` §4).
      ...(context.effects === undefined
        ? {}
        : { effects: context.effects.child(site.path.join("/")) }),
    };

    if (route.detach) {
      // Resolved at dispatch (Decision D94): the record is written now, the
      // delivery is issued now, and the join never learns what became of it.
      records.push({
        index,
        ...named,
        target: route.target,
        outcome: "detached",
        attempts: 0,
        idempotencyKey: site.idempotencyKey,
      });
      const gate = gateOf(route);
      // Its own signal, never the node's: see *A detached delivery is off the
      // node's clock* above. One per delivery rather than one per call, so a
      // fan-out of many sinks does not pile listeners onto a shared signal.
      // Off the node's clock in **both** halves of it: the signal nothing
      // aborts, and no `deadline` either — a delivery that inherited the node's
      // expiry would hand a model route a share of a budget this delivery is
      // defined not to be bounded by (see `RunContext.deadline`, `callModel`).
      //
      // And off the node's **trace entry**, which is the same statement about
      // the other pair a context carries. `storeRecords` and `modelCalls` are
      // the node execution's collectors, created by [`runNode`] and read the
      // moment the join below returns — and by D94 the join does not wait for
      // this delivery. A record pushed through the node's copy would therefore
      // land on the entry or not depending on when the sink answered, so two
      // runs of one composition would produce two trace documents. `docs/trace.md`
      // §5.1 and §7.2 both say they do not: an entry reports what the *join*
      // observed, and a detached delivery's outcome is the one thing it never
      // observes — `outcome: "detached"` and `attempts: 0` are already that
      // statement, and an entry that carried the delivery's model call beside
      // them would contradict both. Dropped rather than collected somewhere
      // else, because there is no entry for a second collector to reach.
      const delivery: RunContext = {
        ...scoped,
        signal: new AbortController().signal,
        deadline: undefined,
        storeRecords: undefined,
        modelCalls: undefined,
        toolDispatches: undefined,
      };
      // And off the **quiescence** reading, which is the same statement about a
      // third reader. A `flow.*` sink runs its own nodes under this execution's
      // id, so a parking webhook that waited for them would wait for exactly the
      // work rule 7 says nothing waits for — a subscriber told about a pause it
      // could have answered when the delivery finally released (see
      // [`inFlight`], [`quiescent`], and `src/serve.ts`'s `parking`). The mark
      // goes down before the delivery is issued, so a sink that reaches its first
      // node in this tick is already inside it, and comes off however the
      // delivery ends — including before `route.run` is reached.
      const undetach = detaching(scoped.execution.id, site.path.join("/"));
      const delivering = (async () => {
        try {
          // `max_concurrency` is an **admission** bound over every in-flight
          // dispatch, detached included (grammar 8.6's key table, D28): a
          // detached delivery waits for a node permit to *start*, exactly as a
          // joined instance does. It waits for it **behind the join**, though —
          // rule 7's "nothing it does can delay the enclosing flow instance" is
          // a statement about the permit queue as much as about the outcome.
          // Both gates are taken after the barrier and as a `"detached"` waiter,
          // so a joined instance of this call never queues behind this delivery
          // and a later execution of this node never queues behind it either.
          await joinedAdmitted;
          await gate.acquire("detached");
          await node.acquire("detached");
          try {
            await route.run(instance.input, delivery, site);
          } finally {
            node.release();
            gate.release();
            retire(plan.admission, admission);
          }
        } finally {
          undetach();
        }
      })().catch((error: unknown) => {
        // Nothing it does can fail the enclosing flow instance, which is what an
        // author asks for by writing the key (grammar 8.6 rule 7). Swallowing it
        // here is also what keeps an unhandled rejection from ending the process
        // long after the map node completed.
        //
        // With one exception, and it is resolved q29's: a divergence may not be
        // absorbed "by `retry:`, `on_error:`, `on_item_error:`, or any policy at
        // any nesting depth", and `detach: true` is a policy — this is the one
        // nesting depth where a swallowed divergence would report a resume as
        // complete while a delivery the record claims to hold was never made.
        // Latched rather than rethrown, because there is nothing here to throw
        // to: [`latchDivergence`] names the two readers that fail the execution
        // on it.
        const diverged = divergenceOf(error);
        if (diverged !== undefined) latchDivergence(scoped.execution.id, diverged);
      });
      // Held against the execution rather than let go of entirely. Rule 7 is
      // about what the flow instance waits for, and it still waits for nothing:
      // this promise is read by [`settleDetached`] alone, on the one way out
      // where a delivery with no record is a delivery that happens **twice**
      // (see there, and `docs/durability.md` §3.2).
      holdDelivery(scoped.execution.id, delivering);
      continue;
    }

    const gate = gateOf(route);
    joined.push(
      (async () => {
        // The route's gate first and the node's second — the same order every
        // dispatch takes them in, detached or not, so there is nothing to
        // deadlock on. A route whose own bound is spent queues on its own gate
        // instead of holding a node permit another route could have used.
        await gate.acquire();
        await node.acquire();
        // Both permits held: this instance can no longer be got in front of, so
        // it is what a detached dispatch was waiting to be behind. Reported here
        // rather than on completion — the barrier orders the *queue*, and making
        // a delivery wait for the join to finish would hold back a message the
        // map node is defined not to wait for (grammar 8.6 rule 7, D94).
        admitted();
        let attempts = 0;
        try {
          const answer = await attemptItem(map, instance, scoped);
          attempts = answer.attempts;
          landed.push({
            index,
            route,
            output: answer.value.output,
            // Which member of a route served each of this instance's model
            // calls is a fact about *this* run (PRD 5.9), and a dispatched
            // instance has no trace entry of its own — so the map node's entry
            // is where it belongs, in source-item order like everything else a
            // fan-out reports.
            ...(answer.value.models === undefined ? {} : { models: answer.value.models }),
            // And the subflows a model invoked inside this instance, for the
            // reason above and one more: the loop that made them is one item's,
            // and two items running concurrently would otherwise leave their
            // records in whatever order they settled — while `docs/trace.md` §5
            // is written about records a fan-out reports in an order the node
            // decided (PRD §9.20).
            ...(answer.value.toolDispatches === undefined
              ? {}
              : { toolDispatches: answer.value.toolDispatches }),
          });
          records.push({
            index,
            ...named,
            target: route.target,
            outcome: "completed",
            attempts,
            idempotencyKey: site.idempotencyKey,
            ...(answer.value.inner === undefined ? {} : { inner: answer.value.inner }),
          });
        } catch (error) {
          attempts = error instanceof ItemAttempts ? error.attempts : 1;
          const cause = error instanceof ItemAttempts ? error.cause : error;
          // `on_item_error` is a policy over what a dispatched instance *did*,
          // and a pause this run has no way to answer is not that — `skip`
          // absorbing it would carry the fan-out past a human the composition
          // declared it needed, which is the reading [`HumanInterrupt`] refuses
          // for the node's own `on_error:`. It leaves through the join instead,
          // and the node above reports it the same way a top-level pause is
          // reported.
          if (interruptOf(cause) !== undefined) throw error;
          // Nor is an abandoned pause: nothing is reading this instance's result
          // any more, so `skip` recording it as an item the fan-out absorbed
          // would put a dispatch record on a trace entry for an outcome that
          // never happened — and would carry the fan-out past a human for the
          // reason above (see [`abandonedOf`]).
          if (abandonedOf(cause) !== undefined) throw error;
          // Nor is a journal that does not describe this run. `skip` would carry
          // the fan-out past an effect the record claims to hold, which is the
          // one thing resolved q29 refuses outright — and it would do so while
          // recording the item as absorbed, so nothing downstream would know.
          if (divergenceOf(cause) !== undefined) throw error;
          failed.push({ index, target: route.target, attempts, error: cause });
          // A dispatched `flow.*` that failed still made a trace, exactly as one
          // that completed did, and under `on_item_error: skip` the run carries
          // on and this record is the *only* account of what happened inside the
          // boundary — every guard, every budget, every attempt (grammar 8.5,
          // PRD 5.3). The attempt reported is the last one the item made, which
          // is the attempt `attempts` counts and the error `error` describes.
          const held = traceOf(cause);
          records.push({
            index,
            ...named,
            target: route.target,
            // What the item's own policy did with it: `skip` dropped it and the
            // fan-out carried on, while `fail` — and a `retry:` that ran out of
            // attempts, which "resolves as `fail` does" (grammar 8.6 rule 10) —
            // failed it. Reporting a failure as `skipped` would tell a reader
            // the map absorbed an item it did not absorb.
            outcome: map.onItemError === "skip" ? "skipped" : "failed",
            attempts,
            idempotencyKey: site.idempotencyKey,
            ...(held === undefined ? {} : { inner: held }),
            error: describe(cause),
          });
        } finally {
          node.release();
          gate.release();
          retire(plan.admission, admission);
        }
      })(),
    );
  }

  await Promise.all(joined);
  // A copy, and the sort is on the copy: `plan.records` is cleared in place at
  // the start of the next execution of this node, and a trace entry already
  // holding it would empty out under a reader.
  const dispatched = [...records].sort((left, right) => left.index - right.index);

  // Exhausted retries resolve as `fail` does (grammar 8.6 rule 10), and the item
  // reported is the **lowest-indexed** failure rather than the first in time:
  // two runs over one array must fail about the same item.
  if (map.onItemError !== "skip" && failed.length > 0) {
    failed.sort((left, right) => left.index - right.index);
    const first = failed[0]!;
    // The records go out **on the failure**, because this is where the account
    // of a fan-out matters most: the items that did run had their effects, and
    // the node's own `on_error:` is about to absorb the one that did not
    // (grammar 8.6 rule 10's "retry each item, and if one still fails, skip the
    // fan-out"). `runNode` reads them back off the error onto the trace entry it
    // builds, so a skipped or fallen-back map still says what it dispatched.
    throw new ItemFailure(
      map.node,
      first.index,
      first.target,
      first.attempts,
      first.error,
      dispatched,
    );
  }

  const byIndex = [...landed].sort((left, right) => left.index - right.index);
  const models = byIndex.flatMap((one) => one.models ?? []);
  const toolDispatches = byIndex.flatMap((one) => one.toolDispatches ?? []);
  return {
    output: {},
    channels: orderedChannels(landed),
    dispatches: dispatched,
    ...(models.length === 0 ? {} : { models }),
    ...(toolDispatches.length === 0 ? {} : { toolDispatches }),
  };
}

/**
 * Every detached `map` delivery still in flight, by execution.
 *
 * A `Set` per execution because a fan-out dispatches many and each settles on
 * its own, and keyed by execution because that is the scope the one reader cares
 * about: [`settleDetached`] is asked about a run that has stopped, and a
 * delivery under a `flow:` node or inside a flow a model called belongs to the
 * same execution as the run that started it (see [`openSession`]).
 */
const detachedDeliveries = new Map<string, Set<Promise<void>>>();

/** Note one delivery for as long as it is in flight. See [`settleDetached`]. */
function holdDelivery(execution: string, delivery: Promise<void>): void {
  let held = detachedDeliveries.get(execution);
  if (held === undefined) {
    held = new Set();
    detachedDeliveries.set(execution, held);
  }
  held.add(delivery);
  void delivery.finally(() => {
    const still = detachedDeliveries.get(execution);
    if (still === undefined) return;
    still.delete(delivery);
    if (still.size === 0) detachedDeliveries.delete(execution);
  });
}

/**
 * Wait for the detached deliveries of an execution whose row **stays open**
 * (`docs/durability.md` §3.2).
 *
 * Grammar 8.6 rule 7 says nothing a detached delivery does may delay the
 * enclosing flow instance, and nothing here does: the join returned long ago,
 * the trace entry was written without it, and this is `runFlow` on its way out
 * of a run that has already stopped advancing.
 *
 * What it buys is the sentence §3.2 makes about a delivery's record — "a replay
 * does not deliver it twice". A delivery's row is written when the delivery
 * answers, so a process that walks out from under one leaves an effect with no
 * record, and the generation that resumes this execution issues it again. For a
 * run that **ended** that costs nothing, because nothing will resume it. For a
 * run that parked at a `human` pause — `agent-compose run`'s own exit-3 path,
 * which is not a crash and not §2's one-statement window — it is a second
 * delivery every time.
 *
 * Called after the wait board is released, so a delivery holding a pause of its
 * own is already abandoned rather than something this could wait on for ever.
 * The loop re-reads the map because a delivery may dispatch a fan-out of its
 * own, and every promise here has its rejection already swallowed by the
 * `.catch` rule 7 requires, so nothing this awaits can throw.
 */
export async function settleDetached(execution: string): Promise<void> {
  for (;;) {
    const held = detachedDeliveries.get(execution);
    if (held === undefined || held.size === 0) return;
    await Promise.all([...held]);
  }
}

/** A failed item, carrying how many attempts its policy made. */
class ItemAttempts extends Error {
  readonly attempts: number;

  constructor(attempts: number, cause: unknown) {
    super(describe(cause));
    this.name = "ItemAttempts";
    this.attempts = attempts;
    this.cause = cause;
  }
}

/**
 * One item, under `on_item_error` (grammar 8.6 rule 10).
 *
 * A retry re-executes the **whole dispatched instance** from its entry as a
 * fresh attempt, and nothing the instance path is built from changes — the item
 * keeps its index — so every attempt derives the same idempotency key
 * (grammar 9.4). The node's own deadline is the one clock: `context.signal` is
 * the map node's, so an item's attempts are spent inside the map's `timeout:`
 * rather than beside it.
 */
async function attemptItem(
  map: MapDescriptor,
  instance: PlannedInstance,
  context: RunContext,
): Promise<{ value: NodeAnswer; attempts: number }> {
  const retry = typeof map.onItemError === "object" ? map.onItemError.retry : undefined;
  const allowed = 1 + (retry?.max ?? 0);
  // What the item *did*, not what its policy allowed — the same distinction
  // `runActivity` draws for a node. The map node's deadline can end the loop
  // mid-backoff, and a record saying five attempts were made against a provider
  // the item reached once describes a run that did not happen.
  let made = 0;
  let last: unknown;
  // The instance is a unit of concurrent work in its own right, and the one the
  // map node's own registration cannot stand in for: this instance runs a graph
  // of its own and advances while a sibling instance is parked, so an execution
  // is quiescent only once every one of them has parked or finished (PRD
  // resolved q34, and see [`quiescent`]). Held across the whole ladder rather
  // than per attempt, because between two attempts the item is still work this
  // execution is doing.
  const busy = working(context.execution.id, instance.site.path.join("/"));
  try {
    for (let attempt = 1; attempt <= allowed; attempt += 1) {
      made = attempt;
      try {
        return {
          value: await instance.route.run(instance.input, context, instance.site),
          attempts: attempt,
        };
      } catch (error) {
        last = error;
        // The rule [`runActivity`]'s ladder follows, for the ladder rule 10
        // gives an item: a pause this run has no way to answer is not something
        // the instance did wrong, and re-executing it would repeat every effect
        // it issued on the way to asking a question that still cannot be
        // delivered.
        if (interruptOf(error) !== undefined) throw new ItemAttempts(made, error);
        // And the same rule for a pause this instance is no longer being waited
        // on for: re-executing it would re-open the pause under a node that has
        // stopped waiting, on top of repeating every effect the instance issued.
        if (abandonedOf(error) !== undefined) throw new ItemAttempts(made, error);
        // And a journal that does not describe this run, for [`runActivity`]'s
        // reason: a second attempt would walk the next recorded effect forward
        // and report a disagreement one step past the one that really happened.
        if (divergenceOf(error) !== undefined) throw new ItemAttempts(made, error);
        if (attempt === allowed) break;
        // And the rule [`runActivity`]'s ladder follows between its attempts,
        // for the same reason and at the same seam: this attempt is over, the
        // next one re-executes the instance at **this very site**, and a pause a
        // settled branch of the failed attempt left open would share its id with
        // the pause the next attempt opens there. Two waits at one id settle
        // each other (see [`abandonPausesUnder`]). The pause the *last* attempt
        // leaves is the node execution's to abandon, which `runActivity`'s
        // `finally` does for every instance this fan-out dispatched.
        abandonPausesUnder(context.execution.id, instance.site.path.join("/"));
        try {
          await sleep(backoffFor(retry!, attempt), context.signal);
        } catch {
          break;
        }
      }
    }
    throw new ItemAttempts(made, last);
  } finally {
    busy();
  }
}

/**
 * The instances' results, folded into one write per channel in **source-item**
 * order (grammar 7.6.4 clause 2).
 *
 * The channels themselves are ordered by name so that the update object a map
 * hands LangGraph has the same key order on every run — the last thing between
 * this and a replay that reproduces the live run exactly.
 */
function orderedChannels(
  landed: readonly { index: number; route: MapRoute; output: unknown }[],
): ChannelWrite[] {
  const held = new Map<string, { reduce: Reduce; values: unknown[] }>();
  for (const one of [...landed].sort((left, right) => left.index - right.index)) {
    const fields = (one.output ?? {}) as Record<string, unknown>;
    for (const write of one.route.writes) {
      const value = fields[write.field];
      // A field the result does not carry performs no write (Decision D110).
      if (value === undefined) continue;
      let channel = held.get(write.channel);
      if (channel === undefined) {
        channel = { reduce: write.reduce, values: [] };
        held.set(write.channel, channel);
      }
      channel.values.push(value);
    }
  }
  return [...held.entries()]
    .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
    .map(([channel, { reduce, values }]) => ({ channel, reduce, values }));
}

// ---------------------------------------------------------------------------
// Human pauses (grammar 8.7, PRD 5.5, 5.11)
// ---------------------------------------------------------------------------

/**
 * A `human` node's wait, as `./graph.ts` describes it.
 *
 * The two schemas are both here because a pause has two audiences. `shown` — the
 * node's `input:`, built by the node's input phase like any other — is what the
 * *human* is handed, and [`schema`] is what an **answer** is held to, whichever
 * surface it arrived on (PRD 5.11, §9.21): the published JSON Schema of the
 * node's `output:`, carried so the status route can hand a UI the contract its
 * answer has to fit without the UI reading the composition. [`parse`] is the
 * emitted Zod for the same surface, which is what actually decides an answer —
 * the pair the schema conformance corpus proves equal, asked at the two ends it
 * is needed at.
 */
export interface HumanDescriptor {
  readonly flow: string;
  readonly node: string;
  /**
   * The wall-clock budget of grammar 8.7, in milliseconds — present exactly when
   * the node declares `timeout:`.
   *
   * It is **not** [`NodePolicy.timeoutMs`] and never resolves from one: a
   * `human` node takes no `timeout` at any of grammar 9.3's levels (D102), so a
   * composition-wide budget can never cut a wait short. This is the node's own
   * `human: { timeout: … }` and nothing else.
   */
  readonly timeoutMs?: number;
  /**
   * Where control goes when the budget runs out: a flow-local node id, or
   * `"__end__"` (grammar 8.7, 9.2).
   *
   * Jointly optional and jointly required with [`timeoutMs`], which the compiler
   * refuses a composition for breaking — so a pause either has both or neither.
   */
  readonly onTimeout?: string;
  /** The published JSON Schema of the node's `output:` (grammar 3.8). */
  readonly schema: JsonSchema;
  /**
   * Hold an answer to that surface, answering the parsed result.
   *
   * Both delivery surfaces call it and both end their refusal in its message,
   * so what it names is the *node* rather than the route or the terminal the
   * answer came from (grammar 8.7, PRD §9.21).
   */
  parse(payload: unknown): unknown;
}

/**
 * One pause this process is holding, as a surface that can answer it sees it.
 *
 * Everything here is what a caller needs to *ask the question and take the
 * answer*: which pause this is, what the human is shown, what their answer has
 * to fit, and how long it has. What the human eventually answers is not here and
 * is not kept — see [`HumanPause`] and `docs/trace.md` §11.
 */
export interface HumanWait {
  /**
   * What addresses this pause inside its execution: the instance path of
   * grammar 9.4, flattened.
   *
   * `"approve/0"` at the top level of a flow, `"review/0/2/approve/0"` for the
   * pause inside the third instance a `map` dispatched. One execution can hold
   * more than one pause at once — a `human` node inside a map-dispatched flow is
   * the reachable case — and this is what tells them apart, deterministically
   * and without a counter: two runs of one composition address the same pause by
   * the same id.
   */
  readonly id: string;
  readonly execution: string;
  readonly flow: string;
  readonly node: string;
  /** The node's `input:`, evaluated — what the human is shown (grammar 8.7). */
  readonly shown: Readonly<Record<string, unknown>>;
  /** What an answer is validated against (PRD 5.11). */
  readonly schema: JsonSchema;
  /** When the pause began, as an ISO 8601 instant. */
  readonly pausedAt: string;
  /** When its budget runs out — present exactly when `timeout:` is declared. */
  readonly expiresAt?: string;
}

/**
 * What the trace records about a pause (`docs/trace.md` §3, PRD 5.3).
 *
 * The pause is a routing-relevant event and so is trace data: when the wait
 * began, how long it had, and how it ended. **What the human answered is not
 * here**, and that is a rule rather than an omission — the same posture
 * `docs/trace.md` §11 takes to a model's completion, which no field of the
 * format carries either. The answer's *arrival* is `settledAt`; its content
 * reaches the run through the node's `writes:` like any other result.
 */
export interface HumanPause {
  /** When the wait began, as an ISO 8601 instant. */
  readonly pausedAt: string;
  /** When it would expire — present exactly when `timeout:` is declared. */
  readonly expiresAt?: string;
  /**
   * When it stopped waiting — present exactly when it did.
   *
   * Absent on the one entry that records a pause nothing settled: a run that
   * ended holding it, which is what `agent-compose run` does with every pause it
   * reaches (see [`HumanInterrupt`]).
   */
  readonly settledAt?: string;
  /** How it stopped waiting — present exactly when `settledAt` is. */
  readonly settled?: "resumed" | "expired";
}

/**
 * A wait whose budget ran out before anyone answered (grammar 8.7).
 *
 * Not a `timeout:` in grammar 9.2's sense and not raised as one: it carries the
 * route the composition declared for exactly this outcome, and [`runNode`]
 * transfers control there **instead of** evaluating the node's own edges — which
 * is §9.2's fallback shape, reached from `on_timeout:` rather than from
 * `on_error:`.
 */
export class HumanExpiry extends Error {
  /**
   * Which pause it was (grammar 9.4's instance path, flattened).
   *
   * Carried for the reason [`HumanInterrupt`] carries it: [`pauseOf`] reads it
   * to decide whether the pause on this error belongs to the node execution
   * asking, and an error travels further than the node that raised it.
   */
  readonly wait: string;
  /** The node id control transfers to, or `"__end__"` (grammar 8.7). */
  readonly route: string;
  /** What the trace records about the pause that expired. */
  readonly pause: HumanPause;

  constructor(
    flow: string,
    node: string,
    wait: string,
    budgetMs: number,
    route: string,
    pause: HumanPause,
  ) {
    super(
      `${flow} node \`${node}\`: nobody answered inside its ${budgetMs}ms wait, so \`on_timeout\` routes to \`${route}\` (grammar 8.7)`,
    );
    this.name = "HumanExpiry";
    this.wait = wait;
    this.route = route;
    this.pause = pause;
  }
}

/**
 * A pause this run has no way to deliver an answer to.
 *
 * A run started **without** an answer surface — an `agent-compose run` whose
 * standard input is not a terminal, and any in-process caller of [`runFlow`]
 * that did not ask for one — reaches a `human` node and stops there. So does one
 * whose surface **went away** while it was running: `agent-compose run` prompts
 * at the terminal it was given, and standard input ending is that surface
 * closing (see [`closeHumanWaits`]). The alternative readings are both worse:
 * waiting forever is a command that never returns, and carrying on with no
 * answer is a graph that routed on a decision nobody made.
 *
 * The message names the delivery surfaces rather than the run's shape, because
 * what a reader needs is where an answer *can* go: the app's resume route
 * (PRD 5.11), or a `run` at a terminal (grammar 8.7).
 *
 * **`on_error:` does not govern it.** Grammar 9's policy is over an *activity* —
 * what the model, the process or the request did — and this is the run's own
 * shape rather than something the pause did wrong; `skip` absorbing it would
 * route past a human whose answer the composition declared it needed. So
 * [`runNode`] answers this ahead of the policy, exactly as it does an input that
 * could not be built.
 */
export class HumanInterrupt extends Error {
  readonly flow: string;
  readonly node: string;
  /** Which pause it is (grammar 9.4's instance path, flattened). */
  readonly wait: string;
  /** What the trace records about it: a pause with no settlement. */
  readonly pause: HumanPause;

  constructor(flow: string, node: string, wait: string, pause: HumanPause) {
    super(
      `${flow} node \`${node}\` is waiting for a human and this run has no way to answer: an answer reaches a pause through \`agent-compose serve\`'s \`POST /executions/:id/resume\`, or at the terminal of an \`agent-compose run\` whose standard input is one (grammar 8.7, PRD 5.11)`,
    );
    this.name = "HumanInterrupt";
    this.flow = flow;
    this.node = node;
    this.wait = wait;
    this.pause = pause;
  }
}

/**
 * A pause nobody is waiting for any more (see [`abandonPausesUnder`]).
 *
 * Not a failure the composition declared and not one it can route on: the task
 * it unwinds is inside an instance whose result was already discarded — one a
 * node stopped waiting for, or one the run ended without — so this error reaches
 * no trace entry and no `on_error:`. Every ladder and policy on its way out lets
 * it through rather than acting on it ([`abandonedOf`]). It exists so the parked
 * task *ends*, releasing the `map` permits and store handles the instance still
 * holds, rather than staying parked on a promise nothing will ever settle.
 */
export class HumanAbandoned extends Error {
  readonly wait: string;

  constructor(flow: string, node: string, wait: string) {
    super(
      `${flow} node \`${node}\`: the pause at \`${wait}\` was abandoned — the execution stopped waiting for the instance holding it`,
    );
    this.name = "HumanAbandoned";
    this.wait = wait;
  }
}

/**
 * A second pause opened under an id the board is still holding a waiting one at
 * (see [`hold`]).
 *
 * Not something a composition can ask for and not an outcome a run can route on:
 * it is the runtime's own invariant, raised at the moment it breaks so that the
 * failure is a named error rather than an execution that waits for ever on a
 * pause no surface can reach.
 */
export class WaitBoardInvariant extends Error {
  /** The id both pauses answer to (grammar 9.4's instance path, flattened). */
  readonly wait: string;

  constructor(wait: string) {
    super(
      `the pause at \`${wait}\` is still waiting, so a second pause cannot be opened under that id: an instance re-executed at a site abandons what the last one left parked there first`,
    );
    this.name = "WaitBoardInvariant";
    this.wait = wait;
  }
}

/**
 * One pause a **placed** node opened, as the wire carries it home
 * (`docs/distributed.md` §3.4, PRD resolved q46).
 *
 * A worker holds no wait board — the board is the hub's, which is what keeps
 * wait-board unity (PRD resolved q43) — so a `human` node reached on a worker
 * does not park there. It **settles its dispatch, paused**, and this is what
 * that settlement carries: the pause's deterministic identity, what the person
 * is shown, when it began, and the effect record its answer will be journaled
 * under.
 *
 * Everything here is derived by the process that *asked*, and nothing is
 * re-derived on the hub. That is the same discipline the env partition follows
 * (`docs/distributed.md` §9.1): two derivations of one answer agree on the day
 * they are written, and a wait identity or an effect key derived twice is a
 * `ReplayDivergence` on the redispatch the day they part.
 */
export interface RemotePause {
  /** Grammar 9.4's instance path, flattened — the identity [`HumanWait.id`] is. */
  readonly wait: string;
  readonly flow: string;
  readonly node: string;
  /** The node's `input:`, evaluated — what the human is shown (grammar 8.7). */
  readonly shown: Readonly<Record<string, unknown>>;
  /**
   * When the node reached the pause **on the worker's clock**.
   *
   * The first of the two instants that describe what the *worker* did, and like
   * the second it is journaled on the settled dispatch row and never
   * republished: the wait the hub plants is dated where it is planted, off the
   * same reading its deadline is armed from ([`holdRemotePause`]), because a
   * pair assembled out of two machines' clocks is an interval of nothing.
   */
  readonly pausedAt: string;
  /**
   * When the budget runs out **on the worker's clock** — present exactly when
   * `timeout:` is declared, and what that process's own trace entry records
   * (`docs/trace.md` §3.4).
   *
   * A fact about what the worker did, and nothing the hub arms or republishes:
   * the deadline a hub shows is derived where its timer is armed
   * ([`holdRemotePause`]), so that a reader is shown the instant the wait will
   * actually end at. It travels because the pause happened on another machine
   * and the settled row is the only record of it.
   */
  readonly expiresAt?: string;
  /**
   * The effect record the answer is journaled under, as the worker's own
   * recorder claimed it (`docs/durability.md` §4).
   *
   * The hub appends the record; the redispatch hands it back in
   * `effect_history`; and the replay of `docs/distributed.md` §7.2 consumes it
   * at exactly the claim that opened this pause, which is what makes the node go
   * live *past* the question rather than ask it again.
   */
  readonly effect: {
    readonly key: string;
    readonly site: string;
    readonly ordinal: number;
    /** The canonical identity [`EffectSlot.request`] computed. */
    readonly request: string;
  };
}

/**
 * A pause this process cannot hold because it is a **worker**: the dispatch
 * settles paused and the hub plants the wait (`docs/distributed.md` §3.4).
 *
 * A subclass of [`HumanInterrupt`] rather than a class beside it, and that is
 * load-bearing rather than tidy: every ladder and policy between a `human` node
 * and the process boundary already lets an interrupt through untouched —
 * [`runActivity`]'s `retry:`, [`attemptItem`]'s `on_item_error:`, [`runNode`]'s
 * `on_error:`, and the tool loop that re-throws one out of a flow-as-tool call.
 * A pause absorbed by an `on_error: skip` on its way to the wire would be a
 * placed node routing past a question the composition declared it needed, which
 * is the one reading [`HumanInterrupt`] exists to refuse — so this is that error,
 * carrying a payload, rather than a second thing those ladders would each have
 * to learn about.
 */
export class RemoteHumanPause extends HumanInterrupt {
  /** What settles the dispatch, and what the hub plants on its board. */
  readonly remote: RemotePause;

  constructor(remote: RemotePause, opened: HumanPause) {
    super(remote.flow, remote.node, remote.wait, opened);
    this.name = "RemoteHumanPause";
    this.message = `${remote.flow} node \`${remote.node}\` is waiting for a human, and it was reached on a worker: the dispatch settles *paused* and the wait is planted on the hub's board under \`${remote.wait}\`, where the ordinary resume surface answers it (docs/distributed.md §3.4, PRD resolved q46)`;
    this.remote = remote;
  }
}

/** Why a resume was refused, or that it was taken. */
export type ResumeOutcome =
  | { readonly ok: true; readonly wait: HumanWait }
  | {
      readonly ok: false;
      readonly reason: "not-waiting" | "ambiguous" | "no-such-wait" | "settled" | "mismatch";
      readonly detail: string;
      /**
       * Every pause still waiting, by id — on the two refusals a caller can
       * answer by re-addressing the request, and only where there is something
       * to list.
       *
       * `"ambiguous"` is one: a resume that named no pause against an execution
       * holding several. `"no-such-wait"` is the other, and it is the one where
       * the list is worth most — a `?wait=` that matched nothing is usually a
       * stale id from an earlier poll, and the ids that *are* waiting are the
       * answer to it. It is absent where the list would be empty, which on
       * `"no-such-wait"` means the execution is holding no pause at all.
       */
      readonly pending?: readonly string[];
    };

/**
 * How a pause stopped waiting.
 *
 * Two of the four are outcomes the composition declared, and they are what the
 * trace records ([`HumanPause.settled`]). The other two are the run's own shape
 * and neither reaches a `settled` key:
 *
 *   * `"abandoned"` is the run saying nobody is listening for this answer any
 *     more — the node that dispatched the instance holding it has stopped
 *     waiting for that instance, or the run itself has ended. It never reaches a
 *     trace entry at all, because the entry it would have ridden out on belongs
 *     to a task whose result was discarded (see [`abandonPausesUnder`]);
 *   * `"interrupted"` is the run saying nothing can answer this pause — the
 *     answer surface it started with has gone away (see [`closeHumanWaits`]).
 *     Its entry *is* reported: it is the same [`HumanInterrupt`] a run started
 *     with no surface raises, so the pause reaches the trace with `pausedAt` and
 *     no settlement, exactly as [`HumanPause.settledAt`] describes.
 */
type Settlement = "resumed" | "expired" | "abandoned" | "interrupted";

/** One pause, with the machinery that settles it exactly once. */
interface Held {
  readonly wait: HumanWait;
  readonly settle: (outcome: Settlement, value: unknown) => boolean;
  readonly parse: (payload: unknown) => unknown;
  /** Set the moment this pause stops waiting, whichever side stopped it. */
  settled?: Settlement;
}

/** Every pause one execution is holding, in the order they began. */
interface WaitBoard {
  /**
   * Whether a resume surface is attached to this run (PRD 5.11).
   *
   * Mutable, because a surface can go away while the run is still going: the
   * terminal one `agent-compose run` attaches loses its answers when standard
   * input ends, and a pause nothing can answer is exactly what [`HumanInterrupt`]
   * is (see [`closeHumanWaits`]). It is only ever turned **off** — nothing
   * attaches a surface to a run that started without one, because a `human` node
   * reached before it attached would already have raised.
   */
  resumable: boolean;
  readonly held: Map<string, Held>;
}

/**
 * The pauses this **process** is holding, by execution id.
 *
 * A module-level table rather than something threaded through the graph, for the
 * reason the store registry is one: a pause is reached from inside a node's
 * activity, arbitrarily deep in a nesting of instances, and the surface that
 * answers it is an HTTP route in another module that has only an execution id to
 * go on. The execution id is what both ends already hold.
 *
 * **In this process, and only for as long as it lives.** That is the same
 * boundary `src/serve.ts` states for the executions it tracks: durable execution
 * and checkpointers are a later milestone, so a `serve` restarted while a human
 * was thinking has lost the wait. The emitted `README.md` says so where a reader
 * meets the resume route.
 */
const humanBoards = new Map<string, WaitBoard>();

/**
 * Who is told when one execution's set of open pauses moves.
 *
 * Kept **beside** the boards rather than on one, because a watcher may exist
 * before the board does. `agent-compose run`'s terminal surface subscribes with
 * the execution id it minted and then starts the run, and a subscription that
 * only worked once a board existed would be a prompt loop whose correctness
 * depended on how much of [`runFlow`] happens before its first `await` — the one
 * failure mode a test cannot tell from a slow machine. The other subscriber,
 * [`runActivity`], is inside the run and could not care; one registry serves
 * both.
 *
 * It is an *event* rather than a poll because of what the second subscriber
 * does: a node's deadline is held still for as long as a pause under that node
 * is pending (grammar 9.2, Decision D102), and the two ends are far apart — the
 * deadline belongs to a `map` or `flow:` node and the pause happens some number
 * of instances below it. A budget that resumed on the next poll tick would make
 * a node's remaining time depend on the tick rather than on the clock.
 *
 * Entries are the subscriber's to remove, and both remove theirs: `runActivity`
 * in the `finally` that ends a node execution, the terminal surface in the
 * `finally` that ends its prompt loop.
 */
const humanWatchers = new Map<string, Set<() => void>>();

/**
 * Every `human` node this composition declares, by `<flow address>.<node id>`.
 *
 * Filled at module scope by `./graph.ts`, which is where the descriptors are
 * emitted, and read by exactly one caller: the **hub**, planting a pause a
 * worker opened ([`holdRemotePause`]). A local pause never consults it — it has
 * its descriptor in hand — so a project with no placements pays a map nothing
 * reads.
 *
 * What it buys is the parity PRD resolved q46 requires: "a placed `human:` node
 * must mean what the same node unplaced means". The schema a status route
 * publishes and the parser a resume payload is held to are the node's own, not a
 * second reading of a JSON Schema that travelled — which is possible at all only
 * because the whole artifact is everywhere (`docs/distributed.md` §4.3), so the
 * hub holds the very descriptor the worker paused on.
 */
const humanNodes = new Map<string, HumanDescriptor>();

/**
 * Register this composition's `human` nodes, by `<flow address>.<node id>`.
 *
 * Called once at module scope by `./graph.ts`, and by nothing else.
 */
export function registerHumanNodes(nodes: Readonly<Record<string, HumanDescriptor>>): void {
  for (const [address, descriptor] of Object.entries(nodes)) humanNodes.set(address, descriptor);
}

/**
 * Whether `<flow address>.<node id>` is a `human:` node of this composition.
 *
 * The registry's other reader, and the reason it is a question rather than a
 * lookup: `./mesh.ts` reads a paused result **before** it settles the dispatch,
 * and a body naming a node this artifact does not have is one it has to refuse
 * *there* — as the one "this hub cannot read your pause" failure §3.4 gives the
 * route — rather than have [`holdRemotePause`] throw a bare error over a
 * dispatch already answered `204`.
 */
export function registersHumanNode(address: string): boolean {
  return humanNodes.has(address);
}

/**
 * Whether a pause reached in this process is **settled home** rather than held
 * (`docs/distributed.md` §3.4).
 *
 * Turned on by `./worker-node.ts` and by nothing else: a worker runs one
 * dispatch of somebody else's execution, and the board a pause belongs on is the
 * hub's. Every other process — `serve`, an interactive `run`, an ejected
 * caller — leaves it off and holds its pauses itself.
 *
 * It is a process-wide switch rather than a field of the run because the pause
 * happens arbitrarily deep inside a placed node's tool loop, exactly where the
 * board is reached from, and because the process that has it on runs one
 * dispatch and exits.
 */
let pausesSettleHome = false;

/** See [`pausesSettleHome`]. Called by `./worker-node.ts` before anything runs. */
export function dispatchPausesHome(): void {
  pausesSettleHome = true;
}

/**
 * Open the pause registry for one execution, saying whether it can be resumed.
 *
 * Called by [`runFlow`] at the top of every run, before the graph is streamed,
 * so a status route polling the moment after `start` answered already has
 * something to read. `resumable` is the run's, not the composition's: the same
 * compiled flow is resumable under `serve`, is resumable under an
 * `agent-compose run` that can reach a terminal, and is not under one that
 * cannot.
 */
export function openHumanWaits(execution: string, resumable: boolean): void {
  humanBoards.set(execution, { resumable, held: new Map() });
}

/**
 * Withdraw this run's answer surface: nothing can answer its pauses any more
 * (grammar 8.7, PRD 5.11).
 *
 * The counterpart of [`openHumanWaits`]'s `resumable` argument, for a surface
 * that is attached when the run starts and can still go away while it is
 * running. One does: the terminal `agent-compose run` prompts at, whose answers
 * stop arriving when standard input ends. A pause nothing can answer is not a
 * new outcome — it is exactly the shape a run started with no surface at all
 * has — so every pause still waiting is settled as a [`HumanInterrupt`] and the
 * board is marked unresumable, which makes every *later* pause raise one where
 * it opens rather than park on a promise nothing will settle.
 *
 * What that buys is one reported outcome rather than two: the run ends with the
 * `status: "interrupted"` document, the exit code and the trace entry that a
 * non-interactive run reaching the same node produces, because it is the same
 * error class on the same chain.
 */
export function closeHumanWaits(execution: string): void {
  const board = humanBoards.get(execution);
  if (board === undefined) return;
  board.resumable = false;
  for (const one of [...board.held.values()]) {
    if (one.settled === undefined) one.settle("interrupted", undefined);
  }
}

/**
 * Drop everything one execution's pauses held, however the run ended.
 *
 * The counterpart of [`openHumanWaits`], called from the same `finally` that
 * releases the run's `scope: execution` stores: a pause that outlived its run
 * would be a wait a resume could still be delivered to, with no graph left to
 * receive it.
 *
 * **Every pause still waiting is abandoned first**, rather than the table being
 * dropped out from under it. A pause holds an expiry timer and, through it, its
 * whole closure — a `human: { timeout: 24h }` whose run ended some other way
 * would otherwise keep a `setTimeout` and everything it closes over alive for a
 * day, one per wait, in a `serve` process that answers many runs. What can still
 * be pending here is a pause on a branch the run stopped scheduling: a fork
 * whose other branch failed ends the run while this one is still parked, and the
 * node holding the pause never reaches the `finally` that would have abandoned
 * it ([`abandonPausesUnder`]).
 */
export function releaseHumanWaits(execution: string): void {
  const board = humanBoards.get(execution);
  if (board !== undefined) {
    for (const one of [...board.held.values()]) {
      if (one.settled === undefined) one.settle("abandoned", undefined);
    }
  }
  humanBoards.delete(execution);
}

/** Whether `id` names a pause at, or inside, the node instance at `site`. */
function under(id: string, site: string): boolean {
  return id === site || id.startsWith(`${site}/`);
}

/**
 * How many pauses `execution` is holding at or inside the node instance at
 * `site` (grammar 9.4's instance path, flattened).
 *
 * A pause is *inside* a node exactly when the node's instance path is a prefix
 * of the pause's — `fan/0` holds `fan/0/1/sign/0` — which is a fact the ids
 * already carry, so no bookkeeping links a wait to the node that dispatched the
 * instance it happened in.
 *
 * What reads it is [`runActivity`]: grammar 9.2's budget bounds one node
 * execution, and Decision D102 says a composition-wide budget can never cut a
 * human wait short — so the time a node spends with a pause open below it is
 * time its own deadline does not count.
 */
export function pausesUnder(execution: string, site: string): number {
  const board = humanBoards.get(execution);
  if (board === undefined) return 0;
  let open = 0;
  for (const one of board.held.values()) {
    if (one.settled === undefined && under(one.wait.id, site)) open += 1;
  }
  return open;
}

/**
 * Be told whenever one of `execution`'s pauses opens or stops waiting; answers
 * the unsubscribe.
 *
 * Subscribing **before the run exists** is allowed and is what one caller does
 * (see [`humanWatchers`]): the listener is registered against the execution id
 * rather than against a board, so nothing turns on whether the board has been
 * opened yet. An id no run ever uses costs one empty `Set` until its
 * unsubscribe runs.
 */
export function watchHumanPauses(execution: string, listener: () => void): () => void {
  let watchers = humanWatchers.get(execution);
  if (watchers === undefined) {
    watchers = new Set();
    humanWatchers.set(execution, watchers);
  }
  const held = watchers;
  held.add(listener);
  return () => {
    held.delete(listener);
    // The empty set goes with the last subscriber, so a `serve` process that
    // has answered many runs is not left holding one per execution id.
    if (held.size === 0 && humanWatchers.get(execution) === held) {
      humanWatchers.delete(execution);
    }
  };
}

// ---------------------------------------------------------------------------
// Quiescence (PRD resolved q34)
// ---------------------------------------------------------------------------

/**
 * The concurrent work each execution has in flight, by the site running it.
 *
 * One entry per unit of work that can reach a `human` node **on its own** —
 * which is a node execution ([`runActivity`]) and a dispatched `map` instance
 * ([`attemptItem`]), and nothing else. Those two are the only places this
 * runtime forks: an instance dispatched by a `map` runs its own graph inside
 * the map node's task (`src/graph.ts`'s
 * `a-dispatch-runs-inside-the-map-nodes-task`), so the map node's site alone
 * could not say whether item 2 was still working while item 1 was parked. A
 * subflow a `flow:` node or an agent's `tools:` instantiates is one per node
 * execution and needs no entry of its own — the node's does for it.
 *
 * A **detached** dispatch is absent (grammar 8.6 rule 7), and keeping it absent
 * takes bookkeeping rather than silence. Nothing waits for a delivery and
 * Decision D118 refuses a `human` node under one, so it can open no pause — but
 * its *sink* is a graph like any other: a `flow.*` reached that way runs its
 * nodes under this execution's id ([`runSubflow`] is handed `site.execution`),
 * and every one of them would register here. Counting them would hold a parking
 * webhook back for the whole of work the flow instance itself does not wait for
 * — a `map` with `detach: true` to a flow whose `http:` node carries a
 * thirty-minute budget would keep a subscriber from being told about a pause it
 * could answer at once, which is rule 7's "nothing it does can delay the
 * enclosing flow instance" broken at the one surface that reads this map.
 * [`detaching`] marks the delivery's whole subtree and [`working`] reads the
 * mark.
 */
const inFlight = new Map<string, Map<string, number>>();

/** Who is told when one execution's in-flight work changes. See [`quiescent`]. */
const quietWatchers = new Map<string, Set<() => void>>();

/**
 * Every **detached** dispatch in flight, by the instance path its sink runs
 * under.
 *
 * A delivery's work is named the way a pause is (grammar 9.4): the dispatch's
 * instance path is a prefix of every site inside its sink — the nodes of a
 * `flow.*` it instantiates, and the subflows an `agent.*` reached that way calls
 * from its `tools:`. So one entry answers for a whole subtree, and nothing has
 * to be threaded across a boundary that rebuilds its context from `$run`.
 *
 * Counted for [`working`]'s reason and one of its own: a node `retry:` that
 * re-executes a `map` issues the next attempt's deliveries at the very paths the
 * failed attempt's are still being delivered at, and nothing cancels those.
 */
const detachedSites = new Map<string, Map<string, number>>();

/**
 * Mark everything under one instance path as a detached dispatch's work for as
 * long as the delivery runs, and answer its release.
 *
 * Called by [`runMap`] before the delivery is issued, so a sink that reaches its
 * first node in the same tick is already inside the mark.
 */
function detaching(execution: string, site: string): () => void {
  let sites = detachedSites.get(execution);
  if (sites === undefined) {
    sites = new Map();
    detachedSites.set(execution, sites);
  }
  const held = sites;
  held.set(site, (held.get(site) ?? 0) + 1);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const count = (held.get(site) ?? 0) - 1;
    if (count > 0) held.set(site, count);
    else held.delete(site);
    if (held.size === 0 && detachedSites.get(execution) === held) detachedSites.delete(execution);
  };
}

/** Whether `site` is at, or inside, a detached dispatch. See [`detaching`]. */
function detachedWork(execution: string, site: string): boolean {
  const sites = detachedSites.get(execution);
  if (sites === undefined) return false;
  for (const root of sites.keys()) {
    if (under(site, root)) return true;
  }
  return false;
}

/**
 * Note one unit of concurrent work for as long as it runs, and answer its
 * release.
 *
 * Counted rather than held as a set, because one site runs more than once in
 * sequence — both retry ladders re-execute an instance at the site its
 * predecessor ran at ([`runActivity`], [`attemptItem`]) — and a release that
 * deleted the entry would drop a live registration if the two ever overlapped.
 *
 * Work inside a **detached** dispatch registers nothing at all: it is not work
 * the enclosing instance is waiting for, and a quiescence that waited for it
 * would be waiting for the one thing grammar 8.6 rule 7 says nothing waits for
 * (see [`inFlight`]). The release such a caller is handed does nothing, because
 * there is nothing to release and no reader whose answer its finishing changes.
 */
function working(execution: string, site: string): () => void {
  if (detachedWork(execution, site)) return () => {};
  let sites = inFlight.get(execution);
  if (sites === undefined) {
    sites = new Map();
    inFlight.set(execution, sites);
  }
  const held = sites;
  held.set(site, (held.get(site) ?? 0) + 1);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const count = (held.get(site) ?? 0) - 1;
    if (count > 0) held.set(site, count);
    else held.delete(site);
    if (held.size === 0 && inFlight.get(execution) === held) inFlight.delete(execution);
    const watchers = quietWatchers.get(execution);
    if (watchers === undefined) return;
    for (const watcher of [...watchers]) watcher();
  };
}

/**
 * Whether `execution` has stopped advancing on its own — every unit of work it
 * is running is waiting on a human (PRD resolved q34).
 *
 * This is what "one webhook per **parking**" is decided by, and the reason it
 * cannot be decided by a timer: a `map` over a flow with `human` nodes opens N
 * pauses in one quiescence, and the item that opens the first may be a hundred
 * milliseconds ahead of the item that opens the third. A debounce would deliver
 * one webhook per item; this waits for the last of them.
 *
 * What makes the reading safe *between* two nodes of one branch is LangGraph's
 * own superstep barrier: a step's tasks all run to completion before the next
 * step is scheduled, so while any task is parked no sibling task can start a
 * node — and a branch with nothing in flight is a branch that cannot open a
 * pause until somebody answers one. What is **not** covered by that barrier is
 * a dispatched instance, which runs a graph of its own inside the map node's
 * task and advances while a sibling instance is parked; that is exactly why
 * [`inFlight`] holds an entry per instance as well as per node execution.
 *
 * What the reading is **about** is the work the flow instance waits for, so a
 * detached dispatch and everything under it is outside it: an execution whose
 * only unparked work is a delivery has stopped advancing on its own, whatever
 * that delivery is still doing (grammar 8.6 rule 7, and see [`detaching`]).
 *
 * An execution with nothing in flight is quiescent, which is the answer a run
 * that has ended needs: nothing more will open.
 */
export function quiescent(execution: string): boolean {
  const sites = inFlight.get(execution);
  if (sites === undefined) return true;
  for (const site of sites.keys()) {
    if (parkedUnder(execution, site) === 0) return false;
  }
  return true;
}

/**
 * How many things `execution` is **parked** on at or inside `site`: the human
 * pauses [`pausesUnder`] counts, plus whatever the registered counters add.
 *
 * The one registrant is `./mesh.ts`, and what it adds is the placement wait of
 * `docs/distributed.md` §6.1 — a placed node whose dispatch no worker has taken.
 * A node awaiting one is a unit of work in flight that cannot advance on its
 * own, which is exactly what [`quiescent`] is asking about, so an execution
 * whose only unfinished work is waiting for a Mac to wake up has parked and the
 * `parked` webhook is owed (§6.6, PRD resolved q34).
 *
 * It is a registry rather than a direct call for one reason: `./runtime.ts` is
 * the module `./mesh.ts` imports, so a call the other way would close a cycle.
 * Every emitted `./graph.ts` imports the mesh — a composition that places
 * nothing still releases through it when a flow ends — and what such a project
 * gets from this is a counter over an empty board, which answers `0` and leaves
 * quiescence exactly what it was before placements existed.
 *
 * [`pausesUnder`] stays untouched, because its **other** reader is
 * [`runActivity`]'s deadline, and a placement wait is time a node's `timeout:`
 * does count: §6.5 makes the chain run "from dispatch", so queueing behind a
 * busy pool is inside the budget where waiting for a human is not (D102).
 */
function parkedUnder(execution: string, site: string): number {
  let parked = pausesUnder(execution, site);
  for (const counter of parkedCounters) parked += counter(execution, site);
  return parked;
}

/** What a registered parked-work counter answers. See [`parkedUnder`]. */
export type ParkedWork = (execution: string, site: string) => number;

/** The counters [`parkedUnder`] adds to the human board's own. */
const parkedCounters: ParkedWork[] = [];

/**
 * Register one more kind of parked work, for [`quiescent`] to count.
 *
 * Called at module scope by `./mesh.ts`, whose counter is the only registrant
 * an emitted project has: a target with no `placements:` holds no placement
 * waits, so the counter answers `0` and quiescence is what it was before
 * placements existed.
 */
export function registerParkedWork(counter: ParkedWork): void {
  parkedCounters.push(counter);
}

/**
 * Be told whenever one of `execution`'s units of work finishes; answers the
 * unsubscribe.
 *
 * The companion of [`watchHumanPauses`] and the half it cannot supply: the last
 * unparked branch of a quiescence **ends** rather than opening a pause, so the
 * moment an execution becomes quiescent is a moment no pause event announces.
 * Both are subscribed to by the one reader that decides a parking webhook
 * (`src/serve.ts`).
 */
export function watchQuiescence(execution: string, listener: () => void): () => void {
  let watchers = quietWatchers.get(execution);
  if (watchers === undefined) {
    watchers = new Set();
    quietWatchers.set(execution, watchers);
  }
  const held = watchers;
  held.add(listener);
  return () => {
    held.delete(listener);
    // The empty set goes with the last subscriber, for [`watchHumanPauses`]'s
    // reason: a `serve` that has answered many runs holds no listener per
    // finished one.
    if (held.size === 0 && quietWatchers.get(execution) === held) {
      quietWatchers.delete(execution);
    }
  };
}

/**
 * Stop holding every pause at or inside the node instance at `site`.
 *
 * A pause below a node that has stopped waiting for the instance it happened in
 * is **orphaned**: nothing will read its answer, because the task that would
 * have read it was abandoned — and left on the board it would be published by
 * the status route as a question a human could still answer and accepted by the
 * resume route as an answer that goes nowhere.
 *
 * Three things reach here, and they are the three moments a task holding a pause
 * stops being one anybody is waiting for:
 *
 *   * [`runActivity`]'s `finally`, which is every way one node execution can
 *     end. The shape that leaves a pause behind is a `map` or `flow:` node whose
 *     own deadline ran out while an instance below it was parked, in the tick
 *     before the pause could hold that deadline still;
 *   * [`runActivity`]'s **retry ladder**, between attempts. A `flow:` node's
 *     attempt is a whole instance, and the failure that ends it is yielded as
 *     soon as it settles — a sibling branch of that instance can still be
 *     parked. The next attempt re-runs the instance at the *same* site, so a
 *     pause left over would share its id with the one the new attempt opens
 *     there — which [`hold`] refuses rather than resolving;
 *   * [`attemptItem`]'s ladder, which is the same seam for `on_item_error:
 *     { retry: … }`: an item's attempts all run at one dispatch site.
 *
 * A fourth shape is refused by the compiler instead — a
 * **detached** dispatch's instance is never observed by the join at all
 * (grammar 8.6 rule 7, Decision D94), so a `human` node under one has nowhere
 * for an answer to be delivered even in principle, and a dispatch that reaches
 * one is a validation error (Decision D118).
 *
 * The parked task is **rejected** rather than left parked: it is inside an
 * instance nobody is driving, and unwinding it lets that instance fail and give
 * back the `map` admission permit it is holding, which a later execution of the
 * same node would otherwise queue behind for ever. What the rejection is *for*
 * is the unwinding — by construction nothing is left to report it to, which is
 * why it carries a class of its own rather than anything a trace entry or an
 * `on_error:` could act on.
 */
export function abandonPausesUnder(execution: string, site: string): void {
  const board = humanBoards.get(execution);
  if (board === undefined) return;
  for (const one of [...board.held.values()]) {
    if (one.settled === undefined && under(one.wait.id, site)) one.settle("abandoned", undefined);
  }
}

/** Tell everyone watching that this execution's set of open pauses has moved. */
function announce(execution: string): void {
  const watchers = humanWatchers.get(execution);
  if (watchers === undefined) return;
  for (const watcher of [...watchers]) watcher();
}

/**
 * Put one pause on the board under its id, **refusing to displace a predecessor
 * that is still waiting**.
 *
 * A wait id is an instance path and a path is re-run: both retry ladders
 * ([`runActivity`], [`attemptItem`]) re-execute an instance at the site its
 * predecessor ran at, so the id a new pause opens under is one the board may
 * already hold. Every such seam abandons what it left behind first
 * ([`abandonPausesUnder`]), which is what makes the entry it overwrites a
 * *settled* one — and this is where that stops being a convention held at three
 * call sites and becomes the board's own rule. A displaced pause that was still
 * waiting is a task parked on a promise nothing can settle any more: it is off
 * the board, so no resume can reach it, no `releaseHumanWaits` can abandon it,
 * and the `map` permit and store handles its instance holds are never given
 * back. The failure mode is a run that hangs, which is the one shape a test
 * cannot tell from a slow one — so the board raises here instead, at the moment
 * the invariant breaks and naming the id it broke at.
 *
 * Unreachable by construction, and stated all the same: it is a bug in the
 * runtime rather than anything a composition can ask for, which is why it is not
 * one of the settlements ([`Settlement`]) and carries a class of its own.
 */
function hold(board: WaitBoard, id: string, pause: Held): void {
  const standing = board.held.get(id);
  if (standing !== undefined && standing.settled === undefined) {
    throw new WaitBoardInvariant(id);
  }
  board.held.set(id, pause);
}

/**
 * Every pause `execution` is still waiting on, **ordered by wait id**.
 *
 * What the status route reports (PRD 5.11) — and, where there is more than one,
 * what a resume addresses itself with. An execution this process is not running,
 * or one holding none, answers with an empty list.
 *
 * Ordered by id rather than by the order the pauses began, because the order
 * they began is not a fact about the composition: a `map`'s instances are
 * admitted under `max_concurrency` and park in whatever order the scheduler
 * interleaved them, so two runs over one array would publish the same two
 * questions in different orders. An id is grammar 9.4's instance path, which is
 * derived from the composition and the source-item index, so ordering on it
 * makes the report reproducible — the same reason `docs/trace.md` §4 and §5 fix
 * an order for the records a run makes. The comparison is over the string, so
 * item `10` sorts before item `2`; what the order buys is that it is the *same*
 * every run, not that it counts.
 */
export function humanWaits(execution: string): readonly HumanWait[] {
  const board = humanBoards.get(execution);
  if (board === undefined) return [];
  return [...board.held.values()]
    .filter((one) => one.settled === undefined)
    .map((one) => one.wait)
    .sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
}

/**
 * Deliver a human's answer to one pause (PRD 5.11's third verb).
 *
 * **Two surfaces call it, and it is the whole of what they share.** The app's
 * `POST /executions/:id/resume` is one; the terminal `agent-compose run` prompts
 * at is the other (grammar 8.7). What a person is asked and how their answer
 * arrives differs — a request body, a line typed at a prompt — but which pause it
 * addresses, what schema it is held to, and what each refusal means are decided
 * here for both, so the two cannot come to different answers about the same
 * board.
 *
 * `wait` names which pause when the execution is holding more than one, and may
 * be omitted when it is holding exactly one — an execution with two pauses
 * pending and no name is `"ambiguous"` rather than a coin toss.
 *
 * **A payload that does not fit the node's `output:` does not consume the
 * wait.** It answers `"mismatch"` and the pause goes on waiting, so a caller who
 * mistyped an enum variant can send the answer again; every other refusal here
 * is about *which* pause rather than about what was in the body.
 *
 * **A settled pause is settled.** Whichever of the two sides got there first —
 * an answer, or the budget running out — wins exactly once, so a resume racing
 * an expiry is decided rather than applied twice.
 *
 * **An answer this accepts can still fail the run.** The pause is journaled as
 * it settles, and a journal that refuses the record leaves the answer accepted
 * and the *node* failing with the write's own error (see [`runHuman`]): the turn
 * was spent, so it is not offered again here, and the run stops rather than
 * going on from a wait its own record does not hold.
 */
export function deliverHumanAnswer(
  execution: string,
  wait: string | undefined,
  payload: unknown,
): ResumeOutcome {
  const board = humanBoards.get(execution);
  const held = board === undefined ? [] : [...board.held.values()];
  // Ordered by id, for [`humanWaits`]'s reason and so that the two surfaces a
  // caller meets — the pauses the status route publishes and the ones a refusal
  // lists — are in one order.
  const pending = held
    .filter((one) => one.settled === undefined)
    .sort((left, right) => (left.wait.id < right.wait.id ? -1 : left.wait.id > right.wait.id ? 1 : 0));

  let chosen: Held | undefined;
  if (wait === undefined) {
    if (pending.length === 0) {
      return {
        ok: false,
        reason: "not-waiting",
        detail: "this execution is not waiting for a human answer",
      };
    }
    if (pending.length > 1) {
      return {
        ok: false,
        reason: "ambiguous",
        detail: `this execution is holding ${pending.length} pauses, so a resume has to name which one it answers`,
        pending: pending.map((one) => one.wait.id),
      };
    }
    chosen = pending[0];
  } else {
    chosen = held.find((one) => one.wait.id === wait);
    if (chosen === undefined) {
      return {
        ok: false,
        reason: "no-such-wait",
        detail: `this execution is holding no pause \`${wait}\``,
        ...(pending.length === 0 ? {} : { pending: pending.map((one) => one.wait.id) }),
      };
    }
  }

  if (chosen.settled !== undefined) {
    return { ok: false, reason: "settled", detail: settledDetail(chosen.wait.id, chosen.settled) };
  }

  let parsed: unknown;
  try {
    parsed = chosen.parse(payload);
  } catch (error) {
    // The wait is untouched: a payload that does not fit is a request to fix and
    // send again, not a turn spent.
    return { ok: false, reason: "mismatch", detail: describe(error) };
  }

  // Settling can still lose the race to an expiry — or to the run stopping — that
  // landed between the parse and here, which is why the answer is `settle`'s
  // rather than this branch's. Whatever settled it is what the refusal names.
  if (!chosen.settle("resumed", parsed)) {
    return {
      ok: false,
      reason: "settled",
      detail: settledDetail(chosen.wait.id, chosen.settled ?? "expired"),
    };
  }
  return { ok: true, wait: chosen.wait };
}

/**
 * Why a pause that is no longer waiting cannot be answered.
 *
 * `arrived` says which of the two surfaces is asking. A **delivery** has an
 * answer in hand and lost a race for it, so the sentence names it; a surface
 * that was *showing* the question and is being told it is over has no answer to
 * name, and a refusal that mentioned one would describe something nobody did.
 * One function rather than two, because everything else about the four
 * sentences — which fact each states, and how it is worded — has to be the same
 * on both.
 */
function settledDetail(id: string, settled: Settlement, arrived = true): string {
  if (settled === "expired") {
    return `the wait at \`${id}\` expired${arrived ? " before this answer arrived" : ""}, and \`on_timeout\` has already routed the execution on (grammar 8.7)`;
  }
  if (settled === "abandoned") {
    return `the wait at \`${id}\` is no longer held: the execution stopped waiting for the node that was asking, so there is nothing left to ${arrived ? "deliver this answer to" : "answer"}`;
  }
  if (settled === "interrupted") {
    return `the wait at \`${id}\` is no longer held: this run's answer surface went away, so the execution stopped there (grammar 8.7)`;
  }
  return `the wait at \`${id}\` has already been answered`;
}

/**
 * Why a pause is no longer waiting, for a surface that is **showing** its
 * question — and `undefined` while it still is.
 *
 * The other half of [`deliverHumanAnswer`]'s refusal taxonomy, for the one
 * surface that can watch a pause rather than only address it. A resume route
 * learns a wait has ended by trying to answer it; a terminal that has already
 * printed the question has to be told, so that the prompt is withdrawn with the
 * sentence the delivery would have refused it with rather than with a wording of
 * its own. Same sentences, one place, so the two surfaces cannot drift.
 *
 * An id the execution is holding nothing under answers the sentence
 * `deliverHumanAnswer` refuses an unknown wait with, because that is what it is:
 * the board this process is running never held it, or the run has ended and
 * taken the board with it.
 */
export function humanWaitEnded(execution: string, wait: string): string | undefined {
  const held = humanBoards.get(execution)?.held.get(wait);
  if (held === undefined) return `this execution is holding no pause \`${wait}\``;
  if (held.settled === undefined) return undefined;
  return settledDetail(wait, held.settled, false);
}

/**
 * Hold a `human` node's pause until somebody answers it, its budget runs out, or
 * the run turns out to have no way to answer at all (grammar 8.7, PRD 5.11).
 *
 * **How the pause is held.** The node's task awaits a promise nothing else
 * resolves, so the superstep the node is in never completes and the graph makes
 * no further progress — which is the whole of what "interrupted" means here.
 * Nothing is checkpointed: this is a promise parked in one process, which is the
 * M2 posture PRD §7 fixes (durable execution is M3), and it is what the emitted
 * `README.md` tells a reader to expect from a restarted `serve`.
 *
 * It is deliberately **not** LangGraph's own `interrupt()` — the shaping PRD §9's
 * resolved question 4 settles, on the two grounds below. That primitive
 * resumes a run from a checkpointer, which this release does not configure, and
 * it announces itself out of the *top-level* stream — while a `map`'s instances
 * and a `flow:` node's subflow run inside their node's own task, as separate runs
 * of separate compiled graphs (PRD resolved q17). A pause three instances down
 * would have to be lifted through two run boundaries that were built to keep
 * their instances' business inside them. Parking the promise leaves the pause
 * exactly where it happened and costs the same durability either shaping has.
 */
export async function runHuman(
  descriptor: HumanDescriptor,
  shown: unknown,
  context: RunContext,
  view: NodeView,
): Promise<NodeAnswer> {
  const id = instancePath(view, descriptor.node).join("/");
  const began = Date.now();
  const pausedAt = new Date(began).toISOString();
  const expiresAt =
    descriptor.timeoutMs === undefined
      ? undefined
      : new Date(began + descriptor.timeoutMs).toISOString();
  const wait: HumanWait = {
    id,
    execution: context.execution.id,
    flow: descriptor.flow,
    node: descriptor.node,
    shown: (shown ?? {}) as Record<string, unknown>,
    schema: descriptor.schema,
    pausedAt,
    ...(expiresAt === undefined ? {} : { expiresAt }),
  };
  // The two instants that describe the pause itself rather than its end. Kept
  // apart from [`HumanPause`] because they are also what the **journal** holds:
  // a replayed wait is dated by the generation that opened it, not by the one
  // that read the record back (see [`JournaledWait`]).
  const instants: Omit<JournaledInstants, "settledAt"> = {
    pausedAt,
    ...(expiresAt === undefined ? {} : { expiresAt }),
  };
  const opened: HumanPause = instants;

  // A settled wait is an effect like any other, and the one whose payload
  // `docs/trace.md` §11 most firmly keeps out of the trace: what a person
  // answered. The journal is where it goes, because a replay that re-asked a
  // question somebody has already answered would be a durability story that
  // asks the human to do the work twice (`docs/durability.md` §3.4).
  const slot = context.effects?.claim("human", { wait: id, node: descriptor.node, shown });
  if (slot?.held !== undefined) {
    if (slot.held.kind === "error") throw replayedFailure(slot.held);
    const held = slot.held.value as JournaledWait;
    // Every instant of the entry is the record's, `pausedAt` included: this
    // process opened no wait, and dating one by its own clock would put the
    // answer before the question (see [`JournaledWait`]).
    const replayedPause: HumanPause = {
      pausedAt: held.pausedAt,
      ...(held.expiresAt === undefined ? {} : { expiresAt: held.expiresAt }),
      settledAt: held.settledAt,
      settled: held.settled,
    };
    if (held.settled === "resumed") {
      // Held to the contract this build declares, exactly as the delivery that
      // recorded it was ([`deliverHumanAnswer`] parses before it settles). This
      // is resolved q29's **second** divergence at the one record kind whose
      // answer a person gave: an `output:` the composition has since narrowed
      // makes the recorded answer one this run may not go on with, and no other
      // reader would catch it — a `human` answer reaches no `parseResult`, so
      // the note [`recordedAnswerOf`] reads is never consulted, and the run
      // would end reporting an output its own schema refuses.
      //
      // Raised as a [`ReplayDivergence`] rather than as the mismatch the parse
      // threw, and off this slot rather than off the note, for that class's
      // reason: it has to travel past every policy and name the step
      // (`docs/durability.md` §7), and here the step is known outright.
      try {
        return { output: descriptor.parse(held.output), human: replayedPause };
      } catch (error) {
        throw new ReplayDivergence(
          slot,
          `the recorded answer no longer satisfies this run's contract: ${describe(error)}`,
        );
      }
    }
    // A wait that ran out its budget replays as one: the route is the
    // composition's, so it is read off the descriptor rather than off the
    // record, and what the record supplies is the instants the entry shows.
    throw new HumanExpiry(
      descriptor.flow,
      descriptor.node,
      id,
      descriptor.timeoutMs ?? 0,
      descriptor.onTimeout ?? END_NODE,
      replayedPause,
    );
  }

  // **A worker settles the dispatch paused instead of parking** (PRD resolved
  // q46, `docs/distributed.md` §3.4). Answered here, ahead of the board, for the
  // reason the board is the hub's: this process holds no wait board, no resume
  // route and no status surface, and the pause's whole life happens on the other
  // side of the wire. **Nothing is journaled**, exactly as below: the hub writes
  // the record when the wait is *answered*, and an unanswered wait is what a
  // resumed generation re-derives (resolved q28).
  //
  // The slot is required rather than optional because it is what the answer will
  // be journaled under; a process running a node with no journal session open is
  // not one a dispatch ever reaches, and it falls through to the interrupt below
  // rather than pausing into a wire that could not carry it home.
  if (pausesSettleHome && slot !== undefined) {
    throw new RemoteHumanPause(
      {
        wait: id,
        flow: descriptor.flow,
        node: descriptor.node,
        shown: (shown ?? {}) as Record<string, unknown>,
        pausedAt,
        ...(expiresAt === undefined ? {} : { expiresAt }),
        effect: {
          key: slot.key,
          site: slot.site,
          ordinal: slot.ordinal,
          request: slot.request,
        },
      },
      opened,
    );
  }

  const board = humanBoards.get(context.execution.id);
  if (board === undefined || !board.resumable) {
    // The pause happened — it is on the trace entry either way — and there is
    // nothing that could ever answer it. **Nothing is journaled**: an
    // unanswered wait is exactly what a resumed generation has to re-park, and
    // a record here would settle it with an outcome nobody gave (resolved q28).
    throw new HumanInterrupt(descriptor.flow, descriptor.node, id, opened);
  }

  return await new Promise<NodeAnswer>((resolve, reject) => {
    let timer: unknown;
    const settle = (outcome: Settlement, value: unknown): boolean => {
      // **This** pause, held by identity rather than looked up by id. A wait id
      // is an instance path, and a path is re-run: both retry ladders
      // ([`runActivity`], [`attemptItem`]) re-execute an instance at the site
      // its predecessor ran at, so the board can hold a *successor* pause under
      // this very id once the predecessor is settled — which [`hold`] is what
      // makes true of every successor. This is the other half of the same rule,
      // and the half an ordering cannot supply: a stale closure — this promise's
      // expiry timer, above all — can still be in flight when its own entry is
      // abandoned and replaced, and it settles the wait it belongs to or nothing
      // at all, never whichever wait happens to answer to its id.
      if (mine.settled !== undefined) return false;
      mine.settled = outcome;
      // Whichever side settled it, the budget is over: the timer and everything
      // it closes over go now rather than at the end of a wait nobody is holding
      // any more (see [`releaseHumanWaits`]).
      if (timer !== undefined) clearTimeout(timer as Parameters<typeof clearTimeout>[0]);
      // Told before the promise is settled, so the deadline a `map` or `flow:`
      // node above this one has been holding still is running again by the time
      // the node below it goes back to work (see [`humanWatchers`]).
      announce(wait.execution);
      if (outcome === "resumed") {
        const ended = stopped(outcome);
        let kept: Extract<JournaledWait, { settled: "resumed" }> | undefined;
        try {
          kept = slot?.keep({
            ...instants,
            settled: "resumed",
            output: value,
            settledAt: ended.settledAt,
          } satisfies JournaledWait) as Extract<JournaledWait, { settled: "resumed" }> | undefined;
        } catch (error) {
          // **The parked promise is what a write failure leaves through**, and
          // that is the whole of why the record is written inside a `try` here
          // rather than beside every other `keep` in this file. The wait is
          // already marked settled above — it has to be, or the answer and the
          // expiry could both land — so a throw that escaped `settle`
          // would leave a wait nothing may settle again holding a promise
          // nothing ever settles: [`closeHumanWaits`] and [`releaseHumanWaits`]
          // both skip a settled entry, a later [`deliverHumanAnswer`] refuses
          // it, and the `human` node's `await` never returns. The run does not
          // fail, does not park and does not end — it hangs, which is the one
          // outcome a durable execution has no way back from.
          //
          // So the failure travels as the node's: the journal could not record
          // what the person said, and a run that went on from a wait its own
          // record does not hold is a run whose resume would ask them again
          // (`docs/durability.md` §3.4).
          reject(error);
          return true;
        }
        // What the journal now holds, where it holds anything, for [`callModel`]'s
        // reason: the answer a person gave is a value the rest of the graph reads
        // and a later effect's identity may be built out of, so both generations
        // are handed the same one (`docs/durability.md` §11.1).
        resolve({
          output: kept === undefined ? value : kept.output,
          human: { ...opened, ...ended },
        });
      } else if (outcome === "expired") {
        const ended = stopped(outcome);
        try {
          slot?.keep({
            ...instants,
            settled: "expired",
            settledAt: ended.settledAt,
          } satisfies JournaledWait);
        } catch (error) {
          // The same rule on the other settlement, and the arm where escaping
          // would cost more: this one is reached from a `setTimeout` callback,
          // where a throw is an uncaught exception rather than something a
          // caller could report. The expiry is not routed either — a run that
          // took `on_timeout:` past a wait whose expiry the journal does not
          // hold would re-park on the resume and spend the budget again.
          reject(error);
          return true;
        }
        reject(
          new HumanExpiry(
            descriptor.flow,
            descriptor.node,
            id,
            descriptor.timeoutMs ?? 0,
            descriptor.onTimeout ?? END_NODE,
            { ...opened, ...ended },
          ),
        );
      } else if (outcome === "interrupted") {
        // The answer surface went away while this pause was open, which is the
        // same thing as never having had one: the pause reaches the trace with
        // no settlement, and the run ends on the interrupt (see
        // [`closeHumanWaits`]).
        reject(new HumanInterrupt(descriptor.flow, descriptor.node, id, opened));
      } else {
        // Nobody is reading this task's result — that is what abandoned means —
        // so what it rejects with is only ever an unwinding, never a report
        // (see [`abandonPausesUnder`]).
        reject(new HumanAbandoned(descriptor.flow, descriptor.node, id));
      }
      return true;
    };

    const mine: Held = {
      wait,
      parse: (payload) => descriptor.parse(payload),
      settle: (outcome, value) => settle(outcome, value),
    };
    hold(board, id, mine);
    announce(wait.execution);

    if (descriptor.timeoutMs !== undefined) {
      // Wall clock from the moment the pause begins (grammar 8.7), and `unref`ed
      // where the runtime offers it: a 24-hour budget must not be the reason a
      // process that has nothing else to do stays up.
      timer = setTimeout(() => settle("expired", undefined), descriptor.timeoutMs);
      if (typeof (timer as { unref?: () => void }).unref === "function") {
        (timer as { unref: () => void }).unref();
      }
    }
  });
}

/**
 * Hold a pause a **worker** opened, on this hub's board, until somebody answers
 * it or its budget runs out (`docs/distributed.md` §3.4, PRD resolved q46).
 *
 * The other half of [`RemoteHumanPause`], and the whole of what makes a placed
 * `human:` node mean what an unplaced one means. Everything a local pause is
 * held by, this pause is held by, because it is the **same board**: the status
 * route publishes it out of [`humanWaits`], `POST /executions/:id/resume`
 * answers it through [`deliverHumanAnswer`], [`pausesUnder`] holds the
 * dispatching node's deadline still while it waits (D102), the `parked`
 * lifecycle webhook fires for it because [`quiescent`] counts it, and
 * [`releaseHumanWaits`] drops it when the run ends.
 *
 * **Two things are the pause's own rather than this process's**, and each is a
 * durability rule rather than a convenience:
 *
 *  * the **identity** is the one the worker derived (grammar 9.4), so the hub
 *    plants the wait a local run would have opened at that site;
 *  * the **contract** is the descriptor's, read out of [`humanNodes`]. The
 *    artifact is everywhere (`docs/distributed.md` §4.3), so the schema a UI is
 *    handed and the parser an answer is held to are this node's own — not a
 *    second reading of something that travelled.
 *
 * **The instants are neither of those, and both are this planting's.** They are
 * the two lines [`runHuman`] opens a local wait with, off one `Date.now()`
 * reading, and that is what PRD resolved q46's parity bar asks of them: a wait's
 * `pausedAt` is when the generation holding the question began holding it and
 * its `expiresAt` is when that generation will stop, so the pair a reader is
 * shown is exactly the node's `timeout:` apart on either side of the wire. The
 * wire's own two instants (`docs/distributed.md` §3.4) are the *worker's*
 * readings, journaled on the settled dispatch row as what that machine's clock
 * said and never republished here — because two machines' clocks disagree, and a
 * pair assembled out of both is an interval of nothing. Dating this wait off the
 * wire's `paused_at` and this hub's deadline is the entry `docs/durability.md`
 * §3.4 refuses by name: on a worker running ahead of this hub it files an answer
 * that arrives before its question.
 *
 * **The budget follows the contract and not the wire**, which is the rule the
 * paragraph above is the reader's side of. The wire's `expires_at` is an
 * instant stamped by the *worker's* clock, and two machines' clocks disagree —
 * so a timer armed at `Date.parse(expires_at) - Date.now()` would give a
 * `timeout: 5m` node no time at all on a worker ten minutes behind this hub, and
 * a quarter of an hour on one ten minutes ahead. What is armed is therefore
 * `descriptor.timeoutMs` — the composition's own budget, which is the same
 * number the worker computed its instant from — from the moment the wait goes on
 * **this** board, which is the only instant a local pause's budget is ever spent
 * from either. A hub that re-derives an unanswered pause after a restart plants
 * it again and arms it again, exactly as a resumed generation re-parks a local
 * wait: PRD resolved q46 says a placed `human:` node means what the same node
 * unplaced means, and "how long do I have" is not a dimension a deploy file may
 * answer differently.
 *
 * **And the deadline published is the deadline armed**, which is the same rule
 * read from the reader's side: `expiresAt` is derived here, from the instant
 * this planting spends the budget from, and the wire's instant is never
 * republished. Publishing the worker's would show a `timeout: 5m` question as
 * expired for the whole five minutes it is answerable on a worker ten minutes
 * behind — a status route saying one thing while the resume route does another —
 * and after a restart the predecessor's instant says the same of an outage
 * longer than the budget. One derivation, beside the arming, for both plantings.
 *
 * **A restart re-dates the pause, exactly as a re-parked local wait is
 * re-dated.** A hub that re-derives an unanswered pause off the settled row
 * plants it here again, so both of its instants are the new generation's and
 * their difference is the whole `timeout:` — which is what the same node
 * unplaced does, because an unanswered wait journals nothing (resolved q28) and
 * a resumed generation opens it from scratch (`docs/durability.md` §5). What the
 * worker's clock said survives on the settled dispatch row, which is where a
 * reader asking when *that machine* reached the node finds it; it is not the
 * date of a wait no process was holding.
 *
 * Answers the record the hub journals — through `keep`, the caller's writer,
 * called **inside** the settlement for the reason [`runHuman`]'s own `slot.keep`
 * is: a run that went on from a wait its own record does not hold would ask the
 * person again on its next resume (`docs/durability.md` §3.4), so the write
 * happens before the promise resolves and a write that throws fails the node
 * rather than the wait. What it is handed is exactly the `JournaledWait` a local
 * pause writes, so the redispatch's `effect_history` hands the worker a record
 * its own replay consumes at the very claim that paused ([`runHuman`]'s replay
 * branch). The two settlements a *composition* declared resolve; the two that
 * are the run's own shape reject, exactly as they do for a local pause — an
 * abandoned wait unwinds the task, and a withdrawn answer surface is a
 * [`HumanInterrupt`].
 */
export async function holdRemotePause(
  execution: string,
  remote: RemotePause,
  keep: (settled: JournaledWait) => void,
): Promise<JournaledWait> {
  const address = `${remote.flow}.${remote.node}`;
  const descriptor = humanNodes.get(address);
  if (descriptor === undefined) {
    // **A composition that no longer declares the node the pause came from.**
    // Unreachable while one generation holds the pause: an artifact both ends
    // hold registers the same nodes — the handshake triple pins one tree
    // (`docs/distributed.md` §4.1) — and the hub refuses a pause naming an
    // unregistered node before it settles the dispatch (`./mesh.ts`'s
    // `pauseOf`). What that reasoning does *not* cover is the path this class is
    // for: a hub restarted on a rebuilt artifact re-derives an unanswered pause
    // straight off the settled row, where no route re-reads it, and finds a
    // `human:` node the composition has since renamed or dropped. That is
    // resolved q29's disagreement exactly — a journal that does not describe
    // this run — so it is that class, at the record the answer would have been
    // written under, rather than a bare error travelling as the node's.
    throw new ReplayDivergence(
      {
        key: remote.effect.key,
        site: remote.effect.site,
        kind: "human",
        ordinal: remote.effect.ordinal,
      },
      `\`${address}\` paused on a worker and this hub registers no such \`human:\` node: it registers ${
        [...humanNodes.keys()].map((name) => `\`${name}\``).join(", ") || "none"
      } (docs/distributed.md §3.4)`,
    );
  }
  // **The wait's own instants, both off the clock that will fire them.** These
  // are [`runHuman`]'s own two lines, character for character, and that is the
  // point: one `Date.now()` reading dates the wait this hub is opening and the
  // deadline it is arming, so the pair a status route publishes is the node's
  // `timeout:` apart whichever machine the question came from. The wire's own
  // `paused_at` and `expires_at` are the worker's readings of its own clock —
  // journaled on the settled dispatch row, never republished here
  // (`docs/distributed.md` §3.4).
  const began = Date.now();
  const pausedAt = new Date(began).toISOString();
  const expiresAt =
    descriptor.timeoutMs === undefined
      ? undefined
      : new Date(began + descriptor.timeoutMs).toISOString();
  const instants: Omit<JournaledInstants, "settledAt"> = {
    pausedAt,
    ...(expiresAt === undefined ? {} : { expiresAt }),
  };
  const opened: HumanPause = instants;
  const wait: HumanWait = {
    id: remote.wait,
    execution,
    flow: remote.flow,
    node: remote.node,
    shown: remote.shown,
    schema: descriptor.schema,
    pausedAt,
    ...(expiresAt === undefined ? {} : { expiresAt }),
  };

  const board = humanBoards.get(execution);
  if (board === undefined || !board.resumable) {
    // The same answer a local pause gets on a run with no answer surface, and
    // the same nothing is journaled. Unreachable through `serve`, which is the
    // only invocation that mounts a mesh at all (`./mesh.ts`'s `mounted`).
    throw new HumanInterrupt(remote.flow, remote.node, remote.wait, opened);
  }

  return await new Promise<JournaledWait>((resolve, reject) => {
    let timer: unknown;
    const settle = (outcome: Settlement, value: unknown): boolean => {
      // **This** pause, by identity rather than by id — [`runHuman`]'s rule and
      // its reason: a redispatch re-executes the node at the same site, so the
      // board can hold a successor under this very id once this one is settled.
      if (mine.settled !== undefined) return false;
      mine.settled = outcome;
      if (timer !== undefined) clearTimeout(timer as Parameters<typeof clearTimeout>[0]);
      // Told before the promise settles, so a deadline the dispatching node has
      // been holding still is running again by the time the redispatch is made.
      announce(execution);
      if (outcome === "resumed" || outcome === "expired") {
        // **Written before the promise resolves**, which is where [`runHuman`]
        // writes a local pause's record and for the same reason: the caller of
        // this promise answers the person `202` and the route returns, so a
        // record appended after it is one a process killed in between never
        // wrote — leaving a wait this board has settled, with nothing in the
        // journal, which the next start re-derives off the settled dispatch row
        // and asks a second time (`docs/durability.md` §3.4).
        //
        // An expiry is journaled the same way and **routed by the node**, not
        // here: the redispatch replays this record, and `runHuman` raises the
        // [`HumanExpiry`] carrying the composition's own `on_timeout:` route
        // (grammar 8.7). That is the parity — the expiry of a placed pause is
        // decided by the same line of the same function as an unplaced one's.
        const settled: JournaledWait =
          outcome === "resumed"
            ? {
                ...instants,
                settled: "resumed",
                output: value,
                settledAt: stopped(outcome).settledAt,
              }
            : { ...instants, settled: "expired", settledAt: stopped(outcome).settledAt };
        try {
          keep(settled);
        } catch (error) {
          // [`runHuman`]'s rule at its own `slot.keep`, which this arm is the
          // other half of: the wait is already marked settled, so a throw that
          // escaped would leave a promise nothing can ever settle and a node
          // that never returns. It travels as the node's failure instead — the
          // journal could not record what the person said, and a run that went
          // on from a wait its own record does not hold is one whose resume
          // would ask them again.
          reject(error);
          return true;
        }
        resolve(settled);
      } else if (outcome === "interrupted") {
        reject(new HumanInterrupt(remote.flow, remote.node, remote.wait, opened));
      } else {
        reject(new HumanAbandoned(remote.flow, remote.node, remote.wait));
      }
      return true;
    };

    const mine: Held = {
      wait,
      parse: (payload) => descriptor.parse(payload),
      settle: (outcome, value) => settle(outcome, value),
    };
    hold(board, remote.wait, mine);
    announce(execution);

    if (descriptor.timeoutMs !== undefined) {
      // The **composition's** budget, from the moment the wait goes on this
      // board — the same line, the same number and the same instant as
      // [`runHuman`]'s own timer, and the instant `expiresAt` above publishes.
      // See the note above on why the wire's `expires_at` is neither armed nor
      // republished.
      //
      // **A restart re-arms it whole**, because the hub re-derives an unanswered
      // pause by planting it again and this is the planting: a local wait nobody
      // answered is re-parked with a fresh budget (`docs/durability.md` §5), and
      // a placed one that spent its predecessor's budget instead would answer
      // "how long do I have" differently for the same node under two deploy
      // files — which PRD resolved q46 does not allow a placement to decide.
      timer = setTimeout(() => settle("expired", undefined), descriptor.timeoutMs);
      if (typeof (timer as { unref?: () => void }).unref === "function") {
        (timer as { unref: () => void }).unref();
      }
    }
  });
}

/** How a pause that reached the trace stopped waiting, as the entry spells it. */
function stopped(outcome: "resumed" | "expired"): {
  readonly settledAt: string;
  readonly settled: "resumed" | "expired";
} {
  return { settledAt: new Date().toISOString(), settled: outcome };
}

/**
 * One settled wait as the journal keeps it (see [`runHuman`]).
 *
 * The answer itself is in it, which is the one payload `docs/trace.md` §11 is
 * most explicit about keeping out of the trace — and the clearest statement of
 * why the journal is a second artifact rather than the trace read twice
 * (`docs/durability.md` §7).
 *
 * **All three instants** are in it, not only the settlement. A pause that a
 * person answered at 10:05 is replayed by a process that started at 11:00, and
 * an entry that took `pausedAt` from *this* process's clock and `settledAt` from
 * the record would say the wait was answered five and fifty-five minutes before
 * it began. `docs/durability.md` §9 promises the opposite — "a reader of the
 * resumed document sees what the execution did, not what this process did" — so
 * the whole `HumanPause` is the record's, and the resumed generation's clock
 * reaches the entry nowhere.
 */
interface JournaledInstants {
  /** When the wait began — the `pausedAt` of the entry the record replays as. */
  readonly pausedAt: string;
  /** When it would have expired, on the generation that opened it. */
  readonly expiresAt?: string;
  /** When it stopped waiting. */
  readonly settledAt: string;
}

/**
 * Exported for the one writer of this record that is not [`runHuman`]: the hub,
 * journaling the answer to a pause a worker opened ([`holdRemotePause`],
 * `docs/distributed.md` §3.4). The shape is stated once, here, because the
 * reader of both is the same replay branch of `runHuman`.
 */
export type JournaledWait = JournaledInstants &
  ({ readonly settled: "resumed"; readonly output: unknown } | { readonly settled: "expired" });

/** LangGraph's terminal pseudo-node, as a `goto` target spells it. */
const END_NODE = "__end__";

/** The [`HumanExpiry`] on this error's `cause` chain, if it came out of one. */
function expiryOf(error: unknown): HumanExpiry | undefined {
  for (let held: unknown = error; held !== undefined && held !== null; ) {
    if (held instanceof HumanExpiry) return held;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/**
 * The [`HumanAbandoned`] on this error's `cause` chain, if it came out of one.
 *
 * An abandonment is an **unwinding**, never an outcome: the task it ends is
 * inside an instance whose result was already discarded, so every ladder and
 * every policy it passes on the way out has to let it through rather than act on
 * it. Three do — [`runActivity`]'s `retry:`, [`attemptItem`]'s `on_item_error`,
 * and [`runNode`]'s `on_error:` — and each reads this for the same reason
 * [`interruptOf`] is read beside it: what reaches them is a [`NodeFailure`] or an
 * [`ItemAttempts`] wrapping it. Absorbing one under `skip` would route a graph
 * past a `human` node whose answer the composition declared it needed, and
 * retrying one would re-open a pause under a node that has stopped waiting.
 */
function abandonedOf(error: unknown): HumanAbandoned | undefined {
  for (let held: unknown = error; held !== undefined && held !== null; ) {
    if (held instanceof HumanAbandoned) return held;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/**
 * The [`HumanInterrupt`] on this error's `cause` chain, if it came out of one.
 *
 * Exported because the two callers that have to tell an interrupted run from a
 * failed one are outside this module: `src/cli.ts`, which reports the outcome
 * and exits on a code of its own, and any ejected caller of [`runFlow`] that
 * wants the same distinction. The chain is walked rather than the error tested,
 * because what reaches them is a [`FlowFailure`] wrapping a [`NodeFailure`]
 * wrapping this.
 */
export function interruptOf(error: unknown): HumanInterrupt | undefined {
  for (let held: unknown = error; held !== undefined && held !== null; ) {
    if (held instanceof HumanInterrupt) return held;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/**
 * The [`RemoteHumanPause`] on this error's `cause` chain, if it came out of one.
 *
 * Read by `./worker-node.ts`, which turns it into the *paused* result of
 * `docs/distributed.md` §3.4. The chain is walked for [`interruptOf`]'s reason
 * and one more: the pause is usually reached inside an attached `flow.*`, which
 * grammar §14.1 rule 4 runs in the attaching agent's placement, so a subflow
 * boundary and a tool loop are both between it and here.
 */
export function remotePauseOf(error: unknown): RemoteHumanPause | undefined {
  for (let held: unknown = error; held !== undefined && held !== null; ) {
    if (held instanceof RemoteHumanPause) return held;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/**
 * The [`HumanPause`] either of the two carried, when the pause was **`site`'s
 * own** — and `undefined` when it belonged to a node further down.
 *
 * The identity check is the whole of this function, and it is what keeps
 * `TraceEntry.human` a `human` node's field: `docs/trace.md` §3 says a node that
 * is not one never carries the key, and an error travels much further than the
 * node that raised it. A [`HumanInterrupt`] raised inside a subflow or a
 * dispatched instance is re-wrapped by [`SubflowFailure`] or [`ItemAttempts`]
 * and arrives on the `cause` chain at the enclosing `flow:` or `map` node's
 * [`runNode`] catch, which walks that chain for everything else it recovers
 * ([`traceOf`], [`dispatchesOf`]). Recovering the pause there too would stamp
 * one wait onto N+1 entries — and onto entries whose node holds no wait at all,
 * each without a `settledAt`, so each reading as a pause the run ended holding.
 *
 * `site` is the caller's own instance path (grammar 9.4, flattened), which is
 * exactly the id [`runHuman`] named the pause under, so equality decides it.
 * Both carriers are read in the order they were: an expiry is the node's own
 * outcome and an interrupt is the run's, and a chain holding both is answered by
 * the nearer one.
 */
function pauseOf(error: unknown, site: string): HumanPause | undefined {
  const expiry = expiryOf(error);
  if (expiry !== undefined && expiry.wait === site) return expiry.pause;
  const interrupt = interruptOf(error);
  if (interrupt !== undefined && interrupt.wait === site) return interrupt.pause;
  return undefined;
}

// ---------------------------------------------------------------------------
// One node execution, end to end
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Durable executions (PRD 5.11, resolved q26–q29, `docs/durability.md`)
// ---------------------------------------------------------------------------

/**
 * What a caller says about the execution it is starting or resuming.
 *
 * `runFlow` in `./graph.ts` is the one caller, and it passes what an invocation
 * already knows: nothing here has to be re-derived from the composition.
 */
export interface ExecutionOpening {
  readonly execution: string;
  readonly flow: string;
  /**
   * What started it. `manual` for `agent-compose run` and for a `manual`
   * trigger; an `http` trigger's own name where one did.
   *
   * Recorded and never dispatched on: resolved q28 makes recovery replay the
   * executions that exist rather than re-fire the trigger that created them.
   */
  readonly trigger: string;
  readonly inputs: Record<string, unknown>;
  readonly sessionKey: string;
  /**
   * The completion webhook this invocation asked for, where it asked for one
   * (grammar 13.3's `callback:`).
   *
   * `src/serve.ts` is the only caller that passes it, and it resolves the URL
   * when the request arrives rather than when the run ends — because the run may
   * end in a *different process* (`docs/durability.md` §6.1), and a URL nobody
   * recorded is a caller nobody can call back.
   */
  readonly callback?: string;
  /**
   * The W3C `traceparent` the request that started this invocation carried,
   * where it carried a valid one (PRD resolved q51).
   *
   * `src/serve.ts` is the only caller that passes it, and for
   * [`callback`][`ExecutionOpening.callback`]'s reason: the export that adopts
   * the caller's trace happens when the execution **settles**, which may be in a
   * different process (`docs/durability.md` §6.1), so the header goes on the
   * lifecycle row rather than staying in the one that read it.
   */
  readonly traceparent?: string;
  /**
   * Whether this generation is **resuming** an execution the journal already
   * holds, rather than starting one.
   *
   * The only thing it changes is whether a recorded effect may be consumed: a
   * generation that started the execution writes and never reads (there is
   * nothing yet to read), and a resuming one consumes what the journal holds up
   * to the frontier and then writes past it (resolved q29).
   */
  readonly resuming?: boolean;
}

/**
 * Begin journaling one execution, and answer with the journal it will use.
 *
 * Called before the graph is streamed, so a record exists for an execution the
 * process may die in the middle of — which is the whole point: a lifecycle row
 * with `status: "open"` is what `serve`'s recovery and `agent-compose resume`
 * enumerate.
 *
 * Every instance nested inside the run — a `flow:` node's, a `map`'s dispatch,
 * a subflow a model called — finds this session by execution id rather than by
 * being handed it, exactly as the wait board is found ([`openHumanWaits`]).
 */
export async function openExecution(opening: ExecutionOpening): Promise<void> {
  const journal = await openJournal();
  const resuming = opening.resuming === true;
  if (resuming) {
    const row = journal.execution(opening.execution);
    if (row !== undefined && row.journalVersion !== JOURNAL_VERSION) {
      throw new Error(
        `\`${opening.execution}\` was journaled at version ${row.journalVersion} and this build reads version ${JOURNAL_VERSION}: a journal is read by the compiler release that wrote it (\`docs/durability.md\` §11)`,
      );
    }
  } else {
    journal.begin({
      id: opening.execution,
      flow: opening.flow,
      trigger: opening.trigger,
      inputs: opening.inputs,
      sessionKey: opening.sessionKey,
      ...(opening.callback === undefined ? {} : { callback: opening.callback }),
      ...(opening.traceparent === undefined ? {} : { traceparent: opening.traceparent }),
      status: "open",
      journalVersion: JOURNAL_VERSION,
      startedAt: new Date().toISOString(),
    });
  }
  openSession(opening.execution, journal, resuming);
  settledJournals.set(opening.execution, journal);
}

/**
 * Record how one execution ended — or that it has not ended at all.
 *
 * Three outcomes and only two of them close the row, which is resolved q28's
 * scope read at the one place it is decided:
 *
 *  * **no error** — `completed`. Nothing left to replay.
 *  * **an interrupt** — the run reached a `human` pause with nobody to answer
 *    it (grammar 8.7). The row stays **open**, because that is precisely the
 *    execution `agent-compose resume` and `serve`'s recovery exist for: the
 *    wait id is deterministic, so a resumed generation re-parks under it.
 *  * **a divergence** — the row stays **open** too, and this is the outcome that
 *    is easiest to get wrong. A [`ReplayDivergence`] is not a statement about
 *    the execution; it is a statement about the disagreement between the
 *    execution's record and the composition *this build* is holding
 *    (`docs/durability.md` §7: "the execution stays open"). Closing it `failed`
 *    would record this build's disagreement as the execution's outcome and make
 *    it unresumable for ever — and `serve` replays every open execution at every
 *    start, so one deploy that moved a prompt would burn every open execution,
 *    parked humans included, in a single restart.
 *  * **anything else** — `failed`. A composition's own error policy has already
 *    decided this run; replaying it would re-derive the same failure from the
 *    same record.
 */
export function settleExecution(execution: string, error?: unknown): void {
  const journal = settledJournals.get(execution);
  if (journal === undefined) return;
  if (staysOpen(execution, error)) return;
  if (error === undefined) {
    journal.end(execution, "completed");
    return;
  }
  journal.end(execution, "failed", describe(error));
}

/**
 * Whether an execution that stopped this way is one the journal keeps **open**
 * — and so one a resume will replay.
 *
 * [`settleExecution`]'s first question, exported because it is also `runFlow`'s:
 * a run whose row stays open has not finished with the world, so what it owns
 * has to outlive it (`src/graph.ts`, `docs/durability.md` §5). Two functions
 * deciding it separately would eventually decide it differently, and the way
 * that failure shows up — a partition removed under an execution somebody
 * resumes tomorrow — is one no test of either function alone would catch.
 *
 * Read off the **latch** as well as off the error, because the one divergence
 * that has no error to travel on is a detached delivery's (see
 * [`latchDivergence`]): a run whose only divergence was raised there is not one
 * to be closed `completed` either.
 */
export function staysOpen(execution: string, error?: unknown): boolean {
  if (divergenceOf(error) !== undefined || latchedDivergence(execution) !== undefined) return true;
  return error !== undefined && interruptOf(error) !== undefined;
}

/**
 * Every execution one process is journaling, so [`settleExecution`] can reach
 * the handle without the caller carrying it through a `finally`.
 */
const settledJournals = new Map<string, Journal>();

/** Release one execution's journaling state. The file stays the project's. */
export function closeExecution(execution: string): void {
  settledJournals.delete(execution);
  closeSession(execution);
}

/**
 * The [`ReplayDivergence`] on this error's `cause` chain, if it came out of one.
 *
 * [`interruptOf`]'s counterpart for the other outcome a run has that is not a
 * failure of the composition: a resume whose journal does not describe this
 * graph. It is read for the same reason — a reporting surface should say *what
 * happened* rather than the class of wrapper the failure arrived in — and the
 * two are the whole of why `src/cli.ts` looks past a `FlowFailure` at all.
 */
export function divergenceOf(error: unknown): ReplayDivergence | undefined {
  for (let held: unknown = error; held !== undefined && held !== null; ) {
    if (held instanceof ReplayDivergence) return held;
    held = (held as { cause?: unknown }).cause;
  }
  return undefined;
}

/** One execution's lifecycle row, or `undefined` where the journal has none. */
export async function journaledExecution(id: string): Promise<ExecutionRow | undefined> {
  if (!journalExists()) return undefined;
  return (await openJournal()).execution(id);
}

/**
 * Every execution the journal holds open, oldest first.
 *
 * What `serve` replays on start (resolved q28), and what a reader is pointed at
 * by an unknown-execution diagnostic.
 */
export async function openExecutions(): Promise<readonly ExecutionRow[]> {
  if (!journalExists()) return [];
  return (await openJournal()).openExecutions();
}

// ---------------------------------------------------------------------------
// The delivery ledger (grammar 13.3, PRD resolved q34, q35)
// ---------------------------------------------------------------------------
//
// `src/serve.ts` is what *makes* a delivery; these are what record it. They are
// here rather than reached for directly because the emitted import graph has
// one shape — `serve.ts` → `runtime.ts` → `journal.ts` — and the four
// lifecycle-row readers above already keep it (see [`journaledExecution`]).

/**
 * Record the intent to deliver one lifecycle webhook, allocating its ordinal.
 *
 * Before any attempt, which is what makes the delivery at-least-once: a process
 * that dies mid-attempt leaves a row a later start finishes, under the delivery
 * id the receiver dedupes on (resolved q35).
 */
export async function intendDelivery(intent: DeliveryIntent): Promise<DeliveryRecord> {
  return (await openJournal()).intendDelivery(intent);
}

/**
 * Record a delivery `callback_allow:` refused, which is one nothing was sent
 * for (grammar 13.3, Decision D127).
 */
export async function refuseDelivery(
  intent: CallbackIntent,
  reason: string,
): Promise<DeliveryRecord> {
  return (await openJournal()).refuseDelivery(intent, reason);
}

/**
 * Record the same refusal against a delivery the journal already holds pending
 * — the row a build that did not declare the execution's trigger left for one
 * that does (`docs/durability.md` §3.7).
 */
export async function refuseRecordedDelivery(
  execution: string,
  ordinal: number,
  reason: string,
): Promise<void> {
  (await openJournal()).refuseRecorded(execution, ordinal, reason);
}

/**
 * End a pending delivery whose schedule has no offset left in it, without an
 * attempt (`docs/durability.md` §3.7).
 *
 * The row a restart under a **shorter** `AGENT_COMPOSE_CALLBACK_RETRY` than the
 * one that wrote it meets: its recorded attempts already number as many as this
 * process's schedule has offsets, so there is nothing to wait for and nothing to
 * record — and a delivery has two ends, neither of which is staying `pending`
 * while the status route reports it as owed.
 */
export async function exhaustRecordedDelivery(
  execution: string,
  ordinal: number,
  reason: string,
): Promise<void> {
  (await openJournal()).exhaustRecorded(execution, ordinal, reason);
}

/** Record what one attempt did, and where the delivery stands after it. */
export async function recordDeliveryAttempt(
  execution: string,
  ordinal: number,
  attempt: DeliveryAttempt,
  status: DeliveryStatus,
): Promise<void> {
  (await openJournal()).recordAttempt(execution, ordinal, attempt, status);
}

/**
 * Every delivery one execution has, by ordinal.
 *
 * Read by the status route, which is what makes a refused or exhausted
 * delivery visible rather than silent (resolved q33, q35), and by the parking
 * webhook, which reads the pauses earlier deliveries already reported.
 */
export async function deliveriesOf(execution: string): Promise<readonly DeliveryRecord[]> {
  if (!journalExists()) return [];
  return (await openJournal()).deliveries(execution);
}

/** Every delivery still owed an attempt — what a restarted `serve` picks up. */
export async function undeliveredDeliveries(): Promise<readonly DeliveryRecord[]> {
  if (!journalExists()) return [];
  return (await openJournal()).undelivered();
}

/** What a report is *of*, before the journal's own half is read into it. */
export interface ReportedExecution {
  readonly id: string;
  readonly flow: string;
  /** What started it: a trigger's name, or `manual` (`docs/durability.md` §3.5). */
  readonly trigger: string;
  readonly status: string;
  /** The pauses it is holding, as the surface that can answer them presents them. */
  readonly interrupts?: readonly unknown[];
  /**
   * The placement waits it is holding — a placed node whose dispatch no worker
   * has taken, or one a worker is running (`docs/distributed.md` §6.1).
   *
   * Its own key rather than a row of `interrupts`, because the two are answered
   * by different things: an interrupt is a question with a schema and a resume
   * URL, and this is a machine that has not shown up yet.
   */
  readonly placements?: readonly unknown[];
  readonly outputs?: Record<string, unknown>;
  readonly error?: string;
  readonly trace?: readonly TraceEntry[];
}

/**
 * What the status route serves about an execution, and what every lifecycle
 * webhook carries (grammar 13.3, PRD resolved q34).
 *
 * **One document, one writer.** The webhook's body is the status route's report
 * — that is the wire grammar 13.3 states — and there are two places a report is
 * made: `serve`, which answers the route and pushes the webhook, and
 * `agent-compose resume`, which closes a `serve`-started execution by hand and
 * journals the `settled` webhook it owes (`docs/durability.md` §6.2) with no app
 * anywhere to serve one. Two writers would agree on the day they were written.
 *
 * `trace_version` travels **with** the trace and only with it (`docs/trace.md`):
 * a version key describing nothing would be a number a reader could pin against
 * no format at all. Two reports have nothing for it to describe — a run still
 * going, which has recorded nothing yet, and a run that **failed** carrying no
 * trace at all, which is a failure raised before the graph ran — and both carry
 * neither key. The gate is whether a trace exists, not whether it has entries in
 * it: a run that failed *inside* the graph having recorded nothing carries
 * `trace: []` and the version beside it, because an empty trace is a statement
 * about the run and an absent one is not. The rule a reader is given is the one
 * this expresses — wherever a `trace` appears, the version that describes it
 * appears beside it, and wherever one is absent so is the other — and it holds on
 * the two surfaces this feeds, the status route and the completion webhook,
 * exactly as it does for `run`'s JSON record and the trace file.
 *
 * `deliveries` is on the report of every execution that has made one. It is what
 * makes a **refused** delivery — a callback URL `callback_allow:` admits nowhere
 * — and an **exhausted** one visible rather than silent, which is what resolved
 * q33 and q35 ask of them: neither is the execution's failure, so the run's own
 * `status` says nothing about either and this is the only place a reader can see
 * them. No credential appears in it, and neither does a delivered body: what is
 * published is what happened.
 */
export async function executionReport(
  execution: ReportedExecution,
): Promise<Record<string, unknown>> {
  let delivered: readonly DeliveryRecord[] = [];
  try {
    delivered = await deliveriesOf(execution.id);
  } catch {
    // A journal this process cannot read is not a reason to refuse the report:
    // what a reader is asking about is the run, and the rest of it is here.
  }
  const waits = execution.interrupts ?? [];
  const placed = execution.placements ?? [];
  return {
    execution_id: execution.id,
    flow: execution.flow,
    trigger: execution.trigger,
    status: execution.status,
    ...(waits.length === 0 ? {} : { interrupts: waits }),
    ...(placed.length === 0 ? {} : { placement_waits: placed }),
    ...(delivered.length === 0 ? {} : { deliveries: delivered.map(reportedDelivery) }),
    ...(execution.outputs === undefined ? {} : { outputs: execution.outputs }),
    ...(execution.error === undefined ? {} : { error: execution.error }),
    ...(execution.trace === undefined
      ? {}
      : { trace_version: TRACE_VERSION, trace: execution.trace }),
  };
}

/**
 * One callback delivery, as a report publishes it.
 *
 * `snake_case` because these are document keys. The **body** is not among them —
 * it is the report a receiver was sent, which a reader already has in front of
 * them — and neither is anything `callback_auth:` resolved.
 */
function reportedDelivery(record: DeliveryRecord): Record<string, unknown> {
  return {
    delivery_id: record.id,
    ordinal: record.ordinal,
    event: record.event,
    url: record.url,
    status: record.status,
    intended_at: record.intendedAt,
    ...(record.settledAt === undefined ? {} : { settled_at: record.settledAt }),
    attempts: record.attempts.map((attempt) => ({
      at: attempt.at,
      outcome: attempt.outcome,
      ...(attempt.detail === undefined ? {} : { detail: attempt.detail }),
    })),
    ...(record.detail === undefined ? {} : { detail: record.detail }),
  };
}

/** The graph state a node reads: the composition's channels, plus `$run`. */
export type GraphStateLike = Readonly<Record<string, unknown>> & { readonly $run: RunChannel };

/** What a node sees before it runs. */
export interface NodeView {
  /** Every channel, as of the start of this step. */
  readonly state: Readonly<Record<string, unknown>>;
  /** The compiler's own channel. */
  readonly run: RunChannel;
  /**
   * The roots a node's *configuration* reads: `input`, `state` and `execution`
   * (grammar 4.1), already bound through their declared shapes.
   *
   * Carried on the view because two constructs need them after the input
   * builder has run: a `map`'s per-item bindings extend them with the item and
   * with the dispatch's own `execution.item_index`, and `over` extends them with
   * the producing node's result.
   */
  readonly roots: Roots;
}

/** Everything `./graph.ts` says about one node (grammar 7.1, 8, 9). */
export interface NodeDescriptor {
  readonly flow: string;
  readonly node: string;
  readonly policy: NodePolicy;
  /** The shapes the roots of this node's expressions are read through. */
  readonly shapes: {
    readonly input: Shape;
    readonly state: Shape;
    readonly output: Shape;
  };
  /**
   * Build the input the activity is given (grammar 8.0).
   *
   * `roots` carries `input`, `state` and `execution` — the three a node's
   * configuration may read (Decision D42: node outputs are readable only from
   * edge guards and `map.over`) — and `view` is what a name-based read resolves
   * against, where no expression stands between the two declarations.
   */
  input(roots: Roots, view: NodeView): unknown;
  /**
   * Run the activity and parse its answer with the emitted schema.
   *
   * The parse is inside, so a nonconforming answer is a node error the node's
   * own `retry:` policy can ask again about (PRD 5.2: the answer is rejected
   * before any edge is evaluated).
   */
  run(input: unknown, context: RunContext, view: NodeView): Promise<NodeAnswer>;
  readonly writes: readonly WriteDescriptor[];
  readonly edges: readonly EdgeDescriptor[];
  /**
   * Whether a `map.over` in this flow reads this node's result, so the result is
   * kept in `$run.outputs` for the map's own step to read (grammar 8.6 rule 11).
   */
  readonly retains?: boolean;
  /**
   * Whether this node takes no `timeout` and no `retry` from grammar 9.3 level 1
   * — a `human` node, and only a `human` node (Decision D102).
   */
  readonly exempt?: boolean;
}

/** What one node's activity produced. */
export interface NodeAnswer {
  /** Its result object, which `writes` maps into channels (grammar 8.0). */
  readonly output: unknown;
  /**
   * What it contributes to the shared conversation history (grammar 10.4):
   * the exchange an `agent:` node composed, or the turns a `context: inherit`
   * subflow instance added to the caller's channel.
   */
  readonly history?: readonly unknown[];
  /**
   * Channel writes the activity made **itself**, already in canonical order — a
   * `map` node's, whose writers are its instances rather than its own output
   * (grammar 7.6.4 clause 2, 8.6 rule 5).
   */
  readonly channels?: readonly ChannelWrite[];
  /** What a `map` dispatched, for the trace (PRD 5.3, 5.6). */
  readonly dispatches?: readonly DispatchRecord[];
  /**
   * What a model dispatched: the subflows an agent's tool loop instantiated, in
   * the order the node can put them (PRD §9.20).
   *
   * `models`' counterpart, and it carries the same two facts: an `agent:` node
   * answers with its loop's own call order, and a `map` answers with its items'
   * concatenated in source-item order. What the node execution *made* is
   * [`RunContext.toolDispatches`], and [`merged`] is where the two meet.
   */
  readonly toolDispatches?: readonly DispatchRecord[];
  /** The trace of the subflow instance a `flow:` node ran (grammar 8.5). */
  readonly inner?: readonly TraceEntry[];
  /** Which member of its route served each model call (PRD 5.9). */
  readonly models?: readonly ModelCall[];
  /** The wait a `human` node held, and how it ended (grammar 8.7). */
  readonly human?: HumanPause;
}

/** One channel a `map` node writes, with every contribution in index order. */
export interface ChannelWrite {
  readonly channel: string;
  readonly reduce: Reduce;
  /** The instances' contributions, ascending by source-item index. */
  readonly values: readonly unknown[];
}

/** The `execution` root, bound for an expression (grammar 4.1). */
const EXECUTION_SHAPE = {
  properties: { id: "string", session_key: "string", item_index: "int" },
} as const;

/**
 * Every record of one kind that a node execution made, reported once (PRD 5.9,
 * §9.20).
 *
 * `made` is the node's own channel ([`RunContext.modelCalls`], and
 * [`RunContext.toolDispatches`] for the other kind): every record, in the order
 * it was made, across every attempt the node's `retry:` policy made and every
 * instance a `map` joined. `ordered` is what the *answer* carried, which is the
 * subset the node put in an order of its own — a `map`'s, which is source-item
 * order — and which is therefore the shape a reader of a successful run expects.
 *
 * The two are not the same set. An answer can only hold what its own attempt
 * produced and only what the node had something to say about, so three kinds of
 * real record fall outside it: an earlier attempt's, an item whose own retries
 * were exhausted and which `on_item_error: skip` absorbed, and an item-level
 * retry's earlier attempts. This puts them back, ahead of `ordered` and in the
 * order they were made, and identifies them by **identity** rather than by
 * shape: [`callModel`] and [`callSubflowTool`] each push the very object they
 * hand on, so a record is in `ordered` exactly when it is the same object.
 */
function merged<T>(
  made: readonly T[],
  ordered: readonly T[] | undefined,
): readonly T[] | undefined {
  if (made.length === 0) return ordered;
  if (ordered === undefined || ordered.length === 0) return [...made];
  const carried = new Set(ordered);
  const outside = made.filter((call) => !carried.has(call));
  return outside.length === 0 ? ordered : [...outside, ...ordered];
}

/**
 * The model calls an entry carries, taken off the loop's live records
 * (`docs/trace.md` §7, §5.3).
 *
 * [`ModelCall.toolCalls`] is the one field of a trace record written *after* the
 * record was made, by a tool loop that is still running when the record reaches
 * [`merged`] — so a call object is a moving thing and an entry must not hold
 * one. It matters in exactly one place, and that place is why this exists: a
 * node deadline is **raced** against the loop (see [`runActivity`]), so a tool
 * call still in flight when the budget runs out unwinds against the aborted
 * signal some turns after this entry was built, and a live object would grow a
 * record for a call the rest of the entry says nothing about — a trace entry
 * that changed after it was written.
 *
 * So the entry takes a copy of each call with the loop's array copied out of
 * it, which is the discipline `dispatches`, `stores` and the outer `models`
 * array already follow, applied one level in. An **empty** list is dropped
 * rather than copied, and that is what makes `docs/trace.md` §7's "never empty"
 * hold for the call a deadline caught between asking for a tool and hearing
 * back: the key is absent there, which §5.3 reads as "no outcome resolved".
 */
function settled(calls: readonly ModelCall[] | undefined): readonly ModelCall[] | undefined {
  return calls?.map((call) => {
    const { toolCalls, ...rest } = call;
    return toolCalls === undefined || toolCalls.length === 0
      ? rest
      : { ...rest, toolCalls: [...toolCalls] };
  });
}

/**
 * Every instance a `flow:` node ran, in the order it ran them (grammar 8.5,
 * PRD 5.3).
 *
 * [`merged`]'s counterpart for subflow traces, and it is a plain concatenation
 * rather than a set difference because the two inputs are disjoint by
 * construction: `collected` holds one trace per attempt that **failed** inside
 * the boundary, gathered by [`runActivity`] from each attempt's
 * [`SubflowFailure`], and `answered` is the trace of the instance that
 * succeeded — which no failure carried. There is at most one of the second, and
 * it goes last because it ran last.
 *
 * The entries of two attempts sit in one list, as a retried node's model calls
 * and store records do, and a reader tells them apart the way the node's own
 * `attempts` count says to: an instance numbers its own supersteps from `1`, so
 * a second `step: 1` entry for the same node is the next attempt beginning.
 * Nesting them per attempt instead would put the attempt boundary in the trace's
 * *shape*, and every reader of `inner` — including a run that did not retry —
 * would have to learn it.
 */
function joined(
  collected: readonly TraceEntry[],
  answered: readonly TraceEntry[] | undefined,
): readonly TraceEntry[] | undefined {
  if (collected.length === 0) return answered;
  return answered === undefined ? [...collected] : [...collected, ...answered];
}

/**
 * Run one node: its input, its activity, its writes, and its routing decision —
 * in one LangGraph task, which is what makes grammar 7.6's P1 (a node's edges
 * are evaluated only after it has completed) structural rather than asserted.
 *
 * The answer is a `Command`: LangGraph's one primitive that carries a state
 * update **and** the control transfer together, so the counter a bounded edge
 * spends (grammar 7.4) and the branch it spends it on land in the same write.
 *
 * **What a guard sees.** The state as of the start of this step, with this
 * node's own writes applied through their channels' reduce policies — so a
 * guard here does not see a concurrent sibling's writes. Grammar 7.6's P1 is
 * per node ("a node's outgoing edges are evaluated only after **that node** has
 * completed"), and this is that reading: routing is part of the node's own task.
 * Reachable only from a fork whose branches write a channel the other branch's
 * guard reads, which
 * `a_guard_sees_its_own_writes_and_not_a_concurrent_siblings` pins.
 *
 * **Which errors `on_error` governs.** The node's own, and only those. Grammar 9
 * is a policy over an *activity* — what the model, the process or the request
 * did — while reading an unset channel or an absent property fails the
 * **execution** (grammar 10.1, Decisions D78, D101, D110). Those are different
 * outcomes, and `skip` and `fallback` would swallow the second into the first,
 * so the input is built **outside** the policy-governed `try`: an expression
 * that cannot be evaluated propagates, and only what the activity did reaches
 * the `catch`.
 *
 * Three more are outside it, and they are a `human` node's (grammar 8.7). A wait
 * whose budget ran out routes to the node's own `on_timeout:` — §9.2's fallback
 * shape, reached from a different key — while a pause this run has no way to
 * answer and a pause nobody is waiting for any more both end the node whatever
 * the policy says, because `skip` absorbing either would route past a human the
 * composition declared it needed. See [`HumanExpiry`], [`HumanInterrupt`] and
 * [`HumanAbandoned`].
 *
 * **What a failure leaves behind.** Every way out of here that throws carries
 * this node's own trace entry on the error ([`carryEntry`]), because a thrown
 * task returns no `Command` and LangGraph discards the superstep it was in —
 * so without that, the one node a reader of a failed run most wants to see is
 * the one node the trace could never hold (PRD 5.3).
 */
export async function runNode(
  descriptor: NodeDescriptor,
  state: GraphStateLike,
): Promise<Command> {
  const run = state.$run;
  const step = run.step + 1;
  const traversal = run.traversals[descriptor.node] ?? 0;

  // Grammar 9.3 level 1, laid over the levels the compiler resolved: the
  // instantiating `flow:` node's `policy:`, which this instance carries.
  const policy = effectivePolicy(descriptor.policy, descriptor.exempt === true, run.policy);

  // The roots a node's *configuration* reads: no `<node>.output` among them,
  // because a node never reads another's output (Decision D42).
  const configuration: Roots = {
    input: bindRoot(run.input, descriptor.shapes.input),
    state: bindRoot(declared(state, descriptor.shapes.state), descriptor.shapes.state),
    execution: bindRoot(run.execution, EXECUTION_SHAPE),
  };
  const view: NodeView = { state, run, roots: configuration };
  // What addresses this node execution inside its run (grammar 9.4, flattened),
  // and so what a pause reached *below* it is named under: a `human` node's wait
  // id is this for the node itself, and this with the instance frames between
  // them appended for one dispatched further down. [`runActivity`] holds its
  // deadline still while one of those is open and abandons any left over when it
  // ends (Decision D102, and see [`abandonPausesUnder`]).
  const site = instancePath(view, descriptor.node).join("/");

  const base: Partial<RunChannel> = {
    step,
    traversals: { [descriptor.node]: traversal + 1 },
  };

  let output: unknown;
  let history: readonly unknown[] | undefined;
  let channels: readonly ChannelWrite[] | undefined;
  let dispatches: readonly DispatchRecord[] | undefined;
  let toolDispatches: readonly DispatchRecord[] | undefined;
  let inner: readonly TraceEntry[] | undefined;
  let models: readonly ModelCall[] | undefined;
  let pause: HumanPause | undefined;
  let attempts = 0;
  let skipped = false;
  let failure: NodeFailure | undefined;
  /**
   * What a **skipped** entry's `error` says.
   *
   * Held here rather than read back off `failure` at the entry below, because
   * `TraceEntry.error` is one field with one shape wherever it appears
   * (`docs/trace.md` §3) and `failure.message` is not that shape. It is the
   * message without the class [`describe`] puts in front of the text on the two
   * entries that carry a failure the node did *not* absorb — the aborting one
   * and the `fallback:` one — so a reader handed the same field on a skip would
   * be handed a different form of it. And it is not there at all for a throw
   * that reached the catch without having been wrapped in a [`NodeFailure`],
   * which would leave a skipped entry with no account of what it absorbed.
   */
  let absorbed: string | undefined;
  // Every store op this node performs, across every attempt its policy makes:
  // an effect that happened is an effect that happened, and a record that kept
  // only the last attempt's would describe a run the store did not see
  // (PRD 5.8). Owned here rather than by `runActivity` so a node that fails
  // still reports what it wrote before it did.
  const storeRecords: StoreRecord[] = [];
  // And every model call, for the same reason and read the same way: whichever
  // way the node leaves, this is the set that really happened, and an answer —
  // when there is one — is what puts the calls it carried in the order the node
  // decided (PRD 5.9, and see `RunContext.modelCalls` and `merged`).
  const modelCalls: ModelCall[] = [];
  // And every instance a `flow:` node's attempts ran, for the third time the
  // same reason: an attempt that failed inside the boundary still ran an
  // instance, and its trace is the only account of what that instance did
  // (grammar 8.5, PRD 5.3). `runActivity` fills this from the `SubflowFailure`
  // each failed attempt threw; the instance that *succeeded* is carried by the
  // answer instead, and the two are joined below.
  const innerTraces: TraceEntry[] = [];
  // And every subflow a model invoked, for the fourth time the same reason: a
  // tool loop that failed on its fourth call still ran three instances, and
  // each one's trace is the only account of what it did (grammar 5.4,
  // PRD §9.20, and see `RunContext.toolDispatches`). `callSubflowTool` pushes
  // here as it files each record; the answer carries the same objects in the
  // order the node could put them, and `merged` reconciles the two.
  const toolDispatched: DispatchRecord[] = [];

  /** This node's entry, for a failure that leaves nothing else behind. */
  const aborted = (error: unknown, made: number, routing?: RoutingDecision): TraceEntry => {
    // A subflow that failed still made a trace, and it is the only account of
    // what happened inside the boundary (grammar 8.5, PRD 5.3). `inner` already
    // holds every instance *this node* ran — `runActivity` collects one per
    // failed attempt — so [`traceOf`] is the recovery for a [`SubflowFailure`]
    // that arrived restated on the `cause` chain instead, the way
    // [`abortedEntry`] recovers an entry from one. It stops at an
    // [`ItemFailure`]: what is under one is a *dispatched* instance, whose trace
    // is on its own record rather than on this entry.
    const held = inner ?? traceOf(error);
    const dispatched = dispatches ?? dispatchesOf(error) ?? plannedDispatches(input);
    // A pause that never settled is on the error that ended the run, and it is
    // the only account of the wait: the node's task never returned an answer to
    // carry one (grammar 8.7). `site` is what keeps it *this* node's pause: the
    // same error carries a pause raised below this node up past every enclosing
    // `flow:` and `map` node, none of which held one (see [`pauseOf`]).
    const paused = pause ?? pauseOf(error, site);
    // Read off the collector the way `stores` and `toolDispatches` below are,
    // and for their reason: whichever way this node ended, `modelCalls` holds
    // every call it made (PRD 5.9). The local is preferred where there is one,
    // because that is the ordering the node decided — the answer's, or the
    // snapshot the `catch` below takes — and the one path that reaches here
    // with calls made and no local set is a **pause**: an interrupt is
    // re-thrown ahead of `on_error:` (grammar 8.7), before the `catch` gets to
    // the line that snapshots them. Its entry would otherwise say the agent
    // node called no model at all, and — since a `flow.*` in `tools:` may hold
    // the `human` node that paused (grammar 5.4) — would carry a
    // `toolDispatches` record with no tool call naming it, which is exactly the
    // indirection PRD §9.20 promises is always there (`docs/trace.md` §7.3,
    // §9).
    const called = models ?? (modelCalls.length === 0 ? undefined : settled(modelCalls));
    return {
      step,
      flow: descriptor.flow,
      node: descriptor.node,
      traversal,
      outcome: "failed",
      attempts: made,
      ...(routing === undefined ? {} : { routing }),
      ...(dispatched === undefined ? {} : { dispatches: dispatched }),
      // Read straight off the collector rather than recovered from the error:
      // every record a model's call filed is pushed there as it is filed, so
      // whichever way this node ended, this is the whole of what its tool loop
      // instantiated (PRD §9.20).
      ...(toolDispatched.length === 0 ? {} : { toolDispatches: [...toolDispatched] }),
      ...(held === undefined ? {} : { inner: held }),
      ...(storeRecords.length === 0 ? {} : { stores: [...storeRecords] }),
      ...(called === undefined ? {} : { models: called }),
      ...(paused === undefined ? {} : { human: paused }),
      error: describe(error),
    };
  };

  // Outside the `try` on purpose — see *Which errors `on_error` governs* above.
  // A `map`'s whole dispatch is decided here too: which items, which routes, and
  // what each instance is passed, so a per-item binding that reads an absent
  // value fails the execution rather than one item (grammar 8.6, D110).
  let input: unknown;
  try {
    input = descriptor.input(configuration, view);
  } catch (error) {
    // No attempt was made: the node never ran, so `0` is what it made.
    throw carryEntry(error, aborted(error, 0));
  }

  try {
    const answer = await runActivity(
      descriptor.flow,
      descriptor.node,
      site,
      policy,
      run.execution,
      (context) => descriptor.run(input, context, view),
      storeRecords,
      modelCalls,
      innerTraces,
      toolDispatched,
    );
    attempts = answer.attempts;
    output = answer.value.output;
    history = answer.value.history;
    channels = answer.value.channels;
    dispatches = answer.value.dispatches;
    // Every subflow a model invoked, read the way `models` below is read: the
    // answer puts the ones it could order in that order — an agent's own call
    // order, a `map`'s source-item order — and the collector holds every record
    // that really happened, including an earlier attempt's (PRD §9.20).
    toolDispatches = merged(toolDispatched, answer.value.toolDispatches);
    // Every instance this node ran, in the order it ran them: the attempts that
    // failed inside the boundary first — `runActivity` collected each one's
    // trace — and the one that answered last, because it happened last. A node
    // that reported only the answer's would describe an execution in which the
    // earlier instances never ran, while their writes are in `stores` above and
    // their model calls in `models` below (PRD 5.3).
    inner = joined(innerTraces, answer.value.inner);
    // Every model call this node execution made, which is more than the answer
    // can carry (PRD 5.9, `RunContext.modelCalls`). An answer holds the calls it
    // *ordered* — a `map`'s in source-item order — and by construction only the
    // ones the attempt it came out of made, so a node that succeeded on its
    // second `retry:` attempt would otherwise report a trace with no trace of
    // the first, spent ladder and all. What `modelCalls` holds beside them
    // really happened and has nowhere else to be reported: an earlier attempt's
    // calls, and the calls of an item the fan-out absorbed under
    // `on_item_error: skip`. They are reported ahead of the ordering the answer
    // imposes, in the order they were made, rather than interleaved into an
    // ordering that is not a clock — see [`merged`]. `stores` on the same entry
    // has always been the whole of `storeRecords` for the same reason, and this
    // is the half that was missing it.
    models = settled(merged(modelCalls, answer.value.models));
    pause = answer.value.human;
  } catch (error) {
    // Two outcomes of a `human` node reach here as throws and neither is an
    // activity failure, so neither is `on_error`'s to decide (grammar 8.7,
    // 9.2). They are answered ahead of the policy for the reason an input that
    // could not be built is answered outside it: `skip` and `fallback:` are
    // policies over what an activity did, and a wait that ran out its budget or
    // a run with no way to answer one are the composition's own control flow.
    failure = error instanceof NodeFailure ? error : undefined;
    if (interruptOf(error) !== undefined) {
      // What the node *made*, which `runActivity` counted and wrapped this in:
      // an interrupt on the second attempt of a node whose first attempt failed
      // some other way is a node that made two, and `docs/trace.md` §3's
      // `attempts` is "how many attempts the node made".
      throw carryEntry(error, aborted(error, failure?.attempts ?? 1));
    }
    // A third leaves here without meeting the policy, and it is not an outcome
    // at all: a pause nobody is waiting for any more. `skip` absorbing it would
    // route this graph past a `human` node whose answer the composition declared
    // it needed — the reading [`HumanInterrupt`] refuses for the interrupt — and
    // it would do so inside an instance whose result was already discarded. It
    // carries **no trace entry**, for the reason it carries no strategy: the
    // entry would belong to a task nothing is left to read (see
    // [`abandonPausesUnder`], [`HumanAbandoned`]).
    if (abandonedOf(error) !== undefined) throw error;
    // A fourth is not an outcome either, and is the one an `on_error:` must not
    // be allowed to absorb: a journal that does not describe this run
    // (resolved q29). `skip` would carry this graph past an effect the record
    // claims to hold, and a `fallback:` would route on a disagreement rather
    // than on anything the composition declared. It carries the entry the
    // aborting path builds, so a reader still sees which node it stopped at.
    if (divergenceOf(error) !== undefined) {
      throw carryEntry(error, aborted(error, failure?.attempts ?? 1));
    }
    // An expiry never travels, which is what makes `expiry.route` safe to route
    // on here: this is where one is answered, by the very node that raised it,
    // and the answer is a `Command` rather than a throw, so — unlike an
    // interrupt, which the line above has already re-thrown past every enclosing
    // node — it is never on another node's `cause` chain. The pause below goes
    // through [`pauseOf`]'s identity check all the same: the two sites read one
    // rule, and a reader should not have to prove this one unreachable to know
    // whose wait the entry is about.
    const expiry = expiryOf(error);
    const strategy: ErrorStrategy =
      expiry === undefined ? policy.onError : { fallback: expiry.route };
    pause = pauseOf(error, site);
    // The same join as the success path, with nothing to join to: every attempt
    // that failed inside the boundary put its instance's trace in `innerTraces`,
    // the one that ended the node included. A `SubflowFailure` reached only
    // through a chain — a `map`'s item, wrapped in an `ItemFailure` — is not one
    // of this node's own attempts and is not one of these: it is a *dispatched*
    // instance, already recorded under its own [`DispatchRecord.inner`], and
    // [`traceOf`] stops at that boundary so it does not arrive here twice.
    inner = joined(innerTraces, undefined);
    // A `map` that failed still dispatched: the items that completed had their
    // effects and the detached ones were delivered, and the records are the only
    // account of them (PRD 5.3, 5.6). They ride out on the `ItemFailure`, which
    // `runActivity` wrapped, so the chain is walked the way `inner` above is —
    // and when the failure is the node's own **deadline** there is no
    // `ItemFailure` to walk, because the deadline is raced and the map's promise
    // was abandoned holding it. The plan is where the records are then read
    // from, and is the reason a timed-out fan-out still says what it dispatched.
    dispatches = dispatchesOf(error) ?? plannedDispatches(input);
    // Every model call this node made, which the failure carried out with it —
    // an exhausted route's whole ladder, or the calls a tool loop made before
    // the one that ended it (PRD 5.9, `RunContext.modelCalls`). `models` is
    // still undefined here: the activity threw, so no answer set it.
    if (modelCalls.length > 0) models = settled(modelCalls);
    // And every subflow a model invoked before the call that ended the node,
    // for the same reason and off the same kind of collector (PRD §9.20).
    if (toolDispatched.length > 0) toolDispatches = [...toolDispatched];
    // `runActivity` wraps everything the activity threw in a `NodeFailure`
    // carrying the attempts it *made*, so the fallback is for an error that
    // reached here without one being made at all — and `0` is what that is.
    attempts = failure?.attempts ?? 0;
    if (strategy === "fail") throw carryEntry(error, aborted(error, attempts));
    if (typeof strategy === "object") {
      // The node's own outgoing edges are not evaluated: the fallback target is
      // scheduled instead (grammar 9.2, Decision D21).
      const entry: TraceEntry = {
        step,
        flow: descriptor.flow,
        node: descriptor.node,
        traversal,
        outcome: "failed",
        attempts,
        error: describe(error),
        ...(dispatches === undefined ? {} : { dispatches }),
        ...(toolDispatches === undefined ? {} : { toolDispatches }),
        ...(inner === undefined ? {} : { inner }),
        ...(storeRecords.length === 0 ? {} : { stores: [...storeRecords] }),
        ...(models === undefined ? {} : { models }),
        ...(pause === undefined ? {} : { human: pause }),
        fallback: strategy.fallback,
      };
      return new Command({
        update: {
          $run: { ...base, ...retained(descriptor, undefined, true), trace: [entry] },
        },
        goto: [strategy.fallback],
      });
    }
    absorbed = describe(error);
    skipped = true;
  }

  const update: Record<string, unknown> = {};
  const localState = declared(state, descriptor.shapes.state);
  const written: string[] = [];
  if (!skipped) {
    const fields = (output ?? {}) as Record<string, unknown>;
    for (const write of descriptor.writes) {
      const value = fields[write.field];
      // A field the result does not carry performs no write (Decision D110).
      if (value === undefined) continue;
      update[write.channel] = value;
      localState[write.channel] = applyWrite(state[write.channel], value, write.reduce);
      written.push(write.channel);
    }
    // A `map`'s writers are its instances, so what it landed arrives already
    // ordered by source-item index and goes to the channel as one batch its
    // reducer unpacks — or as the folded value where the channel could not be
    // handed a batch (grammar 7.6.4 clause 2, and see `orderedUpdate`).
    for (const batch of channels ?? []) {
      // A channel with no contribution at all is not a write: `orderedChannels`
      // opens an entry only for a field an instance really produced, so this
      // guards the invariant rather than naming a case.
      if (batch.values.length === 0) continue;
      update[batch.channel] = orderedUpdate(batch);
      localState[batch.channel] = batch.values.reduce(
        (held, value) => applyWrite(held, value, batch.reduce),
        state[batch.channel],
      );
      written.push(batch.channel);
    }
    if (history !== undefined && history.length > 0) {
      update["messages"] = history;
    }
  }

  let routing: RoutingDecision;
  try {
    const roots: Roots = {
      ...configuration,
      state: bindRoot(localState, descriptor.shapes.state),
      [descriptor.node]: skipped
        ? undefined
        : bindRoot({ output }, { properties: { output: descriptor.shapes.output } }),
    };
    routing = route(
      descriptor.flow,
      descriptor.node,
      descriptor.edges,
      roots,
      run.iterations,
      skipped,
    );
  } catch (error) {
    // A route that could not be decided is still a routing decision, and the
    // guard values are the whole of it — so a `NoViableRoute` hands them on
    // (PRD 5.3). `targets` is empty because that is what went wrong.
    throw carryEntry(
      error,
      aborted(
        error,
        attempts,
        error instanceof NoViableRoute
          ? { edges: [...error.decisions], targets: [], counters: {} }
          : undefined,
      ),
    );
  }

  const entry: TraceEntry = {
    step,
    flow: descriptor.flow,
    node: descriptor.node,
    traversal,
    outcome: skipped ? "skipped" : "completed",
    attempts,
    writes: written,
    routing,
    ...(dispatches === undefined ? {} : { dispatches }),
    ...(toolDispatches === undefined ? {} : { toolDispatches }),
    ...(inner === undefined ? {} : { inner }),
    ...(storeRecords.length === 0 ? {} : { stores: [...storeRecords] }),
    ...(models === undefined ? {} : { models }),
    ...(pause === undefined ? {} : { human: pause }),
    ...(absorbed === undefined ? {} : { error: absorbed }),
  };
  update["$run"] = {
    ...base,
    ...retained(descriptor, output, skipped),
    iterations: routing.counters,
    trace: [entry],
  };
  return new Command({ update, goto: routing.targets });
}

/**
 * What a node keeps in `$run.outputs` for a `map.over` in a later step to read
 * (grammar 8.6 rule 11, and see [`RunChannel.outputs`]).
 *
 * A node no map reads keeps nothing. A node that was **skipped** — or that took
 * a `fallback:`, which produced no result either — writes its key back holding
 * `undefined`, so a map dispatches zero instances rather than fanning out over
 * the array the producer left on an earlier traversal of the same cycle.
 */
function retained(
  descriptor: NodeDescriptor,
  output: unknown,
  skipped: boolean,
): Partial<RunChannel> {
  if (descriptor.retains !== true) return {};
  return { outputs: { [descriptor.node]: skipped ? undefined : output } };
}

function bindRoot(value: unknown, shape: Shape): CelValue {
  const bound = bind(value, shape);
  if (bound === undefined) {
    throw new CelError("a root is absent");
  }
  return bound;
}

/**
 * The channels the `state` root exposes: exactly the ones the composition
 * declares (grammar 4.1, 10.1).
 *
 * The graph's state object holds more than that — `messages`, the implicit
 * conversation history of grammar 10.4, and `$run`, this compiler's own channel
 * — and neither is a name an expression may read: the validator types `state`
 * from the `state:` section alone, so `state.messages` is an undefined channel
 * at compile time and would be a readable object at run time. Narrowing here is
 * what keeps the runtime scope equal to the declared one.
 *
 * It is also what keeps a node's cost flat in the length of the run. `bind`
 * copies what it is given, and `$run` carries the whole routing trace (PRD 5.3),
 * so binding the raw state object copied every earlier step's trace entries into
 * CEL values at every node — quadratic in the trace, for a root nothing can
 * name.
 */
function declared(
  state: Readonly<Record<string, unknown>>,
  shape: Shape,
): Record<string, unknown> {
  const properties = typeof shape === "object" && "properties" in shape ? shape.properties : {};
  const narrowed: Record<string, unknown> = {};
  for (const channel of Object.keys(properties)) {
    // An unset channel stays absent rather than arriving as `undefined`: which
    // channels a value carries is what `has()` reads and what a failed read
    // reports (grammar 10.1, Decision D78).
    if (state[channel] !== undefined) narrowed[channel] = state[channel];
  }
  return narrowed;
}

